# --- VARIÃVEIS DE SISTEMA DE ARQUIVOS (PREVENÃ‡ÃƒO DE QUEDA DE MEMÃ“RIA) ---
# Caminhos **absolutos** na pasta de dados (não dependem do cwd; no Windows evitam gravar em C: quando há outro disco)
_GARIM_ROOT = (os.environ.get("GARIMPEIRO_RESOLVED_DATA_ROOT") or "").strip() or os.path.dirname(
    os.path.abspath(__file__)
)
TEMP_EXTRACT_DIR = os.path.join(_GARIM_ROOT, "temp_garimpo_zips")
TEMP_UPLOADS_DIR = os.path.join(_GARIM_ROOT, "temp_garimpo_uploads")
MAX_XML_PER_ZIP = 10000  # Máx. XMLs por ficheiro ZIP (lista específica, Etapa 3, e partes _dom02… no pacote contab modo domínio)
# Teto em MB do ZIP de contabilidade. O leitor externo (Domínio etc.) recusa ~50 MB;
# 49 MB ficava no limite e às vezes era recusado — 47 MB deixa folga.
MAX_ZIP_CONTAB_MB = 47
MAX_ZIP_CONTAB_BYTES = MAX_ZIP_CONTAB_MB * 1024 * 1024
_ZIP_CONTAB_MARGEM_FECHO = 2 * 1024 * 1024  # diretório central do ZIP + folga ao fechar
# Máximo de botões «XML solto» na UI (aberto); acima disto o utilizador deve usar o ZIP.
MAX_XML_DOWNLOAD_ABERTO_UI = 100
# Compressão ZIP (exportações / pacote contabilidade): ver _zip_export_compresslevel() — env GARIMPEIRO_ZIP_COMPRESSLEVEL.


def _zip_bytes_escritos(zf) -> int:
    """Bytes já gravados no ZIP aberto (antes do diretório central)."""
    fp = getattr(zf, "fp", None)
    if fp is None:
        return 0
    try:
        return int(fp.tell())
    except (OSError, ValueError, TypeError):
        return 0


def _zip_contab_precisa_nova_parte(
    zf, *, ja_tem_ficheiros: bool, reserva_extra: int = 0
) -> bool:
    """True se o ZIP de contabilidade já está no teto de MAX_ZIP_CONTAB_MB (antes do próximo XML)."""
    if zf is None or not ja_tem_ficheiros:
        return False
    margem = _ZIP_CONTAB_MARGEM_FECHO + max(0, int(reserva_extra or 0))
    teto = MAX_ZIP_CONTAB_BYTES - margem
    if teto < 1:
        teto = MAX_ZIP_CONTAB_BYTES
    return _zip_bytes_escritos(zf) >= teto


def _zip_export_compresslevel() -> int:
    """
    Nível zlib para ZIP_DEFLATED (1 = mais rápido, 9 = mais lento e ficheiros menores).
    Omissão **6** — em pastas de rede (UNC) o nível 9 multiplica horas em lotes grandes.
    Variável de ambiente: GARIMPEIRO_ZIP_COMPRESSLEVEL
    """
    raw = (os.environ.get("GARIMPEIRO_ZIP_COMPRESSLEVEL") or "6").strip()
    try:
        n = int(raw)
    except ValueError:
        n = 6
    return max(1, min(n, 9))


def _zipfile_open_write_export(path: str):
    """ZIP de download/pacotes: DEFLATE (nível via GARIMPEIRO_ZIP_COMPRESSLEVEL, omissão 6)."""
    return zipfile.ZipFile(
        str(path), "w", zipfile.ZIP_DEFLATED, compresslevel=_zip_export_compresslevel()
    )


def _caminho_precisa_zip_temp_local(path) -> bool:
    """ZIP aberto diretamente em UNC/pasta de rede costuma falhar ao fechar (Errno 22)."""
    try:
        p = str(Path(path))
    except (TypeError, ValueError, OSError):
        return True
    if p.startswith("\\\\") or p.startswith("//"):
        return True
    return False


def _zip_resolver_caminho_escrita(caminho_final) -> tuple[str, str | None]:
    """
    Devolve (caminho_para_abrir_ZipFile, caminho_final_para_copiar_ou_None).
    Em pasta de rede grava primeiro em temp local (TEMP_UPLOADS_DIR).
    """
    final = Path(caminho_final)
    final_s = str(final)
    if not _caminho_precisa_zip_temp_local(final_s):
        try:
            final.parent.mkdir(parents=True, exist_ok=True)
        except OSError:
            pass
        return final_s, None
    os.makedirs(TEMP_UPLOADS_DIR, exist_ok=True)
    base = _v2_sanitize_nome_export(final.name, max_len=120) or "export.zip"
    if not str(base).lower().endswith(".zip"):
        base = f"{base}.zip"
    tmp = os.path.join(
        TEMP_UPLOADS_DIR,
        f"_zipnet_{int(time.time() * 1000)}_{random.randint(0, 999999999)}_{base}",
    )
    return tmp, final_s


def _zip_finalizar_gravacao(caminho_escrita: str, caminho_final_opcional: str | None) -> str:
    """Copia ZIP da pasta local para o destino final (rede) e devolve o caminho utilizável."""
    if not caminho_final_opcional:
        return caminho_escrita
    if not os.path.isfile(caminho_escrita):
        return caminho_escrita
    dest_dir = os.path.dirname(caminho_final_opcional)
    if dest_dir:
        try:
            os.makedirs(dest_dir, exist_ok=True)
        except OSError:
            pass
    try:
        shutil.copy2(caminho_escrita, caminho_final_opcional)
        try:
            os.remove(caminho_escrita)
        except OSError:
            pass
        return caminho_final_opcional
    except OSError as e:
        msg = (
            f"ZIP criado em `{caminho_escrita}` mas não foi possível copiar para a pasta de destino "
            f"(`{caminho_final_opcional}`): {e}"
        )
        try:
            prev = st.session_state.get("_garimpo_export_zip_erro")
            st.session_state["_garimpo_export_zip_erro"] = (
                f"{prev}\n{msg}" if prev else msg
            )
        except Exception:
            pass
        return caminho_escrita


def _zip_abrir_exportacao(caminho_final):
    """Devolve (ZipFile, caminho_escrita, caminho_final_opcional)."""
    wp, fo = _zip_resolver_caminho_escrita(caminho_final)
    return _zipfile_open_write_export(wp), wp, fo


def _zip_fechar_exportacao(zf, caminho_escrita, caminho_final_opcional=None) -> str:
    """Fecha o ZIP e copia para rede/UNC quando necessário."""
    if zf is not None:
        try:
            zf.close()
        except OSError:
            pass
    return _zip_finalizar_gravacao(caminho_escrita, caminho_final_opcional)


def _lista_ficheiros_pasta_uploads():
    """
    Só ficheiros em TEMP_UPLOADS_DIR (ignora subpastas).
    Abrir uma pasta com open(..., 'rb') no Windows gera erro — o garimpo e os ZIPs devem iterar só ficheiros.
    """
    if not os.path.isdir(TEMP_UPLOADS_DIR):
        return []
    try:
        return [
            f
            for f in os.listdir(TEMP_UPLOADS_DIR)
            if os.path.isfile(os.path.join(TEMP_UPLOADS_DIR, f))
        ]
    except OSError:
        return []


