_GARIMPO_EXTRA_FONTE_DIR_LIMPAR = "_garimpo_extra_fonte_dir_novo_limpar"
SESSION_KEY_GARIMPO_LOTE_SQLITE_PATH = "_garimpo_lote_sqlite_path"
SESSION_KEY_GARIMPO_LOTE_USE_SQLITE = "_garimpo_lote_use_sqlite_fontes"
_GARIMPO_LOTE_SQLITE_MIN = max(
    500, int(os.environ.get("GARIMPEIRO_LOTE_SQLITE_MIN", "1500") or "1500")
)
# Após o lote: 1) primeiro rerun só mostra o relatório; 2) segundo rerun grava o espelho (evita bloquear a UI no passo 1).
SESSION_KEY_GARIMPO_ESPELHO_WRITE_PHASE = "_garimpo_espelho_write_phase"
SESSION_KEY_ARQUIVO_FISCAL_ROOT = "arquivo_fiscal_pasta_raiz"
SESSION_KEY_ARQUIVO_FISCAL_CAPTURA = "arquivo_fiscal_captura_ativa"
# Sessão desktop: quem indexou (filtro opcional por utilizador)
SESSION_KEY_ARQUIVO_FISCAL_USUARIO = "arquivo_fiscal_usuario"
SESSION_KEY_ARQUIVO_FISCAL_FILTRO_PROPRIOS = "arquivo_fiscal_filtro_proprios"
SESSION_KEY_GARIMPO_TELA = "garimpo_tela_modo"  # inicio | garimpo | arquivo | inutil | sped
# Barra lateral (app desktop): arquivo | simples
SESSION_KEY_GARIMPO_MODO_TRABALHO = "garimpo_modo_trabalho"
GARIMPO_MODO_ARQUIVO = "arquivo"
GARIMPO_MODO_SIMPLES = "simples"
_ARQUIVO_FISCAL_NOME_EXCEL = "relatorio_garimpeiro_completo.xlsx"
_ARQUIVO_FISCAL_NOME_EXCEL_META = "relatorio_garimpeiro_completo.meta.json"
# Incrementar quando o layout/colunas do Excel mudarem (força 1 regeneração).
_EXCEL_RELATORIO_VERSAO = 11  # Cancelada: mês da emissão (chave), nunca a data do evento
_ARQUIVO_FISCAL_SUBPASTA_XML = "XML"
_ARQUIVO_FISCAL_SUBPASTA_ZIP = "ZIP"

# Passo 1 — `st.file_uploader` do lote: muita RAM na sessão + `deepcopy` em cada rerun → MemoryError.
GARIMPO_SESSION_UPLOAD_LOTE_XML = "garimpo_ini_lote_xml"
# Por defeito **2 GB** no total (alinhado ao limite que já usavam); `GARIMPEIRO_LOTE_UPLOAD_MAX_BYTES` para afinar.
_GARIMPO_LOTE_UPLOADER_MAX_TOTAL_BYTES = int(
    os.environ.get("GARIMPEIRO_LOTE_UPLOAD_MAX_BYTES", str(2 * 1024 * 1024 * 1024))
)
_GARIMPO_LOTE_UPLOADER_MAX_FILES = int(os.environ.get("GARIMPEIRO_LOTE_UPLOAD_MAX_FILES", "500"))


def _garimpo_bytes_e_contagem_upload_lote_xml():
    """Soma de `UploadedFile.size` e n.º de ficheiros na chave do uploader (sem ler bytes)."""
    try:
        raw = st.session_state.get(GARIMPO_SESSION_UPLOAD_LOTE_XML)
    except Exception:
        return 0, 0
    if raw is None:
        return 0, 0
    fs = list(raw) if isinstance(raw, (list, tuple)) else [raw]
    n_files = len(fs)
    n_bytes = 0
    for f in fs:
        try:
            n_bytes += int(getattr(f, "size", 0) or 0)
        except Exception:
            pass
    return n_bytes, n_files


def _garimpo_liberta_upload_lote_xml_se_pesado() -> None:
    """Antes do `file_uploader`: evita MemoryError no `register_widget` / `deepcopy` do Streamlit."""
    nb, nf = _garimpo_bytes_e_contagem_upload_lote_xml()
    if nb <= _GARIMPO_LOTE_UPLOADER_MAX_TOTAL_BYTES and nf <= _GARIMPO_LOTE_UPLOADER_MAX_FILES:
        return
    try:
        st.session_state.pop(GARIMPO_SESSION_UPLOAD_LOTE_XML, None)
    except Exception:
        return
    gc.collect()
    _lim_b = max(1, int(_GARIMPO_LOTE_UPLOADER_MAX_TOTAL_BYTES))
    _lim_gb = _lim_b / (1024.0**3)
    _lim_disp = f"{_lim_gb:.0f} GB" if _lim_gb >= 1 else f"{_lim_b // (1024 * 1024)} MB"
    st.warning(
        f"Os anexos do lote tinham cerca de **{nb / (1024 * 1024):.0f} MB** (**{nf}** ficheiros), acima do limite seguro para a sessão do browser (~**{_lim_disp}** ou **{_GARIMPO_LOTE_UPLOADER_MAX_FILES}** ficheiros; o Streamlit duplica os dados na memória). "
        "**Anexe de novo** em partes menores ou use a **pasta no servidor**. Opcional: variáveis de ambiente `GARIMPEIRO_LOTE_UPLOAD_MAX_BYTES` e `GARIMPEIRO_LOTE_UPLOAD_MAX_FILES`."
    )


def _garimpo_descarta_upload_lote_xml_apos_copia() -> None:
    """Após gravar os bytes em disco/memória: liberta RAM antes do extract (menos pressão na sessão)."""
    try:
        st.session_state.pop(GARIMPO_SESSION_UPLOAD_LOTE_XML, None)
    except Exception:
        pass
    gc.collect()


def garimpe_subdir_espelho_nome() -> str:
    """Subpasta fixa sob a pasta de destino do espelho (pacote contabilidade)."""
    return "Extração Garimpeiro"


def _garimpo_info_pastas_gravacao_sessao() -> dict:
    """
    Caminhos de gravação do trabalho atual (passo 3 + subpasta do espelho).
    Devolve destino, espelho, subpasta_nome, tem_espelho_gravado, texto_ui (markdown).
    """
    destino_s = str(st.session_state.get("garimpo_lote_save_resolved") or "").strip()
    if not destino_s:
        raw = st.session_state.get("mariana_zip_save_dir")
        if raw is not None:
            destino_s = str(raw).strip().strip('"').strip("'")
    espelho_s = str(st.session_state.get("garimpo_lote_espelho_root") or "").strip()
    sub = garimpe_subdir_espelho_nome()
    espelho_previsto = ""
    if destino_s and not espelho_s:
        try:
            espelho_previsto = str(
                (Path(destino_s).expanduser().resolve() / sub)
            )
        except (OSError, ValueError):
            sep = "\\" if "\\" in destino_s else "/"
            espelho_previsto = f"{destino_s.rstrip(sep)}{sep}{sub}"
    espelho_efetivo = espelho_s or espelho_previsto
    linhas = []
    if destino_s:
        linhas.append(f"- **Pasta de destino (passo 3):** `{destino_s}`")
    if espelho_s:
        linhas.append(f"- **Espelho deste trabalho:** `{espelho_s}`")
    elif espelho_previsto:
        linhas.append(
            f"- **Espelho (será ou foi gravado aqui):** `{espelho_previsto}`"
        )
    texto_ui = "\n".join(linhas)
    return {
        "destino": destino_s,
        "espelho": espelho_efetivo,
        "subpasta": sub,
        "tem_espelho_gravado": bool(espelho_s),
        "texto_ui": texto_ui,
    }


# Durante um único .zip enorme o ciclo interno demora muito; sem refrescos o rodapé fica em «0s» e a barra em 50% (1/2 ficheiros).
# Intervalo alto o bastante para não sobrecarregar o Streamlit com milhares de deltas ao browser.
_GARIM_GRANDE_GARIMPO_REFRESH_XML_A_CADA = 1200
_GARIM_GC_COLETA_A_CADA = max(50, int(os.environ.get("GARIMPEIRO_GC_A_CADA", "250") or "250"))
_GARIM_UI_PAINEL_A_CADA = max(10, int(os.environ.get("GARIMPEIRO_UI_PAINEL_A_CADA", "50") or "50"))


def _session_state_get_garimpo(key, default=None):
    """
    Lê session_state sem rebentar com «SessionInfo before initialization».
    O get_script_run_ctx() sozinho não basta em algumas versões; só try/except é fiável.
    """
    try:
        return st.session_state.get(key, default)
    except Exception:
        return default


def _session_state_pop_garimpo(key):
    try:
        st.session_state.pop(key, None)
    except Exception:
        pass


def _garimpo_analise_sem_pasta_local_projeto() -> bool:
    """
    True (omissão): durante a análise **não** grava uploads em `temp_garimpo_uploads` na pasta do projeto —
    mantém os bytes na sessão Streamlit até nova análise. Exportações ZIP/Excel continuam a ir para a pasta **que escolher**.
    Defina `GARIMPEIRO_ANALISE_SEM_DISCO_LOCAL=0` para voltar a gravar no disco (lotes muito grandes e pouca RAM).
    """
    v = os.environ.get("GARIMPEIRO_ANALISE_SEM_DISCO_LOCAL", "1").strip().lower()
    return v not in ("0", "false", "no", "off")


def _garimpo_limpar_fontes_xml_memoria_sessao():
    _session_state_pop_garimpo(SESSION_KEY_FONTES_XML_MEMORIA)
    _session_state_pop_garimpo(SESSION_KEY_FONTES_XML_DISK_PATHS)
    _garimpo_lote_sqlite_limpar()


def _garimpo_lote_sqlite_forcado_env() -> bool:
    v = (os.environ.get("GARIMPEIRO_LOTE_SQLITE") or "").strip().lower()
    return v in ("1", "true", "yes", "on")


def _garimpo_lote_sqlite_desativado_env() -> bool:
    v = (os.environ.get("GARIMPEIRO_LOTE_SQLITE") or "").strip().lower()
    return v in ("0", "false", "no", "off")


def _garimpo_lote_usa_sqlite() -> bool:
    if _garimpo_lote_sqlite_desativado_env():
        return False
    if _garimpo_lote_sqlite_forcado_env():
        return True
    return bool(st.session_state.get(SESSION_KEY_GARIMPO_LOTE_USE_SQLITE))


def _garimpo_lote_sqlite_caminho_db() -> str:
    p = st.session_state.get(SESSION_KEY_GARIMPO_LOTE_SQLITE_PATH)
    if p:
        return str(p)
    idx_dir = os.path.join(_garimpeiro_resolver_pasta_dados(), "lote_index")
    os.makedirs(idx_dir, exist_ok=True)
    fd, path = tempfile.mkstemp(prefix="fontes_", suffix=".sqlite", dir=idx_dir)
    os.close(fd)
    st.session_state[SESSION_KEY_GARIMPO_LOTE_SQLITE_PATH] = path
    return path


def _garimpo_lote_sqlite_conn() -> sqlite3.Connection:
    conn = sqlite3.connect(_garimpo_lote_sqlite_caminho_db(), check_same_thread=False)
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute(
        "CREATE TABLE IF NOT EXISTS fonte (chave TEXT PRIMARY KEY, caminho TEXT NOT NULL)"
    )
    conn.execute("CREATE INDEX IF NOT EXISTS ix_fonte_caminho ON fonte (caminho)")
    return conn


def _garimpo_lote_sqlite_inserir(mapa: dict[str, str]) -> None:
    if not mapa:
        return
    conn = _garimpo_lote_sqlite_conn()
    try:
        conn.executemany(
            "INSERT OR IGNORE INTO fonte (chave, caminho) VALUES (?, ?)",
            list(mapa.items()),
        )
        conn.commit()
    finally:
        conn.close()


def _garimpo_lote_sqlite_count() -> int:
    conn = _garimpo_lote_sqlite_conn()
    try:
        row = conn.execute("SELECT COUNT(*) FROM fonte").fetchone()
        return int(row[0]) if row else 0
    finally:
        conn.close()


def _garimpo_lote_sqlite_chaves() -> list[str]:
    conn = _garimpo_lote_sqlite_conn()
    try:
        return [r[0] for r in conn.execute("SELECT chave FROM fonte ORDER BY chave").fetchall()]
    finally:
        conn.close()


def _garimpo_lote_sqlite_caminho(chave: str) -> str | None:
    conn = _garimpo_lote_sqlite_conn()
    try:
        row = conn.execute(
            "SELECT caminho FROM fonte WHERE chave = ?", (chave,)
        ).fetchone()
        return str(row[0]) if row else None
    finally:
        conn.close()


def _garimpo_lote_sqlite_caminhos_lower() -> set[str]:
    conn = _garimpo_lote_sqlite_conn()
    try:
        return {str(r[0]) for r in conn.execute("SELECT lower(caminho) FROM fonte").fetchall()}
    finally:
        conn.close()


def _garimpo_lote_sqlite_limpar() -> None:
    path = st.session_state.pop(SESSION_KEY_GARIMPO_LOTE_SQLITE_PATH, None)
    st.session_state.pop(SESSION_KEY_GARIMPO_LOTE_USE_SQLITE, None)
    if not path:
        return
    for suffix in ("", "-wal", "-shm"):
        p = path + suffix if suffix else path
        try:
            if os.path.isfile(p):
                os.remove(p)
        except OSError:
            pass


def _garimpo_lote_persistir_path_map(path_map: dict[str, str]) -> None:
    """Indexa caminhos do lote; lotes grandes vão para SQLite (menos RAM na sessão)."""
    if not path_map:
        return
    exist = dict(_session_state_get_garimpo(SESSION_KEY_FONTES_XML_DISK_PATHS) or {})
    merged = {**exist, **path_map}
    if _garimpo_lote_usa_sqlite():
        _garimpo_lote_sqlite_inserir(merged)
        st.session_state.pop(SESSION_KEY_FONTES_XML_DISK_PATHS, None)
        return
    if len(merged) >= _GARIMPO_LOTE_SQLITE_MIN or _garimpo_lote_sqlite_forcado_env():
        if not _garimpo_lote_sqlite_desativado_env():
            st.session_state[SESSION_KEY_GARIMPO_LOTE_USE_SQLITE] = True
            _garimpo_lote_sqlite_inserir(merged)
            st.session_state.pop(SESSION_KEY_FONTES_XML_DISK_PATHS, None)
            return
    st.session_state[SESSION_KEY_FONTES_XML_DISK_PATHS] = merged


SESSION_KEY_RELATORIO_SQLITE_PATH = "_garimpo_relatorio_sqlite_path"
SESSION_KEY_RELATORIO_PARQUET_PATH = "_garimpo_relatorio_parquet_path"
SESSION_KEY_RELATORIO_USE_SQLITE = "_garimpo_relatorio_use_sqlite"
SESSION_KEY_RELATORIO_COUNT = "_garimpo_relatorio_count_cache"
SESSION_KEY_RELATORIO_COUNT_PROPRIA = "_garimpo_relatorio_count_propria"
SESSION_KEY_RELATORIO_COUNT_TERCEIROS = "_garimpo_relatorio_count_terceiros"
SESSION_KEY_GARIMPO_TERCEIROS_TIPO_COUNTS = "_garimpo_terc_tipo_counts"
SESSION_KEY_GARIMPO_TERCEIROS_VALOR_POR_TIPO = "_garimpo_terc_valor_por_tipo"
SESSION_KEY_GARIMPO_CHAVES_EXCLUIDAS = "_garimpo_chaves_excluidas"
_GARIMPO_RELATORIO_PARQUET_MAX = max(
    500, int(os.environ.get("GARIMPEIRO_RELATORIO_PARQUET_MAX", "8000") or "8000")
)
_GARIMPO_RELATORIO_SQLITE_MIN = max(
    200, int(os.environ.get("GARIMPEIRO_RELATORIO_SQLITE_MIN", "500") or "500")
)


def _relatorio_json_default(o):
    if isinstance(o, (bytes, bytearray, memoryview)):
        return ""
    if isinstance(o, tuple):
        return list(o)
    if isinstance(o, set):
        return list(o)
    if isinstance(o, (datetime, date)):
        return o.isoformat()
    return str(o)


def _relatorio_sanitizar_para_gravacao(res: dict) -> dict:
    """Remove XML em bytes e outros campos que não devem ir para SQLite/JSON do relatório."""
    if not isinstance(res, dict):
        return {}
    out: dict = {}
    for k, v in res.items():
        if str(k) in ("Conteúdo", "Conteudo", "conteudo", "Conteudo_bytes"):
            continue
        if isinstance(v, (bytes, bytearray, memoryview)):
            continue
        if isinstance(v, dict):
            out[k] = _relatorio_sanitizar_para_gravacao(v)
        elif isinstance(v, (list, tuple)):
            out[k] = [
                _relatorio_sanitizar_para_gravacao(x)
                if isinstance(x, dict)
                else ("" if isinstance(x, (bytes, bytearray, memoryview)) else x)
                for x in v
            ]
        else:
            out[k] = v
    return out


def _relatorio_serializar(res: dict) -> str:
    limpo = _relatorio_sanitizar_para_gravacao(res if isinstance(res, dict) else {})
    return json.dumps(limpo, ensure_ascii=False, default=_relatorio_json_default)


def _relatorio_deserializar(payload: str) -> dict:
    return json.loads(payload)


def _relatorio_sqlite_forcado_env() -> bool:
    v = (os.environ.get("GARIMPEIRO_RELATORIO_SQLITE") or "").strip().lower()
    return v in ("1", "true", "yes", "on")


def _relatorio_sqlite_desativado_env() -> bool:
    v = (os.environ.get("GARIMPEIRO_RELATORIO_SQLITE") or "").strip().lower()
    return v in ("0", "false", "no", "off")


def _relatorio_usa_sqlite() -> bool:
    if _relatorio_sqlite_desativado_env():
        return False
    if _relatorio_sqlite_forcado_env():
        return True
    return bool(st.session_state.get(SESSION_KEY_RELATORIO_USE_SQLITE))


def _relatorio_sqlite_caminho_db() -> str:
    p = st.session_state.get(SESSION_KEY_RELATORIO_SQLITE_PATH)
    if p:
        return str(p)
    idx_dir = os.path.join(_garimpeiro_resolver_pasta_dados(), "relatorio_index")
    os.makedirs(idx_dir, exist_ok=True)
    fd, path = tempfile.mkstemp(prefix="relatorio_", suffix=".sqlite", dir=idx_dir)
    os.close(fd)
    st.session_state[SESSION_KEY_RELATORIO_SQLITE_PATH] = path
    return path


def _relatorio_sqlite_conn() -> sqlite3.Connection:
    conn = sqlite3.connect(_relatorio_sqlite_caminho_db(), check_same_thread=False)
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute(
        "CREATE TABLE IF NOT EXISTS relatorio (chave TEXT PRIMARY KEY, payload TEXT NOT NULL)"
    )
    conn.execute("CREATE INDEX IF NOT EXISTS ix_relatorio_chave ON relatorio (chave)")
    return conn


def _relatorio_sqlite_count() -> int:
    conn = _relatorio_sqlite_conn()
    try:
        row = conn.execute("SELECT COUNT(*) FROM relatorio").fetchone()
        return int(row[0]) if row else 0
    finally:
        conn.close()


def _relatorio_sqlite_tem_chave(chave: str) -> bool:
    conn = _relatorio_sqlite_conn()
    try:
        row = conn.execute(
            "SELECT 1 FROM relatorio WHERE chave = ? LIMIT 1", (chave,)
        ).fetchone()
        return row is not None
    finally:
        conn.close()


def _relatorio_sqlite_substituir(rel_list: list) -> None:
    conn = _relatorio_sqlite_conn()
    gravados = 0
    try:
        conn.execute("DELETE FROM relatorio")
        if rel_list:
            rows = []
            for i, r in enumerate(rel_list):
                if not isinstance(r, dict):
                    continue
                try:
                    ch = str(r.get("Chave") or f"_sem_chave_{i}")
                    rows.append((ch, _relatorio_serializar(r)))
                    gravados += 1
                except Exception:
                    continue
            if rows:
                conn.executemany(
                    "INSERT OR REPLACE INTO relatorio (chave, payload) VALUES (?, ?)",
                    rows,
                )
        conn.commit()
    finally:
        conn.close()
    st.session_state[SESSION_KEY_RELATORIO_COUNT] = gravados if rel_list else 0


def _relatorio_sqlite_inserir_um(res: dict) -> None:
    if not isinstance(res, dict):
        return
    try:
        payload = _relatorio_serializar(res)
    except Exception:
        return
    ch = str(res.get("Chave") or hashlib.sha256(payload.encode("utf-8")).hexdigest())
    conn = _relatorio_sqlite_conn()
    try:
        conn.execute(
            "INSERT OR REPLACE INTO relatorio (chave, payload) VALUES (?, ?)",
            (ch, payload),
        )
        conn.commit()
    except Exception:
        pass
    finally:
        conn.close()
    st.session_state[SESSION_KEY_RELATORIO_COUNT] = _relatorio_sqlite_count()


def _relatorio_sqlite_remover_chaves(chaves: set) -> None:
    if not chaves:
        return
    conn = _relatorio_sqlite_conn()
    try:
        conn.executemany(
            "DELETE FROM relatorio WHERE chave = ?",
            [(c,) for c in chaves],
        )
        conn.commit()
    finally:
        conn.close()
    st.session_state[SESSION_KEY_RELATORIO_COUNT] = _relatorio_sqlite_count()


def _relatorio_sqlite_contar_payload_contem(substr: str) -> int:
    """COUNT rápido no SQLite sem deserializar JSON (substr em Pasta no payload)."""
    if not substr:
        return 0
    conn = _relatorio_sqlite_conn()
    try:
        row = conn.execute(
            "SELECT COUNT(*) FROM relatorio WHERE payload LIKE ?",
            (f"%{substr}%",),
        ).fetchone()
        return int(row[0]) if row else 0
    finally:
        conn.close()


def _relatorio_atualizar_contagens_pasta(rel_list: list | None = None) -> None:
    """Guarda totais própria/terceiros na sessão (evita reler 80k+ linhas em cada rerun)."""
    terc_tipo = None
    terc_valor = None
    if rel_list is not None:
        n_pr = sum(1 for r in rel_list if "EMITIDOS_CLIENTE" in (r.get("Pasta") or ""))
        n_te = sum(1 for r in rel_list if "RECEBIDOS_TERCEIROS" in (r.get("Pasta") or ""))
        terc_tipo, terc_valor = _valor_contabil_terceiros_de_relatorio(rel_list)
    elif _relatorio_usa_sqlite():
        n_pr = _relatorio_sqlite_contar_payload_contem("EMITIDOS_CLIENTE")
        n_te = _relatorio_sqlite_contar_payload_contem("RECEBIDOS_TERCEIROS")
    else:
        lst = list(st.session_state.get("relatorio") or [])
        n_pr = sum(1 for r in lst if "EMITIDOS_CLIENTE" in (r.get("Pasta") or ""))
        n_te = sum(1 for r in lst if "RECEBIDOS_TERCEIROS" in (r.get("Pasta") or ""))
        terc_tipo, terc_valor = _valor_contabil_terceiros_de_relatorio(lst)
    st.session_state[SESSION_KEY_RELATORIO_COUNT_PROPRIA] = n_pr
    st.session_state[SESSION_KEY_RELATORIO_COUNT_TERCEIROS] = n_te
    if terc_tipo is not None:
        st.session_state[SESSION_KEY_GARIMPO_TERCEIROS_TIPO_COUNTS] = dict(terc_tipo)
    if terc_valor is not None:
        st.session_state[SESSION_KEY_GARIMPO_TERCEIROS_VALOR_POR_TIPO] = terc_valor


def _relatorio_sqlite_todos() -> list:
    conn = _relatorio_sqlite_conn()
    out: list = []
    try:
        cur = conn.execute("SELECT payload FROM relatorio ORDER BY chave")
        while True:
            batch = cur.fetchmany(2500)
            if not batch:
                break
            for (payload,) in batch:
                out.append(_relatorio_deserializar(payload))
    finally:
        conn.close()
    return out


def _relatorio_sqlite_limpar() -> None:
    path = st.session_state.pop(SESSION_KEY_RELATORIO_SQLITE_PATH, None)
    st.session_state.pop(SESSION_KEY_RELATORIO_USE_SQLITE, None)
    st.session_state.pop(SESSION_KEY_RELATORIO_COUNT, None)
    pq = st.session_state.pop(SESSION_KEY_RELATORIO_PARQUET_PATH, None)
    if pq:
        try:
            if os.path.isfile(pq):
                os.remove(pq)
        except OSError:
            pass
    if path:
        for suffix in ("", "-wal", "-shm"):
            p = path + suffix if suffix else path
            try:
                if os.path.isfile(p):
                    os.remove(p)
            except OSError:
                pass


def _relatorio_parquet_ativo() -> bool:
    v = (os.environ.get("GARIMPEIRO_RELATORIO_PARQUET") or "1").strip().lower()
    return v not in ("0", "false", "no", "off")


def _relatorio_gravar_parquet(rel_list: list) -> None:
    if not rel_list or not _relatorio_parquet_ativo():
        return
    if len(rel_list) > _GARIMPO_RELATORIO_PARQUET_MAX:
        return
    try:
        cache_dir = os.path.join(_garimpeiro_resolver_pasta_dados(), "relatorio_cache")
        os.makedirs(cache_dir, exist_ok=True)
        path = os.path.join(cache_dir, "relatorio_atual.parquet")
        rows = []
        for r in rel_list:
            rr = dict(r)
            rng = rr.get("Range")
            if isinstance(rng, (tuple, list)) and len(rng) >= 2:
                rr["Range_min"], rr["Range_max"] = rng[0], rng[1]
                rr.pop("Range", None)
            rows.append(rr)
        pd.DataFrame(rows).to_parquet(path, index=False, engine="pyarrow")
        st.session_state[SESSION_KEY_RELATORIO_PARQUET_PATH] = path
    except Exception:
        try:
            path = os.path.join(
                _garimpeiro_resolver_pasta_dados(), "relatorio_cache", "relatorio_atual.parquet"
            )
            rows = []
            for r in rel_list:
                rr = dict(r)
                rng = rr.get("Range")
                if isinstance(rng, (tuple, list)) and len(rng) >= 2:
                    rr["Range_min"], rr["Range_max"] = rng[0], rng[1]
                    rr.pop("Range", None)
                rows.append(rr)
            pd.DataFrame(rows).to_parquet(path, index=False)
            st.session_state[SESSION_KEY_RELATORIO_PARQUET_PATH] = path
        except Exception:
            pass


def _relatorio_promover_para_sqlite(rel_list: list | None = None) -> None:
    lst = rel_list if rel_list is not None else list(st.session_state.get("relatorio") or [])
    if not lst:
        return
    st.session_state[SESSION_KEY_RELATORIO_USE_SQLITE] = True
    _relatorio_sqlite_substituir(lst)
    st.session_state["relatorio"] = []
    _relatorio_gravar_parquet(lst)


def _relatorio_limpar() -> None:
    _relatorio_sqlite_limpar()
    st.session_state["relatorio"] = []
    st.session_state.pop(SESSION_KEY_GARIMPO_CHAVES_EXCLUIDAS, None)
    st.session_state.pop("_garimpo_auto_sync_prop_v1", None)
    st.session_state.pop(SESSION_KEY_RELATORIO_COUNT_PROPRIA, None)
    st.session_state.pop(SESSION_KEY_RELATORIO_COUNT_TERCEIROS, None)
    st.session_state.pop(SESSION_KEY_GARIMPO_TERCEIROS_TIPO_COUNTS, None)
    st.session_state.pop(SESSION_KEY_GARIMPO_TERCEIROS_VALOR_POR_TIPO, None)


def _arquivo_fiscal_desativado_env() -> bool:
    v = (os.environ.get("GARIMPEIRO_ARQUIVO_FISCAL") or "").strip().lower()
    return v in ("0", "false", "no", "off")


def _garimpeiro_pasta_instalacao() -> Path | None:
    """Pasta onde o programa foi instalado (Setup), se conhecida."""
    for key in ("GARIMPEIRO_INSTALL_ROOT", "GARIMPEIRO_DATA_ROOT"):
        s = (os.environ.get(key) or "").strip().strip('"').strip("'")
        if not s:
            continue
        try:
            return Path(s).expanduser()
        except (OSError, ValueError):
            return Path(s)
    return None


def _arquivo_fiscal_raiz() -> Path:
    try:
        from core.pastas_layout import pasta_arquivo
    except ImportError:
        pasta_arquivo = None  # type: ignore[assignment]

    def _dir_ok(p: Path) -> bool:
        try:
            return p.is_dir()
        except OSError:
            return False

    env_arq = (os.environ.get("GARIMPEIRO_ARQUIVO_FISCAL_ROOT") or "").strip().strip('"').strip("'")
    if env_arq:
        p = Path(env_arq).expanduser()
        if _dir_ok(p):
            return p

    s = str(st.session_state.get(SESSION_KEY_ARQUIVO_FISCAL_ROOT) or "").strip().strip('"').strip("'")
    if s:
        p = Path(s).expanduser()
        if _dir_ok(p):
            return p

    try:
        from core.exportacoes import pasta_dados_garimpeiro

        partilha = pasta_dados_garimpeiro()
        arq_p = pasta_arquivo(partilha, criar=False) if pasta_arquivo else partilha / "Arquivo"
        if _dir_ok(arq_p):
            if (arq_p / "_catalogo_empresas.json").is_file():
                return arq_p
            try:
                for c in arq_p.iterdir():
                    if c.is_dir() and (c / "arquivo.sqlite").is_file():
                        return arq_p
            except OSError:
                pass
    except Exception:
        pass

    inst = _garimpeiro_pasta_instalacao()
    if inst is not None:
        if pasta_arquivo is not None:
            return pasta_arquivo(inst, criar=True)
        raiz = inst / "Arquivo"
        try:
            raiz.mkdir(parents=True, exist_ok=True)
        except OSError:
            pass
        return raiz
    dados = Path(_garimpeiro_resolver_pasta_dados())
    if pasta_arquivo is not None:
        return pasta_arquivo(dados, criar=True)
    raiz = dados / "Arquivo"
    try:
        raiz.mkdir(parents=True, exist_ok=True)
    except OSError:
        pass
    return raiz


def _arquivo_fiscal_captura_ativa() -> bool:
    if _arquivo_fiscal_desativado_env():
        return False
    if _streamlit_likely_community_cloud():
        return False
    if _garimpo_modo_simples():
        return False
    # Streamlit (legado): só grava no arquivo se o utilizador ativar na aba «Documentos já lidos».
    # Desktop (headless): define True/False antes do garimpo conforme o checkbox «Capturar».
    return bool(st.session_state.get(SESSION_KEY_ARQUIVO_FISCAL_CAPTURA, False))


def _arquivo_fiscal_usuario_sessao() -> str:
    return str(st.session_state.get(SESSION_KEY_ARQUIVO_FISCAL_USUARIO) or "").strip()


def _arquivo_fiscal_filtro_so_meus() -> bool:
    """Auxiliar logada: só linhas com o seu nome em usuario."""
    return bool(st.session_state.get(SESSION_KEY_ARQUIVO_FISCAL_FILTRO_PROPRIOS)) and bool(
        _arquivo_fiscal_usuario_sessao()
    )


def _arquivo_fiscal_sql_filtro_usuario(params: list) -> str:
    if not _arquivo_fiscal_filtro_so_meus():
        return ""
    params.append(_arquivo_fiscal_usuario_sessao())
    return " AND trim(COALESCE(usuario, '')) = ?"


def _arquivo_fiscal_definir_usuario_sessao(
    nome: str, *, filtro_proprios: bool = False
) -> None:
    """Desktop: define utilizador da sessão (filtro opcional «só os meus»)."""
    st.session_state[SESSION_KEY_ARQUIVO_FISCAL_USUARIO] = str(nome or "").strip()
    st.session_state[SESSION_KEY_ARQUIVO_FISCAL_FILTRO_PROPRIOS] = bool(filtro_proprios)


def _arquivo_fiscal_cnpj_limpo(cnpj) -> str:
    return "".join(c for c in str(cnpj or "") if c.isdigit())[:14]


_ARQUIVO_FISCAL_CATALOGO_JSON = "_catalogo_empresas.json"
_ARQUIVO_FISCAL_CATALOGO_LOG_DIR = "_log_catalogo_empresas"
# Cadastro SPED (bloco 0000) — Sepultador / importação Domínio por empresa
_CADASTRO_SPED_CATALOGO_KEYS = ("uf", "ie", "cod_mun", "im", "razao_social", "ind_perfil")


def _arquivo_fiscal_unificar_nome_cadastro(entrada: dict) -> dict:
    """Razão social do SPED e nome da planilha de empresas são o mesmo cadastro."""
    nom = str(entrada.get("nome") or "").strip()
    razao = str(entrada.get("razao_social") or "").strip()
    unificado = razao or nom
    if unificado:
        entrada["nome"] = unificado
        entrada["razao_social"] = unificado
    return entrada


def _arquivo_fiscal_catalogo_campos_sped_de_dict(v: dict | None) -> dict:
    if not isinstance(v, dict):
        return {}
    out: dict[str, str] = {}
    for k in _CADASTRO_SPED_CATALOGO_KEYS:
        s = str(v.get(k) or "").strip()
        if k == "uf":
            s = s.upper()[:2]
        elif k == "cod_mun":
            s = "".join(c for c in s if c.isdigit())[:7]
        elif k == "ie":
            s = s.strip()
        elif k == "ind_perfil":
            s = s.upper()[:1]
            s = s if s in ("A", "B", "C") else ""
        if s:
            out[k] = s
    return out


def _arquivo_fiscal_catalogo_mesclar_campos_sped(
    entrada: dict, fonte: dict | None = None
) -> dict:
    """Preserva cadastro SPED ao editar só código/nome."""
    extra = _arquivo_fiscal_catalogo_campos_sped_de_dict(fonte)
    if extra:
        entrada.update(extra)
    return entrada
_ARQUIVO_FISCAL_INATIVAS_DIR = "_inativas"


def _arquivo_fiscal_catalogo_path() -> Path:
    return _arquivo_fiscal_raiz() / _ARQUIVO_FISCAL_CATALOGO_JSON


def _arquivo_fiscal_catalogo_log_dir() -> Path:
    return _arquivo_fiscal_raiz() / _ARQUIVO_FISCAL_CATALOGO_LOG_DIR


def _arquivo_fiscal_inativas_raiz() -> Path:
    """Pastas de empresas inativadas (fora do uso diário)."""
    return _arquivo_fiscal_raiz() / _ARQUIVO_FISCAL_INATIVAS_DIR


def _arquivo_fiscal_empresa_esta_ativa(info: dict | None) -> bool:
    """True se ativa (omissão = ativa, para catálogos antigos)."""
    if not info:
        return True
    v = info.get("ativa", True)
    if v is False or v == 0:
        return False
    if isinstance(v, str) and v.strip().lower() in (
        "0",
        "false",
        "nao",
        "não",
        "inativa",
        "inativo",
        "no",
    ):
        return False
    return True


def _arquivo_fiscal_carregar_catalogo() -> dict[str, dict]:
    path = _arquivo_fiscal_catalogo_path()
    if not path.is_file():
        return {}
    try:
        import json

        raw = json.loads(path.read_text(encoding="utf-8"))
        if not isinstance(raw, dict):
            return {}
        out: dict[str, dict] = {}
        for k, v in raw.items():
            cx = _arquivo_fiscal_cnpj_limpo(k)
            if len(cx) != 14 or not isinstance(v, dict):
                continue
            entrada = {
                "codigo": str(v.get("codigo") or "").strip(),
                "nome": str(v.get("nome") or "").strip(),
                "ativa": _arquivo_fiscal_empresa_esta_ativa(v),
            }
            _arquivo_fiscal_catalogo_mesclar_campos_sped(entrada, v)
            _arquivo_fiscal_unificar_nome_cadastro(entrada)
            inat_em = str(v.get("inativada_em") or "").strip()
            if inat_em and not entrada["ativa"]:
                entrada["inativada_em"] = inat_em
            out[cx] = entrada
        return out
    except (OSError, ValueError, TypeError):
        return {}


def _arquivo_fiscal_guardar_catalogo(catalogo: dict[str, dict]) -> None:
    import json
    from datetime import datetime

    path = _arquivo_fiscal_catalogo_path()
    path.parent.mkdir(parents=True, exist_ok=True)
    limpo: dict[str, dict] = {}
    agora = datetime.now().isoformat(timespec="seconds")
    for k, v in (catalogo or {}).items():
        cx = _arquivo_fiscal_cnpj_limpo(k)
        if len(cx) != 14:
            continue
        cod = str((v or {}).get("codigo") or "").strip()
        nom = str((v or {}).get("nome") or "").strip()
        if not cod and not nom:
            continue
        ativa = _arquivo_fiscal_empresa_esta_ativa(v)
        entrada = {
            "codigo": cod,
            "nome": nom,
            "ativa": ativa,
            "atualizado_em": agora,
        }
        _arquivo_fiscal_catalogo_mesclar_campos_sped(entrada, v)
        _arquivo_fiscal_unificar_nome_cadastro(entrada)
        inat_em = str((v or {}).get("inativada_em") or "").strip()
        if inat_em and not ativa:
            entrada["inativada_em"] = inat_em
        limpo[cx] = entrada
    path.write_text(
        json.dumps(limpo, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )


def _arquivo_fiscal_registrar_log_catalogo(
    *,
    motivo: str = "atualizacao",
    origem: str | None = None,
    novas: int = 0,
    atualizadas: int = 0,
    ignoradas: int = 0,
    total: int | None = None,
) -> str | None:
    """
    Guarda snapshot do catálogo atual (JSON) + linha no histórico.
    Pasta: ArquivoFiscal/_log_catalogo_empresas/
    Devolve o caminho do snapshot ou None.
    """
    import json
    from datetime import datetime

    cat = _arquivo_fiscal_carregar_catalogo()
    if total is None:
        total = len(cat)
    pasta = _arquivo_fiscal_catalogo_log_dir()
    try:
        pasta.mkdir(parents=True, exist_ok=True)
    except OSError:
        return None
    agora = datetime.now()
    stamp = agora.strftime("%Y%m%d_%H%M%S")
    snap = pasta / f"catalogo_{stamp}.json"
    linhas = []
    for cx, info in sorted(
        cat.items(),
        key=lambda kv: (
            0 if str((kv[1] or {}).get("codigo") or "").isdigit() else 1,
            int((kv[1] or {}).get("codigo") or 0)
            if str((kv[1] or {}).get("codigo") or "").isdigit()
            else 999999,
            str((kv[1] or {}).get("nome") or "").lower(),
            kv[0],
        ),
    ):
        linhas.append(
            {
                "codigo": str((info or {}).get("codigo") or "").strip(),
                "nome": str((info or {}).get("nome") or "").strip(),
                "cnpj": cx,
            }
        )
    payload = {
        "gerado_em": agora.isoformat(timespec="seconds"),
        "motivo": str(motivo or "atualizacao"),
        "origem": str(origem or ""),
        "novas": int(novas or 0),
        "atualizadas": int(atualizadas or 0),
        "ignoradas": int(ignoradas or 0),
        "total": int(total or 0),
        "empresas": linhas,
    }
    try:
        snap.write_text(
            json.dumps(payload, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
    except OSError:
        return None
    hist = pasta / "historico.txt"
    linha = (
        f"{agora.strftime('%d/%m/%Y %H:%M:%S')}\t{motivo}\t"
        f"total={total}\tnovas={novas}\tatualizadas={atualizadas}\t"
        f"ignoradas={ignoradas}\torigem={origem or '—'}\t"
        f"snapshot={snap.name}\n"
    )
    try:
        with hist.open("a", encoding="utf-8") as f:
            f.write(linha)
    except OSError:
        pass
    return str(snap)


def _arquivo_fiscal_cnpj_de_nome_pasta(nome: str) -> str | None:
    try:
        from core.exportacoes import cnpj_de_nome_pasta

        cx = cnpj_de_nome_pasta(nome)
        return cx or None
    except ImportError:
        s = str(nome or "").strip()
        if len(s) == 14 and s.isdigit():
            return s
        m = re.search(r"(\d{14})$", s)
        return m.group(1) if m else None


def _arquivo_fiscal_alias_de_nome_pasta(nome: str, cnpj: str) -> tuple[str, str]:
    """Extrai código e nome legível do prefixo da pasta (ex.: 578_AFFONSO_…_CNPJ)."""
    prefix = str(nome or "").strip()
    if prefix.endswith(cnpj):
        prefix = prefix[: -len(cnpj)].rstrip("_- ")
    if not prefix:
        return "", ""
    parts = [p for p in prefix.split("_") if p]
    if not parts:
        return "", prefix.replace("_", " ").strip()
    codigo = ""
    nome_parts = parts
    if parts[0].isdigit():
        codigo = parts[0]
        nome_parts = parts[1:]
    nome = " ".join(nome_parts).replace("_", " ").strip()
    if not nome:
        nome = prefix.replace("_", " ").strip()
    return codigo, nome


def _arquivo_fiscal_pasta_tem_dados(pasta: Path) -> bool:
    if not pasta.is_dir():
        return False
    return (pasta / "arquivo.sqlite").is_file() or (
        pasta / _ARQUIVO_FISCAL_SUBPASTA_XML
    ).is_dir()


def _arquivo_fiscal_sincronizar_catalogo_disco() -> dict[str, dict]:
    """Atualiza catálogo local a partir das pastas existentes em ArquivoFiscal/."""
    cat = _arquivo_fiscal_carregar_catalogo()
    for raiz in _arquivo_fiscal_raizes_candidatas():
        if not raiz.is_dir():
            continue
        try:
            itens = list(raiz.iterdir())
        except OSError:
            continue
        for item in itens:
            if not item.is_dir():
                continue
            if item.name.startswith("_"):
                continue
            cx = _arquivo_fiscal_cnpj_de_nome_pasta(item.name)
            if len(cx or "") != 14 or not _arquivo_fiscal_pasta_tem_dados(item):
                continue
            cod_p, nom_p = _arquivo_fiscal_alias_de_nome_pasta(item.name, cx)
            cur = cat.get(cx, {})
            novo = {
                "codigo": str(cur.get("codigo") or cod_p or "").strip(),
                "nome": str(cur.get("nome") or nom_p or "").strip(),
                "ativa": _arquivo_fiscal_empresa_esta_ativa(cur)
                if cx in cat
                else True,
            }
            _arquivo_fiscal_catalogo_mesclar_campos_sped(novo, cur)
            if not novo["ativa"]:
                inat_em = str(cur.get("inativada_em") or "").strip()
                if inat_em:
                    novo["inativada_em"] = inat_em
            if novo["codigo"] or novo["nome"] or cx not in cat:
                cat[cx] = novo
    _arquivo_fiscal_guardar_catalogo(cat)
    return cat


def _arquivo_fiscal_registrar_empresa(
    cnpj: str,
    *,
    codigo: str = "",
    nome: str = "",
    uf: str = "",
    ie: str = "",
    cod_mun: str = "",
    im: str = "",
    razao_social: str = "",
) -> None:
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return
    cat = _arquivo_fiscal_carregar_catalogo()
    cur = cat.get(cx, {})
    cod = str(codigo or cur.get("codigo") or "").strip()
    nom = str(
        razao_social or nome or cur.get("razao_social") or cur.get("nome") or ""
    ).strip()
    cat[cx] = {
        "codigo": cod,
        "nome": nom,
        "ativa": True,
    }
    _arquivo_fiscal_catalogo_mesclar_campos_sped(
        cat[cx],
        {
            "uf": uf,
            "ie": ie,
            "cod_mun": cod_mun,
            "im": im,
            "razao_social": razao_social or nom,
        },
    )
    _arquivo_fiscal_catalogo_mesclar_campos_sped(cat[cx], cur)
    _arquivo_fiscal_unificar_nome_cadastro(cat[cx])
    _arquivo_fiscal_guardar_catalogo(cat)
    if cod:
        slug = _v2_sanitize_nome_export(f"{cod}_{nom}" if nom else cod, max_len=48)
        if slug:
            st.session_state["mariana_zip_basename"] = slug


def _arquivo_fiscal_atualizar_cadastro_sped(
    cnpj: str,
    *,
    uf: str = "",
    ie: str = "",
    cod_mun: str = "",
    im: str = "",
    razao_social: str = "",
    ind_perfil: str = "",
) -> dict:
    """Grava UF, IE, município IBGE, IM e razão social SPED no catálogo da empresa."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return {"ok": False, "erro": "CNPJ inválido."}
    cat = _arquivo_fiscal_carregar_catalogo()
    cur = cat.get(cx)
    if not isinstance(cur, dict):
        return {
            "ok": False,
            "erro": "Empresa não está no catálogo — crie-a antes (código/nome).",
        }
    patch = _arquivo_fiscal_catalogo_campos_sped_de_dict(
        {
            "uf": uf,
            "ie": ie,
            "cod_mun": cod_mun,
            "im": im,
            "razao_social": razao_social,
            "ind_perfil": ind_perfil,
        }
    )
    if not patch:
        return {"ok": False, "erro": "Nenhum campo SPED informado."}
    cur.update(patch)
    _arquivo_fiscal_unificar_nome_cadastro(cur)
    cat[cx] = cur
    _arquivo_fiscal_guardar_catalogo(cat)
    return {"ok": True, "campos": patch}


def _arquivo_fiscal_caminho_sped_vigente_competencia(
    cnpj: str, ano: int, mes: int
) -> Path | None:
    """Ficheiro .txt do SPED ativo no Garimpeiro para MM/AAAA."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return None
    import sped_cruzamento as sc

    comp = f"{int(mes):02d}/{int(ano):04d}"
    ind_path = _sped_indice_path(cx)
    if not ind_path.is_file():
        return None
    ind = sc.indice_sped_carregar(ind_path)
    ativo = None
    for h in ind.historico:
        if not h.get("ativo"):
            continue
        hc = str(h.get("competencia") or "").strip()
        if hc.replace(" ", "") == comp.replace(" ", ""):
            ativo = h
            break
        parts = hc.split("/")
        if len(parts) == 2:
            try:
                if f"{int(parts[0]):02d}/{int(parts[1])}" == comp:
                    ativo = h
                    break
            except ValueError:
                pass
    if not ativo:
        return None
    pasta = _arquivo_fiscal_pasta_empresa(cx)
    rel = str(ativo.get("arquivo_guardado") or "").strip()
    if rel:
        p = (pasta / rel.replace("\\", "/")).resolve()
        if p.is_file():
            return p
    hist = pasta / "SPED" / "historico"
    if not hist.is_dir():
        return None
    imp = str(ativo.get("importado_em") or "")
    nome = Path(str(ativo.get("nome") or "sped.txt")).name
    if imp:
        stamp = re.sub(r"[^0-9T\-]", "", imp)[:19]
        if stamp:
            for f in sorted(hist.glob(f"{stamp}_*"), key=lambda x: x.name):
                if f.is_file():
                    return f.resolve()
    safe = re.sub(r'[<>:"/\\|?*]', "_", nome)[:180] or "sped.txt"
    for f in sorted(hist.glob("*"), key=lambda p: p.stat().st_mtime, reverse=True):
        if f.is_file() and (f.name.endswith(safe) or f.name.endswith(nome)):
            return f.resolve()
    return None


def _arquivo_fiscal_importar_cadastro_sped_de_ficheiro(
    cnpj: str, caminho: str | Path
) -> dict:
    import sped_cruzamento as sc

    p = Path(caminho).expanduser()
    if not p.is_file():
        return {"ok": False, "erro": "Ficheiro SPED não encontrado."}
    cad = sc.parse_cadastro_0000_arquivo(p.read_bytes())
    if cad is None:
        return {"ok": False, "erro": "Registo 0000 não encontrado no TXT."}
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if cad.cnpj and cad.cnpj != cx:
        return {
            "ok": False,
            "erro": (
                f"CNPJ do SPED ({format_cnpj_visual(cad.cnpj)}) "
                f"≠ empresa ({format_cnpj_visual(cx)})."
            ),
        }
    res = _arquivo_fiscal_atualizar_cadastro_sped(
        cx,
        uf=cad.uf,
        ie=cad.ie,
        cod_mun=cad.cod_mun,
        im=cad.im,
        razao_social=cad.nome,
        ind_perfil=getattr(cad, "ind_perfil", "") or "",
    )
    if not res.get("ok"):
        return res
    return {
        "ok": True,
        "campos": {
            "razao_social": cad.nome,
            "uf": cad.uf,
            "ie": cad.ie,
            "cod_mun": cad.cod_mun,
            "im": cad.im,
            "ind_perfil": getattr(cad, "ind_perfil", "") or "",
        },
    }


def _arquivo_fiscal_importar_cadastro_sped_vigente(
    cnpj: str, ano: int, mes: int
) -> dict:
    p = _arquivo_fiscal_caminho_sped_vigente_competencia(cnpj, int(ano), int(mes))
    if p is None:
        return {
            "ok": False,
            "erro": (
                f"Não há SPED ativo importado para {int(mes):02d}/{int(ano)}. "
                "Importe o SPED Fiscal na aba SPED × Excel antes de preencher."
            ),
        }
    return _arquivo_fiscal_importar_cadastro_sped_de_ficheiro(cnpj, p)


def _arquivo_fiscal_importar_cadastro_sped_primeiro_ativo(cnpj: str) -> dict:
    """Lê o 0000 do SPED ativo mais recente (qualquer competência)."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return {"ok": False, "erro": "CNPJ inválido."}
    import sped_cruzamento as sc

    ind_path = _sped_indice_path(cx)
    if not ind_path.is_file():
        return {"ok": False, "erro": "Nenhum SPED importado para esta empresa."}
    ind = sc.indice_sped_carregar(ind_path)
    pasta = _arquivo_fiscal_pasta_empresa(cx)
    candidatos = [h for h in ind.historico if h.get("ativo")]
    candidatos.sort(
        key=lambda h: str(h.get("importado_em") or ""),
        reverse=True,
    )
    for h in candidatos:
        rel = str(h.get("arquivo_guardado") or "").strip()
        paths: list[Path] = []
        if rel:
            paths.append((pasta / rel.replace("\\", "/")).resolve())
        hist = pasta / "SPED" / "historico"
        nome = Path(str(h.get("nome") or "sped.txt")).name
        if hist.is_dir():
            for f in sorted(hist.glob("*"), key=lambda p: p.stat().st_mtime, reverse=True):
                if f.is_file() and f.name.endswith(nome):
                    paths.append(f.resolve())
                    break
        for p in paths:
            if p.is_file():
                res = _arquivo_fiscal_importar_cadastro_sped_de_ficheiro(cx, p)
                if res.get("ok"):
                    return res
    return {
        "ok": False,
        "erro": "Não foi possível ler o registo 0000 de nenhum SPED ativo.",
    }


def _arquivo_fiscal_invalidar_cache_pasta(cnpj: str) -> None:
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return
    try:
        st.session_state.pop(f"_arquivo_fiscal_dir_resolvido_{cx}", None)
    except Exception:
        pass


def _arquivo_fiscal_atualizar_dados_empresa(
    cnpj: str,
    *,
    codigo: str = "",
    nome: str = "",
    novo_cnpj: str | None = None,
    renomear_pasta: bool = True,
    uf: str | None = None,
    ie: str | None = None,
    cod_mun: str | None = None,
    im: str | None = None,
    razao_social: str | None = None,
) -> dict:
    """
    Atualiza código/nome (e opcionalmente o CNPJ) no catálogo.
    Se o CNPJ mudar: migra a chave do catálogo, renomeia a pasta e atualiza
    cnpj_empresa no SQLite.
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return {"ok": False, "erro": "CNPJ atual inválido."}
    cod = str(codigo or "").strip()
    nom = str(nome or "").strip()
    if not cod and not nom:
        return {"ok": False, "erro": "Informe pelo menos o código ou o nome."}

    cx_novo = cx
    if novo_cnpj is not None and str(novo_cnpj).strip():
        cx_novo = _arquivo_fiscal_cnpj_limpo(novo_cnpj)
        if len(cx_novo) != 14:
            return {"ok": False, "erro": "Novo CNPJ inválido — são necessários 14 dígitos."}

    cat = _arquivo_fiscal_carregar_catalogo()
    cnpj_alterou = cx_novo != cx

    if cnpj_alterou:
        if cx_novo in cat and cx_novo != cx:
            return {
                "ok": False,
                "erro": (
                    f"Já existe empresa com o CNPJ {format_cnpj_visual(cx_novo)} "
                    "no catálogo. Não é possível sobrescrever."
                ),
            }
        # Pasta destino do novo CNPJ já ocupada?
        pasta_conflito = _arquivo_fiscal_resolver_pasta_empresa(cx_novo)
        if pasta_conflito is not None and pasta_conflito.is_dir():
            return {
                "ok": False,
                "erro": (
                    f"Já existe arquivo fiscal para o CNPJ {format_cnpj_visual(cx_novo)}.\n"
                    f"Pasta: {pasta_conflito}"
                ),
            }
        info = cat.pop(cx, {"codigo": cod, "nome": nom, "ativa": True})
        info["codigo"] = cod
        info["nome"] = nom
        info["ativa"] = _arquivo_fiscal_empresa_esta_ativa(info)
        _arquivo_fiscal_catalogo_mesclar_campos_sped(info, info)
        _arquivo_fiscal_unificar_nome_cadastro(info)
        cat[cx_novo] = info
    else:
        cur = cat.get(cx, {})
        entrada = {
            "codigo": cod,
            "nome": nom,
            "ativa": _arquivo_fiscal_empresa_esta_ativa(cur),
        }
        inat_em = str(cur.get("inativada_em") or "").strip()
        if inat_em and not entrada["ativa"]:
            entrada["inativada_em"] = inat_em
        _arquivo_fiscal_catalogo_mesclar_campos_sped(entrada, cur)
        if any(
            x is not None
            for x in (uf, ie, cod_mun, im, razao_social)
        ):
            _arquivo_fiscal_catalogo_mesclar_campos_sped(
                entrada,
                {
                    "uf": uf or "",
                    "ie": ie or "",
                    "cod_mun": cod_mun or "",
                    "im": im or "",
                    "razao_social": razao_social or "",
                },
            )
        if razao_social is not None and str(razao_social).strip():
            entrada["nome"] = str(razao_social).strip()
            entrada["razao_social"] = entrada["nome"]
        else:
            entrada["razao_social"] = nom
            entrada["nome"] = nom
        cat[cx] = entrada

    _arquivo_fiscal_guardar_catalogo(cat)

    pasta_nova = None
    aviso = ""
    existente = _arquivo_fiscal_resolver_pasta_empresa(cx)
    pasta_trabalho: Path | None = existente if existente is not None and existente.is_dir() else None

    if renomear_pasta and cnpj_alterou and pasta_trabalho is not None:
        slug = _v2_sanitize_nome_export(
            f"{cod}_{nom}" if cod and nom else (cod or nom),
            max_len=48,
        )
        destino_nome = f"{slug}_{cx_novo}" if slug else cx_novo
        destino = pasta_trabalho.parent / destino_nome
        if destino.resolve() != pasta_trabalho.resolve():
            if destino.exists():
                pasta_nova = str(pasta_trabalho)
                aviso = "Catálogo atualizado, mas a pasta não foi renomeada (destino já existe)."
            else:
                try:
                    _arquivo_fiscal_invalidar_cache_pasta(cx)
                    _arquivo_fiscal_invalidar_cache_pasta(cx_novo)
                    pasta_trabalho.rename(destino)
                    pasta_trabalho = destino
                    pasta_nova = str(destino)
                    st.session_state[f"_arquivo_fiscal_dir_resolvido_{cx_novo}"] = str(
                        destino
                    )
                except OSError as ex:
                    aviso = f"Catálogo atualizado, mas a pasta não foi renomeada: {ex}"
                    pasta_nova = str(pasta_trabalho)

    # Atualiza CNPJ no SQLite da pasta (quando o número mudou)
    if cnpj_alterou and pasta_trabalho is not None:
        db = pasta_trabalho / "arquivo.sqlite"
        if db.is_file():
            try:
                conn = sqlite3.connect(str(db), timeout=30)
                try:
                    _arquivo_fiscal_ensure_schema(conn, cx)
                    tem = conn.execute(
                        "SELECT 1 FROM sqlite_master WHERE type='table' AND name='xml_arquivo'"
                    ).fetchone()
                    if tem:
                        conn.execute(
                            "UPDATE xml_arquivo SET cnpj_empresa = ? WHERE cnpj_empresa = ?",
                            (cx_novo, cx),
                        )
                        conn.commit()
                finally:
                    conn.close()
            except sqlite3.Error as ex:
                aviso = (
                    (aviso + "\n") if aviso else ""
                ) + f"Falha ao atualizar CNPJ no índice: {ex}"

    if cnpj_alterou:
        _arquivo_fiscal_invalidar_cache_pasta(cx)
        try:
            _arquivo_fiscal_invalidar_runtime_cache(cx)
        except Exception:
            pass
        try:
            _arquivo_fiscal_invalidar_runtime_cache(cx_novo)
        except Exception:
            pass

    if cod:
        slug = _v2_sanitize_nome_export(f"{cod}_{nom}" if nom else cod, max_len=48)
        if slug:
            st.session_state["mariana_zip_basename"] = slug

    snap = _arquivo_fiscal_registrar_log_catalogo(
        motivo="edicao_manual",
        origem=f"{cx}->{cx_novo}" if cnpj_alterou else cx_novo,
        novas=0,
        atualizadas=1,
        ignoradas=0,
        total=len(cat),
    )
    out = {
        "ok": True,
        "cnpj": cx_novo,
        "cnpj_anterior": cx,
        "cnpj_alterou": cnpj_alterou,
        "codigo": cod,
        "nome": nom,
        "rotulo": _arquivo_fiscal_rotulo_empresa(cx_novo, cat),
        "pasta": pasta_nova,
        "log_snapshot": snap,
    }
    if aviso:
        out["aviso"] = aviso
    return out


def _arquivo_fiscal_norm_coluna_catalogo(nome: str) -> str:
    """Normaliza cabeçalho: minúsculas, sem acentos, só a-z0-9 (ex.: CÓD → cod)."""
    import unicodedata

    s = str(nome or "").strip().lower()
    s = unicodedata.normalize("NFKD", s)
    s = "".join(c for c in s if not unicodedata.combining(c))
    return re.sub(r"[^a-z0-9]", "", s)


def _arquivo_fiscal_mapear_colunas_catalogo(colunas: list) -> dict[str, str]:
    """Detecta colunas CNPJ / código / nome em cabeçalhos variados."""
    aliases = {
        "cnpj": {
            "cnpj",
            "cnpjempresa",
            "cnpjdocliente",
            "documento",
            "doc",
            "cgc",
        },
        "codigo": {
            "codigo",
            "cod",
            "cd",  # CÓD após normalização sem acento raro
            "code",
            "id",
            "idempresa",
            "codempresa",
            "codigocliente",
            "codcliente",
        },
        "nome": {
            "nome",
            "empresa",
            "cliente",
            "razao",
            "razaosocial",
            "nomefantasia",
            "fantasia",
            "descricao",
            "nomeempresa",
        },
    }
    mapa: dict[str, str] = {}
    for col in colunas:
        n = _arquivo_fiscal_norm_coluna_catalogo(col)
        if not n or n.startswith("unnamed"):
            continue
        for destino, alts in aliases.items():
            if destino in mapa:
                continue
            if n in alts or any(a in n for a in alts if len(a) >= 4):
                mapa[destino] = col
                break
    for col in colunas:
        n = _arquivo_fiscal_norm_coluna_catalogo(col)
        if n in ("razaosocial", "razao"):
            mapa["nome"] = col
            break
    return mapa


def _arquivo_fiscal_importar_catalogo_ficheiro(caminho: str | Path) -> dict:
    """
    Atualiza o catálogo do escritório a partir de Excel (.xlsx/.xls) ou CSV.
    Faz merge por CNPJ (não apaga empresas que não estão no ficheiro).
    Aceita planilha tipo FISCAL — EMPRESAS (CÓD, RAZÃO SOCIAL, CNPJ).
    """
    import pandas as pd

    path = Path(caminho).expanduser()
    if not path.is_file():
        return {"ok": False, "erro": f"Ficheiro não encontrado: {path}"}

    suf = path.suffix.lower()
    try:
        if suf in (".xlsx", ".xls"):
            xl = pd.ExcelFile(path)
            # Preferir aba EMPRESAS (lista do escritório)
            sheet = None
            for nome in xl.sheet_names:
                if _arquivo_fiscal_norm_coluna_catalogo(nome) == "empresas":
                    sheet = nome
                    break
            if sheet is None:
                sheet = xl.sheet_names[0]
            df = pd.read_excel(path, sheet_name=sheet, dtype=str)
        elif suf in (".csv", ".txt"):
            # Tenta ; (Brasil) e depois ,
            try:
                df = pd.read_csv(path, dtype=str, sep=";", encoding="utf-8-sig")
                if df.shape[1] < 2:
                    df = pd.read_csv(path, dtype=str, sep=",", encoding="utf-8-sig")
            except UnicodeDecodeError:
                df = pd.read_csv(path, dtype=str, sep=";", encoding="latin-1")
                if df.shape[1] < 2:
                    df = pd.read_csv(path, dtype=str, sep=",", encoding="latin-1")
        else:
            return {
                "ok": False,
                "erro": "Formato não suportado. Use Excel (.xlsx) ou CSV.",
            }
    except Exception as ex:
        return {"ok": False, "erro": f"Falha ao ler o ficheiro: {ex}"}

    if df is None or df.empty:
        return {"ok": False, "erro": "Ficheiro vazio."}

    df.columns = [str(c).strip() for c in df.columns]
    mapa = _arquivo_fiscal_mapear_colunas_catalogo(list(df.columns))
    if "cnpj" not in mapa:
        return {
            "ok": False,
            "erro": (
                "Não encontrei a coluna de CNPJ.\n"
                "Use cabeçalhos como: CNPJ, Código, Nome (ou Razão Social)."
            ),
        }

    cat = _arquivo_fiscal_carregar_catalogo()
    novas = 0
    atualizadas = 0
    ignoradas = 0

    for _, row in df.iterrows():
        cx = _arquivo_fiscal_cnpj_limpo(row.get(mapa["cnpj"]))
        if len(cx) != 14:
            ignoradas += 1
            continue
        cod = ""
        nom = ""
        if "codigo" in mapa:
            cod = str(row.get(mapa["codigo"]) or "").strip()
            if cod.endswith(".0") and cod.replace(".", "", 1).isdigit():
                cod = cod[:-2]
        if "nome" in mapa:
            nom = str(row.get(mapa["nome"]) or "").strip()
        if not cod and not nom:
            ignoradas += 1
            continue
        cur = cat.get(cx, {})
        # Mantém valor antigo se a coluna vier vazia nesta linha
        cod_f = cod or str(cur.get("codigo") or "").strip()
        nom_f = nom or str(cur.get("razao_social") or cur.get("nome") or "").strip()
        if cx not in cat:
            novas += 1
        elif (
            str(cur.get("codigo") or "").strip() != cod_f
            or str(cur.get("nome") or cur.get("razao_social") or "").strip() != nom_f
        ):
            atualizadas += 1
        else:
            ignoradas += 1
            continue
        entrada = {
            "codigo": cod_f,
            "nome": nom_f,
            "ativa": True if cx not in cat else _arquivo_fiscal_empresa_esta_ativa(cur),
        }
        _arquivo_fiscal_catalogo_mesclar_campos_sped(entrada, cur)
        entrada["nome"] = nom_f
        entrada["razao_social"] = nom_f
        inat_em = str(cur.get("inativada_em") or "").strip()
        if inat_em and not entrada["ativa"]:
            entrada["inativada_em"] = inat_em
        cat[cx] = entrada

    _arquivo_fiscal_guardar_catalogo(cat)
    snap = _arquivo_fiscal_registrar_log_catalogo(
        motivo="importacao_excel",
        origem=str(path),
        novas=novas,
        atualizadas=atualizadas,
        ignoradas=ignoradas,
        total=len(cat),
    )
    return {
        "ok": True,
        "novas": novas,
        "atualizadas": atualizadas,
        "ignoradas": ignoradas,
        "log_snapshot": snap,
        "total_catalogo": len(cat),
        "ficheiro": str(path),
    }


def _arquivo_fiscal_mover_pasta_entre(
    origem: Path,
    destino_pai: Path,
) -> tuple[Path | None, str]:
    """Move pasta da empresa; devolve (destino, aviso)."""
    import shutil

    if origem is None or not origem.is_dir():
        return None, ""
    try:
        destino_pai.mkdir(parents=True, exist_ok=True)
    except OSError as ex:
        return None, f"Não foi possível criar pasta destino: {ex}"
    dest = destino_pai / origem.name
    if dest.resolve() == origem.resolve():
        return origem, ""
    if dest.exists():
        # Evita colisão: acrescenta sufixo
        n = 2
        while True:
            alt = destino_pai / f"{origem.name}_v{n}"
            if not alt.exists():
                dest = alt
                break
            n += 1
    try:
        shutil.move(str(origem), str(dest))
    except OSError as ex:
        return None, f"Falha ao mover pasta: {ex}"
    return dest, ""


def _arquivo_fiscal_inativar_empresa(cnpj: str) -> dict:
    """
    Marca empresa como inativa e move o ArquivoFiscal para _inativas/.
    Não apaga XML nem SQLite.
    """
    from datetime import datetime

    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return {"ok": False, "erro": "CNPJ inválido."}
    cat = _arquivo_fiscal_carregar_catalogo()
    info = cat.get(cx)
    if not info:
        return {"ok": False, "erro": "Empresa não encontrada no catálogo."}
    if not _arquivo_fiscal_empresa_esta_ativa(info):
        return {"ok": False, "erro": "Esta empresa já está inativa."}

    pasta = _arquivo_fiscal_resolver_pasta_empresa(cx)
    pasta_movida = None
    aviso = ""
    if pasta is not None and pasta.is_dir():
        # Só move se ainda estiver na raiz ativa (não em _inativas)
        try:
            pai_nome = pasta.parent.name.lower()
        except Exception:
            pai_nome = ""
        ja_inativa = pai_nome == _ARQUIVO_FISCAL_INATIVAS_DIR.lower()
        if not ja_inativa:
            _arquivo_fiscal_invalidar_cache_pasta(cx)
            dest, aviso = _arquivo_fiscal_mover_pasta_entre(
                pasta, _arquivo_fiscal_inativas_raiz()
            )
            if dest is not None:
                pasta_movida = str(dest)
                _arquivo_fiscal_invalidar_cache_pasta(cx)
            elif aviso:
                # Continua inativação no catálogo mesmo se a pasta falhar
                pass

    agora = datetime.now().isoformat(timespec="seconds")
    novo = dict(info)
    novo["ativa"] = False
    novo["inativada_em"] = agora
    cat[cx] = novo
    _arquivo_fiscal_guardar_catalogo(cat)
    snap = _arquivo_fiscal_registrar_log_catalogo(
        motivo="inativacao",
        origem=f"cnpj={cx}",
        atualizadas=1,
        total=len(cat),
    )
    return {
        "ok": True,
        "cnpj": cx,
        "rotulo": _arquivo_fiscal_rotulo_empresa(cx, cat),
        "pasta": pasta_movida,
        "aviso": aviso,
        "log_snapshot": snap,
    }


def _arquivo_fiscal_reativar_empresa(cnpj: str) -> dict:
    """Reativa empresa e devolve a pasta de _inativas/ para a raiz do ArquivoFiscal."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return {"ok": False, "erro": "CNPJ inválido."}
    cat = _arquivo_fiscal_carregar_catalogo()
    info = cat.get(cx)
    if not info:
        return {"ok": False, "erro": "Empresa não encontrada no catálogo."}
    if _arquivo_fiscal_empresa_esta_ativa(info):
        return {"ok": False, "erro": "Esta empresa já está ativa."}

    pasta = _arquivo_fiscal_resolver_pasta_empresa(cx)
    pasta_movida = None
    aviso = ""
    if pasta is not None and pasta.is_dir():
        try:
            pai_nome = pasta.parent.name.lower()
        except Exception:
            pai_nome = ""
        if pai_nome == _ARQUIVO_FISCAL_INATIVAS_DIR.lower():
            _arquivo_fiscal_invalidar_cache_pasta(cx)
            dest, aviso = _arquivo_fiscal_mover_pasta_entre(
                pasta, _arquivo_fiscal_raiz()
            )
            if dest is not None:
                pasta_movida = str(dest)
                _arquivo_fiscal_invalidar_cache_pasta(cx)

    novo = dict(info)
    novo["ativa"] = True
    novo.pop("inativada_em", None)
    cat[cx] = novo
    _arquivo_fiscal_guardar_catalogo(cat)
    snap = _arquivo_fiscal_registrar_log_catalogo(
        motivo="reativacao",
        origem=f"cnpj={cx}",
        atualizadas=1,
        total=len(cat),
    )
    return {
        "ok": True,
        "cnpj": cx,
        "rotulo": _arquivo_fiscal_rotulo_empresa(cx, cat),
        "pasta": pasta_movida,
        "aviso": aviso,
        "log_snapshot": snap,
    }


def _arquivo_fiscal_excluir_empresa(cnpj: str) -> dict:
    """Tira a empresa do catálogo. Move a pasta do arquivo para _inativas — não apaga XML."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return {"ok": False, "erro": "CNPJ inválido."}
    cat = _arquivo_fiscal_carregar_catalogo()
    info = cat.get(cx)
    if not info:
        return {"ok": False, "erro": "Empresa não encontrada no catálogo."}
    aviso = ""
    pasta_movida = None
    if _arquivo_fiscal_empresa_esta_ativa(info):
        res = _arquivo_fiscal_inativar_empresa(cx)
        aviso = str(res.get("aviso") or "")
        pasta_movida = res.get("pasta")
        if not res.get("ok"):
            aviso = str(res.get("erro") or aviso)
        cat = _arquivo_fiscal_carregar_catalogo()
    else:
        pasta = _arquivo_fiscal_resolver_pasta_empresa(cx)
        if pasta is not None and pasta.is_dir():
            try:
                pai_nome = pasta.parent.name.lower()
            except Exception:
                pai_nome = ""
            if pai_nome != _ARQUIVO_FISCAL_INATIVAS_DIR.lower():
                dest, aviso_m = _arquivo_fiscal_mover_pasta_entre(
                    pasta, _arquivo_fiscal_inativas_raiz()
                )
                if dest is not None:
                    pasta_movida = str(dest)
                elif aviso_m:
                    aviso = aviso_m
    cat.pop(cx, None)
    _arquivo_fiscal_guardar_catalogo(cat)
    snap = _arquivo_fiscal_registrar_log_catalogo(
        motivo="exclusao",
        origem=f"cnpj={cx}",
        atualizadas=1,
        total=len(cat),
    )
    return {
        "ok": True,
        "cnpj": cx,
        "rotulo": str((info or {}).get("nome") or cx),
        "pasta": pasta_movida,
        "aviso": aviso,
        "log_snapshot": snap,
    }


def _arquivo_fiscal_exportar_catalogo_ficheiro(caminho: str | Path) -> dict:
    """
    Exporta o catálogo atual (só ativas) para Excel (.xlsx) ou CSV.
    Colunas: Código, Nome, CNPJ — mesmo formato aceite na importação.
    """
    import pandas as pd

    path = Path(caminho).expanduser()
    cat = _arquivo_fiscal_carregar_catalogo()
    rows: list[dict[str, str]] = []
    for cx, info in sorted(
        cat.items(),
        key=lambda kv: (
            0 if str((kv[1] or {}).get("codigo") or "").isdigit() else 1,
            int((kv[1] or {}).get("codigo") or 0)
            if str((kv[1] or {}).get("codigo") or "").isdigit()
            else 999999,
            str((kv[1] or {}).get("nome") or "").lower(),
            kv[0],
        ),
    ):
        if not _arquivo_fiscal_empresa_esta_ativa(info):
            continue
        razao = str(
            (info or {}).get("razao_social") or (info or {}).get("nome") or ""
        ).strip()
        rows.append(
            {
                "Código": str((info or {}).get("codigo") or "").strip(),
                "Nome": razao,
                "Razão Social": razao,
                "CNPJ": cx,
            }
        )
    df = pd.DataFrame(rows, columns=["Código", "Nome", "Razão Social", "CNPJ"])
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        suf = path.suffix.lower()
        if suf == ".csv":
            df.to_csv(path, index=False, sep=";", encoding="utf-8-sig")
        else:
            if suf not in (".xlsx", ".xls"):
                path = path.with_suffix(".xlsx")
            df.to_excel(path, index=False, sheet_name="EMPRESAS")
    except Exception as ex:
        return {"ok": False, "erro": f"Falha ao gravar o ficheiro: {ex}"}
    return {
        "ok": True,
        "total": len(rows),
        "ficheiro": str(path),
    }


def _arquivo_fiscal_rotulo_empresa(cnpj: str, catalogo: dict | None = None) -> str:
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    cat = catalogo if catalogo is not None else _arquivo_fiscal_carregar_catalogo()
    info = cat.get(cx, {})
    cod = str(info.get("codigo") or "").strip()
    nom = str(info.get("razao_social") or info.get("nome") or "").strip()
    if cod and nom:
        return f"{cod} — {nom}"
    if cod:
        return cod
    if nom:
        return nom
    return format_cnpj_visual(cx) if len(cx) == 14 else cx


def _arquivo_fiscal_listar_empresas_catalogo(
    *,
    incluir_sem_arquivo: bool = True,
    apenas_ativas: bool | None = True,
) -> list[dict]:
    """
    Lista empresas do catálogo (+ pastas no disco).
    apenas_ativas: True = só ativas; False = só inativas; None = todas.
    """
    cat = _arquivo_fiscal_carregar_catalogo()
    vistos: set[str] = set()
    rows: list[dict] = []

    def _add(cx: str, cod: str = "", nom: str = "") -> None:
        if len(cx) != 14 or cx in vistos:
            return
        info = cat.get(cx, {})
        ativa = _arquivo_fiscal_empresa_esta_ativa(info) if info else True
        if apenas_ativas is True and not ativa:
            return
        if apenas_ativas is False and ativa:
            return
        if incluir_sem_arquivo:
            tem_pasta = True
        else:
            tem_pasta = bool(_arquivo_fiscal_resolver_pasta_empresa(cx))
        if not tem_pasta and not incluir_sem_arquivo:
            return
        vistos.add(cx)
        cod_f = str(cod or info.get("codigo") or "").strip()
        nom_f = str(nom or info.get("razao_social") or info.get("nome") or "").strip()
        rows.append(
            {
                "cnpj": cx,
                "codigo": cod_f,
                "nome": nom_f,
                "rotulo": _arquivo_fiscal_rotulo_empresa(cx, cat),
                "tem_arquivo": tem_pasta,
                "ativa": ativa,
                "inativada_em": str(info.get("inativada_em") or "").strip(),
            }
        )

    # Pastas ativas na raiz (não varre _inativas aqui — entram via catálogo)
    if apenas_ativas is not False:
        for raiz in _arquivo_fiscal_raizes_candidatas():
            if not raiz.is_dir():
                continue
            try:
                itens = list(raiz.iterdir())
            except OSError:
                continue
            for item in itens:
                if not item.is_dir() or item.name.startswith("_"):
                    continue
                cx = _arquivo_fiscal_cnpj_de_nome_pasta(item.name)
                if len(cx or "") != 14 or not _arquivo_fiscal_pasta_tem_dados(item):
                    continue
                if cx in cat and not _arquivo_fiscal_empresa_esta_ativa(cat.get(cx)):
                    continue
                cod_p, nom_p = _arquivo_fiscal_alias_de_nome_pasta(item.name, cx)
                _add(cx, cod_p, nom_p)
    for cx, info in cat.items():
        _add(cx, str(info.get("codigo") or ""), str(info.get("nome") or ""))

    rows.sort(
        key=lambda r: (
            int(r["codigo"]) if str(r.get("codigo") or "").isdigit() else 999999,
            str(r.get("nome") or "").lower(),
            r["cnpj"],
        )
    )
    return rows


def _arquivo_fiscal_listar_empresas_inativas() -> list[dict]:
    """Só empresas marcadas como inativas no catálogo."""
    return _arquivo_fiscal_listar_empresas_catalogo(
        incluir_sem_arquivo=True,
        apenas_ativas=False,
    )


def _arquivo_fiscal_buscar_empresas(texto: str) -> list[dict]:
    """Resolve código, nome (parcial) ou CNPJ (catálogo do escritório + arquivo no disco)."""
    _arquivo_fiscal_sincronizar_catalogo_disco()
    cat = _arquivo_fiscal_carregar_catalogo()
    empresas = _arquivo_fiscal_listar_empresas_catalogo(
        incluir_sem_arquivo=True, apenas_ativas=True
    )
    q = str(texto or "").strip()
    if not q:
        return []
    cx_q = _arquivo_fiscal_cnpj_limpo(q)
    if len(cx_q) == 14:
        info = cat.get(cx_q, {})
        if info and not _arquivo_fiscal_empresa_esta_ativa(info):
            return []
        return [
            {
                "cnpj": cx_q,
                "codigo": str(info.get("codigo") or "").strip(),
                "nome": str(info.get("nome") or "").strip(),
                "rotulo": _arquivo_fiscal_rotulo_empresa(cx_q, cat),
                "tem_arquivo": bool(_arquivo_fiscal_resolver_pasta_empresa(cx_q)),
                "ativa": True,
            }
        ]
    q_low = q.lower()
    q_norm = re.sub(r"\s+", " ", q_low)
    hits: list[dict] = []
    for emp in empresas:
        cx = emp["cnpj"]
        cod = str(emp.get("codigo") or "").strip()
        nom = str(emp.get("nome") or "").strip()
        rot = str(emp.get("rotulo") or "").strip()
        if cod and cod == q:
            hits.append(
                {
                    "cnpj": cx,
                    "codigo": cod,
                    "nome": nom,
                    "rotulo": rot,
                    "tem_arquivo": bool(emp.get("tem_arquivo")),
                }
            )
            continue
        blob = f"{cod} {nom} {rot} {cx}".lower()
        if q_low in blob or q_norm in blob:
            hits.append(
                {
                    "cnpj": cx,
                    "codigo": cod,
                    "nome": nom,
                    "rotulo": rot,
                    "tem_arquivo": bool(emp.get("tem_arquivo")),
                }
            )
    hits.sort(
        key=lambda r: (
            0 if str(r.get("codigo") or "") == q else 1,
            int(r["codigo"]) if str(r.get("codigo") or "").isdigit() else 999999,
            str(r.get("nome") or "").lower(),
        )
    )
    if _arquivo_fiscal_filtro_so_meus():
        u = _arquivo_fiscal_usuario_sessao()
        hits = [h for h in hits if _arquivo_fiscal_empresa_tem_usuario(h["cnpj"], u)]
    return hits


def _arquivo_fiscal_empresa_tem_usuario(cnpj: str, usuario: str) -> bool:
    """True se a auxiliar já indexou algum XML desta empresa."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    u = str(usuario or "").strip()
    if len(cx) != 14 or not u or not _arquivo_fiscal_db_path(cx).is_file():
        return False
    conn = _arquivo_fiscal_conn(cx)
    try:
        row = conn.execute(
            """
            SELECT 1 FROM xml_arquivo
            WHERE cnpj_empresa = ? AND trim(COALESCE(usuario, '')) = ?
            LIMIT 1
            """,
            (cx, u),
        ).fetchone()
        return bool(row)
    finally:
        conn.close()


def _competencia_registo_arquivo(
    chave: str | None, ano, mes, data_emissao: str | None
) -> tuple[int, int] | None:
    """Ano/mês para o calendário — colunas, data_emissao ou chave 44."""
    try:
        a = int(ano) if ano is not None else 0
        m = int(mes) if mes is not None else 0
    except (TypeError, ValueError):
        a, m = 0, 0
    if a > 0 and 1 <= m <= 12:
        return a, m
    de = str(data_emissao or "").strip()
    if len(de) >= 7 and de[4] == "-":
        try:
            a, m = int(de[:4]), int(de[5:7])
            if a > 0 and 1 <= m <= 12:
                return a, m
        except ValueError:
            pass
    digs = "".join(c for c in str(chave or "").split("#", 1)[0] if c.isdigit())
    if len(digs) >= 6:
        ch = digs[-44:] if len(digs) >= 44 else digs[:44]
        try:
            aa = int(ch[2:4])
            mm = int(ch[4:6])
            if 1 <= mm <= 12:
                ano_ch = 2000 + aa if aa < 70 else 1900 + aa
                return ano_ch, mm
        except (TypeError, ValueError):
            pass
    return None


def _arquivo_fiscal_raizes_candidatas() -> list[Path]:
    """Pastas raiz do arquivo fiscal a procurar (só a pasta de instalação, se definida)."""
    raizes: list[Path] = []
    vistos: set[str] = set()

    def _add(raw: str) -> None:
        s = str(raw or "").strip().strip('"').strip("'")
        if not s:
            return
        try:
            p = Path(s).expanduser()
            chave = str(p).replace("/", "\\").lower()
            if chave.startswith("\\\\"):
                chave = chave.replace("\\\\10.10.100.201\\xml\\garimpeiro", "p:\\garimpeiro")
                chave = chave.replace("\\\\10.10.100.201\\xml", "p:")
        except (OSError, ValueError):
            p = Path(s)
            chave = str(p).lower()
        if chave not in vistos:
            vistos.add(chave)
            raizes.append(p)

    _add(os.environ.get("GARIMPEIRO_ARQUIVO_FISCAL_ROOT") or "")
    _add(str(st.session_state.get(SESSION_KEY_ARQUIVO_FISCAL_ROOT) or ""))
    try:
        from core.exportacoes import pasta_dados_garimpeiro
        from core.pastas_layout import pasta_arquivo

        _add(str(pasta_arquivo(pasta_dados_garimpeiro(), criar=False)))
    except Exception:
        pass
    _add(str(_arquivo_fiscal_raiz()))
    inst = _garimpeiro_pasta_instalacao()
    if inst is not None:
        _add(str(inst / "Arquivo"))
        _add(str(inst / "ArquivoFiscal"))
    _add(str(Path(_garimpeiro_resolver_pasta_dados()) / "ArquivoFiscal"))
    _add(str(Path(os.path.dirname(os.path.abspath(__file__))) / "ArquivoFiscal"))
    return raizes


def _arquivo_fiscal_pasta_empresa_nova(cnpj: str) -> Path:
    """Caminho canónico: código_razão_CNPJ (ex.: 578_AFFONSO_…_45785442000390)."""
    c = _arquivo_fiscal_cnpj_limpo(cnpj)
    cat = _arquivo_fiscal_carregar_catalogo()
    info = cat.get(c, {}) if isinstance(cat, dict) else {}
    try:
        from core.exportacoes import nome_pasta_empresa_padrao

        nome = nome_pasta_empresa_padrao(
            c,
            codigo=str(info.get("codigo") or "").strip(),
            nome=str(info.get("nome") or "").strip(),
        )
    except ImportError:
        nome = c or "sem_cnpj"
    if nome == c:
        alias = _v2_sanitize_nome_export(
            st.session_state.get("mariana_zip_basename") or "", max_len=48
        )
        if alias and len(c) == 14 and not alias.endswith(c):
            nome = f"{alias}_{c}"
    return _arquivo_fiscal_raiz() / nome


def _arquivo_fiscal_pontuacao_pasta_empresa(pasta: Path, cnpj: str) -> tuple[int, int, float]:
    """Maior = melhor: (tem sqlite, registos do CNPJ, mtime do banco)."""
    c = _arquivo_fiscal_cnpj_limpo(cnpj)
    db = pasta / "arquivo.sqlite"
    if db.is_file():
        try:
            conn = sqlite3.connect(str(db), timeout=30)
            try:
                tem = conn.execute(
                    "SELECT 1 FROM sqlite_master WHERE type='table' AND name='xml_arquivo'"
                ).fetchone()
                if not tem:
                    return (1, 0, float(db.stat().st_mtime))
                row = conn.execute(
                    "SELECT COUNT(*) FROM xml_arquivo WHERE cnpj_empresa = ?",
                    (c,),
                ).fetchone()
                n = int(row[0] or 0) if row else 0
            finally:
                conn.close()
            return (2, n, float(db.stat().st_mtime))
        except (OSError, sqlite3.Error):
            return (1, 0, 0.0)
    if (pasta / _ARQUIVO_FISCAL_SUBPASTA_XML).is_dir():
        try:
            return (1, 1, float(pasta.stat().st_mtime))
        except OSError:
            pass
    return (0, 0, 0.0)


def _arquivo_fiscal_candidatos_pasta_empresa(cnpj: str) -> list[Path]:
    c = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(c) != 14:
        return []
    candidatos: list[Path] = []
    vistos: set[str] = set()

    def _add(p: Path) -> None:
        chave = str(p).replace("/", "\\").lower()
        if chave.startswith("\\\\"):
            chave = chave.replace("\\\\10.10.100.201\\xml\\garimpeiro", "p:\\garimpeiro")
            chave = chave.replace("\\\\10.10.100.201\\xml", "p:")
        if chave not in vistos:
            vistos.add(chave)
            candidatos.append(p)

    _add(_arquivo_fiscal_pasta_empresa_nova(cnpj))
    for raiz in _arquivo_fiscal_raizes_candidatas():
        if not raiz.is_dir():
            continue
        # Preferir pasta ativa na raiz; também aceitar em _inativas
        for base in (raiz, raiz / _ARQUIVO_FISCAL_INATIVAS_DIR):
            if not base.is_dir():
                continue
            direto = base / c
            if direto.is_dir():
                _add(direto)
            try:
                for item in base.iterdir():
                    if not item.is_dir():
                        continue
                    nome = item.name
                    if nome.startswith("_"):
                        continue
                    if nome == c or nome.endswith(f"_{c}"):
                        _add(item)
                    else:
                        try:
                            from core.exportacoes import cnpj_de_nome_pasta

                            if cnpj_de_nome_pasta(nome) == c:
                                _add(item)
                        except ImportError:
                            pass
            except OSError:
                continue
    return candidatos


def _arquivo_fiscal_resolver_pasta_empresa(cnpj: str) -> Path | None:
    """Pasta existente com dados do CNPJ. Se houver várias, fica a que tem mais arquivo."""
    c = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(c) != 14:
        return None
    cache_key = f"_arquivo_fiscal_dir_resolvido_{c}"
    achados: list[Path] = []
    vistos: set[str] = set()

    def _add(p: Path) -> None:
        chave = str(p).replace("/", "\\")
        if chave.lower().startswith("\\\\"):
            chave = chave.replace("\\\\10.10.100.201\\xml\\GARIMPEIRO", "P:\\GARIMPEIRO")
            chave = chave.replace("\\\\10.10.100.201\\xml\\garimpeiro", "P:\\GARIMPEIRO")
            chave = chave.replace("\\\\10.10.100.201\\xml", "P:")
        if chave in vistos:
            return
        if not p.is_dir() or not (p / "arquivo.sqlite").is_file():
            return
        vistos.add(chave)
        achados.append(p)

    cached = str(st.session_state.get(cache_key) or "").strip()
    if cached:
        _add(Path(cached))
    for raiz in _arquivo_fiscal_raizes_candidatas():
        if not raiz.is_dir():
            continue
        for base in (raiz, raiz / _ARQUIVO_FISCAL_INATIVAS_DIR):
            if not base.is_dir():
                continue
            _add(base / c)
            try:
                for item in base.iterdir():
                    if not item.is_dir() or item.name.startswith("_"):
                        continue
                    if not (item.name == c or item.name.endswith(f"_{c}")):
                        try:
                            from core.exportacoes import cnpj_de_nome_pasta

                            if cnpj_de_nome_pasta(item.name) != c:
                                continue
                        except ImportError:
                            continue
                    _add(item)
            except OSError:
                continue
    if not achados:
        achados = list(_arquivo_fiscal_candidatos_pasta_empresa(cnpj) or [])
    if not achados:
        return None
    raiz_can = _arquivo_fiscal_raiz()
    try:
        rp = str(raiz_can.resolve()).replace("/", "\\").lower()
    except OSError:
        rp = str(raiz_can).replace("/", "\\").lower()

    def _sob_raiz_can(p: Path) -> bool:
        try:
            s = str(p.resolve()).replace("/", "\\").lower()
        except OSError:
            s = str(p).replace("/", "\\").lower()
        return s.startswith(rp)

    pool = [p for p in achados if _sob_raiz_can(p)] or achados
    melhor = max(pool, key=lambda p: _arquivo_fiscal_pontuacao_pasta_empresa(p, cnpj))
    if _arquivo_fiscal_pontuacao_pasta_empresa(melhor, cnpj)[0] <= 0:
        return None
    st.session_state[cache_key] = str(melhor)
    return melhor


def _path_esta_sob_raiz_arquivo(p: Path) -> bool:
    raiz = _arquivo_fiscal_raiz()
    try:
        return str(p.resolve()).replace("/", "\\").lower().startswith(
            str(raiz.resolve()).replace("/", "\\").lower()
        )
    except OSError:
        return str(p).replace("/", "\\").lower().startswith(
            str(raiz).replace("/", "\\").lower()
        )


def _arquivo_fiscal_ficheiro_indice_existe(
    cnpj: str,
    chave: str,
    *,
    conn: sqlite3.Connection | None = None,
    emp: Path | None = None,
    rel_cache: dict[str, str] | None = None,
) -> bool:
    """True se o registo aponta para um XML que existe no disco (pasta actual da empresa)."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    ch = str(chave or "").strip()
    if len(cx) != 14 or not ch:
        return False
    rel = (rel_cache or {}).get(ch) if rel_cache is not None else None
    own = False
    if rel is None:
        if conn is None:
            try:
                conn = _arquivo_fiscal_conn(cx)
                own = True
            except Exception:
                return False
        try:
            row = conn.execute(
                "SELECT caminho_relativo FROM xml_arquivo WHERE chave = ?",
                (ch,),
            ).fetchone()
        except Exception:
            row = None
        finally:
            if own and conn is not None:
                try:
                    conn.close()
                except Exception:
                    pass
        if not row or not row[0]:
            return False
        rel = str(row[0])
    if not rel:
        return False
    try:
        if emp is None:
            emp = _arquivo_fiscal_pasta_empresa(cx)
        dest = emp / str(rel).replace("/", os.sep)
        return dest.is_file()
    except OSError:
        return False


def _arquivo_fiscal_filtrar_chaves_só_com_xml(cnpj: str, chaves: set[str]) -> set[str]:
    """Remove do índice de skip chaves órfãs (SQLite sem ficheiro — leitura errada anterior)."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14 or not chaves:
        return chaves
    ch_list = sorted(ch for ch in chaves if ch)
    if not ch_list:
        return set()
    try:
        emp = _arquivo_fiscal_pasta_empresa(cx)
        conn = _arquivo_fiscal_conn(cx)
    except Exception:
        return chaves
    out: set[str] = set()
    try:
        for i in range(0, len(ch_list), 400):
            bloco = ch_list[i : i + 400]
            qs = ",".join("?" * len(bloco))
            try:
                rows = conn.execute(
                    f"SELECT chave, caminho_relativo FROM xml_arquivo WHERE chave IN ({qs})",
                    bloco,
                ).fetchall()
            except Exception:
                continue
            rel_map = {
                str(r[0]): str(r[1] or "")
                for r in rows
                if r and r[0] and r[1]
            }
            for ch in bloco:
                rel = rel_map.get(ch)
                if not rel:
                    continue
                try:
                    if (emp / rel.replace("/", os.sep)).is_file():
                        out.add(ch)
                except OSError:
                    pass
        return out
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _arquivo_fiscal_pasta_empresa(cnpj: str) -> Path:
    c = _arquivo_fiscal_cnpj_limpo(cnpj)
    existente = _arquivo_fiscal_resolver_pasta_empresa(cnpj)
    if existente is not None and not _path_esta_sob_raiz_arquivo(existente):
        _arquivo_fiscal_invalidar_cache_pasta(c)
        existente = None
    if existente is not None:
        return existente
    return _arquivo_fiscal_pasta_empresa_nova(cnpj)


def _arquivo_fiscal_pasta_xml_empresa(cnpj: str) -> Path:
    """XML no disco: XML/AAAA/Mês/EP_AAAA_MM_Serie_…/ (contabilidade)."""
    return _arquivo_fiscal_pasta_empresa(cnpj) / _ARQUIVO_FISCAL_SUBPASTA_XML


def _arquivo_fiscal_pasta_zip_empresa(cnpj: str) -> Path:
    """ZIPs persistidos do arquivo fiscal (mesmos XML, formato compactado)."""
    pasta = _arquivo_fiscal_pasta_empresa(cnpj) / _ARQUIVO_FISCAL_SUBPASTA_ZIP
    pasta.mkdir(parents=True, exist_ok=True)
    return pasta


def _arquivo_fiscal_rotulo_filtro_zip(
    is_propria: int | None, status: str | None
) -> str:
    if is_propria == 1:
        lado = "Emissao_propria"
    elif is_propria == 0:
        lado = "Terceiros"
    else:
        lado = "Todas"
    stt = (str(status or "").strip().upper() or "Todos")
    return f"{lado}_{stt}"


def _arquivo_fiscal_prefixo_zip(
    ano: int | None,
    mes: int | None,
    is_propria: int | None,
    status: str | None,
) -> str:
    rot = _arquivo_fiscal_rotulo_filtro_zip(is_propria, status)
    if ano is not None and mes is not None:
        try:
            return f"{int(ano)}_{int(mes):02d}_{rot}"
        except (TypeError, ValueError):
            pass
    return f"completo_{rot}"


def _arquivo_fiscal_limpar_zips_da_pasta(pasta: Path) -> None:
    for p in pasta.glob("*.zip"):
        try:
            p.unlink()
        except OSError:
            pass


def _arquivo_fiscal_competencia_de_item(it: dict) -> tuple[int, int] | None:
    """Ano/mês de emissão a partir do registo do arquivo fiscal."""
    de = str(it.get("data_emissao") or "").strip()
    iso = _arquivo_fiscal_data_emissao_iso(de) if de else None
    if iso and len(iso) >= 7:
        try:
            a, m = int(iso[:4]), int(iso[5:7])
            if 1 <= m <= 12:
                return a, m
        except ValueError:
            pass
    try:
        a, m = int(it.get("ano")), int(it.get("mes"))
        if 1 <= m <= 12:
            return a, m
    except (TypeError, ValueError):
        pass
    return None


_MESES_ARQUIVO_NOME = (
    "",
    "Janeiro",
    "Fevereiro",
    "Março",
    "Abril",
    "Maio",
    "Junho",
    "Julho",
    "Agosto",
    "Setembro",
    "Outubro",
    "Novembro",
    "Dezembro",
)
_MESES_ARQUIVO_NOME_SET = frozenset(_MESES_ARQUIVO_NOME[1:])


def _arquivo_fiscal_nome_pasta_mes(mes) -> str:
    try:
        m = int(mes)
        if 1 <= m <= 12:
            return _MESES_ARQUIVO_NOME[m]
    except (TypeError, ValueError):
        pass
    return "sem_mes"


def _arquivo_fiscal_slug_grupo_de_registo(
    *,
    is_propria,
    status,
    serie,
    modelo,
    ano,
    mes,
    operacao=None,
    slug_legado: str | None = None,
) -> str:
    """Pasta EP_/T_ sob o mês (ex.: EP_2026_06_Serie_1_Entrada_Autorizadas_NFe)."""
    leg = str(slug_legado or "").strip().replace("\\", "/").rstrip("/")
    if leg:
        if "/" in leg:
            leg = leg.split("/")[-1]
        if leg.startswith(("EP_", "T_", "DOM_")):
            return leg
    try:
        slug = _pacote_contab_slug_grupo(
            bool(is_propria),
            str(status or ""),
            str(serie if serie is not None else "0"),
            str(modelo or ""),
            ano,
            mes,
            operacao,
        )
    except Exception:
        slug = ""
    return slug or ""


def _arquivo_fiscal_pasta_xml_de_registo(
    ano,
    mes,
    *,
    is_propria=1,
    status="",
    serie="0",
    modelo="",
    operacao=None,
    slug_legado: str | None = None,
) -> str:
    """Subpasta relativa sob XML/ — AAAA/Mês/EP_… (contabilidade)."""
    mes_nome = _arquivo_fiscal_nome_pasta_mes(mes)
    grupo = _arquivo_fiscal_slug_grupo_de_registo(
        is_propria=is_propria,
        status=status,
        serie=serie,
        modelo=modelo,
        ano=ano,
        mes=mes,
        operacao=operacao,
        slug_legado=slug_legado,
    )
    try:
        a = int(ano)
    except (TypeError, ValueError):
        a = 0
    if grupo and a > 0 and mes_nome != "sem_mes":
        return f"{a:04d}/{mes_nome}/{grupo}"
    if a > 0 and mes_nome != "sem_mes":
        return f"{a:04d}/{mes_nome}"
    if grupo:
        return grupo
    if mes_nome != "sem_mes":
        return mes_nome
    return "sem_data"


def _arquivo_fiscal_slug_db_de_pasta(pasta: str) -> str:
    for part in reversed(str(pasta or "").replace("\\", "/").split("/")):
        if part.startswith(("EP_", "T_", "DOM_")):
            return part
    parts = str(pasta or "").replace("\\", "/").split("/")
    return parts[-1] if parts else str(pasta or "")


def _arquivo_fiscal_mes_de_slug(slug: str) -> tuple[int, int] | None:
    """Ano/mês a partir de slug (Junho/EP_2026_06_…, EP_2026_06_… ou legado 2026/06)."""
    s = str(slug or "").strip().replace("\\", "/").rstrip("/")
    if not s:
        return None
    if s in _MESES_ARQUIVO_NOME_SET:
        return None
    if "/" in s:
        partes = s.split("/")
        if partes[0] in _MESES_ARQUIVO_NOME_SET:
            s = "/".join(partes[1:])
        elif re.fullmatch(r"\d{4}", partes[0]):
            if len(partes) >= 2 and partes[1] in _MESES_ARQUIVO_NOME_SET:
                s = "/".join(partes[2:]) if len(partes) > 2 else partes[1]
            elif len(partes) >= 2 and re.fullmatch(r"\d{2}", partes[1]):
                try:
                    a, mes = int(partes[0]), int(partes[1])
                    if 1 <= mes <= 12:
                        return a, mes
                except ValueError:
                    pass
            elif len(partes) >= 2:
                s = "/".join(partes[1:])
    m = re.search(r"_(\d{4})_(\d{2})(?:_|$)", s)
    if not m:
        return None
    try:
        a, mes = int(m.group(1)), int(m.group(2))
        if 1 <= mes <= 12:
            return a, mes
    except ValueError:
        pass
    return None


def _arquivo_fiscal_caminho_formato_mes_nome(rel: str) -> bool:
    """True se XML/AAAA/Mês/EP_…/ficheiro.xml (ou manual_inutilizadas)."""
    rel = str(rel or "").replace("\\", "/").strip("/")
    parts = rel.split("/")
    if len(parts) < 3 or parts[0] != _ARQUIVO_FISCAL_SUBPASTA_XML:
        return False
    if parts[1] == "manual_inutilizadas":
        return True
    if len(parts) < 5:
        return False
    if not re.fullmatch(r"\d{4}", parts[1]):
        return False
    if parts[2] not in _MESES_ARQUIVO_NOME_SET:
        return False
    return bool(parts[3].startswith(("EP_", "T_", "DOM_")))


def _arquivo_fiscal_pasta_ano_mes_de_res(res: dict) -> str:
    """Subpasta sob XML/ — mês de emissão + grupo contabilidade."""
    try:
        a = int(res.get("Ano"))
        m = int(res.get("Mes"))
        if a > 0 and 1 <= m <= 12:
            return _arquivo_fiscal_pasta_xml_de_registo(
                a,
                m,
                is_propria=bool(res.get("_is_propria", True)),
                status=str(res.get("Status") or ""),
                serie=str(res.get("Série") or res.get("Serie") or "0"),
                modelo=str(res.get("Tipo") or ""),
                operacao=res.get("Operacao") or res.get("Operação"),
            )
    except (TypeError, ValueError):
        pass
    de = str(res.get("Data_Emissao") or res.get("Data Emissão") or "").strip()
    iso = _arquivo_fiscal_data_emissao_iso(de) if de else None
    if iso and len(iso) >= 7:
        try:
            a, m = int(iso[:4]), int(iso[5:7])
            if a > 0 and 1 <= m <= 12:
                return _arquivo_fiscal_pasta_xml_de_registo(
                    a,
                    m,
                    is_propria=bool(res.get("_is_propria", True)),
                    status=str(res.get("Status") or ""),
                    serie=str(res.get("Série") or res.get("Serie") or "0"),
                    modelo=str(res.get("Tipo") or ""),
                    operacao=res.get("Operacao") or res.get("Operação"),
                )
        except ValueError:
            pass
    return "sem_data"


def _arquivo_fiscal_pasta_de_registo(
    ano,
    mes,
    slug_pasta: str | None,
    *,
    is_propria=1,
    status="",
    serie="0",
    modelo="",
    operacao=None,
) -> str:
    return _arquivo_fiscal_pasta_xml_de_registo(
        ano,
        mes,
        is_propria=is_propria,
        status=status,
        serie=serie,
        modelo=modelo,
        operacao=operacao,
        slug_legado=slug_pasta,
    )


_ARQUIVO_FISCAL_FORMATO_PASTAS_V = "3"  # XML/AAAA/Mês/EP_…/ + ZIP/AAAA/Mês/EP_….zip
_ARQUIVO_META_FORMATO_PASTAS = "formato_pastas_v"


_arquivo_fiscal_migrado_ano_mes: set[str] = set()


def _arquivo_fiscal_meta_get(conn: sqlite3.Connection, chave: str, default=None):
    try:
        row = conn.execute(
            "SELECT valor FROM arquivo_meta WHERE chave = ?", (chave,)
        ).fetchone()
        return row[0] if row else default
    except Exception:
        return default


def _arquivo_fiscal_meta_set(conn: sqlite3.Connection, chave: str, valor: str) -> None:
    conn.execute(
        "INSERT OR REPLACE INTO arquivo_meta (chave, valor) VALUES (?, ?)",
        (chave, str(valor)),
    )


def _arquivo_fiscal_mover_xml_seguro(src: Path, dest: Path) -> bool:
    """Copia ou move sem perder XML — só apaga origem se o destino tiver o mesmo tamanho."""
    if not src.is_file():
        return dest.is_file()
    dest.parent.mkdir(parents=True, exist_ok=True)
    if dest.is_file():
        try:
            if src.stat().st_size == dest.stat().st_size:
                if src.resolve() != dest.resolve():
                    src.unlink()
                return True
        except OSError:
            pass
        return True
    try:
        shutil.copy2(src, dest)
    except OSError:
        try:
            shutil.move(str(src), str(dest))
        except OSError:
            return False
    if not dest.is_file():
        return False
    try:
        if src.is_file() and src.stat().st_size == dest.stat().st_size:
            if src.resolve() != dest.resolve():
                src.unlink()
    except OSError:
        pass
    return dest.is_file()


def _arquivo_fiscal_candidatos_xml_legado(
    base_xml: Path,
    nome: str,
    ano,
    mes,
    ep_slug: str,
    slug_old: str | None,
) -> list[Path]:
    """Locais antigos onde o XML pode estar no disco."""
    mes_nome = _arquivo_fiscal_nome_pasta_mes(mes)
    cands: list[Path] = []
    try:
        a = int(ano)
        m = int(mes)
    except (TypeError, ValueError):
        a = m = 0
    leg = str(slug_old or "").strip().replace("\\", "/")
    if leg:
        cands.append(base_xml / leg.replace("/", os.sep) / nome)
    if ep_slug:
        if a > 0 and mes_nome != "sem_mes":
            cands.append(base_xml / f"{a:04d}" / mes_nome / ep_slug / nome)
            cands.append(base_xml / mes_nome / ep_slug / nome)
        if a > 0 and 1 <= m <= 12:
            cands.append(base_xml / f"{a:04d}" / f"{m:02d}" / nome)
            cands.append(base_xml / f"{a:04d}" / nome)
    vistos: set[str] = set()
    out: list[Path] = []
    for p in cands:
        k = str(p).lower()
        if k in vistos:
            continue
        vistos.add(k)
        out.append(p)
    return out


def _arquivo_fiscal_remover_pastas_vazias(pasta: Path) -> None:
    """Remove só diretórios vazios — nunca apaga ficheiros."""
    if not pasta.is_dir():
        return
    for sub in sorted(pasta.rglob("*"), key=lambda p: len(p.parts), reverse=True):
        if sub.is_dir():
            try:
                next(sub.iterdir())
            except StopIteration:
                try:
                    sub.rmdir()
                except OSError:
                    pass


def _arquivo_fiscal_migrar_pastas_ano_mes(conn: sqlite3.Connection, cnpj: str) -> int:
    """
    Organiza XML em XML/AAAA/Mês/EP_AAAA_MM_Serie_…/ (ou T_…).
    Migra formatos legados sem apagar XML (cópia verificada).
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return 0
    base = _arquivo_fiscal_pasta_empresa(cx)
    base_xml = base / _ARQUIVO_FISCAL_SUBPASTA_XML
    rows = conn.execute(
        """
        SELECT chave, caminho_relativo, nome_arquivo, ano, mes, slug_pasta,
               is_propria, operacao, serie, modelo, status
        FROM xml_arquivo
        WHERE cnpj_empresa = ?
        """,
        (cx,),
    ).fetchall()
    movidos = 0
    pend = 0
    for chave, rel_old, nome, ano, mes, slug_old, is_pr, operacao, serie, modelo, status in rows:
        rel_old_s = str(rel_old or "").replace("\\", "/")
        if not rel_old_s or not nome:
            continue
        if rel_old_s.startswith(f"{_ARQUIVO_FISCAL_SUBPASTA_XML}/manual_inutilizadas/"):
            continue
        if _arquivo_fiscal_caminho_formato_mes_nome(rel_old_s):
            continue
        pasta = _arquivo_fiscal_pasta_de_registo(
            ano,
            mes,
            slug_old,
            is_propria=is_pr,
            status=status,
            serie=serie,
            modelo=modelo,
            operacao=operacao,
        )
        rel_new = f"{_ARQUIVO_FISCAL_SUBPASTA_XML}/{pasta}/{nome}"
        if rel_new == rel_old_s:
            continue
        dest = base / rel_new.replace("/", os.sep)
        src = base / rel_old_s.replace("/", os.sep)
        ep_slug = _arquivo_fiscal_slug_grupo_de_registo(
            is_propria=is_pr,
            status=status,
            serie=serie,
            modelo=modelo,
            ano=ano,
            mes=mes,
            operacao=operacao,
            slug_legado=slug_old,
        )
        if not _arquivo_fiscal_mover_xml_seguro(src, dest):
            for tentativa in _arquivo_fiscal_candidatos_xml_legado(
                base_xml, nome, ano, mes, ep_slug, slug_old
            ):
                if _arquivo_fiscal_mover_xml_seguro(tentativa, dest):
                    break
        if not dest.is_file():
            continue
        slug_db = _arquivo_fiscal_slug_db_de_pasta(pasta)
        conn.execute(
            """
            UPDATE xml_arquivo
            SET caminho_relativo = ?, slug_pasta = ?, atualizado_em = ?
            WHERE chave = ?
            """,
            (
                rel_new,
                slug_db,
                datetime.now().isoformat(timespec="seconds"),
                chave,
            ),
        )
        movidos += 1
        pend += 1
        if pend >= _ARQUIVO_FISCAL_GRAVAR_LOTE_COMMIT_A_CADA:
            conn.commit()
            pend = 0
    if pend:
        conn.commit()
    _arquivo_fiscal_remover_pastas_vazias(base_xml)
    leg = _arquivo_fiscal_limpar_xml_mes_numerico_empresa(cx)
    leg_raiz = _arquivo_fiscal_limpar_xml_mes_raiz_empresa(cx)
    if leg.get("dup_removidos") or leg.get("movidos") or leg_raiz.get("dup_removidos") or leg_raiz.get("movidos"):
        _arquivo_fiscal_remover_pastas_vazias(base_xml)
    _arquivo_fiscal_migrado_ano_mes.add(cx)
    return movidos


def _arquivo_fiscal_indice_nomes_xml_mes(pasta_mes: Path) -> dict[str, Path]:
    """Nome de ficheiro → caminho em XML/AAAA/Mês/…"""
    out: dict[str, Path] = {}
    if not pasta_mes.is_dir():
        return out
    for f in pasta_mes.rglob("*.xml"):
        if f.is_file():
            out.setdefault(f.name, f)
    return out


def _arquivo_fiscal_limpar_xml_mes_numerico_empresa(cnpj: str) -> dict:
    """
    Trata pastas legado XML/AAAA/MM/ (mês numérico):
    - apaga cópias com o mesmo nome e tamanho já presentes em XML/AAAA/Mês/;
    - move o restante para XML/AAAA/Mês/EP_…/ conforme identify_xml_info.
    Não altera o SQLite (evita sobrescrever cancelamento por autorizada na mesma chave).
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return {"dup_removidos": 0, "movidos": 0, "falhas": 0}
    base_xml = _arquivo_fiscal_pasta_xml_empresa(cx)
    if not base_xml.is_dir():
        return {"dup_removidos": 0, "movidos": 0, "falhas": 0}
    dup_removidos = movidos = falhas = 0
    for ano_dir in list(base_xml.iterdir()):
        if not ano_dir.is_dir() or not re.fullmatch(r"\d{4}", ano_dir.name):
            continue
        for mes_dir in list(ano_dir.iterdir()):
            if not mes_dir.is_dir() or not re.fullmatch(r"\d{2}", mes_dir.name):
                continue
            try:
                mm = int(mes_dir.name)
                if not 1 <= mm <= 12:
                    continue
            except ValueError:
                continue
            mes_nome = _arquivo_fiscal_nome_pasta_mes(mm)
            dest_mes = ano_dir / mes_nome
            indice = _arquivo_fiscal_indice_nomes_xml_mes(dest_mes)
            for src in list(mes_dir.rglob("*.xml")):
                if not src.is_file():
                    continue
                existente = indice.get(src.name)
                if existente is not None:
                    try:
                        if existente.stat().st_size == src.stat().st_size:
                            src.unlink()
                            dup_removidos += 1
                            continue
                        # Mesmo nome no mês certo (EP_…/) — cópia em AAAA/MM/ é legado obsoleto.
                        src.unlink()
                        dup_removidos += 1
                        continue
                    except OSError:
                        pass
                try:
                    raw = src.read_bytes()
                except OSError:
                    falhas += 1
                    continue
                res, is_p = identify_xml_info(raw, cx, src.name)
                if not res:
                    falhas += 1
                    continue
                slug_rel = _arquivo_fiscal_slug_de_res(res, is_p)
                nome_xml = _nome_arquivo_xml_contabilidade(res, src.name)
                dest = base_xml.parent / _ARQUIVO_FISCAL_SUBPASTA_XML / slug_rel / nome_xml
                if dest.is_file():
                    try:
                        if dest.read_bytes() == raw:
                            src.unlink()
                            dup_removidos += 1
                            continue
                    except OSError:
                        pass
                    alt = dest.parent / src.name
                    if alt.is_file():
                        try:
                            if alt.read_bytes() == raw:
                                src.unlink()
                                dup_removidos += 1
                                continue
                        except OSError:
                            pass
                    dest = alt
                if _arquivo_fiscal_mover_xml_seguro(src, dest):
                    movidos += 1
                    indice[src.name] = dest
                else:
                    falhas += 1
            _arquivo_fiscal_remover_pastas_vazias(mes_dir)
    return {
        "dup_removidos": dup_removidos,
        "movidos": movidos,
        "falhas": falhas,
    }


def _arquivo_fiscal_ano_de_slug_ou_res(
    slug: str | None, res: dict | None, fallback: int = 0
) -> int:
    s = str(slug or "")
    m = re.search(r"(?:^|/)(?:EP_|T_|DOM_)(\d{4})_\d{2}_", s)
    if m:
        return int(m.group(1))
    if res:
        try:
            a = int(res.get("Ano"))
            if a > 0:
                return a
        except (TypeError, ValueError):
            pass
    return int(fallback) if fallback > 0 else 0


def _arquivo_fiscal_processar_xml_legado_para_mes(
    *,
    base_empresa: Path,
    cnpj: str,
    src: Path,
    dest_mes: Path,
    indice: dict[str, Path],
) -> tuple[str, int]:
    """
    Move ou remove um XML legado em direção a XML/AAAA/Mês/.
    Retorna ('dup'|'movido'|'falha', 1).
    """
    existente = indice.get(src.name)
    if existente is not None:
        try:
            src.unlink()
            return "dup", 1
        except OSError:
            pass
    try:
        raw = src.read_bytes()
    except OSError:
        return "falha", 1
    res, is_p = identify_xml_info(raw, cnpj, src.name)
    if not res:
        return "falha", 1
    slug_rel = _arquivo_fiscal_slug_de_res(res, is_p)
    nome_xml = _nome_arquivo_xml_contabilidade(res, src.name)
    dest = base_empresa / _ARQUIVO_FISCAL_SUBPASTA_XML / slug_rel / nome_xml
    if dest.is_file():
        try:
            if dest.read_bytes() == raw:
                src.unlink()
                return "dup", 1
        except OSError:
            pass
        alt = dest.parent / src.name
        if alt.is_file():
            try:
                if alt.read_bytes() == raw:
                    src.unlink()
                    return "dup", 1
            except OSError:
                pass
        dest = alt
    if _arquivo_fiscal_mover_xml_seguro(src, dest):
        indice[src.name] = dest
        return "movido", 1
    return "falha", 1


def _arquivo_fiscal_limpar_xml_mes_raiz_empresa(cnpj: str) -> dict:
    """
    Trata pastas legado XML/Mês/ e XML/EP_…/ na raiz (sem AAAA/):
    move para XML/AAAA/Mês/EP_…/ e remove duplicatas já em 2026/.
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return {"dup_removidos": 0, "movidos": 0, "falhas": 0}
    base_xml = _arquivo_fiscal_pasta_xml_empresa(cx)
    if not base_xml.is_dir():
        return {"dup_removidos": 0, "movidos": 0, "falhas": 0}
    dup_removidos = movidos = falhas = 0
    base_empresa = base_xml.parent
    for sub in list(base_xml.iterdir()):
        if not sub.is_dir():
            continue
        if re.fullmatch(r"\d{4}", sub.name):
            continue
        if sub.name == "manual_inutilizadas":
            continue
        mes_nome = sub.name if sub.name in _MESES_ARQUIVO_NOME_SET else None
        if mes_nome is None and not sub.name.startswith(("EP_", "T_", "DOM_")):
            continue
        ano_hint = _arquivo_fiscal_ano_de_slug_ou_res(sub.name, None)
        if mes_nome and ano_hint <= 0:
            ano_hint = 2026
        if mes_nome:
            dest_mes = base_xml / f"{ano_hint:04d}" / mes_nome
        else:
            dest_mes = None
        indice: dict[str, Path] = {}
        if dest_mes is not None and dest_mes.is_dir():
            indice = _arquivo_fiscal_indice_nomes_xml_mes(dest_mes)
        for src in list(sub.rglob("*.xml")):
            if not src.is_file():
                continue
            if dest_mes is None:
                try:
                    raw = src.read_bytes()
                except OSError:
                    falhas += 1
                    continue
                res, is_p = identify_xml_info(raw, cx, src.name)
                if not res:
                    falhas += 1
                    continue
                try:
                    ano = int(res.get("Ano"))
                    mes = int(res.get("Mes"))
                except (TypeError, ValueError):
                    falhas += 1
                    continue
                if not (ano > 0 and 1 <= mes <= 12):
                    falhas += 1
                    continue
                dest_mes = base_xml / f"{ano:04d}" / _arquivo_fiscal_nome_pasta_mes(mes)
                indice = _arquivo_fiscal_indice_nomes_xml_mes(dest_mes)
            acao, _ = _arquivo_fiscal_processar_xml_legado_para_mes(
                base_empresa=base_empresa,
                cnpj=cx,
                src=src,
                dest_mes=dest_mes,
                indice=indice,
            )
            if acao == "dup":
                dup_removidos += 1
            elif acao == "movido":
                movidos += 1
            else:
                falhas += 1
        _arquivo_fiscal_remover_pastas_vazias(sub)
    return {
        "dup_removidos": dup_removidos,
        "movidos": movidos,
        "falhas": falhas,
    }


def _arquivo_fiscal_pasta_zip_ano(cnpj: str, ano: int) -> Path:
    pasta = _arquivo_fiscal_pasta_zip_empresa(cnpj) / f"{int(ano):04d}"
    pasta.mkdir(parents=True, exist_ok=True)
    return pasta


def _arquivo_fiscal_pasta_zip_ano_mes(cnpj: str, ano: int, mes: int) -> Path:
    """ZIP/AAAA/Mês/ — mesmo critério das pastas XML."""
    pasta = _arquivo_fiscal_pasta_zip_ano(cnpj, ano) / _arquivo_fiscal_nome_pasta_mes(mes)
    pasta.mkdir(parents=True, exist_ok=True)
    return pasta


def _arquivo_fiscal_zips_legados_mes(cnpj: str, ano: int, mes: int) -> list[Path]:
    """ZIP antigos (AAAA_MM.zip na raiz do ano) — a remover ao regenerar."""
    zip_base = _arquivo_fiscal_pasta_zip_empresa(cnpj)
    prefix = _arquivo_fiscal_nome_zip_mes(ano, mes)
    vistos: set[str] = set()
    out: list[Path] = []
    for pasta in (zip_base / f"{int(ano):04d}", zip_base):
        if not pasta.is_dir():
            continue
        for zp in pasta.glob(f"{prefix}*.zip"):
            k = str(zp).lower()
            if k not in vistos:
                vistos.add(k)
                out.append(zp)
    return sorted(out)


def _arquivo_fiscal_zips_do_mes(cnpj: str, ano: int, mes: int) -> list[Path]:
    zip_base = _arquivo_fiscal_pasta_zip_empresa(cnpj)
    mes_nome = _arquivo_fiscal_nome_pasta_mes(mes)
    novos = sorted((zip_base / f"{int(ano):04d}" / mes_nome).glob("*.zip"))
    if novos:
        return novos
    return _arquivo_fiscal_zips_legados_mes(cnpj, ano, mes)


def _arquivo_fiscal_limpar_subpastas_zip_mes(zip_dir: Path) -> None:
    """Remove subpastas dentro de ZIP/AAAA/Mês/ (ex.: Junho/Junho/ legado)."""
    if not zip_dir.is_dir():
        return
    for sub in list(zip_dir.iterdir()):
        if sub.is_dir():
            try:
                shutil.rmtree(sub)
            except OSError:
                pass


def _arquivo_fiscal_limpar_zips_legados_empresa(cnpj: str) -> int:
    """Remove espelho legado na raiz ZIP/, subpastas duplicadas e ZIP AAAA_MM.zip antigos."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return 0
    zip_base = _arquivo_fiscal_pasta_zip_empresa(cx)
    if not zip_base.is_dir():
        return 0
    removidos = 0
    for sub in list(zip_base.iterdir()):
        if sub.is_dir() and not re.fullmatch(r"\d{4}", sub.name):
            try:
                shutil.rmtree(sub)
                removidos += 1
            except OSError:
                pass
    for mes in _arquivo_fiscal_meses_distintos_db(cx):
        ano, mm = mes
        zip_dir = _arquivo_fiscal_pasta_zip_ano_mes(cx, ano, mm)
        _arquivo_fiscal_limpar_subpastas_zip_mes(zip_dir)
        for zp in _arquivo_fiscal_zips_legados_mes(cx, ano, mm):
            try:
                zp.unlink()
                removidos += 1
            except OSError:
                pass
    for zp in zip_base.glob("*.zip"):
        try:
            zp.unlink()
            removidos += 1
        except OSError:
            pass
    return removidos


def _arquivo_fiscal_reorganizar_zips_empresa(cnpj: str) -> tuple[int, list[str]]:
    """Recria ZIP/AAAA/Mês/EP_….zip (um ZIP por pastinha contabilidade)."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return 0, []
    _arquivo_fiscal_limpar_zips_legados_empresa(cx)
    meses = _arquivo_fiscal_meses_distintos_db(cx)
    n_ok = 0
    erros: list[str] = []
    for ano, mes in meses:
        _zpath, _cnt, err = _arquivo_fiscal_atualizar_zip_mes(cx, ano, mes)
        if _zpath:
            n_ok += 1
        elif err:
            erros.append(f"{ano}/{mes:02d}: {err}")
    return n_ok, erros


def _arquivo_fiscal_reorganizar_empresa(cnpj: str) -> dict:
    """
    Reorganiza XML (AAAA/Mês/EP_…) e recria ZIPs por mês.
    Seguro: não apaga XML sem verificar cópia idêntica no destino.
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return {"ok": False, "msg": "CNPJ inválido."}
    conn = _arquivo_fiscal_conn(cx)
    try:
        movidos = _arquivo_fiscal_migrar_pastas_ano_mes(conn, cx)
        _arquivo_fiscal_meta_set(conn, _ARQUIVO_META_FORMATO_PASTAS, _ARQUIVO_FISCAL_FORMATO_PASTAS_V)
        conn.commit()
    finally:
        conn.close()
    n_zip, erros_zip = _arquivo_fiscal_reorganizar_zips_empresa(cx)
    _arquivo_fiscal_invalidar_runtime_cache(cx)
    return {
        "ok": True,
        "movidos": movidos,
        "zips": n_zip,
        "erros_zip": erros_zip,
        "pasta": str(_arquivo_fiscal_pasta_empresa(cx)),
    }


def _arquivo_fiscal_nome_zip_mes(ano: int, mes: int) -> str:
    return f"{int(ano)}_{int(mes):02d}"


def _arquivo_fiscal_meses_distintos_db(cnpj: str) -> list[tuple[int, int]]:
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cnpj) != 14 or not _arquivo_fiscal_db_path(cnpj).is_file():
        return []
    conn = _arquivo_fiscal_conn(cnpj)
    try:
        rows = conn.execute(
            """
            SELECT DISTINCT ano, mes
            FROM xml_arquivo
            WHERE cnpj_empresa = ? AND ano IS NOT NULL AND mes IS NOT NULL
            ORDER BY ano, mes
            """,
            (cnpj,),
        ).fetchall()
    finally:
        conn.close()
    out: list[tuple[int, int]] = []
    for a, m in rows:
        try:
            aa, mm = int(a), int(m)
            if 1 <= mm <= 12:
                out.append((aa, mm))
        except (TypeError, ValueError):
            continue
    return out


def _arquivo_fiscal_limpar_estrutura_zip_antiga(cnpj: str) -> None:
    """Remove espelho legado em ZIP/ (pastas EP_/T_ na raiz), mantendo ZIP/AAAA/Mês/."""
    _arquivo_fiscal_limpar_zips_legados_empresa(cnpj)


def _arquivo_fiscal_escrever_zips_xml_flat(
    pares: list[tuple[Path, str]],
    zip_dir: Path,
    nome_base: str,
) -> list[str]:
    """Cria ZIP(s) com XML na raiz (sem subpastas). Parte ao atingir MAX_XML_PER_ZIP ou MAX_ZIP_CONTAB_MB. Retorna caminhos criados."""
    zip_dir.mkdir(parents=True, exist_ok=True)
    partes: list[str] = []
    zf = None
    wp = fo = None
    part_idx = 1
    count = 0
    try:
        for p, arc in pares:
            if not p.is_file():
                continue
            if zf is None or count >= MAX_XML_PER_ZIP or _zip_contab_precisa_nova_parte(
                zf, ja_tem_ficheiros=count > 0
            ):
                if zf is not None:
                    actual = _zip_fechar_exportacao(zf, wp, fo)
                    if partes:
                        partes[-1] = actual
                sufixo = f"_pt{part_idx:02d}" if part_idx > 1 else ""
                nome_zip = str(zip_dir / f"{nome_base}{sufixo}.zip")
                zf, wp, fo = _zip_abrir_exportacao(nome_zip)
                partes.append(nome_zip)
                part_idx += 1
                count = 0
            zf.write(str(p), arcname=arc)
            count += 1
        if zf is not None:
            actual = _zip_fechar_exportacao(zf, wp, fo)
            if partes:
                partes[-1] = actual
    except OSError:
        return []
    return partes


def _arquivo_fiscal_marcar_zip_mes(cnpj: str, ano: int, mes: int) -> None:
    """Marca competência para atualizar o ZIP espelho após o garimpo."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return
    try:
        a, m = int(ano), int(mes)
    except (TypeError, ValueError):
        return
    if not (1 <= m <= 12):
        return
    pend = st.session_state.setdefault("_arquivo_fiscal_zip_pendentes_mes", set())
    pend.add((cx, a, m))


def _arquivo_fiscal_marcar_slug_zip(cnpj: str, slug: str) -> None:
    """Marca o mês de emissão (a partir do slug) para atualizar o ZIP espelho."""
    comp = _arquivo_fiscal_mes_de_slug(slug)
    if comp:
        _arquivo_fiscal_marcar_zip_mes(cnpj, comp[0], comp[1])


def _arquivo_fiscal_atualizar_zip_mes(
    cnpj: str, ano: int, mes: int
) -> tuple[str | None, int, str | None]:
    """
    Compacta XML do mês em ZIP/AAAA/Mês/EP_AAAA_MM_Serie_….zip
    (mesmo nome das pastas em XML/; _pt02 se passar do limite por ZIP).
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return None, 0, "CNPJ inválido."
    try:
        a, m = int(ano), int(mes)
    except (TypeError, ValueError):
        return None, 0, "Competência inválida."
    if not (1 <= m <= 12):
        return None, 0, "Mês inválido."
    itens = _arquivo_fiscal_listar(cx, ano=a, mes=m)
    if not itens:
        return None, 0, f"Sem XML indexados para {a}/{m:02d}."
    base = _arquivo_fiscal_pasta_empresa(cx)
    zip_dir = _arquivo_fiscal_pasta_zip_ano_mes(cx, a, m)
    _arquivo_fiscal_limpar_subpastas_zip_mes(zip_dir)
    for zp in zip_dir.glob("*.zip"):
        try:
            zp.unlink()
        except OSError:
            pass
    for zp in _arquivo_fiscal_zips_legados_mes(cx, a, m):
        try:
            zp.unlink()
        except OSError:
            pass
    grupos: dict[str, list[tuple[Path, str]]] = {}
    for it in itens:
        rel = str(it.get("caminho_relativo") or "").replace("/", os.sep)
        if not rel:
            continue
        p = base / rel
        if not p.is_file():
            continue
        slug = _arquivo_fiscal_slug_db_de_pasta(
            str(it.get("slug_pasta") or it.get("caminho_relativo") or "")
        )
        if not slug or slug in ("sem_grupo", "sem_data"):
            slug = "sem_grupo"
        grupos.setdefault(slug, []).append(
            (p, str(it.get("nome_arquivo") or p.name))
        )
    if not grupos:
        return None, 0, f"XML de {a}/{m:02d} listados no banco mas ausentes no disco."
    criados: list[str] = []
    total_xml = 0
    for slug in sorted(grupos):
        pares = grupos[slug]
        total_xml += len(pares)
        partes = _arquivo_fiscal_escrever_zips_xml_flat(pares, zip_dir, slug)
        criados.extend(partes)
    if not criados:
        return None, 0, "Não foi possível criar o ZIP."
    return criados[0], total_xml, None


def _arquivo_fiscal_atualizar_zip_slug(
    cnpj: str, slug: str
) -> tuple[str | None, int, str | None]:
    """Compatibilidade: atualiza o ZIP do mês inferido a partir do slug."""
    comp = _arquivo_fiscal_mes_de_slug(slug)
    if not comp:
        return None, 0, f"Não foi possível identificar o mês em {slug}."
    return _arquivo_fiscal_atualizar_zip_mes(cnpj, comp[0], comp[1])


def _arquivo_fiscal_processar_zips_pendentes(cnpj: str | None = None) -> None:
    """Atualiza ZIP/{ano}_{mes}.zip para cada competência com XML novos no garimpo."""
    pend = st.session_state.pop("_arquivo_fiscal_zip_pendentes_mes", None) or set()
    st.session_state.pop("_arquivo_fiscal_zip_pendentes_slug", None)
    if not pend:
        return
    cx_filtro = _arquivo_fiscal_cnpj_limpo(cnpj) if cnpj else None
    for cx, ano, mes in sorted(pend):
        if cx_filtro and cx != cx_filtro:
            continue
        try:
            _arquivo_fiscal_atualizar_zip_mes(cx, ano, mes)
        except Exception:
            pass


def _arquivo_fiscal_db_path(cnpj: str) -> Path:
    return _arquivo_fiscal_pasta_empresa(cnpj) / "arquivo.sqlite"


def _sped_indice_path(cnpj: str) -> Path:
    return _arquivo_fiscal_pasta_empresa(cnpj) / sped_cruzamento._NOME_SPED_INDICE


def _sped_mapa_chaves_empresa(cnpj: str) -> dict[str, str]:
    """Chave 44 → mês(es) SPED (MM/AAAA; …) em que a chave foi escriturada."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return {}
    return sped_cruzamento.mapa_mes_sped_por_chave(
        sped_cruzamento.indice_sped_carregar(_sped_indice_path(cx))
    )


def _sped_aplicar_coluna_em_dataframes(
    mapa: dict[str, str],
    *dfs,
):
    """Devolve tupla de DataFrames com coluna «Mês SPED» (vários meses; vazio = sem SPED)."""
    mapa_u = mapa if isinstance(mapa, dict) else {}
    out = []
    for df in dfs:
        if df is None or not isinstance(df, pd.DataFrame) or df.empty:
            out.append(df)
        else:
            out.append(sped_cruzamento.df_adicionar_coluna_mes_sped(df, mapa_u))
    return tuple(out)


def _arquivo_fiscal_atualizar_excel_apos_sped(cnpj_limpo: str) -> str | None:
    """Regrava o Excel da empresa com SPED, razão social participante, etc."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj_limpo)
    if len(cx) != 14 or _arquivo_fiscal_total(cx) <= 0:
        return None
    try:
        emp = _arquivo_fiscal_pasta_empresa(cx)
        xpath, _msg = _arquivo_fiscal_gerar_excel_a_partir_pasta_xml(emp, cx)
        return xpath
    except Exception:
        return None


def _arquivo_fiscal_mtime(path: Path) -> float:
    try:
        return float(path.stat().st_mtime) if path.is_file() else 0.0
    except OSError:
        return 0.0


def _arquivo_fiscal_excel_meta_path(cnpj: str) -> Path:
    return _arquivo_fiscal_pasta_empresa(cnpj) / _ARQUIVO_FISCAL_NOME_EXCEL_META


def _arquivo_fiscal_marcar_excel_desatualizado(cnpj_limpo: str) -> None:
    """Invalida o meta do Excel — força remontagem na próxima abertura/sincronização."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj_limpo)
    if len(cx) != 14:
        return
    try:
        meta_p = _arquivo_fiscal_excel_meta_path(cx)
        if meta_p.is_file():
            meta_p.unlink()
    except OSError:
        pass


def _arquivo_fiscal_excel_gravar_meta(
    cnpj_limpo: str, *, versao: int | None = None
) -> None:
    cx = _arquivo_fiscal_cnpj_limpo(cnpj_limpo)
    if len(cx) != 14:
        return
    xls = _arquivo_fiscal_excel_path(cx)
    meta = {
        "versao": int(versao if versao is not None else _EXCEL_RELATORIO_VERSAO),
        "gerado_em": datetime.now().isoformat(timespec="seconds"),
        "sqlite_mtime": _arquivo_fiscal_mtime(_arquivo_fiscal_db_path(cx)),
        "sped_mtime": _arquivo_fiscal_mtime(_sped_indice_path(cx)),
        "excel_mtime": _arquivo_fiscal_mtime(xls),
        "xml_total": int(_arquivo_fiscal_total(cx) or 0),
        "com_mes_sped": _sped_indice_path(cx).is_file(),
    }
    try:
        _arquivo_fiscal_excel_meta_path(cx).write_text(
            json.dumps(meta, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
    except OSError:
        pass


def _arquivo_fiscal_excel_precisa_regenerar(cnpj_limpo: str) -> bool:
    """
    True se o Excel completo precisa de ser gerado.
    Não usa a data do SQLite (abrir o app faz commit/WAL e isso não é nota nova).
    Fica desatualizado quando o meta foi apagado (garimpo/canceladas) ou a
    contagem/SPED mudou.
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj_limpo)
    if len(cx) != 14:
        return False
    xls = _arquivo_fiscal_excel_path(cx)
    if not xls.is_file():
        return True
    xml_n = int(_arquivo_fiscal_total(cx) or 0)
    sped_p = _sped_indice_path(cx)
    sped_mt = _arquivo_fiscal_mtime(sped_p)
    meta_p = _arquivo_fiscal_excel_meta_path(cx)
    if not meta_p.is_file():
        return True
    try:
        meta = json.loads(meta_p.read_text(encoding="utf-8"))
    except (OSError, ValueError, TypeError):
        return True
    if int(meta.get("versao") or 0) < _EXCEL_RELATORIO_VERSAO:
        return True
    if int(meta.get("xml_total") or -1) != xml_n:
        return True
    if sped_p.is_file() and not meta.get("com_mes_sped"):
        return True
    if float(meta.get("sped_mtime") or 0) < sped_mt - 0.001:
        return True
    return False


def _arquivo_fiscal_garantir_excel_empresa(
    cnpj_limpo: str, *, forcar: bool = False
) -> tuple[str | None, str]:
    """
    Garante Excel atualizado na pasta da empresa (XML + SPED vigente + participante).
    Se já estiver em dia, devolve o caminho sem reler os XML.
    Mensagem «já atualizado» = não regenerou (só abrir).
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj_limpo)
    if len(cx) != 14:
        return None, "CNPJ inválido — são necessários 14 dígitos."
    if _arquivo_fiscal_total(cx) <= 0:
        return None, "Sem XML indexados para esta empresa."
    xls = _arquivo_fiscal_excel_path(cx)
    if not forcar and xls.is_file() and not _arquivo_fiscal_excel_precisa_regenerar(cx):
        return str(xls), "Excel já atualizado — a abrir."
    emp = _arquivo_fiscal_pasta_empresa(cx)
    return _arquivo_fiscal_gerar_excel_a_partir_pasta_xml(emp, cx)


def _arquivo_fiscal_excel_competencia_meta_path(cnpj: str, ano: int, mes: int) -> Path:
    p = _arquivo_fiscal_excel_path_competencia(cnpj, ano, mes)
    return p.with_name(p.stem + ".meta.json")


def _arquivo_fiscal_excel_competencia_precisa_regenerar(
    cnpj_limpo: str, ano: int, mes: int
) -> bool:
    """True se o Excel do mês não existe ou a contagem do mês mudou (notas novas)."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj_limpo)
    if len(cx) != 14:
        return False
    xls = _arquivo_fiscal_excel_path_competencia(cx, int(ano), int(mes))
    if not xls.is_file():
        return True
    n_mes = int(
        _arquivo_fiscal_contar(cx, ano=int(ano), mes=int(mes)) or 0
    )
    meta_p = _arquivo_fiscal_excel_competencia_meta_path(cx, int(ano), int(mes))
    if not meta_p.is_file():
        return True
    try:
        meta = json.loads(meta_p.read_text(encoding="utf-8"))
    except (OSError, ValueError, TypeError):
        return True
    if int(meta.get("versao") or 0) < _EXCEL_RELATORIO_VERSAO:
        return True
    if int(meta.get("xml_mes") or -1) != int(n_mes):
        return True
    return False


def _arquivo_fiscal_excel_competencia_gravar_meta(
    cnpj_limpo: str, ano: int, mes: int
) -> None:
    cx = _arquivo_fiscal_cnpj_limpo(cnpj_limpo)
    if len(cx) != 14:
        return
    xls = _arquivo_fiscal_excel_path_competencia(cx, int(ano), int(mes))
    n_mes = int(_arquivo_fiscal_contar(cx, ano=int(ano), mes=int(mes)) or 0)
    meta = {
        "versao": int(_EXCEL_RELATORIO_VERSAO),
        "gerado_em": datetime.now().isoformat(timespec="seconds"),
        "ano": int(ano),
        "mes": int(mes),
        "xml_mes": int(n_mes),
        "sqlite_mtime": _arquivo_fiscal_mtime(_arquivo_fiscal_db_path(cx)),
        "excel_mtime": _arquivo_fiscal_mtime(xls),
    }
    try:
        _arquivo_fiscal_excel_competencia_meta_path(cx, int(ano), int(mes)).write_text(
            json.dumps(meta, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
    except OSError:
        pass


def _arquivo_fiscal_garantir_excel_competencia(
    cnpj_limpo: str,
    ano: int,
    mes: int,
    *,
    forcar: bool = False,
) -> tuple[str | None, str]:
    """
    Garante Excel do mês. Se já estiver em dia, devolve o caminho sem regenerar.
    Mensagem «já atualizado» = não regenerou (só abrir).
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj_limpo)
    if len(cx) != 14:
        return None, "CNPJ inválido."
    if not 1 <= int(mes) <= 12:
        return None, "Mês inválido."
    xls = _arquivo_fiscal_excel_path_competencia(cx, int(ano), int(mes))
    if (
        not forcar
        and xls.is_file()
        and not _arquivo_fiscal_excel_competencia_precisa_regenerar(cx, int(ano), int(mes))
    ):
        return str(xls), f"Excel {int(mes):02d}/{int(ano)} já atualizado — a abrir."
    return _arquivo_fiscal_gerar_excel_competencia(cx, int(ano), int(mes))


def _sped_processar_ficheiros_empresa(
    cnpj: str,
    uploads: list[tuple[str, bytes]],
) -> tuple[bool, str]:
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return False, "CNPJ inválido — são necessários 14 dígitos."
    if not uploads:
        return False, "Nenhum ficheiro SPED enviado."
    ok, msg, _ind = sped_cruzamento.processar_sped_uploads(
        uploads,
        _sped_indice_path(cx),
        cnpj_esperado=cx,
    )
    if ok:
        _arquivo_fiscal_marcar_excel_desatualizado(cx)
        msg = f"{msg}\n\nExcel marcado para atualização (coluna Mês SPED)."
    return ok, msg


def _sped_remover_entrada_empresa(cnpj: str, entrada_id: str) -> tuple[bool, str]:
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return False, "CNPJ inválido."
    ok, msg = sped_cruzamento.indice_sped_remover_por_id(_sped_indice_path(cx), entrada_id)
    if ok:
        _arquivo_fiscal_marcar_excel_desatualizado(cx)
    return ok, msg


def _sped_ativar_entrada_empresa(cnpj: str, entrada_id: str) -> tuple[bool, str]:
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return False, "CNPJ inválido."
    ok, msg = sped_cruzamento.indice_sped_ativar_por_id(_sped_indice_path(cx), entrada_id)
    if ok:
        _arquivo_fiscal_marcar_excel_desatualizado(cx)
    return ok, msg


def _sped_limpar_indice_empresa(cnpj: str) -> None:
    p = _sped_indice_path(cnpj)
    try:
        if p.is_file():
            p.unlink()
    except OSError:
        pass
    hist = _arquivo_fiscal_pasta_empresa(cnpj) / "SPED"
    try:
        if hist.is_dir():
            shutil.rmtree(hist)
    except OSError:
        pass


_arquivo_fiscal_schema_pronto: set[str] = set()
_ARQUIVO_FISCAL_GRAVAR_LOTE_COMMIT_A_CADA = 500
# Acima disto, não pré-carrega chave→sha na RAM (empresas grandes derrubavam o processo).
_ARQUIVO_FISCAL_SHA_MAP_PRELOAD_MAX = 8_000


def _arquivo_fiscal_sha256_ficheiro(path: Path, *, buf: int = 1024 * 1024) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as f:
        while True:
            bloco = f.read(buf)
            if not bloco:
                break
            h.update(bloco)
    return h.hexdigest()


def _arquivo_fiscal_sha_igual_lote(
    lote: dict | None, conn: sqlite3.Connection, chave: str, sha: str
) -> bool:
    """Evita regravar XML já indexado com o mesmo conteúdo (cache de sessão ou SELECT)."""
    sm = lote.get("sha_map") if isinstance(lote, dict) else None
    cx = str((lote or {}).get("cnpj") or "") if isinstance(lote, dict) else ""
    cx = _arquivo_fiscal_cnpj_limpo(cx)
    emp_cached = None
    if isinstance(lote, dict) and lote.get("emp_dir"):
        try:
            emp_cached = Path(str(lote["emp_dir"]))
        except (TypeError, ValueError, OSError):
            emp_cached = None

    def _ficheiro_ok(chave: str, conn: sqlite3.Connection) -> bool:
        return _arquivo_fiscal_ficheiro_indice_existe(
            cx, chave, conn=conn, emp=emp_cached
        )

    if isinstance(sm, dict) and chave in sm:
        if str(sm[chave]) != sha:
            return False
        if len(cx) == 14 and not _ficheiro_ok(chave, conn):
            return False
        return True
    try:
        row = conn.execute(
            "SELECT sha256 FROM xml_arquivo WHERE chave = ?", (chave,)
        ).fetchone()
    except Exception:
        row = None
    if not row or not row[0]:
        return False
    if str(row[0]) != sha:
        return False
    if len(cx) == 14:
        if emp_cached is None:
            try:
                emp_cached = _arquivo_fiscal_pasta_empresa(cx)
                if isinstance(lote, dict):
                    lote["emp_dir"] = str(emp_cached)
            except Exception:
                emp_cached = None
        if emp_cached is not None and not _arquivo_fiscal_ficheiro_indice_existe(
            cx, chave, conn=conn, emp=emp_cached
        ):
            return False
    if isinstance(sm, dict):
        sm[chave] = str(row[0])
    return True


def _arquivo_fiscal_backfill_ano_mes_da_chave(conn: sqlite3.Connection, cx: str) -> None:
    if _arquivo_fiscal_meta_get(conn, "ano_mes_chave_backfill_v1") == "1":
        return
    try:
        rows = conn.execute(
            """
            SELECT chave FROM xml_arquivo
            WHERE cnpj_empresa = ? AND (ano IS NULL OR mes IS NULL)
            """,
            (cx,),
        ).fetchall()
        for (ch,) in rows:
            par = _chave44_ano_mes_emissao(str(ch or ""))
            if not par:
                continue
            a, m = par
            conn.execute(
                """
                UPDATE xml_arquivo
                SET ano = ?, mes = ?,
                    data_emissao = COALESCE(
                        NULLIF(trim(data_emissao), ''),
                        printf('%04d-%02d-01', ?, ?)
                    )
                WHERE chave = ? AND cnpj_empresa = ?
                """,
                (a, m, a, m, ch, cx),
            )
    except sqlite3.Error:
        pass
    _arquivo_fiscal_meta_set(conn, "ano_mes_chave_backfill_v1", "1")
    try:
        conn.commit()
    except sqlite3.Error:
        pass


def _arquivo_fiscal_ensure_schema(conn: sqlite3.Connection, cnpj: str) -> None:
    """
    Garante tabelas do arquivo fiscal.
    CREATE TABLE IF NOT EXISTS corre sempre (evita «no such table: xml_arquivo»
    quando o .sqlite foi recriado/vazio e o cache em memória ainda marcava o CNPJ).
    Migrações pesadas só uma vez por CNPJ por processo.
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS xml_arquivo (
            chave TEXT PRIMARY KEY,
            cnpj_empresa TEXT NOT NULL,
            numero INTEGER,
            serie TEXT,
            modelo TEXT,
            status TEXT,
            ano INTEGER,
            mes INTEGER,
            is_propria INTEGER,
            operacao TEXT,
            slug_pasta TEXT,
            nome_arquivo TEXT NOT NULL,
            caminho_relativo TEXT NOT NULL,
            caminho_origem TEXT,
            capturado_em TEXT,
            atualizado_em TEXT,
            sha256 TEXT
        )
        """
    )
    conn.execute(
        "CREATE INDEX IF NOT EXISTS ix_arquivo_competencia "
        "ON xml_arquivo (cnpj_empresa, ano, mes)"
    )
    conn.execute(
        "CREATE INDEX IF NOT EXISTS ix_arquivo_slug ON xml_arquivo (slug_pasta)"
    )
    try:
        conn.execute("ALTER TABLE xml_arquivo ADD COLUMN data_emissao TEXT")
    except sqlite3.OperationalError:
        pass
    try:
        conn.execute("ALTER TABLE xml_arquivo ADD COLUMN usuario TEXT")
    except sqlite3.OperationalError:
        pass
    try:
        conn.execute("ALTER TABLE xml_arquivo ADD COLUMN uf_parceiro TEXT")
    except sqlite3.OperationalError:
        pass
    try:
        conn.execute("ALTER TABLE xml_arquivo ADD COLUMN resumo_json TEXT")
    except sqlite3.OperationalError:
        pass
    try:
        conn.execute("ALTER TABLE xml_arquivo ADD COLUMN cfops TEXT")
    except sqlite3.OperationalError:
        pass
    try:
        conn.execute(
            "CREATE INDEX IF NOT EXISTS ix_arquivo_usuario "
            "ON xml_arquivo (cnpj_empresa, usuario)"
        )
    except sqlite3.OperationalError:
        pass
    try:
        conn.execute(
            "CREATE INDEX IF NOT EXISTS ix_arquivo_uf_parceiro "
            "ON xml_arquivo (cnpj_empresa, uf_parceiro)"
        )
    except sqlite3.OperationalError:
        pass
    try:
        conn.execute(
            "CREATE INDEX IF NOT EXISTS ix_arquivo_cfops "
            "ON xml_arquivo (cnpj_empresa, cfops)"
        )
    except sqlite3.OperationalError:
        pass
    try:
        conn.execute(
            "CREATE INDEX IF NOT EXISTS ix_arquivo_painel "
            "ON xml_arquivo (cnpj_empresa, ano, is_propria, mes)"
        )
    except sqlite3.OperationalError:
        pass
    try:
        conn.execute(
            "CREATE INDEX IF NOT EXISTS ix_arquivo_propria_st "
            "ON xml_arquivo (cnpj_empresa, is_propria, status)"
        )
    except sqlite3.OperationalError:
        pass
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS arquivo_meta (
            chave TEXT PRIMARY KEY,
            valor TEXT
        )
        """
    )
    _arquivo_fiscal_backfill_ano_mes_da_chave(conn, cx)
    if cx in _arquivo_fiscal_schema_pronto:
        try:
            conn.commit()
        except sqlite3.Error:
            pass
        return
    if _arquivo_fiscal_meta_get(conn, "data_emissao_backfill_v1") != "1":
        conn.execute(
            """
            UPDATE xml_arquivo
            SET data_emissao = printf('%04d-%02d-01', ano, mes)
            WHERE data_emissao IS NULL AND ano IS NOT NULL AND mes IS NOT NULL
            """
        )
        _arquivo_fiscal_meta_set(conn, "data_emissao_backfill_v1", "1")
        conn.commit()
    if _arquivo_fiscal_meta_get(conn, "ano_mes_chave_backfill_v1") != "1":
        _arquivo_fiscal_backfill_ano_mes_da_chave(conn, cx)
    else:
        try:
            conn.commit()
        except sqlite3.Error:
            pass
    # Par autorizada + cancelamento (não sobrescrever um com o outro)
    if _arquivo_fiscal_meta_get(conn, "par_xml_canceladas_v1") != "1":
        _arquivo_fiscal_migrar_chaves_par_canceladas(conn)
        _arquivo_fiscal_meta_set(conn, "par_xml_canceladas_v1", "1")
        conn.commit()
    if _arquivo_fiscal_meta_get(conn, _ARQUIVO_META_FORMATO_PASTAS) != _ARQUIVO_FISCAL_FORMATO_PASTAS_V:
        _arquivo_fiscal_migrar_pastas_ano_mes(conn, cx)
        _arquivo_fiscal_meta_set(conn, _ARQUIVO_META_FORMATO_PASTAS, _ARQUIVO_FISCAL_FORMATO_PASTAS_V)
        conn.commit()
    _arquivo_fiscal_schema_pronto.add(cx)
    # Depois de schema_pronto: o reparo abre outra ligação e não reentra aqui.
    if _arquivo_fiscal_meta_get(conn, "canceladas_dedupe_autorizada_v1") != "1":
        try:
            _arquivo_fiscal_reparar_canceladas_duplicadas(cx)
            _arquivo_fiscal_meta_set(conn, "canceladas_dedupe_autorizada_v1", "1")
            conn.commit()
        except Exception:
            pass
    if _arquivo_fiscal_meta_get(conn, "canceladas_mes_emissao_v1") != "1":
        try:
            _arquivo_fiscal_reparar_canceladas_mes_emissao(conn, cx)
            _arquivo_fiscal_meta_set(conn, "canceladas_mes_emissao_v1", "1")
            conn.commit()
        except Exception:
            pass


def _arquivo_fiscal_caminho_rede(p: Path | str) -> bool:
    """P: ou UNC — evitar WAL/resolve/stat pesados na partilha."""
    s = str(p or "").replace("/", "\\")
    if not s:
        return False
    if s.startswith("\\\\") or s.startswith("//"):
        return True
    u = s.upper()
    return u == "P:" or u.startswith("P:\\")


def _arquivo_fiscal_aplicar_pragmas(conn: sqlite3.Connection, db_path: Path) -> None:
    conn.execute("PRAGMA busy_timeout=120000")
    conn.execute("PRAGMA temp_store=MEMORY")
    if _arquivo_fiscal_caminho_rede(db_path):
        conn.execute("PRAGMA journal_mode=DELETE")
        conn.execute("PRAGMA synchronous=NORMAL")
        return
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("PRAGMA synchronous=NORMAL")


def _arquivo_fiscal_conn(cnpj: str) -> sqlite3.Connection:
    pasta = _arquivo_fiscal_pasta_empresa(cnpj)
    pasta.mkdir(parents=True, exist_ok=True)
    dbp = _arquivo_fiscal_db_path(cnpj)
    conn = sqlite3.connect(str(dbp), check_same_thread=False, timeout=120.0)
    _arquivo_fiscal_aplicar_pragmas(conn, dbp)
    _arquivo_fiscal_ensure_schema(conn, cnpj)
    return conn


def _arquivo_fiscal_conn_leve(cnpj: str) -> sqlite3.Connection:
    """Ligação para gravar inutilizadas: evita migrações pesadas se o schema já correu."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    pasta = _arquivo_fiscal_pasta_empresa(cx)
    pasta.mkdir(parents=True, exist_ok=True)
    dbp = _arquivo_fiscal_db_path(cx)
    conn = sqlite3.connect(str(dbp), check_same_thread=False, timeout=120.0)
    _arquivo_fiscal_aplicar_pragmas(conn, dbp)
    if cx not in _arquivo_fiscal_schema_pronto:
        _arquivo_fiscal_ensure_schema(conn, cx)
    return conn


def _arquivo_fiscal_gravar_lote_iniciar(cnpj: str) -> dict:
    """Abre lote de gravação (para loops longos sem reindentar blocos enormes)."""
    cm = _arquivo_fiscal_gravar_lote(cnpj)
    ctx = cm.__enter__()
    st.session_state["_arquivo_fiscal_gravar_lote_cm"] = cm
    return ctx


def _arquivo_fiscal_gravar_lote_terminar() -> None:
    cm = st.session_state.pop("_arquivo_fiscal_gravar_lote_cm", None)
    if cm is not None:
        cm.__exit__(None, None, None)


@contextmanager
def _arquivo_fiscal_gravar_lote(cnpj: str):
    """
    Uma ligação SQLite + cache de SHA durante o garimpo — evita abrir/commit por XML.
    SHA só das chaves deste lote. Não reconstrói ZIP-espelho do mês (só nos exports).
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    conn = _arquivo_fiscal_conn(cx)
    ctx = {
        "cnpj": cx,
        "conn": conn,
        "sha_map": {},
        "pending": 0,
        "n_gravados": 0,
        "n_inseridos": 0,
        "sha_lazy": True,
        "dirs_ok": set(),
    }
    try:
        ctx["emp_dir"] = str(_arquivo_fiscal_pasta_empresa(cx))
    except Exception:
        ctx["emp_dir"] = ""
    prev = st.session_state.get("_arquivo_fiscal_gravar_lote_ctx")
    st.session_state["_arquivo_fiscal_gravar_lote_ctx"] = ctx
    try:
        yield ctx
        n_ins = int(ctx.get("n_inseridos") or 0)
        if n_ins > 0:
            try:
                atual = _arquivo_fiscal_meta_get(conn, "xml_total")
                if atual is not None and str(atual).isdigit():
                    _arquivo_fiscal_meta_set(
                        conn, "xml_total", str(int(atual) + n_ins)
                    )
            except Exception:
                pass
        if ctx.get("pending") or n_ins > 0:
            conn.commit()
    finally:
        try:
            conn.close()
        except Exception:
            pass
        if prev is None:
            st.session_state.pop("_arquivo_fiscal_gravar_lote_ctx", None)
        else:
            st.session_state["_arquivo_fiscal_gravar_lote_ctx"] = prev
        if int(ctx.get("n_gravados") or 0) > 0:
            _arquivo_fiscal_marcar_excel_desatualizado(cx)
            _arquivo_fiscal_invalidar_runtime_cache(
                cx, tocar_meta=False, manter_schema=True, manter_comp_resumo=True
            )


def _arquivo_fiscal_slug_de_res(res: dict, is_propria: bool) -> str:
    """Subpasta relativa em XML/ — {Mês}/EP_… ou T_… (contabilidade)."""
    res_u = dict(res)
    res_u["_is_propria"] = is_propria
    return _arquivo_fiscal_pasta_ano_mes_de_res(res_u)


def _arquivo_fiscal_chave_registro(res: dict) -> str | None:
    ch = str(res.get("Chave") or "").strip()
    if ch.startswith("INUT_"):
        return ch
    k44 = _chave44_digitos(ch)
    if k44:
        return k44
    if ch:
        return ch
    return None


def _arquivo_fiscal_tipo_xml_indice(res: dict) -> str:
    """
    Tipo de XML na mesma chave 44 — Domínio precisa do par autorizada + cancelamento.
    DOC = NF autorizada/normal; CANCELADOS/DENEGADOS/REJEITADOS = evento ou proc distinto.
    """
    ch = str(res.get("Chave") or "").strip()
    if ch.startswith("INUT_") or ch.startswith("MANUAL_INUT_"):
        return "INUT"
    st = str(res.get("Status") or "").strip().upper()
    if st == "CANCELADOS":
        return "CANCELADOS"
    if st == "DENEGADOS":
        return "DENEGADOS"
    if st == "REJEITADOS":
        return "REJEITADOS"
    return "DOC"


def _arquivo_fiscal_chave_indice(res: dict) -> str | None:
    """
    Chave única no SQLite: autorizada = só os 44 dígitos;
    cancelamento/denegação/rejeição = «44#STATUS» para não apagar a autorizada.
    """
    base = _arquivo_fiscal_chave_registro(res)
    if not base:
        return None
    tipo = _arquivo_fiscal_tipo_xml_indice(res)
    if tipo in ("DOC", "INUT"):
        return base
    return f"{base}#{tipo}"


def _arquivo_fiscal_migrar_chaves_par_canceladas(conn: sqlite3.Connection) -> None:
    """
    Linhas antigas: cancelamento gravado com a mesma chave 44 da autorizada
    (sobrescrevia). Renomeia para chave#CANCELADOS (idem denegada/rejeitada).
    """
    for st in ("CANCELADOS", "DENEGADOS", "REJEITADOS"):
        sufixo = f"#{st}"
        try:
            # Evita conflito se a chave#STATUS já existir
            conn.execute(
                """
                UPDATE xml_arquivo
                SET chave = chave || ?
                WHERE upper(trim(COALESCE(status, ''))) = ?
                  AND instr(chave, '#') = 0
                  AND length(chave) = 44
                  AND chave GLOB '[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]*'
                  AND (chave || ?) NOT IN (SELECT chave FROM xml_arquivo)
                """,
                (sufixo, st, sufixo),
            )
        except sqlite3.Error:
            pass


def _arquivo_fiscal_chaves_autorizada_duplicada_com_evento(
    conn: sqlite3.Connection, cnpj: str
) -> list[str]:
    """Chave 44 em CANCELADOS quando já existe o par chave#CANCELADOS (evento)."""
    rows = conn.execute(
        """
        SELECT a.chave
        FROM xml_arquivo a
        WHERE a.cnpj_empresa = ?
          AND instr(a.chave, '#') = 0
          AND length(trim(a.chave)) = 44
          AND upper(trim(COALESCE(a.status, ''))) = 'CANCELADOS'
          AND EXISTS (
            SELECT 1 FROM xml_arquivo e
            WHERE e.cnpj_empresa = a.cnpj_empresa
              AND e.chave = a.chave || '#CANCELADOS'
          )
        """,
        (cnpj,),
    ).fetchall()
    out: list[str] = []
    for (ch,) in rows:
        k = _chave44_digitos(ch) or str(ch or "").strip()
        if len(k) == 44:
            out.append(k)
    return out


def _chave44_ano_mes_emissao(chave: str) -> tuple[int, int] | None:
    """AAMM da chave de acesso = competência de emissão da NF (não a do evento)."""
    d = "".join(c for c in str(chave or "") if c.isdigit())
    if len(d) < 44:
        return None
    k = d[:44]
    try:
        ano = 2000 + int(k[2:4])
        mes = int(k[4:6])
    except ValueError:
        return None
    if 1990 <= ano <= 2099 and 1 <= mes <= 12:
        return ano, mes
    return None


def _data_emissao_alinha_mes_chave(iso: str, chave: str) -> str:
    """Se a data não cai no mês da chave, usa AAAA-MM-01 da emissão."""
    par = _chave44_ano_mes_emissao(chave)
    if not par:
        return str(iso or "").strip()[:10]
    ano_ch, mes_ch = par
    iso_n = _arquivo_fiscal_data_emissao_iso(iso) or ""
    if len(iso_n) >= 10:
        try:
            if int(iso_n[:4]) == ano_ch and int(iso_n[5:7]) == mes_ch:
                return iso_n[:10]
        except ValueError:
            pass
    return f"{ano_ch:04d}-{mes_ch:02d}-01"


def _arquivo_fiscal_reparar_canceladas_mes_emissao(
    conn: sqlite3.Connection, cnpj: str
) -> int:
    """
    Canceladas já indexadas com o mês do dhRegEvento voltam ao mês da emissão
    (AAMM da chave). Um único UPDATE — o ciclo linha-a-linha travava a janela.
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    cur = conn.execute(
        """
        UPDATE xml_arquivo
        SET
          ano = 2000 + CAST(substr(replace(chave, '#CANCELADOS', ''), 3, 2) AS INTEGER),
          mes = CAST(substr(replace(chave, '#CANCELADOS', ''), 5, 2) AS INTEGER),
          data_emissao = CASE
            WHEN data_emissao IS NOT NULL
             AND length(data_emissao) >= 10
             AND substr(data_emissao, 6, 2)
                 = substr(replace(chave, '#CANCELADOS', ''), 5, 2)
             AND substr(data_emissao, 1, 4) = printf(
                 '%04d',
                 2000 + CAST(substr(replace(chave, '#CANCELADOS', ''), 3, 2) AS INTEGER)
             )
            THEN substr(data_emissao, 1, 10)
            ELSE printf(
              '%04d-%02d-01',
              2000 + CAST(substr(replace(chave, '#CANCELADOS', ''), 3, 2) AS INTEGER),
              CAST(substr(replace(chave, '#CANCELADOS', ''), 5, 2) AS INTEGER)
            )
          END
        WHERE cnpj_empresa = ?
          AND upper(trim(COALESCE(status, ''))) = 'CANCELADOS'
          AND length(replace(chave, '#CANCELADOS', '')) >= 44
          AND (
            mes IS NULL
            OR mes != CAST(substr(replace(chave, '#CANCELADOS', ''), 5, 2) AS INTEGER)
            OR ano != 2000 + CAST(substr(replace(chave, '#CANCELADOS', ''), 3, 2) AS INTEGER)
            OR data_emissao IS NULL
            OR substr(COALESCE(data_emissao, ''), 6, 2)
               != substr(replace(chave, '#CANCELADOS', ''), 5, 2)
          )
        """,
        (cx,),
    )
    n = int(cur.rowcount or 0)
    if n:
        try:
            _arquivo_fiscal_marcar_excel_desatualizado(cx)
        except Exception:
            pass
    return n


def _arquivo_fiscal_reparar_canceladas_duplicadas(cnpj_empresa: str) -> int:
    """
    Arruma duplicatas já gravadas: autorizada marcada CANCELADOS + evento no índice.
    A autorizada volta a NORMAIS (XML para Autorizadas). O evento permanece.
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj_empresa)
    if len(cx) != 14:
        return 0
    conn = _arquivo_fiscal_conn(cx)
    try:
        lista = _arquivo_fiscal_chaves_autorizada_duplicada_com_evento(conn, cx)
    finally:
        conn.close()
    if not lista:
        return 0
    n_ok, _n_reais, _n_aus, _msg = _arquivo_fiscal_desmarcar_chaves_canceladas_manuais(
        cx, lista
    )
    return int(n_ok or 0)


def _arquivo_fiscal_fonte_origem(f_name: str) -> str | None:
    if _garimpo_lote_usa_sqlite():
        p = _garimpo_lote_sqlite_caminho(f_name)
        if p:
            return p
    pm = _session_state_get_garimpo(SESSION_KEY_FONTES_XML_DISK_PATHS)
    if isinstance(pm, dict) and f_name in pm:
        return str(pm[f_name])
    return None


def _arquivo_fiscal_alinhar_data_cancelada_com_original(conn, res: dict) -> None:
    """No gravar: mês da NF autorizada / chave, nunca dhRegEvento do cancelamento."""
    ch = str(res.get("Chave") or "")
    k44 = "".join(c for c in ch if c.isdigit())[:44]
    if len(k44) != 44:
        return
    iso = ""
    try:
        twin = conn.execute(
            "SELECT data_emissao, ano, mes FROM xml_arquivo WHERE chave = ? LIMIT 1",
            (k44,),
        ).fetchone()
    except sqlite3.Error:
        twin = None
    if twin and str(twin[0] or "").strip():
        iso = _arquivo_fiscal_data_emissao_iso(twin[0]) or ""
    if not iso and twin and twin[1] is not None and twin[2] is not None:
        try:
            a, m = int(twin[1]), int(twin[2])
            if 1 <= m <= 12:
                iso = f"{a:04d}-{m:02d}-01"
        except (TypeError, ValueError):
            iso = ""
    if not iso:
        iso = _data_emissao_alinha_mes_chave(str(res.get("Data_Emissao") or ""), ch)
    if iso and len(iso) >= 7:
        res["Data_Emissao"] = iso[:10]
        res["Ano"] = iso[:4]
        res["Mes"] = iso[5:7]


def _arquivo_fiscal_gravar_um(
    cnpj_empresa: str,
    res: dict,
    is_propria: bool,
    xml_bytes,
    nome_original: str,
    *,
    caminho_origem: str | None = None,
) -> bool:
    """
    Grava XML na pasta do arquivo fiscal e regista/atualiza no SQLite.
    Cancelamento e autorização da mesma chave 44 ficam os DOIS (ficheiros e índice),
    para a Domínio escriturar primeiro a normal e depois a cancelada.
    """
    chave_logica = _arquivo_fiscal_chave_registro(res)
    chave = _arquivo_fiscal_chave_indice(res)
    if not chave or not chave_logica:
        return False
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj_empresa)
    if len(cnpj) != 14:
        return False
    raw = bytes(xml_bytes) if not isinstance(xml_bytes, (bytes, bytearray)) else xml_bytes
    if not raw:
        return False
    sha = hashlib.sha256(raw).hexdigest()
    lote = st.session_state.get("_arquivo_fiscal_gravar_lote_ctx")

    own_conn = False
    if isinstance(lote, dict) and lote.get("cnpj") == cnpj and lote.get("conn") is not None:
        conn = lote["conn"]
    else:
        conn = _arquivo_fiscal_conn(cnpj)
        own_conn = True

    lote_ativo = (
        lote if isinstance(lote, dict) and lote.get("cnpj") == cnpj else None
    )
    if _arquivo_fiscal_sha_igual_lote(lote_ativo, conn, chave, sha):
        ja_propria = False
        try:
            row_pr = conn.execute(
                "SELECT COALESCE(is_propria, 0) FROM xml_arquivo WHERE chave = ?",
                (chave,),
            ).fetchone()
            ja_propria = bool(row_pr and int(row_pr[0] or 0) == 1)
        except Exception:
            ja_propria = False
        if ja_propria or not is_propria:
            if own_conn:
                try:
                    conn.close()
                except Exception:
                    pass
            return False

    if str(res.get("Status") or "").strip().upper() == "CANCELADOS":
        _arquivo_fiscal_alinhar_data_cancelada_com_original(conn, res)

    slug_rel = _arquivo_fiscal_slug_de_res(res, is_propria)
    slug_db = _arquivo_fiscal_slug_db_de_pasta(slug_rel)
    nome_xml = _nome_arquivo_xml_contabilidade(res, nome_original)
    rel = Path(_ARQUIVO_FISCAL_SUBPASTA_XML) / slug_rel / nome_xml
    rel_s = str(rel).replace("\\", "/")
    dest = _arquivo_fiscal_pasta_empresa(cnpj) / rel
    if isinstance(lote, dict) and lote.get("cnpj") == cnpj:
        dirs_ok = lote.setdefault("dirs_ok", set())
        pk = str(dest.parent)
        if pk not in dirs_ok:
            dest.parent.mkdir(parents=True, exist_ok=True)
            dirs_ok.add(pk)
    else:
        dest.parent.mkdir(parents=True, exist_ok=True)

    precisa_escrever = True
    if dest.is_file():
        try:
            st_sz = dest.stat().st_size
            if st_sz == len(raw):
                if _arquivo_fiscal_sha256_ficheiro(dest) == sha:
                    precisa_escrever = False
                elif os.environ.get("GARIMPEIRO_HEADLESS") != "1" and _arquivo_fiscal_caminho_rede(
                    dest
                ):
                    precisa_escrever = False
        except OSError:
            precisa_escrever = True
    if precisa_escrever:
        dest.write_bytes(raw)
    agora = datetime.now().isoformat(timespec="seconds")
    try:
        numero = int(res.get("Número") or res.get("Numero") or 0)
    except (TypeError, ValueError):
        numero = None
    try:
        ano = int(res.get("Ano"))
    except (TypeError, ValueError):
        ano = None
    try:
        mes = int(res.get("Mes"))
    except (TypeError, ValueError):
        mes = None
    _de_raw = str(res.get("Data_Emissao") or res.get("Data Emissão") or "").strip()
    data_emissao = _arquivo_fiscal_data_emissao_iso(_de_raw)
    if not data_emissao and ano is not None and mes is not None:
        data_emissao = f"{int(ano):04d}-{int(mes):02d}-01"
    elif data_emissao:
        try:
            ano = int(data_emissao[:4])
            mes = int(data_emissao[5:7])
        except (TypeError, ValueError):
            pass

    old_rel = None
    try:
        row_old = conn.execute(
            "SELECT caminho_relativo FROM xml_arquivo WHERE chave = ?", (chave,)
        ).fetchone()
        if row_old and row_old[0]:
            old_rel = str(row_old[0]).replace("\\", "/")
    except Exception:
        pass
    usuario_reg = _arquivo_fiscal_usuario_sessao() or None
    uf_parceiro = _arquivo_fiscal_uf_parceiro_de_res(res, bool(is_propria))
    cfops_db = _arquivo_fiscal_cfops_para_db(res)
    had_row = False
    try:
        had_row = (
            conn.execute(
                "SELECT 1 FROM xml_arquivo WHERE chave = ?", (chave,)
            ).fetchone()
            is not None
        )
    except Exception:
        had_row = False
    try:
        resumo_js = _relatorio_serializar(res)
    except Exception:
        resumo_js = None
    try:
        conn.execute(
            """
            INSERT INTO xml_arquivo (
                chave, cnpj_empresa, numero, serie, modelo, status, ano, mes,
                is_propria, operacao, slug_pasta, nome_arquivo, caminho_relativo,
                caminho_origem, capturado_em, atualizado_em, sha256, data_emissao,
                usuario, uf_parceiro, resumo_json, cfops
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(chave) DO UPDATE SET
                numero=excluded.numero, serie=excluded.serie, modelo=excluded.modelo,
                status=CASE
                    WHEN upper(trim(COALESCE(xml_arquivo.status, ''))) = 'INUTILIZADOS'
                     AND upper(trim(COALESCE(excluded.status, ''))) = 'REJEITADOS'
                    THEN xml_arquivo.status
                    ELSE excluded.status
                END,
                ano=excluded.ano,
                mes=excluded.mes,
                is_propria=excluded.is_propria, operacao=excluded.operacao,
                slug_pasta=excluded.slug_pasta, nome_arquivo=excluded.nome_arquivo,
                caminho_relativo=excluded.caminho_relativo,
                caminho_origem=COALESCE(excluded.caminho_origem, caminho_origem),
                atualizado_em=excluded.atualizado_em, sha256=excluded.sha256,
                data_emissao=excluded.data_emissao,
                usuario=COALESCE(excluded.usuario, xml_arquivo.usuario),
                uf_parceiro=COALESCE(NULLIF(excluded.uf_parceiro, ''), xml_arquivo.uf_parceiro),
                resumo_json=COALESCE(excluded.resumo_json, xml_arquivo.resumo_json),
                cfops=COALESCE(NULLIF(excluded.cfops, ''), xml_arquivo.cfops)
            """,
            (
                chave,
                cnpj,
                numero,
                str(res.get("Série") or res.get("Serie") or ""),
                str(res.get("Tipo") or ""),
                str(res.get("Status") or ""),
                ano,
                mes,
                1 if is_propria else 0,
                str(res.get("Operacao") or res.get("Operação") or ""),
                slug_db,
                nome_xml,
                str(rel).replace("\\", "/"),
                caminho_origem,
                agora,
                agora,
                sha,
                data_emissao,
                usuario_reg,
                uf_parceiro or None,
                resumo_js,
                cfops_db or None,
            ),
        )
        if isinstance(lote, dict) and lote.get("cnpj") == cnpj:
            lote.setdefault("sha_map", {})[chave] = sha
            lote["pending"] = int(lote.get("pending") or 0) + 1
            if not had_row:
                lote["n_inseridos"] = int(lote.get("n_inseridos") or 0) + 1
            limite_commit = (
                2500
                if os.environ.get("GARIMPEIRO_HEADLESS") == "1"
                else _ARQUIVO_FISCAL_GRAVAR_LOTE_COMMIT_A_CADA
            )
            if lote["pending"] >= limite_commit:
                conn.commit()
                lote["pending"] = 0
        elif own_conn:
            conn.commit()
    finally:
        if own_conn:
            conn.close()
    if own_conn:
        _arquivo_fiscal_marcar_excel_desatualizado(cnpj)
    # Só remove ficheiro antigo do MESMO tipo (ex.: reindexar cancelamento).
    # Nunca apaga a autorizada ao gravar o cancelamento (chaves de índice diferentes).
    if old_rel and old_rel != rel_s:
        old_path = _arquivo_fiscal_pasta_empresa(cnpj) / old_rel.replace("/", os.sep)
        try:
            if old_path.is_file():
                op = str(old_path).replace("\\", "/").lower()
                dp = str(dest).replace("\\", "/").lower()
                if op != dp:
                    old_path.unlink()
        except OSError:
            pass
    em_lote = isinstance(lote, dict) and lote.get("cnpj") == cnpj
    if not em_lote:
        if ano is not None and mes is not None:
            _arquivo_fiscal_marcar_zip_mes(cnpj, ano, mes)
        else:
            comp = _arquivo_fiscal_mes_de_slug(slug_rel)
            if comp:
                _arquivo_fiscal_marcar_zip_mes(cnpj, comp[0], comp[1])
    if not em_lote:
        _arquivo_fiscal_invalidar_runtime_cache(cnpj)
    else:
        lote["n_gravados"] = int(lote.get("n_gravados") or 0) + 1
    return True


def _arquivo_fiscal_registar_inutil_manual(
    cnpj_empresa: str,
    tipo: str,
    serie: str,
    nota: int,
    data_iso: str | None = None,
) -> bool:
    """Regista inutilização manual no SQLite (lista Sefaz) para o cálculo de buracos."""
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj_empresa)
    if len(cnpj) != 14:
        return False
    mod = _normaliza_modelo_filtro(tipo)
    ser = _normaliza_serie_filtro(serie)
    try:
        num = int(nota)
    except (TypeError, ValueError):
        return False
    if not mod or not ser or num <= 0:
        return False
    agora = datetime.now().isoformat(timespec="seconds")
    conn = _arquivo_fiscal_conn(cnpj)
    try:
        _arquivo_fiscal_registar_inutil_manual_em_conn(
            conn, cnpj, mod, ser, num, agora, data_iso
        )
        conn.commit()
    finally:
        conn.close()
    _arquivo_fiscal_invalidar_runtime_cache(cnpj)
    return True


def _arquivo_fiscal_atualizar_apos_inutilizadas(cnpj_limpo: str) -> None:
    """
    Após inutilizadas manuais (Sefaz): invalida caches de buracos/Excel.
    O Excel é remontado em segundo plano (garantir_excel_empresa).
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj_limpo)
    if len(cx) != 14:
        return
    _arquivo_fiscal_invalidar_runtime_cache(cx)
    _arquivo_fiscal_apagar_cache_ui_disco(cx)
    _arquivo_fiscal_marcar_excel_desatualizado(cx)


def _arquivo_fiscal_extrair_chaves44(texto: str) -> list[str]:
    """Extrai chaves de 44 dígitos de texto colado (uma por linha ou em bloco)."""
    out: list[str] = []
    seen: set[str] = set()
    for linha in str(texto or "").splitlines():
        k = _chave44_digitos(linha)
        if k and k not in seen:
            seen.add(k)
            out.append(k)
    blob = "".join(ch if ch.isdigit() else " " for ch in str(texto or ""))
    for m in re.finditer(r"\d{44}", blob):
        k = m.group(0)
        if k not in seen:
            seen.add(k)
            out.append(k)
    return out


def _arquivo_fiscal_marcar_chaves_como_canceladas(
    cnpj_empresa: str,
    chaves: list[str] | str,
    *,
    is_propria: int | None = None,
) -> tuple[int, int, int, str]:
    """
    Marca notas já indexadas como CANCELADOS quando só existe o XML autorizado
    (sem evento de cancelamento). Move o XML para a pasta Canceladas (EP_/T_).

    Devolve (marcadas, ja_canceladas, nao_encontradas, mensagem).
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj_empresa)
    if len(cx) != 14:
        return 0, 0, 0, "CNPJ inválido."
    if isinstance(chaves, str):
        lista = _arquivo_fiscal_extrair_chaves44(chaves)
    else:
        lista = []
        seen: set[str] = set()
        for raw in chaves or []:
            k = _chave44_digitos(raw)
            if k and k not in seen:
                seen.add(k)
                lista.append(k)
    if not lista:
        return 0, 0, 0, "Nenhuma chave de 44 dígitos encontrada no texto."

    emp = _arquivo_fiscal_pasta_empresa(cx)
    agora = datetime.now().isoformat(timespec="seconds")
    marcadas = 0
    ja_ok = 0
    ausentes = 0
    erros = 0
    meses_zip: set[tuple[int, int]] = set()

    conn = _arquivo_fiscal_conn(cx)
    try:
        for chave in lista:
            row = conn.execute(
                """
                SELECT status, numero, serie, modelo, ano, mes, is_propria,
                       operacao, slug_pasta, nome_arquivo, caminho_relativo,
                       data_emissao
                FROM xml_arquivo WHERE chave = ?
                """,
                (chave,),
            ).fetchone()
            if not row:
                ausentes += 1
                continue
            (
                status,
                numero,
                serie,
                modelo,
                ano,
                mes,
                is_propria_row,
                operacao,
                slug_pasta,
                nome_arquivo,
                caminho_relativo,
                data_emissao_db,
            ) = row
            if is_propria is not None and int(is_propria_row or 0) != int(is_propria):
                ausentes += 1
                continue
            st_u = str(status or "").strip().upper()
            ja_evento = conn.execute(
                "SELECT 1 FROM xml_arquivo WHERE chave = ? LIMIT 1",
                (f"{chave}#CANCELADOS",),
            ).fetchone()
            if ja_evento:
                # Evento já no índice: não marcar também a autorizada (duplicava no painel).
                ja_ok += 1
                continue
            if st_u == "CANCELADOS":
                ja_ok += 1
                continue
            if st_u and st_u not in ("NORMAIS", "AUTORIZADAS", ""):
                # denegada/rejeitada/inutil — não forçar cancelamento
                erros += 1
                continue
            try:
                a = int(ano) if ano is not None else 0
                m = int(mes) if mes is not None else 0
            except (TypeError, ValueError):
                a, m = 0, 0

            novo_rel = str(caminho_relativo or "").replace("\\", "/")
            slug_db = str(slug_pasta or "")
            src = emp / str(caminho_relativo or "").replace("/", os.sep)
            data_em = _arquivo_fiscal_dh_emi_de_xml(src, chave) or str(
                data_emissao_db or ""
            ).strip()
            if a > 0 and 1 <= m <= 12:
                novo_slug_rel = _arquivo_fiscal_pasta_xml_de_registo(
                    a,
                    m,
                    is_propria=int(is_propria_row or 0),
                    status="CANCELADOS",
                    serie=str(serie or "0"),
                    modelo=str(modelo or ""),
                    operacao=str(operacao or "") or None,
                )
                slug_db = _arquivo_fiscal_slug_db_de_pasta(novo_slug_rel)
                nome_xml = str(nome_arquivo or f"{chave}.xml").strip() or f"{chave}.xml"
                if not nome_xml.lower().endswith(".xml"):
                    nome_xml = f"{nome_xml}.xml"
                novo_rel = (
                    f"{_ARQUIVO_FISCAL_SUBPASTA_XML}/{novo_slug_rel}/{nome_xml}"
                ).replace("\\", "/")
                src = emp / str(caminho_relativo or "").replace("/", os.sep)
                dest = emp / novo_rel.replace("/", os.sep)
                if src.is_file() and src.resolve() != dest.resolve():
                    dest.parent.mkdir(parents=True, exist_ok=True)
                    if not _arquivo_fiscal_mover_xml_seguro(src, dest):
                        erros += 1
                        continue
                    if not data_em:
                        data_em = _arquivo_fiscal_dh_emi_de_xml(dest, chave)

            conn.execute(
                """
                UPDATE xml_arquivo
                SET status = ?, slug_pasta = ?, caminho_relativo = ?,
                    atualizado_em = ?,
                    data_emissao = COALESCE(NULLIF(?, ''), data_emissao)
                WHERE chave = ?
                """,
                ("CANCELADOS", slug_db, novo_rel, agora, data_em or "", chave),
            )
            marcadas += 1
            if a > 0 and 1 <= m <= 12:
                meses_zip.add((a, m))
        conn.commit()
    finally:
        conn.close()

    for a, m in meses_zip:
        _arquivo_fiscal_marcar_zip_mes(cx, a, m)
    _arquivo_fiscal_invalidar_runtime_cache(cx)
    _arquivo_fiscal_apagar_cache_ui_disco(cx)
    _arquivo_fiscal_marcar_excel_desatualizado(cx)
    if meses_zip:
        _arquivo_fiscal_processar_zips_pendentes(cx)

    msg = (
        f"Canceladas por chave: {marcadas} marcada(s)"
        f" · {ja_ok} já estavam canceladas"
        f" · {ausentes} não encontradas no arquivo"
    )
    if erros:
        msg += f" · {erros} ignorada(s) (outro status / falha ao mover)"
    return marcadas, ja_ok, ausentes, msg


def _arquivo_fiscal_chaves_autorizadas_por_numero(
    cnpj_empresa: str,
    serie: str,
    nota: int,
    modelo: str | None = None,
    *,
    is_propria: int = 1,
) -> list[str]:
    """Chaves de XML autorizados (NORMAIS/CANCELADOS) com esta série/número e lado EP/T."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj_empresa)
    ser = _normaliza_serie_filtro(serie)
    mod = _normaliza_modelo_filtro(modelo) if modelo else ""
    try:
        num = int(nota)
    except (TypeError, ValueError):
        return []
    lado = 1 if int(is_propria) else 0
    if len(cx) != 14 or not ser or num <= 0:
        return []
    conn = _arquivo_fiscal_conn(cx)
    try:
        if mod:
            rows = conn.execute(
                """
                SELECT chave, upper(trim(COALESCE(status, ''))) AS st
                FROM xml_arquivo
                WHERE cnpj_empresa = ? AND is_propria = ?
                  AND numero = ?
                  AND trim(serie) = trim(?)
                  AND upper(trim(COALESCE(modelo, ''))) = upper(trim(?))
                  AND instr(chave, '#') = 0
                """,
                (cx, lado, num, ser, mod),
            ).fetchall()
        else:
            rows = conn.execute(
                """
                SELECT chave, upper(trim(COALESCE(status, ''))) AS st
                FROM xml_arquivo
                WHERE cnpj_empresa = ? AND is_propria = ?
                  AND numero = ?
                  AND trim(serie) = trim(?)
                  AND instr(chave, '#') = 0
                """,
                (cx, lado, num, ser),
            ).fetchall()
    finally:
        conn.close()
    out: list[str] = []
    seen: set[str] = set()
    for chave, st in rows:
        k = _chave44_digitos(chave) or str(chave or "").strip()
        if not k or k in seen or k.startswith("MANUAL_"):
            continue
        st_u = str(st or "").strip().upper()
        if st_u and st_u not in ("NORMAIS", "AUTORIZADAS", "CANCELADOS", ""):
            continue
        seen.add(k)
        out.append(k)
    return out


def _arquivo_fiscal_marcar_numeros_como_canceladas(
    cnpj_empresa: str,
    itens: list[tuple[str, str, int]] | None,
    *,
    is_propria: int = 1,
) -> tuple[int, int, int, str]:
    """
    Marca como canceladas a partir de (modelo, série, nota).
    Modelo pode ir vazio. is_propria=1 emissão própria, 0 terceiros.
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj_empresa)
    if len(cx) != 14:
        return 0, 0, 0, "CNPJ inválido."
    lado = 1 if int(is_propria) else 0
    lado_txt = "emissão própria" if lado else "terceiros"
    chaves: list[str] = []
    seen: set[str] = set()
    n_lin = 0
    for item in itens or []:
        if not item or len(item) < 3:
            continue
        mod, ser, nota = item[0], item[1], item[2]
        n_lin += 1
        for k in _arquivo_fiscal_chaves_autorizadas_por_numero(
            cx, ser, nota, mod or None, is_propria=lado
        ):
            if k not in seen:
                seen.add(k)
                chaves.append(k)
    if not chaves:
        return (
            0,
            0,
            n_lin,
            f"{n_lin} linha(s), nenhuma nota autorizada encontrada "
            f"no arquivo com essa série e número ({lado_txt}).",
        )
    marcadas, ja_ok, ausentes, msg = _arquivo_fiscal_marcar_chaves_como_canceladas(
        cx, chaves, is_propria=lado
    )
    extra = (
        f"{lado_txt.capitalize()}: {n_lin} linha(s) → {len(chaves)} chave(s) no arquivo. "
    )
    return marcadas, ja_ok, ausentes, extra + msg


def _arquivo_fiscal_xml_parece_evento_cancelamento(path: Path) -> bool:
    """True = XML de evento/procEvento de cancelamento (não é a NF autorizada)."""
    try:
        raw = path.read_bytes()[:12000]
    except OSError:
        return False
    t = raw.decode("utf-8", errors="ignore").lower().replace(" ", "")
    if "tpevento>110111" in t or "<tpevento>110111" in t:
        return True
    if "procevento" in t and ("cancelament" in t or "110111" in t):
        return True
    if "infevento" in t and "110111" in t:
        return True
    return False


def _arquivo_fiscal_chaves_canceladas_marcacao_manual(
    cnpj_empresa: str,
    *,
    ano: int | None = None,
    mes: int | None = None,
) -> list[str]:
    """
    Notas CANCELADOS que são marcação manual (XML de autorização), não evento.
    Se ano/mês forem dados, só esse mês de competência.
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj_empresa)
    if len(cx) != 14:
        return []
    emp = _arquivo_fiscal_pasta_empresa(cx)
    sql = """
            SELECT chave, nome_arquivo, caminho_relativo
            FROM xml_arquivo
            WHERE upper(trim(COALESCE(status, ''))) = 'CANCELADOS'
              AND instr(chave, '#') = 0
    """
    params: list = []
    if ano is not None:
        sql += " AND CAST(ano AS INTEGER) = ?"
        params.append(int(ano))
    if mes is not None:
        sql += " AND CAST(mes AS INTEGER) = ?"
        params.append(int(mes))
    conn = _arquivo_fiscal_conn(cx)
    try:
        rows = conn.execute(sql, params).fetchall()
    finally:
        conn.close()
    out: list[str] = []
    for chave, nome_arquivo, caminho_relativo in rows:
        k = _chave44_digitos(chave) or str(chave or "").strip()
        if len(k) != 44:
            continue
        nome_l = str(nome_arquivo or "").strip().lower()
        rel = str(caminho_relativo or "").replace("\\", "/")
        rel_l = rel.lower()
        if "_cancelamento" in nome_l or "_cancelamento" in rel_l:
            continue
        src = emp / rel.replace("/", os.sep) if rel else None
        if src is not None and src.is_file() and _arquivo_fiscal_xml_parece_evento_cancelamento(src):
            continue
        out.append(k)
    return out


def _arquivo_fiscal_desmarcar_todas_canceladas_manuais(
    cnpj_empresa: str,
    *,
    ano: int | None = None,
    mes: int | None = None,
) -> tuple[int, int, int, str]:
    """
    Desfaz marcações manuais (opcionalmente só de um mês).
    Mantém cancelamentos que vieram do XML de evento.
    """
    lista = _arquivo_fiscal_chaves_canceladas_marcacao_manual(
        cnpj_empresa, ano=ano, mes=mes
    )
    if not lista:
        if ano is not None and mes is not None:
            return 0, 0, 0, (
                f"Nenhuma cancelada manual em {int(mes):02d}/{int(ano)}. "
                "As que vieram do XML de cancelamento ficaram como estão."
            )
        return 0, 0, 0, (
            "Nenhuma cancelada manual encontrada. "
            "As que vieram do XML de cancelamento ficaram como estão."
        )
    n_ok, n_reais, n_aus, msg = _arquivo_fiscal_desmarcar_chaves_canceladas_manuais(
        cnpj_empresa, lista
    )
    if ano is not None and mes is not None:
        msg = f"{int(mes):02d}/{int(ano)} — {msg}"
    return n_ok, n_reais, n_aus, msg


def _arquivo_fiscal_desmarcar_chaves_canceladas_manuais(
    cnpj_empresa: str,
    chaves: list[str] | str,
    *,
    is_propria: int | None = None,
) -> tuple[int, int, int, str]:
    """
    Desfaz a marcação manual (ecrã Canceladas): volta status para NORMAIS
    e move o XML da pasta Canceladas para Autorizadas.

    Não altera cancelamentos reais (ficheiro *_cancelamento.xml, chave #CANCELADOS
    ou XML de evento 110111).
    Devolve (revertidas, ignoradas_reais, nao_encontradas, mensagem).
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj_empresa)
    if len(cx) != 14:
        return 0, 0, 0, "CNPJ inválido."
    if isinstance(chaves, str):
        lista = _arquivo_fiscal_extrair_chaves44(chaves)
    else:
        lista = []
        seen: set[str] = set()
        for raw in chaves or []:
            k = _chave44_digitos(raw)
            if k and k not in seen:
                seen.add(k)
                lista.append(k)
    if not lista:
        return 0, 0, 0, "Nenhuma chave de 44 dígitos encontrada no texto."

    emp = _arquivo_fiscal_pasta_empresa(cx)
    agora = datetime.now().isoformat(timespec="seconds")
    revertidas = 0
    reais = 0
    ausentes = 0
    erros = 0
    meses_zip: set[tuple[int, int]] = set()

    conn = _arquivo_fiscal_conn(cx)
    try:
        for chave in lista:
            row = conn.execute(
                """
                SELECT status, numero, serie, modelo, ano, mes, is_propria,
                       operacao, slug_pasta, nome_arquivo, caminho_relativo
                FROM xml_arquivo WHERE chave = ?
                """,
                (chave,),
            ).fetchone()
            if not row:
                ausentes += 1
                continue
            (
                status,
                numero,
                serie,
                modelo,
                ano,
                mes,
                is_propria_row,
                operacao,
                slug_pasta,
                nome_arquivo,
                caminho_relativo,
            ) = row
            if is_propria is not None and int(is_propria_row or 0) != int(is_propria):
                ausentes += 1
                continue
            st_u = str(status or "").strip().upper()
            nome_l = str(nome_arquivo or "").strip().lower()
            rel_l = str(caminho_relativo or "").replace("\\", "/").lower()
            if "_cancelamento" in nome_l or "_cancelamento" in rel_l:
                reais += 1
                continue
            src_chk = emp / str(caminho_relativo or "").replace("/", os.sep)
            if src_chk.is_file() and _arquivo_fiscal_xml_parece_evento_cancelamento(src_chk):
                reais += 1
                continue
            if st_u != "CANCELADOS":
                ausentes += 1
                continue
            try:
                a = int(ano) if ano is not None else 0
                m = int(mes) if mes is not None else 0
            except (TypeError, ValueError):
                a, m = 0, 0

            novo_rel = str(caminho_relativo or "").replace("\\", "/")
            slug_db = str(slug_pasta or "")
            if a > 0 and 1 <= m <= 12:
                novo_slug_rel = _arquivo_fiscal_pasta_xml_de_registo(
                    a,
                    m,
                    is_propria=int(is_propria_row or 0),
                    status="NORMAIS",
                    serie=str(serie or "0"),
                    modelo=str(modelo or ""),
                    operacao=str(operacao or "") or None,
                )
                slug_db = _arquivo_fiscal_slug_db_de_pasta(novo_slug_rel)
                nome_xml = str(nome_arquivo or f"{chave}.xml").strip() or f"{chave}.xml"
                if not nome_xml.lower().endswith(".xml"):
                    nome_xml = f"{nome_xml}.xml"
                novo_rel = (
                    f"{_ARQUIVO_FISCAL_SUBPASTA_XML}/{novo_slug_rel}/{nome_xml}"
                ).replace("\\", "/")
                src = emp / str(caminho_relativo or "").replace("/", os.sep)
                dest = emp / novo_rel.replace("/", os.sep)
                if src.is_file() and src.resolve() != dest.resolve():
                    dest.parent.mkdir(parents=True, exist_ok=True)
                    if not _arquivo_fiscal_mover_xml_seguro(src, dest):
                        erros += 1
                        continue

            conn.execute(
                """
                UPDATE xml_arquivo
                SET status = ?, slug_pasta = ?, caminho_relativo = ?,
                    atualizado_em = ?
                WHERE chave = ?
                """,
                ("NORMAIS", slug_db, novo_rel, agora, chave),
            )
            revertidas += 1
            if a > 0 and 1 <= m <= 12:
                meses_zip.add((a, m))
        conn.commit()
    finally:
        conn.close()

    for a, m in meses_zip:
        _arquivo_fiscal_marcar_zip_mes(cx, a, m)
    _arquivo_fiscal_invalidar_runtime_cache(cx)
    _arquivo_fiscal_apagar_cache_ui_disco(cx)
    _arquivo_fiscal_marcar_excel_desatualizado(cx)
    if meses_zip:
        _arquivo_fiscal_processar_zips_pendentes(cx)

    msg = (
        f"Desfazer marcação: {revertidas} voltou(aram) a autorizadas"
        f" · {reais} ignorada(s) (cancelamento real no XML)"
        f" · {ausentes} não estavam como canceladas manuais / não encontradas"
    )
    if erros:
        msg += f" · {erros} falha(s) ao mover o XML"
    return revertidas, reais, ausentes, msg


def _arquivo_fiscal_sincronizar_inutilizadas_do_relatorio(cnpj_empresa: str) -> int:
    """Copia inutilizações manuais do relatório da sessão para o arquivo fiscal."""
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj_empresa)
    if len(cnpj) != 14:
        return 0
    n = 0
    for item in _relatorio_get_list() or []:
        if not _inutil_sem_xml_manual(item):
            continue
        mod = str(item.get("Tipo") or "").strip()
        ser = str(item.get("Série") or "").strip()
        try:
            nota = int(item.get("Número") or 0)
        except (TypeError, ValueError):
            continue
        if _arquivo_fiscal_aplicar_inutil_numero(cnpj, mod, ser, nota) in (
            "promovida",
            "nova",
        ):
            n += 1
    return n


def _arquivo_fiscal_faixa_numeracao_para_inutil(
    cnpj: str,
) -> dict[tuple[str, str], tuple[int, int]]:
    """Intervalo min–max por (modelo, série) a partir do arquivo fiscal indexado."""
    raw = _arquivo_fiscal_faixa_numeros_por_serie(cnpj)
    out: dict[tuple[str, str], tuple[int, int]] = {}
    for key, (mn, mx, _ur) in raw.items():
        if "|" not in str(key):
            continue
        mod, ser = str(key).split("|", 1)
        mod = _normaliza_modelo_filtro(mod.strip())
        ser = _normaliza_serie_filtro(ser.strip())
        if not mod or not ser or mx <= 0:
            continue
        k = (mod, ser)
        ini, fim = int(mn), int(mx)
        if k in out:
            o_ini, o_fim = out[k]
            out[k] = (min(o_ini, ini), max(o_fim, fim))
        else:
            out[k] = (ini, fim)
    return out


def _arquivo_fiscal_faixa_series_em_conn(
    conn: sqlite3.Connection,
    cnpj: str,
    pares: set[tuple[str, str]],
) -> dict[tuple[str, str], tuple[int, int]]:
    """MIN/MAX só das séries da lista — não varre o arquivo inteiro em memória."""
    out: dict[tuple[str, str], tuple[int, int]] = {}
    series = sorted({s for _m, s in pares if s})
    if not series:
        return out
    ph = ",".join("?" * len(series))
    rows = conn.execute(
        f"""
        SELECT modelo, serie, MIN(numero), MAX(numero)
        FROM xml_arquivo
        WHERE cnpj_empresa = ? AND is_propria = 1
          AND numero IS NOT NULL AND numero > 0
          AND trim(serie) IN ({ph})
          AND upper(trim(COALESCE(status, ''))) != 'INUTILIZADOS'
        GROUP BY modelo, serie
        """,
        (cnpj, *series),
    ).fetchall()
    pares_n = {
        (_normaliza_modelo_filtro(m), _normaliza_serie_filtro(s)) for m, s in pares
    }
    for mod, ser, nmin, nmax in rows:
        mod_n = _normaliza_modelo_filtro(mod)
        ser_n = _normaliza_serie_filtro(ser)
        if (mod_n, ser_n) not in pares_n:
            continue
        try:
            ini = int(nmin)
            fim = int(nmax)
        except (TypeError, ValueError):
            continue
        if fim <= 0:
            continue
        k = (mod_n, ser_n)
        if k in out:
            o_ini, o_fim = out[k]
            out[k] = (min(o_ini, ini), max(o_fim, fim))
        else:
            out[k] = (ini, fim)
    return out


def _descricao_faixa_inutil(
    mod: str, ser: str, faixa: dict[tuple[str, str], tuple[int, int]]
) -> str:
    lim = _faixa_xml_lookup(mod, ser, faixa)
    if lim is None:
        series = sorted(
            {s for (m, s) in faixa if _normaliza_modelo_filtro(m) == _normaliza_modelo_filtro(mod)}
        )
        if series:
            return (
                f"Sem XML indexados para {mod} série {ser}. "
                f"Séries com XML para este modelo: {', '.join(series)}."
            )
        return f"Sem XML de emissão própria indexados para {mod} série {ser}."
    return f"Intervalo indexado para {mod} série {ser}: notas {lim[0]:,} a {lim[1]:,}.".replace(",", ".")


def _arquivo_fiscal_inutil_ja_registada(
    cnpj: str,
    tipo: str,
    serie: str,
    nota: int,
) -> bool:
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj)
    mod = _normaliza_modelo_filtro(tipo)
    ser = _normaliza_serie_filtro(serie)
    try:
        num = int(nota)
    except (TypeError, ValueError):
        return False
    if len(cnpj) != 14 or not mod or not ser or num <= 0:
        return False
    conn = _arquivo_fiscal_conn(cnpj)
    try:
        row = conn.execute(
            """
            SELECT 1 FROM xml_arquivo
            WHERE cnpj_empresa = ? AND is_propria = 1
              AND upper(trim(COALESCE(status, ''))) = 'INUTILIZADOS'
              AND upper(trim(modelo)) = upper(trim(?))
              AND trim(serie) = trim(?)
              AND numero = ?
            LIMIT 1
            """,
            (cnpj, mod, ser, num),
        ).fetchone()
        return row is not None
    finally:
        conn.close()


_ST_INUTIL_NAO_SOBREPOR = frozenset({"NORMAIS", "CANCELADOS", "DENEGADOS"})


def _arquivo_fiscal_registar_inutil_manual_em_conn(
    conn: sqlite3.Connection,
    cnpj: str,
    mod: str,
    ser: str,
    num: int,
    agora: str,
    data_iso: str | None = None,
) -> bool:
    chave = f"MANUAL_INUT_{mod}_{ser}_{num}"
    rel = f"{_ARQUIVO_FISCAL_SUBPASTA_XML}/manual_inutilizadas/{chave}.txt"
    iso = (str(data_iso).strip() or None) if data_iso else None
    ano_i, mes_i = _arquivo_fiscal_ano_mes_de_iso(iso)
    conn.execute(
        """
        INSERT INTO xml_arquivo (
            chave, cnpj_empresa, numero, serie, modelo, status, ano, mes,
            is_propria, operacao, slug_pasta, nome_arquivo, caminho_relativo,
            caminho_origem, capturado_em, atualizado_em, sha256, data_emissao
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(chave) DO UPDATE SET
            numero=excluded.numero, serie=excluded.serie, modelo=excluded.modelo,
            status=excluded.status, is_propria=excluded.is_propria,
            atualizado_em=excluded.atualizado_em,
            ano=COALESCE(excluded.ano, xml_arquivo.ano),
            mes=COALESCE(excluded.mes, xml_arquivo.mes),
            data_emissao=COALESCE(
                NULLIF(excluded.data_emissao, ''),
                xml_arquivo.data_emissao
            )
        """,
        (
            chave,
            cnpj,
            num,
            ser,
            mod,
            "INUTILIZADOS",
            ano_i,
            mes_i,
            1,
            "SAIDA",
            "manual_inutilizadas",
            f"{chave}.txt",
            rel,
            "REGISTRO_MANUAL_SEFAZ",
            agora,
            agora,
            "",
            iso,
        ),
    )
    return True


def _arquivo_fiscal_aplicar_inutil_numero_em_conn(
    conn: sqlite3.Connection,
    cnpj: str,
    mod: str,
    ser: str,
    num: int,
    agora: str,
    data_iso: str | None = None,
) -> str:
    rows = conn.execute(
        """
        SELECT chave, upper(trim(COALESCE(status, ''))) AS st
        FROM xml_arquivo
        WHERE cnpj_empresa = ? AND is_propria = 1
          AND upper(trim(modelo)) = upper(trim(?))
          AND trim(serie) = trim(?)
          AND numero = ?
        """,
        (cnpj, mod, ser, num),
    ).fetchall()
    sts = {str(st or "").strip().upper() for _ch, st in rows}
    if sts & _ST_INUTIL_NAO_SOBREPOR:
        return "ocupada"
    n_prom = conn.execute(
        """
        UPDATE xml_arquivo
        SET status = 'INUTILIZADOS', atualizado_em = ?
        WHERE cnpj_empresa = ? AND is_propria = 1
          AND upper(trim(modelo)) = upper(trim(?))
          AND trim(serie) = trim(?)
          AND numero = ?
          AND upper(trim(COALESCE(status, ''))) = 'REJEITADOS'
        """,
        (agora, cnpj, mod, ser, num),
    ).rowcount
    dt = str(data_iso).strip() if data_iso else ""
    if int(n_prom or 0) > 0:
        chave_man = f"MANUAL_INUT_{mod}_{ser}_{num}"
        conn.execute(
            "DELETE FROM xml_arquivo WHERE cnpj_empresa = ? AND chave = ?",
            (cnpj, chave_man),
        )
        if dt:
            conn.execute(
                """
                UPDATE xml_arquivo
                SET data_emissao = ?
                WHERE cnpj_empresa = ? AND is_propria = 1
                  AND upper(trim(modelo)) = upper(trim(?))
                  AND trim(serie) = trim(?)
                  AND numero = ?
                  AND upper(trim(COALESCE(status, ''))) = 'INUTILIZADOS'
                """,
                (dt, cnpj, mod, ser, num),
            )
        return "promovida"
    if "INUTILIZADOS" in sts:
        if dt:
            conn.execute(
                """
                UPDATE xml_arquivo
                SET data_emissao = ?, atualizado_em = ?
                WHERE cnpj_empresa = ? AND is_propria = 1
                  AND upper(trim(modelo)) = upper(trim(?))
                  AND trim(serie) = trim(?)
                  AND numero = ?
                  AND upper(trim(COALESCE(status, ''))) = 'INUTILIZADOS'
                """,
                (dt, agora, cnpj, mod, ser, num),
            )
        return "dup"
    if _arquivo_fiscal_registar_inutil_manual_em_conn(
        conn, cnpj, mod, ser, num, agora, data_iso
    ):
        return "nova"
    return "falhou"


def _arquivo_fiscal_aplicar_inutil_numero(
    cnpj_empresa: str,
    tipo: str,
    serie: str,
    nota: int,
    data_iso: str | None = None,
) -> str:
    """
    Marca o número como inutilizado no arquivo.

    - promovida: XML rejeitado passa a INUTILIZADOS (a Sefaz inutilizou o número)
    - nova: não havia XML; cria o registo manual
    - dup: já estava inutilizado
    - ocupada: já existe autorizada/cancelada/denegada — não altera
    - falhou: dados inválidos ou erro a gravar
    """
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj_empresa)
    mod = _normaliza_modelo_filtro(tipo)
    ser = _normaliza_serie_filtro(serie)
    try:
        num = int(nota)
    except (TypeError, ValueError):
        return "falhou"
    if len(cnpj) != 14 or not mod or not ser or num <= 0:
        return "falhou"
    agora = datetime.now().isoformat(timespec="seconds")
    conn = _arquivo_fiscal_conn(cnpj)
    try:
        r = _arquivo_fiscal_aplicar_inutil_numero_em_conn(
            conn, cnpj, mod, ser, num, agora, data_iso
        )
        conn.commit()
        if r in ("promovida", "nova"):
            _arquivo_fiscal_invalidar_runtime_cache(cnpj)
        return r
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()


def _arquivo_fiscal_buracos_numeros_mod_serie(
    cnpj: str,
    modelo: str,
    serie: str,
) -> list[int]:
    """Notas em buraco (emissão própria) para modelo/série em todo o arquivo indexado."""
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj)
    mod = _normaliza_modelo_filtro(modelo)
    ser = _normaliza_serie_filtro(serie)
    if len(cnpj) != 14 or not mod or not ser:
        return []
    comp = _arquivo_fiscal_competencias_resumo(cnpj)
    if not comp:
        return []
    nums: set[int] = set()
    for ano in sorted({a for a, _ in comp.keys()}, reverse=True):
        meses = sorted(m for m in range(1, 13) if (int(ano), m) in comp)
        if not meses:
            continue
        df = _arquivo_fiscal_buracos_reais_periodo(cnpj, int(ano), meses)
        if df is None or df.empty:
            continue
        if "Serie" in df.columns and "Série" not in df.columns:
            df = df.rename(columns={"Serie": "Série"})
        if not {"Tipo", "Série", "Num_Faltante"}.issubset(df.columns):
            continue
        sub = df[
            (df["Tipo"].astype(str) == mod) & (df["Série"].astype(str) == ser)
        ]
        for n in sub["Num_Faltante"].astype(int).unique():
            nums.add(int(n))
    return sorted(nums)


def _arquivo_fiscal_contar_inutilizadas(cnpj: str) -> tuple[int, int]:
    """Total de inutilizadas no arquivo e quantas são registo manual Sefaz."""
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cnpj) != 14:
        return 0, 0
    conn = _arquivo_fiscal_conn(cnpj)
    try:
        tot = conn.execute(
            """
            SELECT COUNT(*) FROM xml_arquivo
            WHERE cnpj_empresa = ? AND is_propria = 1
              AND upper(trim(COALESCE(status, ''))) = 'INUTILIZADOS'
            """,
            (cnpj,),
        ).fetchone()[0]
        man = conn.execute(
            """
            SELECT COUNT(*) FROM xml_arquivo
            WHERE cnpj_empresa = ? AND is_propria = 1
              AND upper(trim(COALESCE(status, ''))) = 'INUTILIZADOS'
              AND chave LIKE 'MANUAL_INUT_%'
            """,
            (cnpj,),
        ).fetchone()[0]
        return int(tot or 0), int(man or 0)
    finally:
        conn.close()


def _arquivo_fiscal_kind_inutil_manual(
    chave,
    slug_pasta=None,
    caminho_origem=None,
    caminho_relativo=None,
) -> str:
    """
    stub = lista Sefaz sem XML; promovida = rejeitada marcada nesta guia.
    Vazio = inutilização real (XML) — não eliminar.
    """
    ch = str(chave or "").strip()
    rel = str(caminho_relativo or "").replace("\\", "/").lower()
    slug = str(slug_pasta or "").strip().lower()
    orig = str(caminho_origem or "").strip()
    if (
        ch.startswith("MANUAL_INUT_")
        or slug == "manual_inutilizadas"
        or orig in ("REGISTRO_MANUAL_SEFAZ", "REGISTRO_MANUAL")
        or "manual_inutilizadas" in rel
        or rel.endswith(".txt")
    ):
        return "stub"
    k44 = _chave44_digitos(ch)
    if k44 and ("rejeitad" in rel or "rejeit" in slug):
        return "promovida"
    return ""


def _arquivo_fiscal_listar_inutilizadas_manuais(
    cnpj: str,
    *,
    ano: int | None = None,
    mes: int | None = None,
) -> list[dict]:
    """Inutilizadas criadas na guia Indicar Inutilizadas (sem XML de inutilização)."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14 or not _arquivo_fiscal_db_path(cx).is_file():
        return []
    conn = _arquivo_fiscal_conn(cx)
    try:
        rows = conn.execute(
            """
            SELECT chave, modelo, serie, numero, ano, mes, data_emissao,
                   caminho_relativo, slug_pasta, caminho_origem
            FROM xml_arquivo
            WHERE cnpj_empresa = ? AND is_propria = 1
              AND upper(trim(COALESCE(status, ''))) = 'INUTILIZADOS'
              AND (
                chave LIKE 'MANUAL_INUT_%'
                OR slug_pasta = 'manual_inutilizadas'
                OR caminho_origem IN ('REGISTRO_MANUAL_SEFAZ', 'REGISTRO_MANUAL')
                OR caminho_relativo LIKE '%manual_inutilizadas%'
                OR lower(COALESCE(caminho_relativo, '')) LIKE '%rejeitad%'
                OR lower(COALESCE(slug_pasta, '')) LIKE '%rejeit%'
              )
            ORDER BY modelo, serie, numero
            """,
            (cx,),
        ).fetchall()
    finally:
        conn.close()
    out: list[dict] = []
    for ch, mod, ser, num, ano_db, mes_db, de, rel, slug, orig in rows:
        kind = _arquivo_fiscal_kind_inutil_manual(ch, slug, orig, rel)
        if not kind:
            continue
        try:
            n = int(num) if num is not None else 0
        except (TypeError, ValueError):
            n = 0
        try:
            a = int(ano_db) if ano_db is not None else None
        except (TypeError, ValueError):
            a = None
        try:
            m = int(mes_db) if mes_db is not None else None
        except (TypeError, ValueError):
            m = None
        data_txt = _valor_data_emissao_dd_mm_yyyy(de) if de else "—"
        if a and m and 1 <= m <= 12:
            comp = f"{a:04d}/{m:02d}"
        else:
            comp = "—"
        out.append(
            {
                "chave": str(ch or ""),
                "modelo": _normaliza_modelo_filtro(mod) or str(mod or ""),
                "serie": _normaliza_serie_filtro(ser) or str(ser or ""),
                "numero": n,
                "ano": a,
                "mes": m,
                "data": data_txt or "—",
                "competencia": comp,
                "kind": kind,
                "tipo_txt": (
                    "Lista Sefaz" if kind == "stub" else "Rejeitada promovida"
                ),
                "caminho_relativo": str(rel or ""),
            }
        )
    if ano is not None and mes is not None:
        ano_i, mes_i = int(ano), int(mes)
        por_mes = _arquivo_fiscal_cache_ano(cx, ano_i)["por_mes"]
        filtrados: list[dict] = []
        for it in out:
            a, m = it.get("ano"), it.get("mes")
            if a == ano_i and m == mes_i:
                filtrados.append(it)
                continue
            if a is None or m is None:
                mes_comp = _arquivo_fiscal_inferir_mes_competencia_inutilizada(
                    por_mes,
                    it.get("modelo") or "",
                    it.get("serie") or "",
                    int(it.get("numero") or 0),
                    mes_armazenado=m,
                )
                if mes_comp == mes_i:
                    filtrados.append(it)
        out = filtrados
    return out


def _arquivo_fiscal_eliminar_inutilizadas_manuais(
    cnpj_empresa: str,
    chaves: list[str] | None = None,
    *,
    ano: int | None = None,
    mes: int | None = None,
    triplas: list[tuple[str, str, int]] | None = None,
) -> tuple[int, int, int, str]:
    """
    Remove o que a guia Indicar Inutilizadas gravou à mão.
    Stubs (MANUAL_INUT_) saem do índice; rejeitadas promovidas voltam a REJEITADOS.
    XML de inutilização da Sefaz não é apagado.
    Devolve (stubs, revertidas, ignoradas, mensagem).
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj_empresa)
    if len(cx) != 14:
        return 0, 0, 0, "CNPJ inválido."
    if not chaves and not triplas and not (ano is not None and mes is not None):
        return 0, 0, 0, "Indique as linhas, a lista colada ou o mês do calendário."

    itens = _arquivo_fiscal_listar_inutilizadas_manuais(cx, ano=ano, mes=mes)
    if chaves:
        alvo_ch = {str(c).strip() for c in chaves if str(c).strip()}
        itens = [it for it in itens if it.get("chave") in alvo_ch]
    if triplas:
        pares = set()
        for mod, ser, num in triplas:
            try:
                n = int(num)
            except (TypeError, ValueError):
                continue
            pares.add(
                (
                    _normaliza_modelo_filtro(mod),
                    _normaliza_serie_filtro(ser),
                    n,
                )
            )
        itens = [
            it
            for it in itens
            if (
                _normaliza_modelo_filtro(it.get("modelo")),
                _normaliza_serie_filtro(it.get("serie")),
                int(it.get("numero") or 0),
            )
            in pares
        ]
    if not itens:
        if ano is not None and mes is not None and not chaves and not triplas:
            return 0, 0, 0, (
                f"Nenhuma inutilizada manual em {int(mes):02d}/{int(ano)}."
            )
        return 0, 0, 0, "Nenhum registo manual correspondente para eliminar."

    emp = _arquivo_fiscal_pasta_empresa(cx)
    agora = datetime.now().isoformat(timespec="seconds")
    stubs = 0
    revertidas = 0
    ignoradas = 0
    conn = _arquivo_fiscal_conn(cx)
    try:
        for it in itens:
            ch = str(it.get("chave") or "").strip()
            kind = str(it.get("kind") or "")
            if not ch or kind not in ("stub", "promovida"):
                ignoradas += 1
                continue
            if kind == "stub":
                rel = str(it.get("caminho_relativo") or "").replace("\\", "/")
                conn.execute(
                    "DELETE FROM xml_arquivo WHERE cnpj_empresa = ? AND chave = ?",
                    (cx, ch),
                )
                stubs += 1
                if rel and "manual_inutilizadas" in rel.lower():
                    p = emp / rel.replace("/", os.sep)
                    try:
                        if p.is_file() and p.suffix.lower() == ".txt":
                            p.unlink()
                    except OSError:
                        pass
                continue
            conn.execute(
                """
                UPDATE xml_arquivo
                SET status = 'REJEITADOS', atualizado_em = ?
                WHERE cnpj_empresa = ? AND chave = ?
                  AND upper(trim(COALESCE(status, ''))) = 'INUTILIZADOS'
                """,
                (agora, cx, ch),
            )
            revertidas += 1
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()
    _arquivo_fiscal_atualizar_apos_inutilizadas(cx)
    partes = []
    if stubs:
        partes.append(f"{stubs} da lista Sefaz eliminada(s)")
    if revertidas:
        partes.append(f"{revertidas} rejeitada(s) voltaram ao status original")
    if ignoradas:
        partes.append(f"{ignoradas} ignorada(s)")
    if ano is not None and mes is not None and not chaves and not triplas:
        prefixo = f"{int(mes):02d}/{int(ano)} — "
    else:
        prefixo = ""
    if not partes:
        return 0, 0, ignoradas, prefixo + "Nada foi alterado."
    return stubs, revertidas, ignoradas, prefixo + " · ".join(partes) + "."


def _arquivo_fiscal_contar_canceladas(cnpj: str) -> int:
    """Total de notas canceladas (uma por chave de 44 dígitos)."""
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cnpj) != 14:
        return 0
    conn = _arquivo_fiscal_conn(cnpj)
    try:
        tot = conn.execute(
            """
            SELECT COUNT(*) FROM (
                SELECT CASE
                    WHEN instr(chave, '#') > 0 THEN substr(chave, 1, instr(chave, '#') - 1)
                    ELSE chave
                END AS k44
                FROM xml_arquivo
                WHERE cnpj_empresa = ?
                  AND upper(trim(COALESCE(status, ''))) = 'CANCELADOS'
                GROUP BY k44
            )
            """,
            (cnpj,),
        ).fetchone()[0]
        return int(tot or 0)
    finally:
        conn.close()


def _arquivo_fiscal_indice_rejeitadas_inutilizadas(
    conn: sqlite3.Connection,
    cnpj: str,
    pares: set[tuple[str, str]],
) -> tuple[set[tuple[str, str, int]], set[tuple[str, str, int]]]:
    """Só rejeitadas e já inutilizadas das séries do lote — não lê autorizadas/canceladas."""
    reje = set()
    inut = set()
    if not pares:
        return reje, inut
    rows = conn.execute(
        """
        SELECT modelo, serie, numero, upper(trim(COALESCE(status, '')))
        FROM xml_arquivo
        WHERE cnpj_empresa = ? AND is_propria = 1
          AND upper(trim(COALESCE(status, ''))) IN ('REJEITADOS', 'INUTILIZADOS')
        """,
        (cnpj,),
    )
    for mod, ser, num, st in rows:
        mod_n = _normaliza_modelo_filtro(mod)
        ser_n = _normaliza_serie_filtro(ser)
        if (mod_n, ser_n) not in pares:
            continue
        try:
            n = int(num)
        except (TypeError, ValueError):
            continue
        if n <= 0:
            continue
        k = (mod_n, ser_n, n)
        if st == "REJEITADOS":
            reje.add(k)
        else:
            inut.add(k)
    return reje, inut


def _arquivo_fiscal_contexto_inutil_numeros(
    conn: sqlite3.Connection,
    cnpj: str,
    pares: set[tuple[str, str]],
    numeros: list[int],
) -> tuple[
    set[tuple[str, str, int]],
    set[tuple[str, str, int]],
    set[tuple[str, str, int]],
]:
    """
    Lê só os números da lista (não a série inteira): rejeitadas, já
    inutilizadas e ocupadas (autorizada/cancelada/denegada).
    Número da lista que não aparece no arquivo = buraco.
    """
    reje: set[tuple[str, str, int]] = set()
    inut_keys: set[tuple[str, str, int]] = set()
    ocup: set[tuple[str, str, int]] = set()
    nums = sorted({int(n) for n in numeros if int(n) > 0})
    if not pares or not nums:
        return reje, inut_keys, ocup
    ph = ",".join("?" * len(nums))
    rows = conn.execute(
        f"""
        SELECT modelo, serie, numero, upper(trim(COALESCE(status, '')))
        FROM xml_arquivo
        WHERE cnpj_empresa = ? AND is_propria = 1
          AND numero IN ({ph})
        """,
        (cnpj, *nums),
    ).fetchall()
    st_ocupa = _ARQUIVO_FISCAL_STATUS_COM_NUMERO
    for mod, ser, num, st in rows:
        mod_n = _normaliza_modelo_filtro(mod)
        ser_n = _normaliza_serie_filtro(ser)
        if (mod_n, ser_n) not in pares:
            continue
        try:
            n = int(num)
        except (TypeError, ValueError):
            continue
        if n <= 0:
            continue
        k = (mod_n, ser_n, n)
        st_u = str(st or "").strip().upper()
        if st_u == "REJEITADOS":
            reje.add(k)
        elif st_u == "INUTILIZADOS":
            inut_keys.add(k)
        elif st_u in st_ocupa or st_u:
            ocup.add(k)
    return reje, inut_keys, ocup


def _arquivo_fiscal_aplicar_inutil_lote_buracos_rejeitadas(
    conn: sqlite3.Connection,
    cnpj: str,
    triplas: list[tuple[str, str, int]],
    faixa: dict,
    datas: dict,
    agora: str,
) -> tuple[int, int, int, int, list[tuple[str, str]], int]:
    """
    Cruza a lista da Sefaz com os números da própria lista: rejeitadas sobem;
    ausentes (buraco) entram; autorizadas/canceladas/denegadas não mudam.
    """
    n_ok = n_ign_fora = n_dup = n_prom = n_nao_buraco = 0
    ign_series: list[tuple[str, str]] = []
    seen_ign: set[tuple[str, str]] = set()
    dentro: list[tuple[str, str, int]] = []
    pares: set[tuple[str, str]] = set()
    for mod_n, ser_n, n in triplas:
        if not _tripla_inutil_dentro_faixa_xml(mod_n, ser_n, n, faixa):
            n_ign_fora += 1
            k_ign = (mod_n, ser_n)
            if k_ign not in seen_ign:
                seen_ign.add(k_ign)
                ign_series.append(k_ign)
            continue
        dentro.append((mod_n, ser_n, n))
        pares.add((mod_n, ser_n))
    reje, inut, ocup = _arquivo_fiscal_contexto_inutil_numeros(
        conn, cnpj, pares, [n for _m, _s, n in dentro]
    )
    promover: list[tuple[str, str, int]] = []
    novas: list[tuple[str, str, int]] = []
    for k in dentro:
        if k in reje:
            promover.append(k)
        elif k in inut:
            n_dup += 1
        elif k in ocup:
            n_nao_buraco += 1
        else:
            novas.append(k)
            n_ok += 1
    n_prom = len(promover)
    if promover:
        conn.executemany(
            """
            UPDATE xml_arquivo
            SET status = 'INUTILIZADOS', atualizado_em = ?
            WHERE cnpj_empresa = ? AND is_propria = 1
              AND upper(trim(modelo)) = upper(trim(?))
              AND trim(serie) = trim(?)
              AND numero = ?
              AND upper(trim(COALESCE(status, ''))) = 'REJEITADOS'
            """,
            [(agora, cnpj, m, s, n) for m, s, n in promover],
        )
        conn.executemany(
            "DELETE FROM xml_arquivo WHERE cnpj_empresa = ? AND chave = ?",
            [(cnpj, f"MANUAL_INUT_{m}_{s}_{n}") for m, s, n in promover],
        )
        dts = []
        for m, s, n in promover:
            dt = str(datas.get((m, s, n)) or "").strip()
            if dt:
                dts.append((dt, cnpj, m, s, n))
        if dts:
            conn.executemany(
                """
                UPDATE xml_arquivo
                SET data_emissao = ?
                WHERE cnpj_empresa = ? AND is_propria = 1
                  AND upper(trim(modelo)) = upper(trim(?))
                  AND trim(serie) = trim(?)
                  AND numero = ?
                  AND upper(trim(COALESCE(status, ''))) = 'INUTILIZADOS'
                """,
                dts,
            )
    if novas:
        rows_ins = []
        for m, s, n in novas:
            chave = f"MANUAL_INUT_{m}_{s}_{n}"
            rel = f"{_ARQUIVO_FISCAL_SUBPASTA_XML}/manual_inutilizadas/{chave}.txt"
            dt = datas.get((m, s, n))
            iso = (str(dt).strip() or None) if dt else None
            ano_i, mes_i = _arquivo_fiscal_ano_mes_de_iso(iso)
            rows_ins.append(
                (
                    chave,
                    cnpj,
                    n,
                    s,
                    m,
                    "INUTILIZADOS",
                    ano_i,
                    mes_i,
                    1,
                    "SAIDA",
                    "manual_inutilizadas",
                    f"{chave}.txt",
                    rel,
                    "REGISTRO_MANUAL_SEFAZ",
                    agora,
                    agora,
                    "",
                    iso,
                )
            )
        conn.executemany(
            """
            INSERT INTO xml_arquivo (
                chave, cnpj_empresa, numero, serie, modelo, status, ano, mes,
                is_propria, operacao, slug_pasta, nome_arquivo, caminho_relativo,
                caminho_origem, capturado_em, atualizado_em, sha256, data_emissao
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(chave) DO UPDATE SET
                numero=excluded.numero, serie=excluded.serie, modelo=excluded.modelo,
                status=excluded.status, is_propria=excluded.is_propria,
                atualizado_em=excluded.atualizado_em,
                ano=COALESCE(excluded.ano, xml_arquivo.ano),
                mes=COALESCE(excluded.mes, xml_arquivo.mes),
                data_emissao=COALESCE(
                    NULLIF(excluded.data_emissao, ''),
                    xml_arquivo.data_emissao
                )
            """,
            rows_ins,
        )
    return n_ok, n_ign_fora, n_dup, n_prom, ign_series, n_nao_buraco


def aplicar_inutilizadas_arquivo_fiscal(
    cnpj_limpo: str,
    *,
    up_inut_planilha=None,
    texto_inut_planilha=None,
    pick_bur_inut=None,
    mb_bur=None,
    sb_bur=None,
    mf_faixa: str = "NF-e",
    sf_faixa: str = "",
    n0_faixa: int = 1,
    n1_faixa: int = 1,
) -> tuple[bool, str]:
    """
    Aplica inutilizações usando só o arquivo fiscal já indexado — sem garimpo nesta sessão.
    Atualiza o SQLite (buracos em «Documentos já lidos») e o Excel se existir.
    """
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj_limpo)
    if len(cnpj) != 14:
        return False, "CNPJ inválido — são necessários 14 dígitos."

    linhas: list[str] = []
    triplas_aplicar: list[tuple[str, str, int]] = []
    _seen: set[tuple[str, str, int]] = set()
    _datas: dict[tuple[str, str, int], str] = {}

    def _agendar(mod: str, ser: str, nota: int) -> None:
        mod_n = _normaliza_modelo_filtro(mod)
        ser_n = _normaliza_serie_filtro(ser)
        try:
            n = int(nota)
        except (TypeError, ValueError):
            return
        if not mod_n or not ser_n or n <= 0:
            return
        k = (mod_n, ser_n, n)
        if k in _seen:
            return
        _seen.add(k)
        triplas_aplicar.append(k)

    _dfs_inut: list[pd.DataFrame] = []
    if up_inut_planilha is not None:
        _df_up, _err_up = dataframe_de_upload_inutil(up_inut_planilha)
        if _err_up:
            linhas.append(f"Ficheiro inutilizadas: {_err_up}")
        elif _df_up is not None and not _df_up.empty:
            _dfs_inut.append(_df_up)
    if texto_inut_planilha and str(texto_inut_planilha).strip():
        _df_pc, _err_pc = dataframe_de_texto_colar_planilha(str(texto_inut_planilha).strip())
        if _err_pc:
            linhas.append(f"Texto colado (inutilizadas): {_err_pc}")
        elif _df_pc is not None and not _df_pc.empty:
            _dfs_inut.append(_df_pc)
    if _dfs_inut:
        for _df_av in _dfs_inut:
            linhas.extend(_avisos_inutil_sefaz_de_df(_df_av))
        _df_merged = (
            pd.concat(_dfs_inut, ignore_index=True) if len(_dfs_inut) > 1 else _dfs_inut[0]
        )
        _tri, _err_tr = triplas_inutil_de_dataframe(_df_merged)
        if _err_tr:
            return False, _err_tr
        _datas.update(_mapa_datas_inutil_de_dataframe(_df_merged))
        for _mod, _ser, _nota in _tri:
            _agendar(_mod, _ser, _nota)

    if pick_bur_inut:
        if not mb_bur or not str(sb_bur or "").strip():
            return False, "Para «Dos buracos», escolha modelo e série."
        for _nb in pick_bur_inut:
            _agendar(mb_bur, str(sb_bur).strip(), int(_nb))

    sf = str(sf_faixa or "").strip()
    if sf and n0_faixa is not None and n1_faixa is not None:
        try:
            n0 = int(n0_faixa)
            n1 = int(n1_faixa)
        except (TypeError, ValueError):
            n0 = n1 = 0
        if n0 > 0 and n1 > 0:
            if n0 > n1:
                return False, "Faixa: a nota inicial não pode ser maior que a final."
            bur_f = set(_arquivo_fiscal_buracos_numeros_mod_serie(cnpj, mf_faixa, sf))
            for n in range(n0, n1 + 1):
                if n in bur_f:
                    _agendar(mf_faixa, sf, n)

    if not triplas_aplicar:
        msg = "Nada a aplicar. Cole a lista da Sefaz, importe planilha ou indique notas/faixa."
        if linhas:
            msg += "\n\n" + "\n".join(linhas)
        return False, msg

    n_ocup = 0
    agora = datetime.now().isoformat(timespec="seconds")
    conn = _arquivo_fiscal_conn_leve(cnpj)
    try:
        tem_propria = conn.execute(
            """
            SELECT 1 FROM xml_arquivo
            WHERE cnpj_empresa = ? AND is_propria = 1 LIMIT 1
            """,
            (cnpj,),
        ).fetchone()
        if not tem_propria:
            return (
                False,
                "Não há XML de emissão própria indexados no arquivo fiscal para este CNPJ.",
            )
        faixa = {(m, s): (1, 1_000_000_000) for m, s, _n in triplas_aplicar}
        n_ok, n_ign_fora, n_dup, n_prom, ign_series, n_nao_buraco = (
            _arquivo_fiscal_aplicar_inutil_lote_buracos_rejeitadas(
                conn, cnpj, triplas_aplicar, faixa, _datas, agora
            )
        )
        _arquivo_fiscal_corrigir_inutil_manual_competencia(conn, cnpj)
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()
    _arquivo_fiscal_invalidar_runtime_cache(cnpj)

    def _texto_ign_fora() -> str:
        partes = [
            f"{n_ign_fora} ignorada(s) — fora do intervalo das notas já lidas no arquivo "
            "(1.ª a última XML indexada desta série)."
        ]
        for m_ign, s_ign in ign_series[:5]:
            partes.append(_descricao_faixa_inutil(m_ign, s_ign, faixa))
        return "\n".join(partes)

    if n_ok == 0 and n_prom == 0 and not n_dup:
        msg = (
            "Nenhuma inutilização aplicada — a lista não cruzou com buracos do sistema "
            "nem com rejeitadas."
        )
        if n_nao_buraco:
            msg += (
                f"\n\n{n_nao_buraco} número(s) da lista não são buraco nem rejeitada "
                "no arquivo."
            )
        if n_ocup:
            msg += (
                f"\n\n{n_ocup} número(s) da lista já existem como "
                "autorizada/cancelada/denegada — o status não foi alterado."
            )
        if n_ign_fora:
            msg += f"\n\n{_texto_ign_fora()}"
        if linhas:
            msg += "\n\n" + "\n".join(linhas)
        return False, msg

    if n_ok:
        linhas.insert(0, f"**{n_ok}** inutilização(ões) registadas no arquivo fiscal.")
    if n_prom:
        linhas.append(
            f"{n_prom} rejeitada(s) passaram a inutilizada(s) (número na lista da Sefaz)."
        )
    if n_dup:
        linhas.append(f"{n_dup} já constavam como inutilizadas.")
    if n_nao_buraco:
        linhas.append(
            f"{n_nao_buraco} da lista não são buraco nem rejeitada no arquivo — não gravadas."
        )
    if n_ocup:
        linhas.append(
            f"{n_ocup} ignorada(s) — já existem como autorizada, cancelada ou denegada."
        )
    if n_ign_fora:
        linhas.append(_texto_ign_fora())
    linhas.append(
        "Só se cruzou a lista com os buracos que o sistema já marca e com as rejeitadas."
    )
    linhas.append(
        "Buracos e Excel serão atualizados (inutilizadas deixam de contar como buraco)."
    )
    _arquivo_fiscal_atualizar_apos_inutilizadas(cnpj)
    return True, "\n\n".join(linhas)


def eliminar_inutilizadas_arquivo_fiscal(
    cnpj_limpo: str,
    *,
    texto_inut_planilha=None,
    chaves: list[str] | None = None,
    ano: int | None = None,
    mes: int | None = None,
) -> tuple[bool, str]:
    """
    Desfaz inutilizações manuais (lista colada, linhas escolhidas ou mês).
    Não apaga XML de inutilização da Sefaz.
    """
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj_limpo)
    if len(cnpj) != 14:
        return False, "CNPJ inválido — são necessários 14 dígitos."
    triplas: list[tuple[str, str, int]] | None = None
    if texto_inut_planilha and str(texto_inut_planilha).strip():
        _df_pc, _err_pc = dataframe_de_texto_colar_planilha(
            str(texto_inut_planilha).strip()
        )
        if _err_pc:
            return False, f"Texto colado (inutilizadas): {_err_pc}"
        if _df_pc is None or _df_pc.empty:
            return False, "A lista colada não tem linhas reconhecíveis."
        _tri, _err_tr = triplas_inutil_de_dataframe(_df_pc)
        if _err_tr:
            return False, _err_tr
        triplas = list(_tri or [])
        if not triplas:
            return False, "A lista colada não tem modelo, série e número para eliminar."
    n_st, n_rev, n_ign, msg = _arquivo_fiscal_eliminar_inutilizadas_manuais(
        cnpj,
        chaves=chaves,
        ano=ano,
        mes=mes,
        triplas=triplas,
    )
    ok = (n_st + n_rev) > 0
    return ok, msg


def _garimpo_pode_indicar_inutilizadas(cnpj_limpo: str) -> bool:
    """Garimpo na sessão ou XML já indexados no arquivo fiscal."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj_limpo)
    if len(cx) != 14:
        return False
    if st.session_state.get("garimpo_ok") and _relatorio_get_list():
        return True
    return _arquivo_fiscal_total(cx) > 0


def registrar_inutil_unica_arquivo_fiscal(
    cnpj_limpo: str,
    modelo: str,
    serie: str,
    nota: int,
) -> tuple[bool, str]:
    """Regista uma inutilizada no arquivo fiscal (sem garimpo nesta sessão)."""
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj_limpo)
    if len(cnpj) != 14:
        return False, "CNPJ inválido — são necessários 14 dígitos."
    if _arquivo_fiscal_total(cnpj) <= 0:
        return (
            False,
            "Não há XML indexados no arquivo fiscal. Faça um garimpo com captura ou sincronize a pasta XML.",
        )
    try:
        n = int(nota)
    except (TypeError, ValueError):
        return False, "Informe um número de nota válido."
    ser = str(serie).strip()
    if not ser:
        return False, "Informe a série."
    mod = _normaliza_modelo_filtro(str(modelo).strip())
    if not mod:
        return False, "Informe o modelo."
    faixa = _arquivo_fiscal_faixa_numeracao_para_inutil(cnpj)
    if not faixa:
        return False, "Arquivo fiscal sem faixa de numeração (emissão própria)."
    if not _tripla_inutil_dentro_faixa_xml(mod, ser, n, faixa):
        return (
            False,
            f"A nota {n} está fora do intervalo indexado no arquivo para {mod} série {ser}.\n\n"
            f"{_descricao_faixa_inutil(mod, ser, faixa)}",
        )
    r = _arquivo_fiscal_aplicar_inutil_numero(cnpj, mod, ser, n)
    if r == "dup":
        return False, "Esta inutilização já consta no arquivo fiscal."
    if r == "ocupada":
        return (
            False,
            f"A nota {n} já existe como autorizada, cancelada ou denegada — "
            "não pode passar a inutilizada.",
        )
    if r not in ("promovida", "nova"):
        return False, "Não foi possível registar a inutilizada."
    _arquivo_fiscal_atualizar_apos_inutilizadas(cnpj)
    if r == "promovida":
        return (
            True,
            f"Nota {mod} série {ser} nº {n} estava rejeitada e passou a inutilizada.",
        )
    return True, f"Inutilizada registada: {mod} série {ser} nº {n}."


def _arquivo_fiscal_capturar_de_leitura(
    cnpj_empresa: str,
    res: dict | None,
    is_propria: bool,
    xml_bytes,
    nome_original: str,
    fonte_lote: str | None = None,
) -> None:
    if not _arquivo_fiscal_captura_ativa() or not res:
        return
    try:
        origem = _arquivo_fiscal_fonte_origem(fonte_lote) if fonte_lote else None
        if _arquivo_fiscal_gravar_um(
            cnpj_empresa,
            res,
            is_propria,
            xml_bytes,
            nome_original,
            caminho_origem=origem,
        ):
            st.session_state["_arquivo_fiscal_stats_novos"] = int(
                st.session_state.get("_arquivo_fiscal_stats_novos") or 0
            ) + 1
    except Exception:
        pass


def _arquivo_fiscal_total(cnpj: str) -> int:
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cnpj) != 14 or not _arquivo_fiscal_db_path(cnpj).is_file():
        return 0
    cc = _arquivo_fiscal_cache_cnpj(cnpj)
    n_cache = cc.get("xml_total")
    if isinstance(n_cache, int) and n_cache >= 0:
        return n_cache
    conn = _arquivo_fiscal_conn(cnpj)
    try:
        meta_n = _arquivo_fiscal_meta_get(conn, "xml_total")
        if meta_n is not None and str(meta_n).isdigit():
            n = int(meta_n)
            cc["xml_total"] = n
            return n
        row = conn.execute(
            "SELECT COUNT(*) FROM xml_arquivo WHERE cnpj_empresa = ?", (cnpj,)
        ).fetchone()
        n = int(row[0]) if row else 0
        try:
            _arquivo_fiscal_meta_set(conn, "xml_total", str(n))
            conn.commit()
        except sqlite3.Error:
            pass
        cc["xml_total"] = n
        return n
    finally:
        conn.close()


def _arquivo_fiscal_faixa_numeros_por_serie(
    cnpj: str,
    ref_ano: int | None = None,
    ref_mes: int | None = None,
) -> dict[str, tuple[int, int, int]]:
    """
    Emissão própria no arquivo fiscal: modelo|série → (min, max, ultimo_ref).
    Se ref_ano/ref_mes informados, ultimo_ref = MAX(numero) com (ano, mes) <= competência;
    min/max = faixa de todos os registos dessa série no arquivo (informativo).
    """
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cnpj) != 14 or not _arquivo_fiscal_db_path(cnpj).is_file():
        return {}
    try:
        ref_ano_i = int(ref_ano) if ref_ano is not None else None
        ref_mes_i = int(ref_mes) if ref_mes is not None else None
    except (TypeError, ValueError):
        ref_ano_i = ref_mes_i = None
    conn = _arquivo_fiscal_conn(cnpj)
    try:
        rows = conn.execute(
            """
            SELECT modelo, serie,
                   MIN(numero) AS nmin,
                   MAX(numero) AS nmax,
                   MAX(CASE
                     WHEN ? IS NULL OR ? IS NULL THEN numero
                     WHEN ano < ? OR (ano = ? AND mes <= ?) THEN numero
                     ELSE NULL END) AS ult_ref
            FROM xml_arquivo
            WHERE cnpj_empresa = ? AND is_propria = 1
              AND numero IS NOT NULL AND numero > 0
              AND upper(trim(COALESCE(status, ''))) != 'INUTILIZADOS'
            GROUP BY modelo, serie
            """,
            (
                ref_ano_i,
                ref_mes_i,
                ref_ano_i,
                ref_ano_i,
                ref_mes_i,
                cnpj,
            ),
        ).fetchall()
    finally:
        conn.close()
    out: dict[str, tuple[int, int, int]] = {}
    for mod, ser, nmin, nmax, ult_ref in rows:
        if not mod or not ser:
            continue
        try:
            mn = int(nmin) if nmin is not None else 0
            mx = int(nmax) if nmax is not None else 0
            ur = int(ult_ref) if ult_ref is not None else 0
        except (TypeError, ValueError):
            continue
        if mx <= 0:
            continue
        out[f"{str(mod).strip()}|{str(ser).strip()}"] = (mn, mx, ur)
    return out


def _arquivo_fiscal_anos_disponiveis(cnpj: str) -> list[int]:
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cnpj) != 14:
        return []
    try:
        conn = _arquivo_fiscal_conn(cnpj)
        try:
            rows = conn.execute(
                "SELECT DISTINCT ano FROM xml_arquivo WHERE cnpj_empresa = ? "
                "AND ano IS NOT NULL ORDER BY ano DESC",
                (cnpj,),
            ).fetchall()
            return [int(r[0]) for r in rows if r[0] is not None]
        finally:
            conn.close()
    except Exception:
        return []


def _arquivo_fiscal_kpis_empresa(cnpj: str) -> dict:
    """Totais agregados do arquivo fiscal da empresa."""
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj)
    out = {
        "total": 0,
        "meses": 0,
        "propria": 0,
        "terceiros": 0,
        "series": 0,
    }
    if len(cnpj) != 14 or not _arquivo_fiscal_db_path(cnpj).is_file():
        return out
    conn = _arquivo_fiscal_conn(cnpj)
    try:
        row = conn.execute(
            """
            SELECT COUNT(*),
                   COUNT(DISTINCT printf('%04d-%02d', ano, mes)),
                   SUM(CASE WHEN is_propria = 1 THEN 1 ELSE 0 END),
                   SUM(CASE WHEN is_propria = 0 THEN 1 ELSE 0 END)
            FROM xml_arquivo WHERE cnpj_empresa = ?
            """,
            (cnpj,),
        ).fetchone()
        if row:
            out["total"] = int(row[0] or 0)
            out["meses"] = int(row[1] or 0)
            out["propria"] = int(row[2] or 0)
            out["terceiros"] = int(row[3] or 0)
        sr = conn.execute(
            """
            SELECT COUNT(*) FROM (
                SELECT modelo, serie, is_propria
                FROM xml_arquivo
                WHERE cnpj_empresa = ? AND numero IS NOT NULL AND numero > 0
                GROUP BY modelo, serie, is_propria
            )
            """,
            (cnpj,),
        ).fetchone()
        out["series"] = int(sr[0] or 0) if sr else 0
    finally:
        conn.close()
    return out


def _arquivo_fiscal_competencias_resumo(cnpj: str) -> dict[tuple[int, int], dict]:
    """(ano, mês) → {total, propria, terceiros}."""
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cnpj) != 14 or not _arquivo_fiscal_db_path(cnpj).is_file():
        return {}
    cc = _arquivo_fiscal_cache_cnpj(cnpj)
    cached = cc.get("comp_resumo")
    if isinstance(cached, dict):
        return cached
    conn = _arquivo_fiscal_conn(cnpj)
    try:
        rows = conn.execute(
            """
            SELECT chave, ano, mes, is_propria, data_emissao
            FROM xml_arquivo
            WHERE cnpj_empresa = ?
            """,
            (cnpj,),
        ).fetchall()
    finally:
        conn.close()
    out: dict[tuple[int, int], dict] = {}
    for chave, ano, mes, is_p, de in rows:
        comp = _competencia_registo_arquivo(chave, ano, mes, de)
        if not comp:
            continue
        a, m = comp
        slot = out.setdefault((a, m), {"total": 0, "propria": 0, "terceiros": 0})
        slot["total"] += 1
        if int(is_p or 0) == 1:
            slot["propria"] += 1
        else:
            slot["terceiros"] += 1
    cc["comp_resumo"] = out
    return out


def _arquivo_fiscal_ultima_competencia(cnpj: str) -> tuple[int, int] | None:
    comp = _arquivo_fiscal_competencias_resumo(cnpj)
    if not comp:
        return None
    return max(comp.keys())


def _arquivo_fiscal_tipo_terceiros_resumo(modelo) -> str:
    """Agrupa terceiros só por tipo de documento (NF-e, CT-e, NFC-e, …)."""
    m = str(modelo or "").strip()
    if m in ("CT-e", "CT-e OS"):
        return "CT-e"
    if m in ("NF-e", "NFC-e", "NFS-e", "MDF-e"):
        return m
    return m or "Outros"


def _arquivo_fiscal_sql_filtro_meses(
    mes: int | None,
    meses: list[int] | None,
    params: list,
) -> str:
    """Fragmento SQL AND mes … para um mês, vários ou ano inteiro."""
    if meses:
        ms = sorted({int(m) for m in meses if 1 <= int(m) <= 12})
        if not ms:
            return ""
        ph = ",".join("?" * len(ms))
        params.extend(ms)
        return f" AND mes IN ({ph})"
    if mes is not None:
        params.append(int(mes))
        return " AND mes = ?"
    return ""


def _arquivo_fiscal_data_emissao_iso(valor) -> str | None:
    """Normaliza data de emissão para AAAA-MM-DD (filtro e SQLite)."""
    if valor is None:
        return None
    s = str(valor).strip()
    if not s or s.lower() in ("nan", "nat", "none"):
        return None
    m = re.match(r"^(\d{2})/(\d{2})/(\d{4})(?:[ T].*)?$", s)
    if m:
        d, mo, a = m.group(1), m.group(2), m.group(3)
        return f"{a}-{mo}-{d}"
    if re.match(r"^\d{4}-\d{2}-\d{2}", s):
        return s[:10]
    ts = pd.to_datetime(s, errors="coerce", dayfirst=True)
    if pd.notna(ts):
        return ts.strftime("%Y-%m-%d")
    return None


def _arquivo_fiscal_ano_mes_de_iso(iso: str | None) -> tuple[int | None, int | None]:
    s = str(iso or "").strip()
    if len(s) >= 7 and s[4] == "-":
        try:
            a, mo = int(s[:4]), int(s[5:7])
        except ValueError:
            return None, None
        if 1990 <= a <= 2099 and 1 <= mo <= 12:
            return a, mo
    return None, None


def _arquivo_fiscal_trocar_dia_mes_iso_ambiguo(iso: str | None) -> str | None:
    """
    Pandas lia 01/09/2026 14:31 como 9 de janeiro. Datas já gravadas com
    dia e mês ≤ 12 ficam invertidas; devolve AAAA-MM-DD no sentido BR.
    """
    s = str(iso or "").strip()[:10]
    m = re.match(r"^(\d{4})-(\d{2})-(\d{2})$", s)
    if not m:
        return str(iso or "").strip()[:10] or None
    a, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
    if 1 <= mo <= 12 and 1 <= d <= 12:
        return f"{a:04d}-{d:02d}-{mo:02d}"
    return s


def _arquivo_fiscal_corrigir_inutil_manual_competencia(
    conn: sqlite3.Connection, cnpj: str
) -> int:
    """
    Preenche ano/mês das inutilizadas manuais e corrige data BR ambígua
    só quando ano/mês ainda estão vazios (não mexe em registos já certos).
    """
    rows = conn.execute(
        """
        SELECT chave, data_emissao
        FROM xml_arquivo
        WHERE cnpj_empresa = ?
          AND is_propria = 1
          AND upper(trim(COALESCE(status, ''))) = 'INUTILIZADOS'
          AND (chave LIKE 'MANUAL_INUT_%' OR chave LIKE 'INUT_%')
          AND (ano IS NULL OR mes IS NULL)
        """,
        (cnpj,),
    ).fetchall()
    n = 0
    for chave, dt in rows:
        iso = _arquivo_fiscal_trocar_dia_mes_iso_ambiguo(dt) or _arquivo_fiscal_data_emissao_iso(dt)
        ano, mes = _arquivo_fiscal_ano_mes_de_iso(iso)
        if not ano or not mes:
            continue
        conn.execute(
            """
            UPDATE xml_arquivo
            SET data_emissao = ?, ano = ?, mes = ?
            WHERE cnpj_empresa = ? AND chave = ?
            """,
            (iso, ano, mes, cnpj, chave),
        )
        n += 1
    if _arquivo_fiscal_meta_get(conn, "inutil_data_br_v1") != "1":
        legado = conn.execute(
            """
            SELECT chave, data_emissao, mes
            FROM xml_arquivo
            WHERE cnpj_empresa = ?
              AND is_propria = 1
              AND chave LIKE 'INUT_%'
              AND chave NOT LIKE 'MANUAL_INUT_%'
              AND ano IS NOT NULL AND mes IS NOT NULL
            """,
            (cnpj,),
        ).fetchall()
        for chave, dt, mes_g in legado:
            s = str(dt or "").strip()[:10]
            m = re.match(r"^(\d{4})-(\d{2})-(\d{2})$", s)
            if not m:
                continue
            a, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
            try:
                mes_i = int(mes_g)
            except (TypeError, ValueError):
                continue
            if not (1 <= mo <= 12 and 1 <= d <= 12 and mes_i == mo):
                continue
            iso = f"{a:04d}-{d:02d}-{mo:02d}"
            ano, mes = _arquivo_fiscal_ano_mes_de_iso(iso)
            if not ano or not mes:
                continue
            conn.execute(
                """
                UPDATE xml_arquivo
                SET data_emissao = ?, ano = ?, mes = ?
                WHERE cnpj_empresa = ? AND chave = ?
                """,
                (iso, ano, mes, cnpj, chave),
            )
            n += 1
        _arquivo_fiscal_meta_set(conn, "inutil_data_br_v1", "1")
    return n


def _identify_xml_extrair_data_inutilizacao(tag_l: str) -> str:
    """Data da inutilização na Sefaz (AAAA-MM-DD) — dhRecbto / dhRegEvento no XML de inutilização."""
    tag_l = str(tag_l or "").lower()
    for pat in (
        r"dhrecbto>(\d{4})-(\d{2})-(\d{2})",
        r"dhinut>(\d{4})-(\d{2})-(\d{2})",
        r"dhregevento>(\d{4})-(\d{2})-(\d{2})",
    ):
        m = re.search(pat, tag_l)
        if m:
            return f"{m.group(1)}-{m.group(2)}-{m.group(3)}"
    return ""


def _arquivo_fiscal_data_inutilizacao_de_registo(
    *,
    chave: str | None = None,
    capturado_em: str | None = None,
    atualizado_em: str | None = None,
    resumo_json: str | None = None,
    data_emissao: str | None = None,
) -> str | None:
    """Resolve a data de inutilização para exibição (painel / Excel)."""
    raw_js = resumo_json
    if raw_js:
        try:
            s = str(raw_js).strip()
            if s and s[0] in "{[":
                res = _relatorio_deserializar(s)
                if isinstance(res, dict):
                    for k in (
                        "Data_Inutilizacao",
                        "Data_Inutilização",
                        "Data Inutilização",
                        "Data_Emissao",
                    ):
                        iso = _arquivo_fiscal_data_emissao_iso(res.get(k))
                        if iso:
                            return iso
        except (ValueError, TypeError):
            pass
    ch = str(chave or "").strip()
    if ch.startswith("MANUAL_INUT_"):
        for ts in (capturado_em, atualizado_em):
            iso = _arquivo_fiscal_data_emissao_iso(ts)
            if iso:
                return iso
    for ts in (capturado_em, atualizado_em):
        iso = _arquivo_fiscal_data_emissao_iso(ts)
        if iso:
            return iso
    return _arquivo_fiscal_data_emissao_iso(data_emissao)


def _arquivo_fiscal_parse_data_filtro(texto: str) -> str | None:
    """Aceita dd/mm/aaaa ou aaaa-mm-dd digitados no painel de filtro."""
    return _arquivo_fiscal_data_emissao_iso(str(texto or "").strip())


def _arquivo_fiscal_parse_numero_filtro(texto: str) -> int | None:
    """Aceita número de nota digitado no painel de filtro (vazio = sem limite)."""
    t = str(texto or "").strip().replace(".", "").replace(",", "")
    if not t:
        return None
    try:
        n = int(t)
    except ValueError:
        return None
    return n if n > 0 else None


def _arquivo_fiscal_normalizar_uf(valor) -> str:
    u = str(valor or "").strip().upper()
    return u if len(u) == 2 and u.isalpha() else ""


def _arquivo_fiscal_ufs_filtro(valor) -> list[str]:
    """Aceita 'SP', 'SP,RJ' ou lista — devolve UFs válidas (2 letras)."""
    if valor is None:
        return []
    if isinstance(valor, (list, tuple, set)):
        raw = ",".join(str(x) for x in valor)
    else:
        raw = str(valor)
    out: list[str] = []
    seen: set[str] = set()
    for part in re.split(r"[\s,;|/]+", raw):
        u = _arquivo_fiscal_normalizar_uf(part)
        if u and u not in seen:
            seen.add(u)
            out.append(u)
    return out


def _arquivo_fiscal_uf_parceiro_de_res(res: dict | None, is_propria: bool) -> str:
    """
    UF do parceiro na operação:
    - emissão própria → UF do destinatário;
    - terceiros → UF do emitente.
    """
    res = res or {}
    if is_propria:
        return _arquivo_fiscal_normalizar_uf(res.get("UF_Dest"))
    return _arquivo_fiscal_normalizar_uf(res.get("UF_Emit") or res.get("UF_Dest"))


def _arquivo_fiscal_uf_parceiro_de_xml_bytes(raw: bytes, is_propria: bool) -> str:
    """Extrai UF do parceiro sem reprocessar o XML completo."""
    try:
        tag_l = _identify_xml_string_para_regex(raw).lower()
    except Exception:
        try:
            tag_l = raw.decode("utf-8", errors="ignore").lower()
        except Exception:
            return ""
    if is_propria:
        m = re.search(
            r"(?:<\w+:dest\b|<dest\b)[^>]*>[\s\S]{0,12000}?(?:<\w+:uf>|<uf>)([a-z]{2})</(?:\w+:uf|uf)>",
            tag_l,
            re.S,
        )
    else:
        m = re.search(
            r"(?:<\w+:emit\b|<emit\b)[^>]*>[\s\S]{0,12000}?(?:<\w+:uf>|<uf>)([a-z]{2})</(?:\w+:uf|uf)>",
            tag_l,
            re.S,
        )
        if not m:
            m = re.search(
                r"(?:<\w+:dest\b|<dest\b)[^>]*>[\s\S]{0,12000}?(?:<\w+:uf>|<uf>)([a-z]{2})</(?:\w+:uf|uf)>",
                tag_l,
                re.S,
            )
    return _arquivo_fiscal_normalizar_uf(m.group(1) if m else "")


_ARQUIVO_META_UF_PARCEIRO = "uf_parceiro_v1"
_ARQUIVO_META_CFOPS = "cfops_v1"


def _arquivo_fiscal_normalizar_cfop(valor) -> str:
    d = "".join(c for c in str(valor or "") if c.isdigit())
    if len(d) >= 4:
        return d[:4]
    return ""


def _arquivo_fiscal_cfops_filtro(valor) -> list[str]:
    """Aceita '5102', '5102,6102' ou lista — devolve CFOPs de 4 dígitos."""
    if valor is None:
        return []
    if isinstance(valor, (list, tuple, set)):
        raw = ",".join(str(x) for x in valor)
    else:
        raw = str(valor)
    out: list[str] = []
    seen: set[str] = set()
    for part in re.split(r"[\s,;|/]+", raw):
        c = _arquivo_fiscal_normalizar_cfop(part)
        if c and c not in seen:
            seen.add(c)
            out.append(c)
    return out


def _arquivo_fiscal_cfops_de_lista(codigos: list[str]) -> str:
    """Formato em BD: ,5102,5405, (para LIKE %%,5102,%%)."""
    limpos = [_arquivo_fiscal_normalizar_cfop(c) for c in (codigos or [])]
    limpos = [c for c in limpos if c]
    if not limpos:
        return ""
    # únicos preservando ordem
    seen: set[str] = set()
    ord_: list[str] = []
    for c in limpos:
        if c not in seen:
            seen.add(c)
            ord_.append(c)
    return "," + ",".join(ord_) + ","


def _arquivo_fiscal_cfops_para_db(res: dict | None) -> str:
    res = res or {}
    if res.get("CFOPs"):
        return _arquivo_fiscal_cfops_de_lista(
            [str(x) for x in (res.get("CFOPs") or [])]
        )
    c = _arquivo_fiscal_normalizar_cfop(res.get("CFOP"))
    return _arquivo_fiscal_cfops_de_lista([c] if c else [])


def _arquivo_fiscal_cfops_de_xml_bytes(raw: bytes) -> str:
    try:
        tag_l = _identify_xml_string_para_regex(raw).lower()
    except Exception:
        try:
            tag_l = raw.decode("utf-8", errors="ignore").lower()
        except Exception:
            return ""
    found = re.findall(r"(?:<\w+:cfop>|<cfop>)(\d{4})</", tag_l)
    return _arquivo_fiscal_cfops_de_lista(found)


def _arquivo_fiscal_garantir_cfops(
    cnpj: str,
    *,
    ano: int | None = None,
    mes: int | None = None,
    meses: list[int] | None = None,
    max_disco: int = 25_000,
) -> int:
    """
    Preenche cfops nos XML indexados sem CFOP.
    1) tenta resumo_json (rápido, sem disco);
    2) só depois lê XML do disco, preferindo o recorte ano/mês e com teto max_disco.
    Registos sem CFOP (ex.: CT-e) ficam com ',' para não voltar a varrer.
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14 or not _arquivo_fiscal_db_path(cx).is_file():
        return 0
    conn = _arquivo_fiscal_conn(cx)
    try:
        where = (
            "cnpj_empresa = ? AND (cfops IS NULL OR trim(cfops) = '') "
            "AND caminho_relativo IS NOT NULL "
            "AND caminho_relativo NOT LIKE '%manual_inutilizadas%'"
        )
        params: list = [cx]
        if ano is not None:
            where += " AND ano = ?"
            params.append(int(ano))
        where += _arquivo_fiscal_sql_filtro_meses(mes, meses, params)

        # Fase 1: resumo_json (sem abrir ficheiros)
        rows_js = conn.execute(
            f"""
            SELECT chave, resumo_json FROM xml_arquivo
            WHERE {where}
              AND resumo_json IS NOT NULL AND trim(resumo_json) != ''
            """,
            params,
        ).fetchall()
        n = 0
        for chave, js in rows_js:
            try:
                data = json.loads(js) if isinstance(js, str) else None
            except (ValueError, TypeError):
                data = None
            if not isinstance(data, dict):
                continue
            cf = _arquivo_fiscal_cfops_para_db(data) or ","
            conn.execute(
                "UPDATE xml_arquivo SET cfops = ? WHERE chave = ?",
                (cf, chave),
            )
            n += 1
            if n % 500 == 0:
                conn.commit()

        # Fase 2: disco — só o que ainda falta, com teto
        rows = conn.execute(
            f"""
            SELECT chave, caminho_relativo FROM xml_arquivo
            WHERE {where}
            LIMIT ?
            """,
            (*params, int(max_disco)),
        ).fetchall()
        if not rows and n == 0:
            _arquivo_fiscal_meta_set(conn, _ARQUIVO_META_CFOPS, "1")
            conn.commit()
            return 0
        base = _arquivo_fiscal_pasta_empresa(cx)
        for chave, rel in rows:
            if not rel:
                conn.execute(
                    "UPDATE xml_arquivo SET cfops = ? WHERE chave = ?",
                    (",", chave),
                )
                n += 1
                continue
            path = base / str(rel).replace("/", os.sep)
            if not path.is_file():
                conn.execute(
                    "UPDATE xml_arquivo SET cfops = ? WHERE chave = ?",
                    (",", chave),
                )
                n += 1
                continue
            try:
                raw = path.read_bytes()
            except OSError:
                conn.execute(
                    "UPDATE xml_arquivo SET cfops = ? WHERE chave = ?",
                    (",", chave),
                )
                n += 1
                continue
            cf = _arquivo_fiscal_cfops_de_xml_bytes(raw) or ","
            conn.execute(
                "UPDATE xml_arquivo SET cfops = ? WHERE chave = ?",
                (cf, chave),
            )
            n += 1
            if n % 400 == 0:
                conn.commit()
        _arquivo_fiscal_meta_set(conn, _ARQUIVO_META_CFOPS, "1")
        conn.commit()
        if n:
            _arquivo_fiscal_invalidar_runtime_cache(cx)
        return n
    finally:
        conn.close()


def _arquivo_fiscal_garantir_uf_parceiro(cnpj: str) -> int:
    """
    Preenche uf_parceiro nos XML já indexados (1× por empresa).
    Devolve quantos registos atualizou.
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14 or not _arquivo_fiscal_db_path(cx).is_file():
        return 0
    conn = _arquivo_fiscal_conn(cx)
    try:
        if _arquivo_fiscal_meta_get(conn, _ARQUIVO_META_UF_PARCEIRO) == "1":
            # Ainda pode haver novos sem UF — completa só os vazios
            pass
        rows = conn.execute(
            """
            SELECT chave, caminho_relativo, is_propria
            FROM xml_arquivo
            WHERE cnpj_empresa = ?
              AND (uf_parceiro IS NULL OR trim(uf_parceiro) = '')
              AND caminho_relativo IS NOT NULL
              AND caminho_relativo NOT LIKE '%manual_inutilizadas%'
            """,
            (cx,),
        ).fetchall()
        if not rows:
            _arquivo_fiscal_meta_set(conn, _ARQUIVO_META_UF_PARCEIRO, "1")
            conn.commit()
            return 0
        base = _arquivo_fiscal_pasta_empresa(cx)
        n = 0
        for chave, rel, is_p in rows:
            if not rel:
                continue
            path = base / str(rel).replace("/", os.sep)
            if not path.is_file():
                continue
            try:
                raw = path.read_bytes()
            except OSError:
                continue
            uf = _arquivo_fiscal_uf_parceiro_de_xml_bytes(raw, bool(int(is_p or 0)))
            if not uf:
                continue
            conn.execute(
                "UPDATE xml_arquivo SET uf_parceiro = ? WHERE chave = ?",
                (uf, chave),
            )
            n += 1
            if n % 400 == 0:
                conn.commit()
        _arquivo_fiscal_meta_set(conn, _ARQUIVO_META_UF_PARCEIRO, "1")
        conn.commit()
        if n:
            _arquivo_fiscal_invalidar_runtime_cache(cx)
        return n
    finally:
        conn.close()


def _arquivo_fiscal_sql_filtros_avancados(
    *,
    serie: str | None = None,
    modelo: str | None = None,
    data_inicio: str | None = None,
    data_fim: str | None = None,
    numero_inicio: int | None = None,
    numero_fim: int | None = None,
    uf_parceiro: str | list | None = None,
    cfop: str | list | None = None,
    params: list,
) -> str:
    """Fragmentos SQL para série, modelo, faixa de nota, datas, UF e CFOP."""
    sql = ""
    ser = str(serie or "").strip()
    if ser and ser.lower() not in ("todas", "qualquer", "todos"):
        sql += " AND trim(serie) = trim(?)"
        params.append(ser)
    mod = str(modelo or "").strip()
    if mod and mod.lower() not in ("todas", "qualquer", "todos"):
        sql += " AND upper(trim(modelo)) = upper(trim(?))"
        params.append(mod)
    if numero_inicio is not None:
        sql += " AND numero IS NOT NULL AND numero >= ?"
        params.append(int(numero_inicio))
    if numero_fim is not None:
        sql += " AND numero IS NOT NULL AND numero <= ?"
        params.append(int(numero_fim))
    di = _arquivo_fiscal_data_emissao_iso(data_inicio)
    df = _arquivo_fiscal_data_emissao_iso(data_fim)
    _col_data = "COALESCE(data_emissao, printf('%04d-%02d-01', ano, mes))"
    if di:
        sql += f" AND {_col_data} >= ?"
        params.append(di)
    if df:
        sql += f" AND {_col_data} <= ?"
        params.append(df)
    ufs = _arquivo_fiscal_ufs_filtro(uf_parceiro)
    if ufs:
        if len(ufs) == 1:
            sql += " AND upper(trim(COALESCE(uf_parceiro, ''))) = ?"
            params.append(ufs[0])
        else:
            ph = ", ".join("?" for _ in ufs)
            sql += f" AND upper(trim(COALESCE(uf_parceiro, ''))) IN ({ph})"
            params.extend(ufs)
    cfops = _arquivo_fiscal_cfops_filtro(cfop)
    if cfops:
        # cfops na BD: ,5102,5405, — basta um dos pedidos coincidir
        partes = []
        for c in cfops:
            partes.append("COALESCE(cfops, '') LIKE ?")
            params.append(f"%,{c},%")
        sql += " AND (" + " OR ".join(partes) + ")"
    return sql


def _arquivo_fiscal_meses_filtro_ativos(
    mes: int | None,
    meses: list[int] | None,
) -> list[int]:
    """Meses pedidos no resumo (1–12). Sem filtro = ano inteiro."""
    if meses:
        ms = sorted({int(m) for m in meses if 1 <= int(m) <= 12})
        return ms
    if mes is not None:
        m = int(mes)
        return [m] if 1 <= m <= 12 else []
    return list(range(1, 13))


def _arquivo_fiscal_inferir_mes_competencia_inutilizada(
    por_mes_ano: dict[int, dict[tuple[str, str], set[int]]],
    mod: str,
    ser: str,
    numero: int,
    *,
    mes_armazenado: int | None = None,
) -> int | None:
    """
    Mês de competência de uma inutilizada pela numeração do ano — não pela data
    em que foi inutilizada na Sefaz (ex.: nota 1894 do intervalo de maio, inutilizada
    em junho, conta em maio).
    """
    key = (
        _normaliza_modelo_filtro(mod),
        _normaliza_serie_filtro(ser),
    )
    if not key[0] or not key[1]:
        if mes_armazenado and 1 <= int(mes_armazenado) <= 12:
            return int(mes_armazenado)
        return None
    try:
        n = int(numero)
    except (TypeError, ValueError):
        if mes_armazenado and 1 <= int(mes_armazenado) <= 12:
            return int(mes_armazenado)
        return None
    if n <= 0:
        return None

    no_intervalo: list[int] = []
    for mes in sorted(por_mes_ano.keys()):
        nums = por_mes_ano.get(mes, {}).get(key, set())
        if nums and min(nums) <= n <= max(nums):
            no_intervalo.append(mes)
    if no_intervalo:
        return min(no_intervalo)

    for mes in range(1, 13):
        nums = por_mes_ano.get(mes, {}).get(key, set())
        if not nums:
            continue
        max_m = max(nums)
        if n <= max_m:
            continue
        fut: set[int] = set()
        for m2 in range(mes + 1, 13):
            fut |= por_mes_ano.get(m2, {}).get(key, set())
        fut_acima = sorted(x for x in fut if x > max_m)
        if not fut_acima:
            continue
        min_fut = fut_acima[0]
        if max_m < n < min_fut and (min_fut - max_m) <= MAX_SALTO_ENTRE_NOTAS_CONSECUTIVAS:
            return mes

    if mes_armazenado and 1 <= int(mes_armazenado) <= 12:
        return int(mes_armazenado)
    return None


def _arquivo_fiscal_series_por_competencia(
    cnpj: str,
    ano: int,
    mes: int | None = None,
    meses: list[int] | None = None,
) -> pd.DataFrame:
    """Resumo no ano/mês ou em vários meses.
    Emissão própria: uma linha por tipo (modelo) + série, com 1ª/última nota.
    Terceiros: uma linha por tipo (NF-e, CT-e, …) — só quantidades, sem série nem notas.
    Inutilizadas entram no mês da numeração (intervalo ou buraco), não no mês do evento Sefaz."""
    from collections import defaultdict

    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cnpj) != 14 or not _arquivo_fiscal_db_path(cnpj).is_file():
        return pd.DataFrame()
    ms_filtro = _arquivo_fiscal_meses_filtro_ativos(mes, meses)
    if not ms_filtro:
        return pd.DataFrame()
    ms_set = set(ms_filtro)
    ano_i = int(ano)
    por_mes_nums = _arquivo_fiscal_cache_ano(cnpj, ano_i)["por_mes"]

    conn = _arquivo_fiscal_conn(cnpj)
    try:
        params_pr: list = [cnpj, ano_i]
        sql_u_pr = _arquivo_fiscal_sql_filtro_usuario(params_pr)
        sql_m_pr = _arquivo_fiscal_sql_filtro_meses(mes, meses, params_pr)
        rows_pr = conn.execute(
            f"""
            SELECT modelo, serie, numero,
                   upper(trim(COALESCE(status, ''))) AS st,
                   mes
            FROM xml_arquivo
            WHERE cnpj_empresa = ? AND ano = ? AND is_propria = 1
              AND numero IS NOT NULL AND numero > 0
              AND upper(trim(COALESCE(status, ''))) != 'INUTILIZADOS'
              {sql_u_pr}
              {sql_m_pr}
            """,
            params_pr,
        ).fetchall()
        params_in: list = [cnpj, ano_i]
        sql_u_in = _arquivo_fiscal_sql_filtro_usuario(params_in)
        rows_inut = conn.execute(
            f"""
            SELECT modelo, serie, numero, mes
            FROM xml_arquivo
            WHERE cnpj_empresa = ? AND is_propria = 1
              AND numero IS NOT NULL AND numero > 0
              AND upper(trim(COALESCE(status, ''))) = 'INUTILIZADOS'
              AND (ano = ? OR ano IS NULL)
              {sql_u_in}
            """,
            params_in,
        ).fetchall()

        sql_te = """
            SELECT CASE WHEN modelo IN ('CT-e', 'CT-e OS') THEN 'CT-e'
                        WHEN trim(COALESCE(modelo, '')) = '' THEN 'Outros'
                        ELSE modelo END AS tipo,
                   COUNT(*) AS qtd,
                   SUM(CASE WHEN upper(status) = 'NORMAIS' THEN 1 ELSE 0 END) AS normais,
                   SUM(CASE WHEN upper(status) = 'CANCELADOS' THEN 1 ELSE 0 END) AS cancelados,
                   SUM(CASE WHEN upper(status) = 'INUTILIZADOS' THEN 1 ELSE 0 END) AS inutilizados
            FROM xml_arquivo
            WHERE cnpj_empresa = ? AND ano = ? AND is_propria = 0
        """
        params_te: list = [cnpj, ano_i]
        sql_te += _arquivo_fiscal_sql_filtro_usuario(params_te)
        sql_te += _arquivo_fiscal_sql_filtro_meses(mes, meses, params_te)
        sql_te += """
            GROUP BY tipo
            ORDER BY tipo
        """
        rows_te = conn.execute(sql_te, params_te).fetchall()
    finally:
        conn.close()

    agg_pr: dict[tuple[str, str], dict] = defaultdict(
        lambda: {
            "nums": set(),
            "qtd": 0,
            "normais": 0,
            "cancelados_nums": set(),
            "inutilizados": 0,
        }
    )
    for mod, ser, num, st, mes_db in rows_pr:
        tipo = _normaliza_modelo_filtro(mod) or "—"
        ser_n = _normaliza_serie_filtro(ser) or "—"
        key = (tipo, ser_n)
        try:
            n = int(num)
        except (TypeError, ValueError):
            continue
        if n <= 0:
            continue
        try:
            mes_comp = int(mes_db) if mes_db is not None else None
        except (TypeError, ValueError):
            mes_comp = None
        if mes_comp is None or mes_comp not in ms_set:
            continue
        st_u = str(st or "").strip().upper()
        bucket = agg_pr[key]
        bucket["nums"].add(n)
        bucket["qtd"] += 1
        if st_u == "NORMAIS":
            bucket["normais"] += 1
        elif st_u == "CANCELADOS":
            bucket["cancelados_nums"].add(n)

    for mod, ser, num, mes_db in rows_inut:
        tipo = _normaliza_modelo_filtro(mod) or "—"
        ser_n = _normaliza_serie_filtro(ser) or "—"
        key = (tipo, ser_n)
        try:
            n = int(num)
        except (TypeError, ValueError):
            continue
        if n <= 0:
            continue
        try:
            mes_i = int(mes_db) if mes_db is not None else None
        except (TypeError, ValueError):
            mes_i = None
        mes_comp = _arquivo_fiscal_inferir_mes_competencia_inutilizada(
            por_mes_nums, mod, ser, n, mes_armazenado=mes_i
        )
        if mes_comp is None or mes_comp not in ms_set:
            continue
        bucket = agg_pr[key]
        bucket["nums"].add(n)
        bucket["qtd"] += 1
        bucket["inutilizados"] += 1

    buracos_por_serie: dict[tuple[str, str], int] = defaultdict(int)
    if ms_filtro:
        try:
            df_bur_reais, _df_fal = _arquivo_fiscal_buracos_painel_periodo(
                cnpj, ano_i, list(ms_filtro)
            )
            if df_bur_reais is not None and not df_bur_reais.empty:
                for _, brow in df_bur_reais.iterrows():
                    tb = _normaliza_modelo_filtro(brow.get("Tipo")) or str(
                        brow.get("Tipo") or ""
                    ).strip()
                    sb = _normaliza_serie_filtro(brow.get("Série")) or str(
                        brow.get("Série") or ""
                    ).strip()
                    if tb and sb:
                        buracos_por_serie[(tb, sb)] += 1
        except Exception:
            pass

    recs: list[dict] = []
    for (tipo, ser_n), b in sorted(agg_pr.items()):
        nums = b["nums"]
        recs.append(
            {
                "Origem": "Emissão própria",
                "Tipo": tipo,
                "Série": ser_n,
                "1ª nota": str(min(nums)) if nums else "",
                "Últ. nota": str(max(nums)) if nums else "",
                "Quantidade": int(b["qtd"]),
                "Buracos": int(buracos_por_serie.get((tipo, ser_n), 0)),
                "Normais": int(b["normais"]),
                "Canceladas": int(len(b["cancelados_nums"])),
                "Inutilizadas": int(b["inutilizados"]),
            }
        )
    for tipo, qtd, no, ca, inu in rows_te:
        recs.append(
            {
                "Origem": "Terceiros",
                "Tipo": str(tipo or "").strip() or "—",
                "Série": "—",
                "1ª nota": "—",
                "Últ. nota": "—",
                "Quantidade": int(qtd or 0),
                "Buracos": "—",
                "Normais": int(no or 0),
                "Canceladas": int(ca or 0),
                "Inutilizadas": int(inu or 0),
            }
        )
    if not recs:
        return pd.DataFrame()
    recs.sort(key=lambda r: (0 if r["Origem"] == "Emissão própria" else 1, r["Tipo"], r["Série"]))
    return pd.DataFrame(recs)


_ARQUIVO_FISCAL_STATUS_COM_NUMERO = frozenset(
    {"NORMAIS", "CANCELADOS", "DENEGADOS", "REJEITADOS"}
)


def _arquivo_fiscal_series_coincidem(serie_a, serie_b) -> bool:
    return _normaliza_serie_filtro(serie_a) == _normaliza_serie_filtro(serie_b)


def _arquivo_fiscal_inutilizados_map(
    cnpj: str, ano: int | None = None
) -> dict[tuple[str, str], set[int]]:
    """Inutilizados (XML ou Sefaz) por (modelo, série), opcionalmente no ano."""
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj)
    out: dict[tuple[str, str], set[int]] = {}
    if len(cnpj) != 14 or not _arquivo_fiscal_db_path(cnpj).is_file():
        return out
    sql = """
            SELECT modelo, serie, numero
            FROM xml_arquivo
            WHERE cnpj_empresa = ? AND is_propria = 1
              AND upper(trim(COALESCE(status, ''))) = 'INUTILIZADOS'
              AND numero IS NOT NULL AND numero > 0
    """
    params: list = [cnpj]
    if ano is not None:
        sql += " AND (ano = ? OR ano IS NULL)"
        params.append(int(ano))
    conn = _arquivo_fiscal_conn(cnpj)
    try:
        rows = conn.execute(sql, params).fetchall()
    finally:
        conn.close()
    for mod, ser, num in rows:
        key = (
            _normaliza_modelo_filtro(mod),
            _normaliza_serie_filtro(ser),
        )
        if not key[0] or not key[1]:
            continue
        try:
            out.setdefault(key, set()).add(int(num))
        except (TypeError, ValueError):
            continue
    return out


def _arquivo_fiscal_nums_propria_ano(
    cnpj: str,
    ano: int,
) -> dict[int, dict[tuple[str, str], set[int]]]:
    """Números de emissão própria por mês e (modelo, série) num ano."""
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj)
    por_mes: dict[int, dict[tuple[str, str], set[int]]] = {}
    if len(cnpj) != 14 or not _arquivo_fiscal_db_path(cnpj).is_file():
        return por_mes
    st_ph = ",".join("?" * len(_ARQUIVO_FISCAL_STATUS_COM_NUMERO))
    conn = _arquivo_fiscal_conn(cnpj)
    try:
        params_n: list = [cnpj, int(ano), *sorted(_ARQUIVO_FISCAL_STATUS_COM_NUMERO)]
        sql_u = _arquivo_fiscal_sql_filtro_usuario(params_n)
        rows = conn.execute(
            f"""
            SELECT modelo, serie, numero, mes, upper(trim(COALESCE(status, ''))) AS st
            FROM xml_arquivo
            WHERE cnpj_empresa = ? AND ano = ? AND mes IS NOT NULL
              AND is_propria = 1 AND numero IS NOT NULL AND numero > 0
              AND upper(trim(COALESCE(status, ''))) IN ({st_ph})
              {sql_u}
            """,
            params_n,
        ).fetchall()
    finally:
        conn.close()
    for mod, ser, num, mes, _st in rows:
        try:
            m = int(mes)
        except (TypeError, ValueError):
            continue
        if not 1 <= m <= 12:
            continue
        key = (
            _normaliza_modelo_filtro(mod),
            _normaliza_serie_filtro(ser),
        )
        if not key[0] or not key[1]:
            continue
        try:
            n = int(num)
        except (TypeError, ValueError):
            continue
        por_mes.setdefault(m, {}).setdefault(key, set()).add(n)
    return por_mes


_arquivo_fiscal_runtime_cache: dict[str, dict] = {}


def _arquivo_fiscal_invalidar_runtime_cache(
    cnpj: str | None = None,
    *,
    tocar_meta: bool = True,
    manter_schema: bool = False,
    manter_comp_resumo: bool = False,
) -> None:
    """Limpa cache em memória após garimpo ou alteração no SQLite."""
    if not cnpj:
        _arquivo_fiscal_runtime_cache.clear()
        _arquivo_fiscal_schema_pronto.clear()
        return
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    _arquivo_fiscal_invalidar_cache_pasta(cx)
    try:
        _arquivo_fiscal_apagar_cache_ui_disco(cx)
    except Exception:
        pass
    if manter_comp_resumo:
        for k in list(_arquivo_fiscal_runtime_cache):
            if k != cx and not str(k).startswith(cx + "::"):
                continue
            cc = _arquivo_fiscal_runtime_cache.get(k)
            if not isinstance(cc, dict):
                _arquivo_fiscal_runtime_cache.pop(k, None)
                continue
            cc["inut_ano"] = {}
            cc["nf_idx_ano"] = {}
            cc["por_mes_ano"] = {}
            cc["xml_total"] = None
            cc["comp_resumo"] = None
        if not manter_schema:
            _arquivo_fiscal_schema_pronto.discard(cx)
        if not tocar_meta:
            return
        try:
            conn = _arquivo_fiscal_conn(cx)
            try:
                conn.execute("DELETE FROM arquivo_meta WHERE chave = ?", ("xml_total",))
                conn.commit()
            finally:
                conn.close()
        except Exception:
            pass
        return
    for k in list(_arquivo_fiscal_runtime_cache):
        if k == cx or str(k).startswith(cx + "::"):
            _arquivo_fiscal_runtime_cache.pop(k, None)
    if not manter_schema:
        _arquivo_fiscal_schema_pronto.discard(cx)
    if not tocar_meta:
        return
    try:
        conn = _arquivo_fiscal_conn(cx)
        try:
            conn.execute("DELETE FROM arquivo_meta WHERE chave = ?", ("xml_total",))
            conn.commit()
        finally:
            conn.close()
    except Exception:
        pass


def _arquivo_fiscal_indice_nf_propria(
    cnpj: str, ano: int | None = None
) -> dict[tuple[str, str, int], list[tuple]]:
    """
    Índice (modelo, série, nota) → ocorrências no arquivo — uma leitura SQL por CNPJ/ano.
    Usado para falsos buracos sem consulta SQL por lacuna.
    """
    from collections import defaultdict

    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    out: dict[tuple[str, str, int], list[tuple]] = defaultdict(list)
    if len(cx) != 14 or not _arquivo_fiscal_db_path(cx).is_file():
        return {}
    st_ph = ",".join("?" * len(_ARQUIVO_FISCAL_STATUS_COM_NUMERO))
    sql = f"""
            SELECT modelo, serie, numero, ano, mes, status, data_emissao
            FROM xml_arquivo
            WHERE cnpj_empresa = ? AND is_propria = 1
              AND numero IS NOT NULL AND numero > 0
              AND upper(trim(COALESCE(status, ''))) IN ({st_ph})
    """
    params: list = [cx, *sorted(_ARQUIVO_FISCAL_STATUS_COM_NUMERO)]
    if ano is not None:
        sql += " AND (ano = ? OR ano IS NULL)"
        params.append(int(ano))
    conn = _arquivo_fiscal_conn(cx)
    try:
        rows = conn.execute(sql, params).fetchall()
    finally:
        conn.close()
    for mod, ser, num, ano, mes, st, de in rows:
        key = (
            _normaliza_modelo_filtro(mod),
            _normaliza_serie_filtro(ser),
        )
        if not key[0] or not key[1]:
            continue
        try:
            n = int(num)
        except (TypeError, ValueError):
            continue
        if n <= 0:
            continue
        try:
            ad = int(ano) if ano is not None else None
        except (TypeError, ValueError):
            ad = None
        try:
            md = int(mes) if mes is not None else None
        except (TypeError, ValueError):
            md = None
        out[(key[0], key[1], n)].append(
            (ad, md, str(st or "").strip() or "—", de)
        )
    return dict(out)


def _arquivo_fiscal_cache_cnpj(cnpj: str) -> dict:
    """Cache por empresa: inutilizadas, índice de NF e por_mes por ano (lazy)."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    # Auxiliar: cache separado por utilizador (não misturar com visão completa)
    if _arquivo_fiscal_filtro_so_meus():
        ck = f"{cx}::u::{_arquivo_fiscal_usuario_sessao()}"
    else:
        ck = cx
    if ck not in _arquivo_fiscal_runtime_cache:
        _arquivo_fiscal_runtime_cache[ck] = {
            "inut_ano": {},
            "nf_idx_ano": {},
            "por_mes_ano": {},
            "xml_total": None,
            "comp_resumo": None,
        }
    return _arquivo_fiscal_runtime_cache[ck]


def _arquivo_fiscal_cache_ano(cnpj: str, ano: int) -> dict:
    """Dados do ano reutilizáveis entre resumo, buracos e tabelas de status."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    cc = _arquivo_fiscal_cache_cnpj(cx)
    ano_i = int(ano)
    if ano_i not in cc["por_mes_ano"]:
        cc["por_mes_ano"][ano_i] = _arquivo_fiscal_nums_propria_ano(cx, ano_i)
    if ano_i not in cc["inut_ano"]:
        cc["inut_ano"][ano_i] = _arquivo_fiscal_inutilizados_map(cx, ano_i)
    if ano_i not in cc["nf_idx_ano"]:
        cc["nf_idx_ano"][ano_i] = _arquivo_fiscal_indice_nf_propria(cx, ano_i)
    return {
        "por_mes": cc["por_mes_ano"][ano_i],
        "inut": cc["inut_ano"][ano_i],
        "nf_idx": cc["nf_idx_ano"][ano_i],
    }


def _arquivo_fiscal_buscar_nf_fora_competencia_mem(
    nf_idx: dict,
    mod: str,
    ser: str,
    numero: int,
    *,
    ano_ref: int,
    mes_ref: int,
) -> tuple[int | None, int | None, str, str | None] | None:
    mod_n = _normaliza_modelo_filtro(mod)
    ser_n = _normaliza_serie_filtro(ser)
    try:
        n = int(numero)
    except (TypeError, ValueError):
        return None
    for ad, md, st_doc, de_doc in nf_idx.get((mod_n, ser_n, n), ()):
        if ad == int(ano_ref) and md == int(mes_ref):
            continue
        return (ad, md, st_doc, de_doc)
    return None


def _arquivo_fiscal_numero_no_intervalo_mes_anterior(
    nf: int,
    por_mes_ano: dict[int, dict[tuple[str, str], set[int]]],
    key: tuple[str, str],
    mes: int,
) -> bool:
    """
    True se o número está entre a 1ª e a última nota de algum mês anterior
    (mesma série) — não pode ser buraco neste mês (ex.: 1894 no intervalo de
    maio não é buraco em junho, mesmo que a NF tenha sido lida com emissão em maio).
    """
    try:
        n = int(nf)
    except (TypeError, ValueError):
        return False
    for m2 in range(1, int(mes)):
        nums_ant = por_mes_ano.get(m2, {}).get(key, set())
        if not nums_ant:
            continue
        if min(nums_ant) <= n <= max(nums_ant):
            return True
    return False


def _arquivo_fiscal_buracos_competencia(
    por_mes_ano: dict[int, dict[tuple[str, str], set[int]]],
    inut: dict[tuple[str, str], set[int]],
    ano: int,
    mes: int,
) -> list[dict]:
    """
    Buracos num único mês de competência:
    - faltas entre notas do próprio mês;
    - faltas entre o último nº do mês e o primeiro nº de meses posteriores
      (ex.: maio termina em 100, junho tem a 101 — buraco em maio).
    Não gera buraco no mês se o número cair no intervalo 1ª–última de um mês anterior.
    """
    nums_mes = por_mes_ano.get(int(mes), {})
    if not nums_mes:
        return []
    periodo = f"{int(ano)} ({int(mes):02d})"
    buracos: list[dict] = []
    for (mod, ser), nums in sorted(nums_mes.items()):
        if not nums:
            continue
        key = (mod, ser)
        inut_s = inut.get(key, set())
        sorted_m = sorted(nums)

        def _aceita_buraco(nf: int) -> bool:
            if nf in inut_s:
                return False
            if _arquivo_fiscal_numero_no_intervalo_mes_anterior(
                nf, por_mes_ano, key, int(mes)
            ):
                return False
            return True

        if len(sorted_m) >= 2:
            for row in enumerar_buracos_por_segmento(sorted_m, mod, ser):
                nf = int(row["Num_Faltante"])
                if not _aceita_buraco(nf):
                    continue
                buracos.append(
                    {
                        "Tipo": mod,
                        "Série": ser,
                        "Num_Faltante": nf,
                        "Período": periodo,
                        "Mês possível": _arquivo_fiscal_emitida_em_texto(
                            None, int(ano), int(mes)
                        ),
                    }
                )
        fut: set[int] = set()
        for m2 in range(int(mes) + 1, 13):
            fut |= por_mes_ano.get(m2, {}).get(key, set())
        max_m = sorted_m[-1]
        fut_acima = sorted(n for n in fut if n > max_m)
        if fut_acima:
            min_fut = fut_acima[0]
            if 0 < min_fut - max_m <= MAX_SALTO_ENTRE_NOTAS_CONSECUTIVAS:
                for b in range(max_m + 1, min_fut):
                    if b not in nums and _aceita_buraco(b):
                        buracos.append(
                            {
                                "Tipo": mod,
                                "Série": ser,
                                "Num_Faltante": b,
                                "Período": periodo,
                                "Mês possível": _arquivo_fiscal_emitida_em_texto(
                                    None, int(ano), int(mes)
                                ),
                            }
                        )
    return buracos


def _arquivo_fiscal_buscar_nf_fora_competencia(
    conn,
    cnpj: str,
    mod: str,
    ser: str,
    numero: int,
    *,
    ano_ref: int,
    mes_ref: int,
) -> tuple[int | None, int | None, str, str | None] | None:
    """NF com mesmo modelo/série/número fora do mês analisado (ex.: lida em junho, buraco em maio)."""
    st_ph = ",".join("?" * len(_ARQUIVO_FISCAL_STATUS_COM_NUMERO))
    mod_n = _normaliza_modelo_filtro(mod)
    rows = conn.execute(
        f"""
        SELECT ano, mes, modelo, serie, status, data_emissao
        FROM xml_arquivo
        WHERE cnpj_empresa = ? AND is_propria = 1
          AND numero = ?
          AND upper(trim(COALESCE(status, ''))) IN ({st_ph})
        ORDER BY ano DESC, mes DESC
        """,
        (cnpj, int(numero), *sorted(_ARQUIVO_FISCAL_STATUS_COM_NUMERO)),
    ).fetchall()
    for ano_doc, mes_doc, mod_db, ser_db, st_doc, de_doc in rows:
        if _normaliza_modelo_filtro(mod_db) != mod_n:
            continue
        if not _arquivo_fiscal_series_coincidem(ser_db, ser):
            continue
        try:
            ad = int(ano_doc) if ano_doc is not None else None
            md = int(mes_doc) if mes_doc is not None else None
        except (TypeError, ValueError):
            ad = md = None
        if ad == int(ano_ref) and md == int(mes_ref):
            continue
        return (ad, md, str(st_doc or "").strip() or "—", de_doc)
    return None


def _arquivo_fiscal_buracos_periodo(
    cnpj: str,
    ano: int,
    meses: list[int],
    *,
    por_mes: dict | None = None,
    inut: dict | None = None,
) -> pd.DataFrame:
    """
    Buracos em **emissão própria** por mês de competência (não mistura meses no mesmo cálculo).
    Inclui faltas entre o último nº do mês e o primeiro dos meses seguintes.
    Inutilizados (XML ou Sefaz) não aparecem como buraco.
    """
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj)
    ms = sorted({int(m) for m in (meses or []) if 1 <= int(m) <= 12})
    cols_bur = ["Tipo", "Série", "Num_Faltante", "Período", "Mês possível"]
    if len(cnpj) != 14 or not ms or not _arquivo_fiscal_db_path(cnpj).is_file():
        return pd.DataFrame(columns=cols_bur)
    if por_mes is None or inut is None:
        ca = _arquivo_fiscal_cache_ano(cnpj, int(ano))
        por_mes = ca["por_mes"]
        inut = ca["inut"]
    buracos: list[dict] = []
    for mes in ms:
        buracos.extend(_arquivo_fiscal_buracos_competencia(por_mes, inut, int(ano), mes))
    return pd.DataFrame(buracos) if buracos else pd.DataFrame(columns=cols_bur)


_MESES_ARQUIVO_CURTO = (
    "",
    "Jan",
    "Fev",
    "Mar",
    "Abr",
    "Mai",
    "Jun",
    "Jul",
    "Ago",
    "Set",
    "Out",
    "Nov",
    "Dez",
)


def _arquivo_fiscal_emitida_em_texto(
    data_emissao=None,
    ano=None,
    mes=None,
) -> str:
    """Mês/ano de emissão legível (ex.: Jun/2026) — prioriza data_emissao do XML."""
    de = _arquivo_fiscal_data_emissao_iso(data_emissao)
    if de and len(de) >= 7:
        try:
            a, m = int(de[:4]), int(de[5:7])
            if 1 <= m <= 12:
                return f"{_MESES_ARQUIVO_CURTO[m]}/{a}"
        except (TypeError, ValueError):
            pass
    try:
        if ano is not None and mes is not None:
            m = int(mes)
            if 1 <= m <= 12:
                return f"{_MESES_ARQUIVO_CURTO[m]}/{int(ano)}"
    except (TypeError, ValueError):
        pass
    return "—"


def _arquivo_fiscal_competencia_exibicao(
    ano,
    mes,
    data_emissao=None,
) -> str:
    """Texto de competência para exibir (ano/mês do índice ou data de emissão)."""
    txt = _arquivo_fiscal_emitida_em_texto(data_emissao, ano, mes)
    if txt != "—":
        return txt
    try:
        if ano is not None and mes is not None:
            return f"{int(ano)}/{int(mes):02d}"
    except (TypeError, ValueError):
        pass
    return "outro período"


def _arquivo_fiscal_falsos_buracos_periodo(
    cnpj: str,
    ano: int,
    meses: list[int],
    *,
    por_mes: dict | None = None,
    inut: dict | None = None,
    nf_idx: dict | None = None,
) -> pd.DataFrame:
    """
    Buracos «falsos»: o número falta no mês analisado (pela sequência), mas a NF já existe
    no arquivo noutra competência (ex.: buraco em maio, nota lida com emissão em junho).
    Analisa **cada mês** à parte — não mistura maio+junho no mesmo cálculo de buraco.
    """
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj)
    ms = sorted({int(m) for m in (meses or []) if 1 <= int(m) <= 12})
    cols = [
        "Tipo",
        "Série",
        "Num_Faltante",
        "Buraco em",
        "Emitida em",
        "Data emissão",
        "Status NF",
    ]
    if len(cnpj) != 14 or not ms or not _arquivo_fiscal_db_path(cnpj).is_file():
        return pd.DataFrame(columns=cols)
    if por_mes is None or inut is None or nf_idx is None:
        ca = _arquivo_fiscal_cache_ano(cnpj, int(ano))
        por_mes = ca["por_mes"]
        inut = ca["inut"]
        nf_idx = ca["nf_idx"]
    falsos: list[dict] = []
    vistos: set[tuple[str, str, int, str]] = set()
    for mes in ms:
        periodo = f"{int(ano)} ({int(mes):02d})"
        for brow in _arquivo_fiscal_buracos_competencia(por_mes, inut, int(ano), mes):
            mod = str(brow.get("Tipo") or "").strip()
            ser = str(brow.get("Série") or "").strip()
            try:
                nf = int(brow.get("Num_Faltante"))
            except (TypeError, ValueError):
                continue
            if not mod or not ser or nf <= 0:
                continue
            chave = (mod, ser, nf, periodo)
            if chave in vistos:
                continue
            hit = _arquivo_fiscal_buscar_nf_fora_competencia_mem(
                nf_idx,
                mod,
                ser,
                nf,
                ano_ref=int(ano),
                mes_ref=int(mes),
            )
            if not hit:
                continue
            ad, md, st_doc, de_doc = hit
            vistos.add(chave)
            emitida = _arquivo_fiscal_emitida_em_texto(de_doc, ad, md)
            falsos.append(
                {
                    "Tipo": mod,
                    "Série": ser,
                    "Num_Faltante": nf,
                    "Buraco em": periodo,
                    "Emitida em": emitida,
                    "Data emissão": _valor_data_emissao_dd_mm_yyyy(de_doc) or "—",
                    "Status NF": st_doc,
                }
            )
    return pd.DataFrame(falsos, columns=cols) if falsos else pd.DataFrame(columns=cols)


def _arquivo_fiscal_buracos_reais_de_todos(
    df_bur: pd.DataFrame,
    df_fal: pd.DataFrame,
) -> pd.DataFrame:
    """Remove buracos «falsos» de um DataFrame de buracos já calculado."""
    if df_bur is None or df_bur.empty:
        return df_bur
    if df_fal is None or df_fal.empty:
        return df_bur
    fal = {
        (
            str(r.get("Tipo") or "").strip(),
            str(r.get("Série") or "").strip(),
            int(r.get("Num_Faltante")),
            str(r.get("Buraco em") or r.get("Período analisado") or "").strip(),
        )
        for _, r in df_fal.iterrows()
    }
    keep = []
    for _, r in df_bur.iterrows():
        k = (
            str(r.get("Tipo") or "").strip(),
            str(r.get("Série") or "").strip(),
            int(r.get("Num_Faltante")),
            str(r.get("Período") or r.get("Buraco em") or "").strip(),
        )
        if k not in fal:
            keep.append(r.to_dict())
    return pd.DataFrame(keep) if keep else df_bur.iloc[0:0].copy()


def _arquivo_fiscal_buracos_painel_periodo(
    cnpj: str,
    ano: int,
    meses: list[int],
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Buracos reais + falsos num único passo (cache do ano, falsos calculados 1×)."""
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj)
    ms = sorted({int(m) for m in (meses or []) if 1 <= int(m) <= 12})
    cols_bur = ["Tipo", "Série", "Num_Faltante", "Período", "Mês possível"]
    cols_fal = [
        "Tipo",
        "Série",
        "Num_Faltante",
        "Buraco em",
        "Emitida em",
        "Data emissão",
        "Status NF",
    ]
    vazio_bur = pd.DataFrame(columns=cols_bur)
    vazio_fal = pd.DataFrame(columns=cols_fal)
    if len(cnpj) != 14 or not ms or not _arquivo_fiscal_db_path(cnpj).is_file():
        return vazio_bur, vazio_fal
    ca = _arquivo_fiscal_cache_ano(cnpj, int(ano))
    por_mes = ca["por_mes"]
    inut = ca["inut"]
    nf_idx = ca["nf_idx"]
    df_fal = _arquivo_fiscal_falsos_buracos_periodo(
        cnpj, ano, ms, por_mes=por_mes, inut=inut, nf_idx=nf_idx
    )
    df_bur = _arquivo_fiscal_buracos_periodo(
        cnpj, ano, ms, por_mes=por_mes, inut=inut
    )
    df_reais = _arquivo_fiscal_buracos_reais_de_todos(df_bur, df_fal)
    return df_reais, df_fal


def _arquivo_fiscal_buracos_reais_periodo(
    cnpj: str,
    ano: int,
    meses: list[int],
) -> pd.DataFrame:
    """Buracos do período excluindo os «falsos» (NF já lida noutra competência)."""
    df_reais, _ = _arquivo_fiscal_buracos_painel_periodo(cnpj, ano, meses)
    return df_reais


def _arquivo_fiscal_resumo_periodo(
    cnpj: str,
    ano: int,
    meses: list[int],
) -> dict:
    """Totais agregados para vários meses no mesmo ano."""
    comp = _arquivo_fiscal_competencias_resumo(cnpj)
    tot = pr = te = 0
    for m in meses:
        info = comp.get((int(ano), int(m)), {})
        tot += int(info.get("total") or 0)
        pr += int(info.get("propria") or 0)
        te += int(info.get("terceiros") or 0)
    return {"total": tot, "propria": pr, "terceiros": te}


_ARQUIVO_FISCAL_STATUS_RESUMO_UI = (
    ("INUTILIZADOS", "Inutilizadas"),
    ("CANCELADOS", "Canceladas"),
    ("NORMAIS", "Autorizadas"),
    ("DENEGADOS", "Denegadas"),
    ("REJEITADOS", "Rejeitadas"),
)


def _arquivo_fiscal_dedup_inutil_por_nota(recs: list[dict]) -> list[dict]:
    """Uma linha por modelo/série/número (XML rejeitado promovido + stub Sefaz)."""
    best: dict[tuple, dict] = {}
    ordem: list[tuple] = []
    for rec in recs:
        k = (
            str(rec.get("Modelo") or "").strip(),
            str(rec.get("Série") or rec.get("Serie") or "").strip(),
            rec.get("Nota"),
        )
        if k not in best:
            ordem.append(k)
        best[k] = rec
    return [best[k] for k in ordem]


def _arquivo_fiscal_tabelas_status_periodo(
    cnpj: str,
    ano: int,
    meses: list[int],
    *,
    is_propria: int = 1,
) -> dict[str, pd.DataFrame]:
    """
    Tabelas por status (emissão própria) para o período — mesmo espírito do relatório híbrido
    (inutilizadas, canceladas, autorizadas, …).
    """
    cols_padrao = ["Modelo", "Série", "Nota", "Data Emissão", "Chave"]
    cols_inut = ["Modelo", "Série", "Nota", "Data Inutilização"]
    vazio = {
        k: pd.DataFrame(columns=cols_inut if k == "INUTILIZADOS" else cols_padrao)
        for k, _ in _ARQUIVO_FISCAL_STATUS_RESUMO_UI
    }
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj)
    ms = sorted({int(m) for m in (meses or []) if 1 <= int(m) <= 12})
    if len(cnpj) != 14 or not ms or not _arquivo_fiscal_db_path(cnpj).is_file():
        return vazio
    st_ok = tuple(k for k, _ in _ARQUIVO_FISCAL_STATUS_RESUMO_UI)
    ph_m = ",".join("?" * len(ms))
    ph_s = ",".join("?" * len(st_ok))
    ms_set = set(ms)
    por_mes_nums = (
        _arquivo_fiscal_cache_ano(cnpj, int(ano))["por_mes"]
        if int(is_propria) == 1
        else {}
    )
    _MAX_STATUS_SQL = 2000
    counts: dict[str, int] = {}
    rows: list = []
    rows_inut: list = []
    conn = _arquivo_fiscal_conn(cnpj)
    try:
        rows_cnt = conn.execute(
            f"""
            SELECT upper(trim(COALESCE(status, ''))) AS st, COUNT(*)
            FROM xml_arquivo
            WHERE cnpj_empresa = ? AND ano = ? AND is_propria = ?
              AND upper(trim(COALESCE(status, ''))) IN ({ph_s})
              AND upper(trim(COALESCE(status, ''))) != 'INUTILIZADOS'
              AND mes IN ({ph_m})
            GROUP BY st
            """,
            (cnpj, int(ano), int(is_propria), *st_ok, *ms),
        ).fetchall()
        for st, n in rows_cnt:
            counts[str(st or "").strip().upper()] = int(n or 0)
        for st_key, _ in _ARQUIVO_FISCAL_STATUS_RESUMO_UI:
            if st_key == "INUTILIZADOS":
                continue
            lim = 2500 if st_key == "CANCELADOS" else _MAX_STATUS_SQL
            parte = conn.execute(
                f"""
                SELECT upper(trim(COALESCE(status, ''))) AS st,
                       modelo, serie, numero, data_emissao, mes, chave
                FROM xml_arquivo
                WHERE cnpj_empresa = ? AND ano = ? AND is_propria = ?
                  AND upper(trim(COALESCE(status, ''))) = ?
                  AND mes IN ({ph_m})
                ORDER BY modelo, serie, numero
                LIMIT {int(lim)}
                """,
                (cnpj, int(ano), int(is_propria), st_key, *ms),
            ).fetchall()
            rows.extend(parte)
        if int(is_propria) == 1:
            rows_inut = conn.execute(
                """
                SELECT modelo, serie, numero, data_emissao, mes, chave,
                       capturado_em, atualizado_em, resumo_json
                FROM xml_arquivo
                WHERE cnpj_empresa = ? AND is_propria = 1
                  AND upper(trim(COALESCE(status, ''))) = 'INUTILIZADOS'
                  AND numero IS NOT NULL AND numero > 0
                  AND (ano = ? OR ano IS NULL)
                ORDER BY modelo, serie, numero
                """,
                (cnpj, int(ano)),
            ).fetchall()
    finally:
        conn.close()
    buckets: dict[str, list[dict]] = {k: [] for k, _ in _ARQUIVO_FISCAL_STATUS_RESUMO_UI}
    # Autorizada (44) marcada CANCELADOS + evento (44#CANCELADOS) = 2 linhas com a
    # mesma chave visível. Fica uma: prefere o evento.
    cancel_por_k44: dict[str, tuple[int, dict]] = {}
    for st, mod, ser, num, de, _mes_db, chave_db in rows:
        st_u = str(st or "").strip().upper()
        if st_u not in buckets:
            continue
        try:
            nota = int(num) if num is not None else ""
        except (TypeError, ValueError):
            nota = str(num or "").strip()
        ch_ex = _chave_exibicao_relatorio(chave_db) or "—"
        rec = {
            "Modelo": str(mod or "").strip(),
            "Série": _normaliza_serie_filtro(ser),
            "Nota": nota,
            "Data Emissão": _valor_data_emissao_dd_mm_yyyy(de) or "—",
            "Chave": ch_ex,
        }
        if st_u == "CANCELADOS":
            k44 = _chave44_digitos(chave_db) or str(chave_db or "").split("#")[0].strip()
            if not k44:
                buckets[st_u].append(rec)
                continue
            pref = 2 if "#" in str(chave_db or "") else 0
            prev = cancel_por_k44.get(k44)
            if prev is None or pref >= prev[0]:
                cancel_por_k44[k44] = (pref, rec)
            continue
        buckets[st_u].append(rec)
    buckets["CANCELADOS"].extend(rec for _p, rec in cancel_por_k44.values())
    for mod, ser, num, de, mes_db, chave_db, cap_em, atu_em, rj in rows_inut:
        try:
            nota = int(num) if num is not None else ""
        except (TypeError, ValueError):
            continue
        try:
            mes_i = int(mes_db) if mes_db is not None else None
        except (TypeError, ValueError):
            mes_i = None
        mes_comp = _arquivo_fiscal_inferir_mes_competencia_inutilizada(
            por_mes_nums, mod, ser, nota, mes_armazenado=mes_i
        )
        if mes_comp is None or mes_comp not in ms_set:
            continue
        di = _arquivo_fiscal_data_inutilizacao_de_registo(
            chave=chave_db,
            capturado_em=cap_em,
            atualizado_em=atu_em,
            resumo_json=rj,
            data_emissao=de,
        )
        buckets["INUTILIZADOS"].append(
            {
                "Modelo": str(mod or "").strip(),
                "Série": _normaliza_serie_filtro(ser),
                "Nota": nota,
                "Data Inutilização": _valor_data_emissao_dd_mm_yyyy(di) or "—",
            }
        )
    buckets["INUTILIZADOS"] = _arquivo_fiscal_dedup_inutil_por_nota(
        buckets["INUTILIZADOS"]
    )
    out: dict[str, pd.DataFrame] = {}
    for k, _ in _ARQUIVO_FISCAL_STATUS_RESUMO_UI:
        recs = buckets.get(k) or []
        cols_out = cols_inut if k == "INUTILIZADOS" else cols_padrao
        df_out = (
            pd.DataFrame(recs, columns=cols_out) if recs else pd.DataFrame(columns=cols_out)
        )
        if k == "INUTILIZADOS":
            df_out.attrs["total"] = len(recs)
        else:
            df_out.attrs["total"] = int(counts.get(k) or len(recs))
        out[k] = df_out
    return out


_ARQUIVO_FISCAL_CACHE_UI_VERSION = 2
_ARQUIVO_FISCAL_CACHE_UI_FILENAME = "resumo_ui_cache.pkl"


def _arquivo_fiscal_cache_ui_path(cnpj: str) -> Path:
    return _arquivo_fiscal_pasta_empresa(cnpj) / _ARQUIVO_FISCAL_CACHE_UI_FILENAME


def _arquivo_fiscal_db_fingerprint(cnpj: str) -> tuple[int, int]:
    p = _arquivo_fiscal_db_path(cnpj)
    if not p.is_file():
        return (0, 0)
    st = p.stat()
    return (int(st.st_mtime_ns), int(st.st_size))


def _arquivo_fiscal_chave_cache_ui(
    cnpj: str, ano: int, mes: int, escopo: str
) -> tuple:
    return (_arquivo_fiscal_cnpj_limpo(cnpj), int(ano), (int(mes),), str(escopo))


def _arquivo_fiscal_series_por_mes_no_ano(
    cnpj: str, ano: int
) -> dict[int, pd.DataFrame]:
    """Uma passagem SQL → séries lidas por mês (1..12)."""
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj)
    vazio = pd.DataFrame()
    out: dict[int, pd.DataFrame] = {m: vazio for m in range(1, 13)}
    if len(cnpj) != 14 or not _arquivo_fiscal_db_path(cnpj).is_file():
        return out
    ano_i = int(ano)
    por_mes_nums = _arquivo_fiscal_cache_ano(cnpj, ano_i)["por_mes"]
    agg: dict[int, dict[tuple[str, str], dict]] = {
        m: defaultdict(
            lambda: {
                "nums": set(),
                "qtd": 0,
                "normais": 0,
                "cancelados_nums": set(),
                "inutilizados": 0,
            }
        )
        for m in range(1, 13)
    }
    te_por_mes: dict[int, list[tuple]] = defaultdict(list)
    conn = _arquivo_fiscal_conn(cnpj)
    try:
        rows_pr = conn.execute(
            """
            SELECT modelo, serie, numero,
                   upper(trim(COALESCE(status, ''))) AS st,
                   mes
            FROM xml_arquivo
            WHERE cnpj_empresa = ? AND ano = ? AND is_propria = 1
              AND numero IS NOT NULL AND numero > 0
              AND upper(trim(COALESCE(status, ''))) != 'INUTILIZADOS'
            """,
            (cnpj, ano_i),
        ).fetchall()
        rows_inut = conn.execute(
            """
            SELECT modelo, serie, numero, mes
            FROM xml_arquivo
            WHERE cnpj_empresa = ? AND is_propria = 1
              AND numero IS NOT NULL AND numero > 0
              AND upper(trim(COALESCE(status, ''))) = 'INUTILIZADOS'
              AND (ano = ? OR ano IS NULL)
            """,
            (cnpj, ano_i),
        ).fetchall()
        rows_te = conn.execute(
            """
            SELECT mes,
                   CASE WHEN modelo IN ('CT-e', 'CT-e OS') THEN 'CT-e'
                        WHEN trim(COALESCE(modelo, '')) = '' THEN 'Outros'
                        ELSE modelo END AS tipo,
                   COUNT(*) AS qtd,
                   SUM(CASE WHEN upper(status) = 'NORMAIS' THEN 1 ELSE 0 END) AS normais,
                   SUM(CASE WHEN upper(status) = 'CANCELADOS' THEN 1 ELSE 0 END) AS cancelados,
                   SUM(CASE WHEN upper(status) = 'INUTILIZADOS' THEN 1 ELSE 0 END) AS inutilizados
            FROM xml_arquivo
            WHERE cnpj_empresa = ? AND ano = ? AND is_propria = 0
            GROUP BY mes, tipo
            ORDER BY mes, tipo
            """,
            (cnpj, ano_i),
        ).fetchall()
    finally:
        conn.close()

    for mod, ser, num, st, mes_db in rows_pr:
        try:
            mes_comp = int(mes_db)
        except (TypeError, ValueError):
            continue
        if not (1 <= mes_comp <= 12):
            continue
        tipo = _normaliza_modelo_filtro(mod) or "—"
        ser_n = _normaliza_serie_filtro(ser) or "—"
        key = (tipo, ser_n)
        try:
            n = int(num)
        except (TypeError, ValueError):
            continue
        if n <= 0:
            continue
        st_u = str(st or "").strip().upper()
        bucket = agg[mes_comp][key]
        bucket["nums"].add(n)
        bucket["qtd"] += 1
        if st_u == "NORMAIS":
            bucket["normais"] += 1
        elif st_u == "CANCELADOS":
            bucket["cancelados_nums"].add(n)

    for mod, ser, num, mes_db in rows_inut:
        tipo = _normaliza_modelo_filtro(mod) or "—"
        ser_n = _normaliza_serie_filtro(ser) or "—"
        key = (tipo, ser_n)
        try:
            n = int(num)
        except (TypeError, ValueError):
            continue
        if n <= 0:
            continue
        try:
            mes_i = int(mes_db) if mes_db is not None else None
        except (TypeError, ValueError):
            mes_i = None
        mes_comp = _arquivo_fiscal_inferir_mes_competencia_inutilizada(
            por_mes_nums, mod, ser, n, mes_armazenado=mes_i
        )
        if mes_comp is None or not (1 <= int(mes_comp) <= 12):
            continue
        bucket = agg[int(mes_comp)][key]
        bucket["nums"].add(n)
        bucket["qtd"] += 1
        bucket["inutilizados"] += 1

    for mes_db, tipo, qtd, no, ca, inu in rows_te:
        try:
            mes_comp = int(mes_db)
        except (TypeError, ValueError):
            continue
        if 1 <= mes_comp <= 12:
            te_por_mes[mes_comp].append((tipo, qtd, no, ca, inu))

    for mes in range(1, 13):
        recs: list[dict] = []
        for (tipo, ser_n), b in sorted(agg[mes].items()):
            nums = b["nums"]
            recs.append(
                {
                    "Origem": "Emissão própria",
                    "Tipo": tipo,
                    "Série": ser_n,
                    "1ª nota": str(min(nums)) if nums else "",
                    "Últ. nota": str(max(nums)) if nums else "",
                    "Quantidade": int(b["qtd"]),
                    "Normais": int(b["normais"]),
                    "Canceladas": int(len(b["cancelados_nums"])),
                    "Inutilizadas": int(b["inutilizados"]),
                }
            )
        for tipo, qtd, no, ca, inu in te_por_mes.get(mes, ()):
            recs.append(
                {
                    "Origem": "Terceiros",
                    "Tipo": str(tipo or "").strip() or "—",
                    "Série": "—",
                    "1ª nota": "—",
                    "Últ. nota": "—",
                    "Quantidade": int(qtd or 0),
                    "Normais": int(no or 0),
                    "Canceladas": int(ca or 0),
                    "Inutilizadas": int(inu or 0),
                }
            )
        if recs:
            recs.sort(
                key=lambda r: (
                    0 if r["Origem"] == "Emissão própria" else 1,
                    r["Tipo"],
                    r["Série"],
                )
            )
            out[mes] = pd.DataFrame(recs)
    return out


def _arquivo_fiscal_status_por_mes_no_ano(
    cnpj: str, ano: int
) -> dict[int, dict[str, pd.DataFrame]]:
    """Status (inutilizadas, canceladas, …) por mês — uma leitura SQL por ano."""
    cols = ["Modelo", "Série", "Nota", "Data Emissão"]
    cols_inut = ["Modelo", "Série", "Nota", "Data Inutilização"]
    vazio_st = {
        k: pd.DataFrame(columns=cols_inut if k == "INUTILIZADOS" else cols)
        for k, _ in _ARQUIVO_FISCAL_STATUS_RESUMO_UI
    }
    out: dict[int, dict[str, pd.DataFrame]] = {
        m: {
            k: pd.DataFrame(columns=cols_inut if k == "INUTILIZADOS" else cols)
            for k, _ in _ARQUIVO_FISCAL_STATUS_RESUMO_UI
        }
        for m in range(1, 13)
    }
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cnpj) != 14 or not _arquivo_fiscal_db_path(cnpj).is_file():
        return out
    ano_i = int(ano)
    por_mes_nums = _arquivo_fiscal_cache_ano(cnpj, ano_i)["por_mes"]
    buckets: dict[int, dict[str, list[dict]]] = {
        m: {k: [] for k, _ in _ARQUIVO_FISCAL_STATUS_RESUMO_UI} for m in range(1, 13)
    }
    st_ok = tuple(k for k, _ in _ARQUIVO_FISCAL_STATUS_RESUMO_UI)
    ph_s = ",".join("?" * len(st_ok))
    conn = _arquivo_fiscal_conn(cnpj)
    try:
        rows = conn.execute(
            f"""
            SELECT upper(trim(COALESCE(status, ''))) AS st,
                   modelo, serie, numero, data_emissao, mes
            FROM xml_arquivo
            WHERE cnpj_empresa = ? AND ano = ? AND is_propria = 1
              AND upper(trim(COALESCE(status, ''))) IN ({ph_s})
              AND upper(trim(COALESCE(status, ''))) != 'INUTILIZADOS'
            ORDER BY st, modelo, serie, numero
            """,
            (cnpj, ano_i, *st_ok),
        ).fetchall()
        rows_inut = conn.execute(
            """
            SELECT modelo, serie, numero, data_emissao, mes, chave,
                   capturado_em, atualizado_em, resumo_json
            FROM xml_arquivo
            WHERE cnpj_empresa = ? AND is_propria = 1
              AND upper(trim(COALESCE(status, ''))) = 'INUTILIZADOS'
              AND numero IS NOT NULL AND numero > 0
              AND (ano = ? OR ano IS NULL)
            ORDER BY modelo, serie, numero
            """,
            (cnpj, ano_i),
        ).fetchall()
    finally:
        conn.close()

    for st, mod, ser, num, de, mes_db in rows:
        try:
            mes_comp = int(mes_db)
        except (TypeError, ValueError):
            continue
        if not (1 <= mes_comp <= 12):
            continue
        st_u = str(st or "").strip().upper()
        if st_u not in buckets[mes_comp]:
            continue
        try:
            nota = int(num) if num is not None else ""
        except (TypeError, ValueError):
            nota = str(num or "").strip()
        buckets[mes_comp][st_u].append(
            {
                "Modelo": str(mod or "").strip(),
                "Série": _normaliza_serie_filtro(ser),
                "Nota": nota,
                "Data Emissão": _valor_data_emissao_dd_mm_yyyy(de) or "—",
            }
        )

    for mod, ser, num, de, mes_db, chave_db, cap_em, atu_em, rj in rows_inut:
        try:
            nota = int(num) if num is not None else ""
        except (TypeError, ValueError):
            continue
        try:
            mes_i = int(mes_db) if mes_db is not None else None
        except (TypeError, ValueError):
            mes_i = None
        mes_comp = _arquivo_fiscal_inferir_mes_competencia_inutilizada(
            por_mes_nums, mod, ser, nota, mes_armazenado=mes_i
        )
        if mes_comp is None or not (1 <= int(mes_comp) <= 12):
            continue
        di = _arquivo_fiscal_data_inutilizacao_de_registo(
            chave=chave_db,
            capturado_em=cap_em,
            atualizado_em=atu_em,
            resumo_json=rj,
            data_emissao=de,
        )
        buckets[int(mes_comp)]["INUTILIZADOS"].append(
            {
                "Modelo": str(mod or "").strip(),
                "Série": _normaliza_serie_filtro(ser),
                "Nota": nota,
                "Data Inutilização": _valor_data_emissao_dd_mm_yyyy(di) or "—",
            }
        )

    for mes in range(1, 13):
        buckets[mes]["INUTILIZADOS"] = _arquivo_fiscal_dedup_inutil_por_nota(
            buckets[mes].get("INUTILIZADOS") or []
        )
        for k, _ in _ARQUIVO_FISCAL_STATUS_RESUMO_UI:
            recs = buckets[mes].get(k) or []
            cols_out = cols_inut if k == "INUTILIZADOS" else cols
            out[mes][k] = (
                pd.DataFrame(recs, columns=cols_out) if recs else vazio_st[k]
            )
    return out


def _arquivo_fiscal_df_para_payload_resumo(
    *,
    cnpj: str,
    ano: int,
    mes: int,
    escopo: str,
    info: dict,
    df_series: pd.DataFrame | None,
    df_bur_reais: pd.DataFrame | None,
    df_falsos: pd.DataFrame | None,
    dfs_st: dict[str, pd.DataFrame] | None,
    max_linhas_status: int = 2000,
) -> dict:
    """Monta o payload das tabelas do resumo (formato da UI desktop)."""
    cache_key = _arquivo_fiscal_chave_cache_ui(cnpj, ano, mes, escopo)
    series_rows: list[tuple] = []
    if df_series is not None and not df_series.empty:
        for _, row in df_series.iterrows():
            series_rows.append(
                (
                    row.get("Origem", ""),
                    row.get("Tipo", row.get("Modelo", "")),
                    row.get("Série", ""),
                    row.get("1ª nota", ""),
                    row.get("Últ. nota", ""),
                    row.get("Quantidade", ""),
                    row.get("Buracos", ""),
                    row.get("Normais", ""),
                    row.get("Canceladas", ""),
                    row.get("Inutilizadas", ""),
                )
            )
    bur_rows: list[tuple] = []
    if df_bur_reais is not None and not df_bur_reais.empty:
        for _, row in df_bur_reais.iterrows():
            bur_rows.append(
                (
                    row.get("Tipo", ""),
                    row.get("Série", ""),
                    row.get("Num_Faltante", ""),
                    row.get("Mês possível", "") or row.get("Período", ""),
                )
            )
    falsos_rows: list[tuple] = []
    if df_falsos is not None and not df_falsos.empty:
        for _, row in df_falsos.iterrows():
            falsos_rows.append(
                (
                    row.get("Tipo", ""),
                    row.get("Série", ""),
                    row.get("Num_Faltante", ""),
                    row.get("Buraco em", row.get("Período analisado", "")),
                    row.get("Emitida em", ""),
                    row.get("Data emissão", ""),
                    row.get("Status NF", ""),
                )
            )
    status_linhas: dict[str, list[tuple]] = {}
    status_totais: dict[str, int] = {}
    dfs_st = dfs_st or {}
    for st_key, _st_nome in _ARQUIVO_FISCAL_STATUS_RESUMO_UI:
        df_st = dfs_st.get(st_key)
        linhas: list[tuple] = []
        total = 0
        if df_st is not None and not df_st.empty:
            total = len(df_st)
            for _, row in df_st.head(max_linhas_status).iterrows():
                if st_key == "CANCELADOS":
                    linhas.append(
                        (
                            row.get("Modelo", ""),
                            row.get("Série", ""),
                            row.get("Nota", ""),
                            row.get("Chave", "") or "—",
                        )
                    )
                elif st_key == "INUTILIZADOS":
                    linhas.append(
                        (
                            row.get("Modelo", ""),
                            row.get("Série", ""),
                            row.get("Nota", ""),
                            row.get("Data Inutilização", "") or "—",
                        )
                    )
                else:
                    linhas.append(
                        (
                            row.get("Modelo", ""),
                            row.get("Série", ""),
                            row.get("Nota", ""),
                            row.get("Data Emissão", ""),
                        )
                    )
        status_linhas[st_key] = linhas
        status_totais[st_key] = total
    tit = f"Competência {int(ano)}/{int(mes):02d}"
    if not int(info.get("total") or 0):
        return {
            "info": info,
            "tit": tit,
            "escopo": escopo,
            "series_rows": [],
            "bur_rows": [],
            "falsos_rows": [],
            "n_reais": 0,
            "n_falsos": 0,
            "status_linhas": {k: [] for k, _ in _ARQUIVO_FISCAL_STATUS_RESUMO_UI},
            "status_totais": {k: 0 for k, _ in _ARQUIVO_FISCAL_STATUS_RESUMO_UI},
            "status_dfs": {},
            "vazio": True,
            "_cache_key": cache_key,
        }
    return {
        "info": info,
        "tit": tit,
        "escopo": escopo,
        "series_rows": series_rows,
        "bur_rows": bur_rows,
        "falsos_rows": falsos_rows,
        "n_reais": len(bur_rows),
        "n_falsos": len(falsos_rows),
        "status_linhas": status_linhas,
        "status_totais": status_totais,
        "status_dfs": dfs_st,
        "vazio": False,
        "_cache_key": cache_key,
    }


def _arquivo_fiscal_preconstruir_cache_ui(
    cnpj: str,
    *,
    escopo_buracos: str = "Mês selecionado",
    max_linhas_status: int = 2000,
    on_progress=None,
) -> dict[tuple, dict]:
    """
    Pré-monta todos os resumos por mês para navegação instantânea na UI.
    Uma passagem por ano (séries, status, buracos) — sem recalcular a cada clique.
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return {}
    comp = _arquivo_fiscal_competencias_resumo(cx)
    if not comp:
        return {}
    anos = sorted({a for a, _ in comp.keys()})
    cache: dict[tuple, dict] = {}
    total_meses = sum(1 for _a, _m in comp.keys())
    feito = 0

    def _prog(mes_txt: str = ""):
        nonlocal feito
        feito += 1
        if on_progress:
            try:
                on_progress(
                    "cache_ui",
                    cur=feito,
                    total=max(total_meses, 1),
                    detalhe=f"A preparar resumo {mes_txt} ({feito}/{total_meses})".replace(
                        ",", "."
                    ),
                )
            except Exception:
                pass

    for ano in anos:
        meses_ano = sorted(m for a, m in comp.keys() if a == int(ano))
        if not meses_ano:
            continue
        _arquivo_fiscal_cache_ano(cx, int(ano))
        series_por_mes = _arquivo_fiscal_series_por_mes_no_ano(cx, int(ano))
        status_por_mes = _arquivo_fiscal_status_por_mes_no_ano(cx, int(ano))
        if escopo_buracos == "Ano inteiro":
            meses_bur_calc = meses_ano
        else:
            meses_bur_calc = meses_ano
        df_bur_all, df_fal_all = _arquivo_fiscal_buracos_painel_periodo(
            cx, int(ano), meses_bur_calc
        )
        for mes in meses_ano:
            periodo = f"{int(ano)} ({int(mes):02d})"
            info = comp.get((int(ano), int(mes)), {"total": 0, "propria": 0, "terceiros": 0})
            if escopo_buracos == "Ano inteiro":
                df_bur_m = df_bur_all
                df_fal_m = df_fal_all
            else:
                df_bur_m = (
                    df_bur_all[df_bur_all["Período"] == periodo]
                    if df_bur_all is not None and not df_bur_all.empty
                    else df_bur_all
                )
                df_fal_m = (
                    df_fal_all[df_fal_all["Buraco em"] == periodo]
                    if df_fal_all is not None and not df_fal_all.empty
                    else df_fal_all
                )
            df_reais_m = _arquivo_fiscal_buracos_reais_de_todos(df_bur_m, df_fal_m)
            payload = _arquivo_fiscal_df_para_payload_resumo(
                cnpj=cx,
                ano=int(ano),
                mes=int(mes),
                escopo=escopo_buracos,
                info=info,
                df_series=series_por_mes.get(int(mes)),
                df_bur_reais=df_reais_m,
                df_falsos=df_fal_m,
                dfs_st=status_por_mes.get(int(mes), {}),
                max_linhas_status=max_linhas_status,
            )
            cache[payload["_cache_key"]] = payload
            _prog(f"{ano}/{mes:02d}")
    return cache


def _arquivo_fiscal_gravar_cache_ui_disco(
    cnpj: str, cache: dict[tuple, dict]
) -> None:
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14 or not cache:
        return
    path = _arquivo_fiscal_cache_ui_path(cx)
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        blob = {
            "versao": _ARQUIVO_FISCAL_CACHE_UI_VERSION,
            "fingerprint": _arquivo_fiscal_db_fingerprint(cx),
            "escopo": "Mês selecionado",
            "cache": cache,
        }
        tmp = path.with_suffix(".pkl.tmp")
        with open(tmp, "wb") as f:
            pickle.dump(blob, f, protocol=pickle.HIGHEST_PROTOCOL)
        tmp.replace(path)
    except OSError:
        pass


def _arquivo_fiscal_carregar_cache_ui_disco(cnpj: str) -> dict[tuple, dict] | None:
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return None
    path = _arquivo_fiscal_cache_ui_path(cx)
    if not path.is_file():
        return None
    try:
        with open(path, "rb") as f:
            blob = pickle.load(f)
    except Exception:
        return None
    if not isinstance(blob, dict):
        return None
    if int(blob.get("versao") or 0) != _ARQUIVO_FISCAL_CACHE_UI_VERSION:
        return None
    if blob.get("fingerprint") != _arquivo_fiscal_db_fingerprint(cx):
        return None
    cache = blob.get("cache")
    return cache if isinstance(cache, dict) and cache else None


def _arquivo_fiscal_painel_cache_chave(cnpj: str, ano: int, meses: list[int]) -> tuple:
    return (
        "painel_desktop_v2",
        _arquivo_fiscal_cnpj_limpo(cnpj),
        int(ano),
        tuple(sorted(int(m) for m in meses)),
    )


def _arquivo_fiscal_painel_cache_get(
    cnpj: str, ano: int, meses: list[int]
) -> dict | None:
    cache = _arquivo_fiscal_carregar_cache_ui_disco(cnpj)
    if not cache:
        return None
    hit = cache.get(_arquivo_fiscal_painel_cache_chave(cnpj, ano, meses))
    if isinstance(hit, dict):
        if hit.get("erro"):
            return None
        if hit.get("vazio"):
            fres = _arquivo_fiscal_resumo_periodo(cnpj, ano, meses)
            if int(fres.get("total") or 0) > 0:
                return None
        return hit
    return None


def _arquivo_fiscal_painel_cache_set(
    cnpj: str, ano: int, meses: list[int], dados: dict
) -> None:
    if not dados or dados.get("erro"):
        return
    if dados.get("vazio"):
        return
    cache = _arquivo_fiscal_carregar_cache_ui_disco(cnpj) or {}
    cache[_arquivo_fiscal_painel_cache_chave(cnpj, ano, meses)] = dados
    _arquivo_fiscal_gravar_cache_ui_disco(cnpj, cache)


def _arquivo_fiscal_apagar_cache_ui_disco(cnpj: str) -> None:
    path = _arquivo_fiscal_cache_ui_path(_arquivo_fiscal_cnpj_limpo(cnpj))
    try:
        if path.is_file():
            path.unlink()
    except OSError:
        pass


def _arquivo_fiscal_sincronizar_pasta(cnpj_empresa: str, cnpj_leitura: str) -> tuple[int, int, str]:
    """
    Varre XML/ no disco da empresa e atualiza o banco (útil após colocar XML à mão num buraco).
    Devolve (indexados, erros, mensagem).
    """
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj_empresa)
    if len(cnpj) != 14:
        return 0, 0, "CNPJ inválido."
    base_xml = _arquivo_fiscal_pasta_xml_empresa(cnpj)
    if not base_xml.is_dir():
        return 0, 0, f"Pasta ainda vazia: `{base_xml}`"
    ok = 0
    err = 0
    for path in base_xml.rglob("*.xml"):
        try:
            raw = path.read_bytes()
        except OSError:
            err += 1
            continue
        res, is_p = identify_xml_info(raw, cnpj_leitura, path.name)
        if not res:
            err += 1
            continue
        try:
            if _arquivo_fiscal_gravar_um(
                cnpj,
                res,
                is_p,
                raw,
                path.name,
                caminho_origem=str(path),
            ):
                ok += 1
            else:
                err += 1
        except Exception:
            err += 1
    pend = st.session_state.get("_arquivo_fiscal_zip_pendentes_slug") or set()
    n_zip = len({s for c, s in pend if c == cnpj})
    _arquivo_fiscal_processar_zips_pendentes(cnpj)
    msg = f"**{ok}** ficheiro(s) indexado(s)" + (f", **{err}** ignorado(s)." if err else ".")
    if n_zip:
        msg += f" **{n_zip}** mês(es) com ZIP atualizado em `{_ARQUIVO_FISCAL_SUBPASTA_ZIP}/`."
    return ok, err, msg


def _arquivo_fiscal_sincronizar_zips_espelho(cnpj: str) -> tuple[int, str]:
    """Recria ZIP/{ano}_{mes}.zip (XML na raiz) para cada mês de emissão indexado."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return 0, "CNPJ inválido."
    meses = _arquivo_fiscal_meses_distintos_db(cx)
    if not meses:
        return 0, "Nenhum mês de emissão indexado no arquivo fiscal."
    _arquivo_fiscal_limpar_estrutura_zip_antiga(cx)
    n_ok = 0
    erros: list[str] = []
    _headless = bool(os.environ.get("GARIMPEIRO_HEADLESS"))
    for i, (ano, mes) in enumerate(meses, start=1):
        rot = _arquivo_fiscal_nome_zip_mes(ano, mes)
        if _headless:
            print(
                f"[garimpeiro] ZIP espelho {i}/{len(meses)}: {rot}…",
                file=sys.stderr,
                flush=True,
            )
        zpath, _cnt, err = _arquivo_fiscal_atualizar_zip_mes(cx, ano, mes)
        if zpath:
            n_ok += 1
        elif err:
            erros.append(f"{rot}: {err}")
    msg = (
        f"**{n_ok}** ZIP(s) criado(s) em `{_ARQUIVO_FISCAL_SUBPASTA_ZIP}/` "
        f"(um por pastinha EP_/T_, ex.: Fevereiro/EP_2026_02_Serie_1_Entrada_Autorizadas_NFe.zip)."
    )
    if erros:
        msg += f" ({len(erros)} ignorado(s): " + "; ".join(erros[:3])
        if len(erros) > 3:
            msg += f" … +{len(erros) - 3}"
        msg += ")"
    return n_ok, msg


def _arquivo_fiscal_corrigir_slugs_db(cnpj: str) -> int:
    """Normaliza slug_pasta (só EP_/T_/DOM_) a partir de caminho_relativo."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return 0
    conn = _arquivo_fiscal_conn(cx)
    n = 0
    try:
        rows = conn.execute(
            "SELECT chave, caminho_relativo, slug_pasta FROM xml_arquivo WHERE cnpj_empresa = ?",
            (cx,),
        ).fetchall()
        agora = datetime.now().isoformat(timespec="seconds")
        for chave, rel, slug_old in rows:
            rel_s = str(rel or "").replace("\\", "/")
            slug_new = _arquivo_fiscal_slug_db_de_pasta(rel_s)
            if not slug_new:
                continue
            if str(slug_old or "").strip() == slug_new:
                continue
            conn.execute(
                "UPDATE xml_arquivo SET slug_pasta = ?, atualizado_em = ? WHERE chave = ?",
                (slug_new, agora, chave),
            )
            n += 1
        conn.commit()
    finally:
        conn.close()
    return n


def _arquivo_fiscal_limpar_orfaos_indice(cnpj: str) -> tuple[int, str]:
    """
    Remove do SQLite registos cujo XML não existe no disco (índice fantasma).
    Exporta lista em reparo_orfaos_indice.txt na pasta da empresa.
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return 0, "CNPJ inválido."
    base = _arquivo_fiscal_pasta_empresa(cx)
    conn = _arquivo_fiscal_conn(cx)
    removidos: list[tuple[str, str]] = []
    try:
        rows = conn.execute(
            "SELECT chave, caminho_relativo FROM xml_arquivo WHERE cnpj_empresa = ?",
            (cx,),
        ).fetchall()
        for chave, rel in rows:
            rel_s = str(rel or "").replace("\\", "/")
            if rel_s.startswith(f"{_ARQUIVO_FISCAL_SUBPASTA_XML}/manual_inutilizadas/"):
                continue
            p = base / rel_s.replace("/", os.sep)
            if not p.is_file():
                removidos.append((str(chave), rel_s))
        if removidos:
            log = base / "reparo_orfaos_indice.txt"
            with log.open("w", encoding="utf-8") as f:
                f.write(f"Removidos do índice ({len(removidos)}) — XML ausente no disco\n\n")
                for ch, rel in removidos:
                    f.write(f"{ch}\t{rel}\n")
            conn.executemany(
                "DELETE FROM xml_arquivo WHERE chave = ?",
                [(ch,) for ch, _ in removidos],
            )
            conn.commit()
    finally:
        conn.close()
    if removidos:
        _arquivo_fiscal_marcar_excel_desatualizado(cx)
        _arquivo_fiscal_invalidar_runtime_cache(cx)
    return len(removidos), str(base / "reparo_orfaos_indice.txt") if removidos else ""


def _arquivo_fiscal_indexar_xml_em_disco(cnpj: str, cnpj_leitura: str) -> tuple[int, int, int]:
    """
    Indexa XML no disco que ainda não estão no SQLite (sem regravar duplicados).
    Devolve (novos, já_indexados, erros).
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    leitura = _arquivo_fiscal_cnpj_limpo(cnpj_leitura)
    if len(cx) != 14:
        return 0, 0, 0
    base = _arquivo_fiscal_pasta_empresa(cx)
    base_xml = _arquivo_fiscal_pasta_xml_empresa(cx)
    if not base_xml.is_dir():
        return 0, 0, 0
    conn = _arquivo_fiscal_conn(cx)
    try:
        idx_paths = {
            str(r or "").replace("\\", "/").lower()
            for (r,) in conn.execute(
                "SELECT caminho_relativo FROM xml_arquivo WHERE cnpj_empresa = ?", (cx,)
            )
        }
        chaves = {
            str(c or "")
            for (c,) in conn.execute(
                "SELECT chave FROM xml_arquivo WHERE cnpj_empresa = ?", (cx,)
            )
        }
    finally:
        conn.close()
    novos = ja = erros = 0
    with _arquivo_fiscal_gravar_lote(cx):
        for path in base_xml.rglob("*.xml"):
            rel = (
                f"{_ARQUIVO_FISCAL_SUBPASTA_XML}/"
                + str(path.relative_to(base_xml)).replace("\\", "/")
            )
            if rel.lower() in idx_paths:
                ja += 1
                continue
            try:
                raw = path.read_bytes()
            except OSError:
                erros += 1
                continue
            res, is_p = identify_xml_info(raw, leitura, path.name)
            if not res:
                erros += 1
                continue
            ch = _arquivo_fiscal_chave_registro(res)
            if ch and ch in chaves:
                ja += 1
                continue
            try:
                if _arquivo_fiscal_gravar_um(
                    cx,
                    res,
                    is_p,
                    raw,
                    path.name,
                    caminho_origem=str(path),
                ):
                    novos += 1
                    if ch:
                        chaves.add(ch)
                    idx_paths.add(rel.lower())
                else:
                    ja += 1
            except Exception:
                erros += 1
    return novos, ja, erros


def _arquivo_fiscal_reparar_empresa(
    cnpj: str,
    *,
    cnpj_leitura: str | None = None,
) -> dict:
    """
    Repara arquivo fiscal já lido: slugs, indexação em falta, órfãos no índice,
    reorganização de pastas, ZIPs espelho e Excel.
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    leitura = _arquivo_fiscal_cnpj_limpo(cnpj_leitura or cnpj)
    if len(cx) != 14:
        return {"ok": False, "msg": "CNPJ inválido."}
    base = _arquivo_fiscal_pasta_empresa(cx)
    if not base.is_dir():
        return {"ok": False, "msg": f"Pasta não encontrada: {base}"}

    n_slugs = _arquivo_fiscal_corrigir_slugs_db(cx)
    novos, ja_idx, err_idx = _arquivo_fiscal_indexar_xml_em_disco(cx, leitura)
    n_orfaos, log_orfaos = _arquivo_fiscal_limpar_orfaos_indice(cx)

    conn = _arquivo_fiscal_conn(cx)
    try:
        movidos = _arquivo_fiscal_migrar_pastas_ano_mes(conn, cx)
        _arquivo_fiscal_meta_set(conn, _ARQUIVO_META_FORMATO_PASTAS, _ARQUIVO_FISCAL_FORMATO_PASTAS_V)
        conn.commit()
    finally:
        conn.close()

    n_slugs2 = _arquivo_fiscal_corrigir_slugs_db(cx)
    n_zip_meses, msg_zip = _arquivo_fiscal_sincronizar_zips_espelho(cx)
    _arquivo_fiscal_apagar_cache_ui_disco(cx)
    _arquivo_fiscal_invalidar_runtime_cache(cx)
    _arquivo_fiscal_marcar_excel_desatualizado(cx)
    xls, msg_xls = _arquivo_fiscal_garantir_excel_empresa(cx, forcar=True)

    disk_n = len(list((_arquivo_fiscal_pasta_xml_empresa(cx)).rglob("*.xml")))
    idx_n = _arquivo_fiscal_total(cx)
    zip_n = len(list((_arquivo_fiscal_pasta_zip_empresa(cx)).rglob("*.zip")))

    resumo = (
        f"Reparo concluído — **{idx_n:,}** no índice · **{disk_n:,}** XML no disco · "
        f"**{zip_n}** ZIP(s). Slugs corrigidos: **{n_slugs + n_slugs2}**. "
        f"Novos indexados: **{novos}**. Órfãos removidos do índice: **{n_orfaos}**. "
        f"ZIPs: {msg_zip.replace('**', '')}"
    ).replace(",", ".")
    if log_orfaos:
        resumo += f" Lista de órfãos: `{log_orfaos}`."
    if xls:
        resumo += f" Excel: `{xls}`."
    else:
        resumo += f" Excel: {msg_xls or 'não gerado'}."

    return {
        "ok": True,
        "cnpj": cx,
        "index_total": idx_n,
        "disk_xml": disk_n,
        "zip_count": zip_n,
        "slugs_corrigidos": n_slugs + n_slugs2,
        "indexados_novos": novos,
        "orfaos_removidos": n_orfaos,
        "movidos": movidos,
        "zip_meses": n_zip_meses,
        "excel": xls,
        "log_orfaos": log_orfaos,
        "msg": resumo,
    }


def _arquivo_fiscal_listar(
    cnpj: str,
    *,
    ano: int | None = None,
    mes: int | None = None,
    meses: list[int] | None = None,
    is_propria: int | None = None,
    status: str | None = None,
    serie: str | None = None,
    modelo: str | None = None,
    data_inicio: str | None = None,
    data_fim: str | None = None,
    numero_inicio: int | None = None,
    numero_fim: int | None = None,
    uf_parceiro: str | list | None = None,
    cfop: str | list | None = None,
    incluir_resumo: bool = False,
) -> list[dict]:
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cnpj) != 14:
        return []
    ufs = _arquivo_fiscal_ufs_filtro(uf_parceiro)
    if ufs:
        # XML antigos no SQLite podem não ter UF — preenche a partir do disco
        _arquivo_fiscal_garantir_uf_parceiro(cnpj)
    cfops_f = _arquivo_fiscal_cfops_filtro(cfop)
    if cfops_f:
        _arquivo_fiscal_garantir_cfops(
            cnpj, ano=ano, mes=mes, meses=meses
        )
    sql = (
        "SELECT chave, nome_arquivo, caminho_relativo, ano, mes, status, slug_pasta, "
        "is_propria, serie, modelo, data_emissao, numero, uf_parceiro, cfops"
        + (", resumo_json" if incluir_resumo else "")
        + " FROM xml_arquivo WHERE cnpj_empresa = ?"
    )
    params: list = [cnpj]
    sql += _arquivo_fiscal_sql_filtro_usuario(params)
    if ano is not None:
        sql += " AND ano = ?"
        params.append(ano)
    sql += _arquivo_fiscal_sql_filtro_meses(mes, meses, params)
    if is_propria is not None:
        sql += " AND is_propria = ?"
        params.append(is_propria)
    if status:
        sql += " AND upper(status) = upper(?)"
        params.append(status)
    sql += _arquivo_fiscal_sql_filtros_avancados(
        serie=serie,
        modelo=modelo,
        data_inicio=data_inicio,
        data_fim=data_fim,
        numero_inicio=numero_inicio,
        numero_fim=numero_fim,
        uf_parceiro=ufs or None,
        cfop=cfops_f or None,
        params=params,
    )
    sql += " ORDER BY data_emissao DESC, ano DESC, mes DESC, numero ASC, chave ASC"
    conn = _arquivo_fiscal_conn(cnpj)
    try:
        rows = conn.execute(sql, params).fetchall()
    finally:
        conn.close()
    cols = (
        "chave",
        "nome_arquivo",
        "caminho_relativo",
        "ano",
        "mes",
        "status",
        "slug_pasta",
        "is_propria",
        "serie",
        "modelo",
        "data_emissao",
        "numero",
        "uf_parceiro",
        "cfops",
    )
    if incluir_resumo:
        cols = cols + ("resumo_json",)
    return [dict(zip(cols, r)) for r in rows]


def _chave44_emissao_ano_mes(chave44: str) -> tuple[int, int] | None:
    """Ano/mês de emissão codificados na chave NFe/CTe (posições yy mm)."""
    k = _chave44_digitos(chave44)
    if not k or len(k) < 6:
        return None
    try:
        yy = int(k[2:4])
        mm = int(k[4:6])
        if mm < 1 or mm > 12:
            return None
        ano = 2000 + yy if yy < 80 else 1900 + yy
        return ano, mm
    except ValueError:
        return None


def _arquivo_fiscal_procurar_xml_chave(
    emp: Path,
    chave_base: str,
    nome_arquivo: str = "",
) -> Path | None:
    """Procura XML no disco quando o caminho indexado ficou desatualizado."""
    nome = str(nome_arquivo or "").strip()
    if nome:
        for p in emp.rglob(nome):
            if p.is_file() and p.suffix.lower() in (".xml", ".zip"):
                return p
    if chave_base:
        for p in emp.rglob(f"*{chave_base}*.xml"):
            if p.is_file():
                return p
    return None


def _arquivo_fiscal_item_pontuacao_sped(
    item: dict,
    *,
    ano_sped: int | None,
    mes_sped: int | None,
) -> int:
    score = 0
    if item.get("existe_disco"):
        score += 1000
    if not item.get("evento"):
        score += 100
    try:
        ia = int(item.get("ano") or 0)
        im = int(item.get("mes") or 0)
    except (TypeError, ValueError):
        ia = im = 0
    if ano_sped and mes_sped and ia == int(ano_sped) and im == int(mes_sped):
        score += 200
    em = _chave44_emissao_ano_mes(str(item.get("chave") or ""))
    if em and ia == em[0] and im == em[1]:
        score += 80
    return score


def _arquivo_fiscal_localizar_por_chaves(
    cnpj: str,
    chaves: set[str] | list[str],
    *,
    incluir_eventos: bool = True,
    ano_sped: int | None = None,
    mes_sped: int | None = None,
) -> dict[str, dict]:
    """
    Localiza no ArquivoFiscal os XMLs das chaves SPED (44 dígitos).
    Procura em todo o índice; prioriza pasta do mês do SPED e, se faltar,
    meses de emissão conforme a chave / registo SQLite.
    Devolve mapa chave_base -> {tem_autorizado, motivo_ausencia, itens[]}.
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    bases: list[str] = []
    for ch in chaves or []:
        k = _chave44_digitos(ch)
        if k and len(k) == 44 and k not in bases:
            bases.append(k)
    if len(cx) != 14 or not bases:
        return {}

    emp = _arquivo_fiscal_pasta_empresa(cx)
    out: dict[str, dict] = {b: {"tem_autorizado": False, "tem_cancelamento": False, "motivo_ausencia": "", "itens": []} for b in bases}

    conn = _arquivo_fiscal_conn(cx)
    try:
        rows_raw = conn.execute(
            """
            SELECT chave, nome_arquivo, caminho_relativo, status, modelo, ano, mes, data_emissao
            FROM xml_arquivo
            WHERE cnpj_empresa = ?
            """,
            (cx,),
        ).fetchall()
    finally:
        conn.close()

    for (
        ch_db,
        nome_arquivo,
        caminho_relativo,
        status,
        modelo,
        ano_db,
        mes_db,
        data_emissao,
    ) in rows_raw:
        ch_db_s = str(ch_db or "")
        base = _chave44_digitos(ch_db_s)
        if not base or base not in out:
            continue
        rel = str(caminho_relativo or "").replace("\\", "/")
        abs_p = emp / rel.replace("/", os.sep) if rel else emp
        existe = abs_p.is_file() if rel else False
        if not existe:
            alt = _arquivo_fiscal_procurar_xml_chave(
                emp, base, str(nome_arquivo or "")
            )
            if alt is not None:
                abs_p = alt
                existe = True
        evento = "#" in ch_db_s or str(status or "").upper() in (
            "CANCELADOS",
            "DENEGADOS",
            "REJEITADOS",
        )
        if evento and not incluir_eventos:
            continue
        out[base]["itens"].append(
            {
                "chave": base,
                "status": str(status or ""),
                "modelo": str(modelo or ""),
                "nome_arquivo": str(nome_arquivo or ""),
                "caminho_relativo": rel,
                "caminho_absoluto": str(abs_p) if existe else (str(abs_p) if rel else ""),
                "existe_disco": existe,
                "evento": evento,
                "ano": ano_db,
                "mes": mes_db,
                "data_emissao": str(data_emissao or ""),
            }
        )

    for base, info in out.items():
        itens = info["itens"]
        for item in itens:
            if item.get("existe_disco"):
                continue
            alt = _arquivo_fiscal_procurar_xml_chave(
                emp, base, str(item.get("nome_arquivo") or "")
            )
            if alt is not None:
                item["caminho_absoluto"] = str(alt)
                item["existe_disco"] = True

        auts = [i for i in itens if not i.get("evento")]
        melhor_aut = None
        if auts:
            melhor_aut = max(
                auts,
                key=lambda i: _arquivo_fiscal_item_pontuacao_sped(
                    i, ano_sped=ano_sped, mes_sped=mes_sped
                ),
            )
        tem_aut = bool(melhor_aut and melhor_aut.get("existe_disco"))
        tem_canc = any(i.get("evento") and i.get("existe_disco") for i in itens)
        info["tem_autorizado"] = tem_aut
        info["tem_cancelamento"] = tem_canc
        if not tem_aut and tem_canc:
            info["motivo_ausencia"] = "somente_cancelamento"
        elif not tem_aut:
            info["motivo_ausencia"] = "sem_autorizado"
        elif tem_aut and melhor_aut and not melhor_aut.get("existe_disco"):
            info["motivo_ausencia"] = "arquivo_ausente"
        elif tem_aut and any(
            i.get("existe_disco") is False for i in itens if not i.get("evento")
        ):
            info["motivo_ausencia"] = "arquivo_ausente"
    return out


def _arquivo_fiscal_contar(
    cnpj: str,
    *,
    ano: int | None = None,
    mes: int | None = None,
    meses: list[int] | None = None,
    is_propria: int | None = None,
    status: str | None = None,
    serie: str | None = None,
    modelo: str | None = None,
    data_inicio: str | None = None,
    data_fim: str | None = None,
    numero_inicio: int | None = None,
    numero_fim: int | None = None,
    uf_parceiro: str | list | None = None,
    cfop: str | list | None = None,
) -> int:
    """COUNT(*) com os mesmos filtros de _arquivo_fiscal_listar (sem materializar linhas)."""
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cnpj) != 14:
        return 0
    ufs = _arquivo_fiscal_ufs_filtro(uf_parceiro)
    if ufs:
        _arquivo_fiscal_garantir_uf_parceiro(cnpj)
    cfops_f = _arquivo_fiscal_cfops_filtro(cfop)
    if cfops_f:
        _arquivo_fiscal_garantir_cfops(cnpj, ano=ano, mes=mes, meses=meses)
    sql = "SELECT COUNT(*) FROM xml_arquivo WHERE cnpj_empresa = ?"
    params: list = [cnpj]
    sql += _arquivo_fiscal_sql_filtro_usuario(params)
    if ano is not None:
        sql += " AND ano = ?"
        params.append(ano)
    sql += _arquivo_fiscal_sql_filtro_meses(mes, meses, params)
    if is_propria is not None:
        sql += " AND is_propria = ?"
        params.append(is_propria)
    if status:
        sql += " AND upper(status) = upper(?)"
        params.append(status)
    sql += _arquivo_fiscal_sql_filtros_avancados(
        serie=serie,
        modelo=modelo,
        data_inicio=data_inicio,
        data_fim=data_fim,
        numero_inicio=numero_inicio,
        numero_fim=numero_fim,
        uf_parceiro=ufs or None,
        cfop=cfops_f or None,
        params=params,
    )
    conn = _arquivo_fiscal_conn(cnpj)
    try:
        row = conn.execute(sql, params).fetchone()
    finally:
        conn.close()
    return int(row[0] or 0) if row else 0


def _arquivo_fiscal_prefixo_zip_avancado(
    *,
    ano: int | None,
    mes: int | None,
    meses: list[int] | None,
    is_propria: int | None,
    status: str | None,
    serie: str | None = None,
    data_inicio: str | None = None,
    data_fim: str | None = None,
    numero_inicio: int | None = None,
    numero_fim: int | None = None,
) -> str:
    rot = _arquivo_fiscal_rotulo_filtro_zip(is_propria, status)
    partes: list[str] = []
    di = _arquivo_fiscal_data_emissao_iso(data_inicio)
    df = _arquivo_fiscal_data_emissao_iso(data_fim)
    if di or df:
        partes.append(f"{di or 'inicio'}_{df or 'fim'}")
    elif meses and len(meses) > 1 and ano is not None:
        _ms = "-".join(f"{int(m):02d}" for m in sorted({int(x) for x in meses}))
        partes.append(f"{int(ano)}_{_ms}")
    elif ano is not None and mes is not None:
        partes.append(f"{int(ano)}_{int(mes):02d}")
    elif ano is not None:
        partes.append(str(int(ano)))
    ser = str(serie or "").strip()
    if ser and ser.lower() not in ("todas", "qualquer", "todos"):
        partes.append(f"ser{ser}")
    if numero_inicio is not None or numero_fim is not None:
        partes.append(f"n{numero_inicio or 0}_{numero_fim or 0}")
    partes.append(rot)
    return "_".join(partes) if partes else f"completo_{rot}"


def _arquivo_fiscal_exportar_para_pasta(
    cnpj: str,
    pasta_destino: str | Path,
    *,
    ano: int | None = None,
    mes: int | None = None,
    meses: list[int] | None = None,
    is_propria: int | None = None,
    status: str | None = None,
    serie: str | None = None,
    modelo: str | None = None,
    data_inicio: str | None = None,
    data_fim: str | None = None,
    numero_inicio: int | None = None,
    numero_fim: int | None = None,
    uf_parceiro: str | list | None = None,
    cfop: str | list | None = None,
    incluir_zip_espelho: bool = False,
) -> tuple[int, int, str | None]:
    """Copia XML filtrados (e opcionalmente ZIP espelho) para a pasta escolhida."""
    itens = _arquivo_fiscal_listar(
        cnpj,
        ano=ano,
        mes=mes,
        meses=meses,
        is_propria=is_propria,
        status=status,
        serie=serie,
        modelo=modelo,
        data_inicio=data_inicio,
        data_fim=data_fim,
        numero_inicio=numero_inicio,
        numero_fim=numero_fim,
        uf_parceiro=uf_parceiro,
        cfop=cfop,
    )
    if not itens:
        return 0, 0, "Nenhum XML no arquivo com estes filtros."
    base = _arquivo_fiscal_pasta_empresa(cnpj)
    try:
        dest = Path(pasta_destino).expanduser().resolve()
    except (OSError, ValueError):
        return 0, 0, "Pasta de destino inválida."
    dest.mkdir(parents=True, exist_ok=True)
    n_xml = 0
    for it in itens:
        rel = str(it.get("caminho_relativo") or "").replace("/", os.sep)
        if not rel:
            continue
        src = base / rel
        if not src.is_file():
            continue
        out = dest / rel
        out.parent.mkdir(parents=True, exist_ok=True)
        try:
            shutil.copy2(src, out)
            n_xml += 1
        except OSError:
            continue
    n_zip = 0
    if incluir_zip_espelho:
        zip_base = _arquivo_fiscal_pasta_zip_empresa(cnpj)
        meses_zip: set[tuple[int, int]] = set()
        for it in itens:
            comp = _arquivo_fiscal_competencia_de_item(it)
            if comp:
                meses_zip.add(comp)
        for ano, mes in sorted(meses_zip):
            for zp in _arquivo_fiscal_zips_do_mes(cnpj, ano, mes):
                out_z = dest / zp.name
                try:
                    shutil.copy2(zp, out_z)
                    n_zip += 1
                except OSError:
                    pass
    if n_xml == 0:
        return 0, 0, "Ficheiros listados no banco mas ausentes no disco."
    return n_xml, n_zip, None


def _arquivo_fiscal_contar_ausentes_disco(cnpj: str, itens: list[dict]) -> int:
    """Quantos registos do índice não têm ficheiro XML no caminho indicado."""
    if not itens:
        return 0
    base = _arquivo_fiscal_pasta_empresa(cnpj)
    n = 0
    for it in itens:
        rel = str(it.get("caminho_relativo") or "").replace("/", os.sep)
        if not rel:
            n += 1
            continue
        if not (base / rel).is_file():
            n += 1
    return n


def _arquivo_fiscal_zip_filtrado(
    cnpj: str,
    *,
    ano: int | None = None,
    mes: int | None = None,
    meses: list[int] | None = None,
    is_propria: int | None = None,
    status: str | None = None,
    serie: str | None = None,
    modelo: str | None = None,
    data_inicio: str | None = None,
    data_fim: str | None = None,
    numero_inicio: int | None = None,
    numero_fim: int | None = None,
) -> tuple[list[str], int, int, str | None]:
    """ZIP(s) para download — um por mês de emissão, XML na raiz (sem subpastas).

    Devolve (caminhos, n_no_zip, n_ausentes_no_disco, erro).
    """
    itens = _arquivo_fiscal_listar(
        cnpj,
        ano=ano,
        mes=mes,
        meses=meses,
        is_propria=is_propria,
        status=status,
        serie=serie,
        modelo=modelo,
        data_inicio=data_inicio,
        data_fim=data_fim,
        numero_inicio=numero_inicio,
        numero_fim=numero_fim,
    )
    if not itens:
        return [], 0, 0, "Nenhum XML no arquivo com estes filtros."
    base = _arquivo_fiscal_pasta_empresa(cnpj)
    os.makedirs(TEMP_UPLOADS_DIR, exist_ok=True)
    stamp = f"{int(time.time())}_{random.randint(1, 999999)}"
    prefixo_filtro = _arquivo_fiscal_prefixo_zip_avancado(
        ano=ano,
        mes=mes,
        meses=meses,
        is_propria=is_propria,
        status=status,
        serie=serie,
        data_inicio=data_inicio,
        data_fim=data_fim,
        numero_inicio=numero_inicio,
        numero_fim=numero_fim,
    )
    por_mes: dict[tuple[int, int], list[tuple[Path, str]]] = {}
    sem_mes: list[tuple[Path, str]] = []
    for it in itens:
        rel = it.get("caminho_relativo") or ""
        p = base / str(rel).replace("/", os.sep)
        if not p.is_file():
            continue
        arc = str(it.get("nome_arquivo") or p.name)
        comp = _arquivo_fiscal_competencia_de_item(it)
        if comp:
            por_mes.setdefault(comp, []).append((p, arc))
        else:
            sem_mes.append((p, arc))
    if not por_mes and not sem_mes:
        return [], 0, len(itens), "Ficheiros listados no banco mas ausentes no disco."
    tmp_dir = Path(TEMP_UPLOADS_DIR) / f"arquivo_fiscal_{cnpj}_{stamp}"
    tmp_dir.mkdir(parents=True, exist_ok=True)
    partes: list[str] = []
    for (a, m), pares in sorted(por_mes.items()):
        nome_base = f"arquivo_{cnpj}_{_arquivo_fiscal_nome_zip_mes(a, m)}_{prefixo_filtro}"
        partes.extend(_arquivo_fiscal_escrever_zips_xml_flat(pares, tmp_dir, nome_base))
    if sem_mes:
        nome_base = f"arquivo_{cnpj}_{prefixo_filtro}_sem_mes"
        partes.extend(_arquivo_fiscal_escrever_zips_xml_flat(sem_mes, tmp_dir, nome_base))
    n_ok = sum(len(v) for v in por_mes.values()) + len(sem_mes)
    n_ausentes = len(itens) - n_ok
    if not partes:
        return [], 0, n_ausentes, "Não foi possível criar o ZIP."
    return partes, n_ok, n_ausentes, None


_ARQUIVO_FISCAL_ZIP_TRES_LOTES = (
    ("NFe_propria", "NFe emissão própria"),
    ("NFe_terceiros", "NFe terceiros"),
    ("CTe", "CT-e"),
)


def _arquivo_fiscal_grupo_zip_tres_lotes(item: dict) -> str | None:
    """Classifica item para um dos 3 ZIPs de envio (NFe própria, NFe terceiros, CT-e)."""
    mod = _normaliza_modelo_filtro(item.get("modelo"))
    is_pr = int(item.get("is_propria") or 0) == 1
    if mod in ("CT-e", "CT-e OS"):
        return "CTe"
    if mod in ("NF-e", "NFC-e"):
        return "NFe_propria" if is_pr else "NFe_terceiros"
    return None


def _arquivo_fiscal_zip_tres_lotes(
    cnpj: str,
    pasta_destino: str | Path,
    *,
    ano: int | None = None,
    mes: int | None = None,
    meses: list[int] | None = None,
    status: str | None = None,
    serie: str | None = None,
    data_inicio: str | None = None,
    data_fim: str | None = None,
    numero_inicio: int | None = None,
    numero_fim: int | None = None,
) -> tuple[list[str], dict[str, int], int, str | None]:
    """
    Cria até 3 ZIPs na pasta escolhida: NFe emissão própria, NFe terceiros e CT-e.
    XML na raiz de cada ZIP (sem subpastas). Respeita período/série/status do filtro.
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return [], {}, 0, "CNPJ inválido."
    itens = _arquivo_fiscal_listar(
        cx,
        ano=ano,
        mes=mes,
        meses=meses,
        status=status,
        serie=serie,
        data_inicio=data_inicio,
        data_fim=data_fim,
        numero_inicio=numero_inicio,
        numero_fim=numero_fim,
    )
    if not itens:
        return [], {}, 0, "Nenhum XML no arquivo com estes filtros."
    try:
        dest = Path(pasta_destino).expanduser().resolve()
    except (OSError, ValueError):
        return [], {}, 0, "Pasta de destino inválida."
    dest.mkdir(parents=True, exist_ok=True)
    base = _arquivo_fiscal_pasta_empresa(cx)
    prefixo = _arquivo_fiscal_prefixo_zip_avancado(
        ano=ano,
        mes=mes,
        meses=meses,
        is_propria=None,
        status=status,
        serie=serie,
        data_inicio=data_inicio,
        data_fim=data_fim,
        numero_inicio=numero_inicio,
        numero_fim=numero_fim,
    )
    grupos: dict[str, list[tuple[Path, str]]] = {
        k: [] for k, _ in _ARQUIVO_FISCAL_ZIP_TRES_LOTES
    }
    for it in itens:
        g = _arquivo_fiscal_grupo_zip_tres_lotes(it)
        if not g:
            continue
        rel = str(it.get("caminho_relativo") or "").replace("/", os.sep)
        if not rel:
            continue
        p = base / rel
        if not p.is_file():
            continue
        arc = str(it.get("nome_arquivo") or p.name)
        grupos[g].append((p, arc))
    partes: list[str] = []
    contagens: dict[str, int] = {}
    for chave, rotulo in _ARQUIVO_FISCAL_ZIP_TRES_LOTES:
        pares = grupos.get(chave) or []
        if not pares:
            contagens[rotulo] = 0
            continue
        nome_base = f"arquivo_{cx}_{prefixo}_{chave}"
        criados = _arquivo_fiscal_escrever_zips_xml_flat(pares, dest, nome_base)
        partes.extend(criados)
        contagens[rotulo] = len(pares)
    n_ok = sum(contagens.values())
    n_ausentes = _arquivo_fiscal_contar_ausentes_disco(cx, itens)
    if not partes:
        return [], contagens, n_ausentes, "Nenhum XML no disco para estes filtros (NFe/CT-e)."
    return partes, contagens, n_ausentes, None


