def _arquivo_fiscal_zip_espelho_filtrado(
    cnpj: str,
    pasta_destino: str | Path,
    *,
    ano: int | None = None,
    mes: int | None = None,
    meses: list[int] | None = None,
    is_propria: int | None = None,
    status: str | None = None,
    serie: str | None = None,
    modelo: str | None = None,
    data_inicio: str | None = None,
    data_fim: str | None = None,
    numero_inicio: int | None = None,
    numero_fim: int | None = None,
    espelho_pasta_zip: bool = False,
) -> tuple[list[str], int, int, str | None]:
    """
    ZIP(s) por pastinha EP_/T_ (série, mês, status…) — formato espelho do arquivo.
    Estrutura: pasta/AAAA/Mês/EP_2026_06_Serie_2_….zip com XML na raiz de cada ZIP.
    Com espelho_pasta_zip=True, prefixa ZIP/ (igual ao disco D:\\…\\ArquivoFiscal\\CNPJ\\ZIP\\).
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return [], 0, 0, "CNPJ inválido."
    itens = _arquivo_fiscal_listar(
        cx,
        ano=ano,
        mes=mes,
        meses=meses,
        is_propria=is_propria,
        status=status,
        serie=serie,
        modelo=modelo,
        data_inicio=data_inicio,
        data_fim=data_fim,
        numero_inicio=numero_inicio,
        numero_fim=numero_fim,
    )
    if not itens:
        return [], 0, 0, "Nenhum XML no arquivo com estes filtros."
    try:
        dest_root = Path(pasta_destino).expanduser().resolve()
    except (OSError, ValueError):
        return [], 0, 0, "Pasta de destino inválida."
    if espelho_pasta_zip:
        dest_root = dest_root / _ARQUIVO_FISCAL_SUBPASTA_ZIP
    dest_root.mkdir(parents=True, exist_ok=True)
    base = _arquivo_fiscal_pasta_empresa(cx)
    grupos: dict[tuple[str, Path], list[tuple[Path, str]]] = {}
    for it in itens:
        rel = str(it.get("caminho_relativo") or "").replace("/", os.sep)
        if not rel:
            continue
        p = base / rel
        if not p.is_file():
            continue
        slug = _arquivo_fiscal_slug_db_de_pasta(
            str(it.get("slug_pasta") or it.get("caminho_relativo") or "")
        )
        if not slug or slug in ("sem_grupo", "sem_data"):
            slug = "sem_grupo"
        try:
            a = int(it.get("ano") or 0)
            m = int(it.get("mes") or 0)
        except (TypeError, ValueError):
            comp = _arquivo_fiscal_competencia_de_item(it)
            a, m = comp if comp else (0, 0)
        if a > 0 and 1 <= m <= 12:
            zip_dir = dest_root / f"{a:04d}" / _arquivo_fiscal_nome_pasta_mes(m)
        else:
            zip_dir = dest_root
        grupos.setdefault((slug, zip_dir), []).append(
            (p, str(it.get("nome_arquivo") or p.name))
        )
    if not grupos:
        return [], 0, len(itens), "Ficheiros listados no banco mas ausentes no disco."
    partes: list[str] = []
    total_xml = 0
    for (slug, zip_dir), pares in sorted(grupos.items(), key=lambda x: (str(x[0][1]), x[0][0])):
        total_xml += len(pares)
        partes.extend(_arquivo_fiscal_escrever_zips_xml_flat(pares, zip_dir, slug))
    n_ausentes = len(itens) - total_xml
    if not partes:
        return [], 0, n_ausentes, "Não foi possível criar os ZIPs."
    return partes, total_xml, n_ausentes, None


def _arquivo_fiscal_raiz_relatorios_excel() -> Path:
    """Pasta Relatórios na partilha xml — independente do Arquivo no D:."""
    try:
        from core.exportacoes import caminho_letra_rede, carregar_config, pasta_dados_garimpeiro
        from core.pastas_layout import pasta_relatorios

        cfg = carregar_config()
        pe = str(cfg.get("pasta_excel") or "").strip()
        if pe:
            root = caminho_letra_rede(Path(pe).expanduser())
        else:
            root = pasta_relatorios(caminho_letra_rede(pasta_dados_garimpeiro()), criar=True)
        try:
            root.mkdir(parents=True, exist_ok=True)
        except OSError:
            pass
        return root
    except ImportError:
        return Path(_garimpeiro_resolver_pasta_dados()) / "Relatórios"


def _arquivo_fiscal_excel_dir_empresa(cnpj: str) -> Path:
    """Excel visível em Relatórios\\{empresa} na partilha GARIMPEIRO (xml)."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    try:
        from core.exportacoes import garantir_pasta_empresa_export

        root = _arquivo_fiscal_raiz_relatorios_excel()
        dest = garantir_pasta_empresa_export(root, sys.modules[__name__], cx)
    except ImportError:
        dest = _arquivo_fiscal_pasta_empresa(cnpj)
        try:
            dest.mkdir(parents=True, exist_ok=True)
        except OSError:
            pass
    return dest


def _arquivo_fiscal_excel_escrever_bytes(
    cnpj_limpo: str, destino: Path, conteudo: bytes
) -> Path:
    """Grava em Relatórios e espelha o mesmo ficheiro na pasta Arquivo da empresa."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj_limpo)
    dest = Path(destino)
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_bytes(conteudo)
    if len(cx) == 14:
        try:
            esp = _arquivo_fiscal_pasta_empresa(cx) / dest.name
            esp.parent.mkdir(parents=True, exist_ok=True)
            esp.write_bytes(conteudo)
        except OSError:
            pass
    return dest


def _arquivo_fiscal_excel_path(cnpj: str) -> Path:
    return _arquivo_fiscal_excel_dir_empresa(cnpj) / _ARQUIVO_FISCAL_NOME_EXCEL


def _arquivo_fiscal_excel_path_competencia(cnpj: str, ano: int, mes: int) -> Path:
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    return (
        _arquivo_fiscal_excel_dir_empresa(cx)
        / f"relatorio_garimpeiro_{int(ano):04d}_{int(mes):02d}.xlsx"
    )


def _chave_exibicao_relatorio(ch) -> str:
    """Chave para relatório/Excel/UI: 44 dígitos ou INUT_/MANUAL_* — sem sufixo interno #STATUS."""
    if ch is None:
        return ""
    try:
        if pd.isna(ch):
            return ""
    except (TypeError, ValueError):
        pass
    s = str(ch).strip()
    if not s or s.lower() == "nan":
        return ""
    k = _arquivo_fiscal_chave_registro({"Chave": s})
    return k if k else s


def _df_normalizar_coluna_chave_relatorio(df):
    """Garante coluna Chave só com 44 dígitos (ou identificadores MANUAL_/INUT_)."""
    if df is None or not isinstance(df, pd.DataFrame) or df.empty or "Chave" not in df.columns:
        return df
    out = df.copy()
    out["Chave"] = out["Chave"].map(_chave_exibicao_relatorio)
    return out


def _arquivo_fiscal_aplicar_overrides_indice(res: dict, it: dict) -> dict:
    """Alinha o resumo com status/ano/mês/chave do índice SQLite."""
    status_db = str(it.get("status") or "").strip().upper()
    chave = str(it.get("chave") or "").strip()
    if status_db:
        res["Status"] = status_db
    if chave:
        res["Chave"] = _chave_exibicao_relatorio(chave)
    if it.get("ano"):
        try:
            res["Ano"] = f"{int(it['ano']):04d}"
        except (TypeError, ValueError):
            pass
    if it.get("mes"):
        try:
            res["Mes"] = f"{int(it['mes']):02d}"
        except (TypeError, ValueError):
            pass
    if it.get("data_emissao"):
        res["Data_Emissao"] = str(it.get("data_emissao") or res.get("Data_Emissao") or "")
    return res


def _arquivo_fiscal_res_de_resumo_json(it: dict) -> dict | None:
    """Deserializa resumo_json do índice (caminho rápido — sem ler XML)."""
    raw = it.get("resumo_json")
    if not raw or not isinstance(raw, str):
        return None
    s = raw.strip()
    if not s or s[0] not in "{[":
        return None
    try:
        res = _relatorio_deserializar(s)
    except (ValueError, TypeError):
        return None
    if not isinstance(res, dict) or not res:
        return None
    # Nunca manter bytes em RAM a partir do cache
    res.pop("Conteúdo", None)
    res.pop("Conteudo", None)
    return res


def _arquivo_fiscal_persistir_resumos_json(
    cnpj: str, pares: list[tuple[str, str]]
) -> None:
    """Grava resumo_json em lote (chave, json)."""
    if not pares:
        return
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    if len(cx) != 14:
        return
    conn = _arquivo_fiscal_conn(cx)
    try:
        conn.executemany(
            "UPDATE xml_arquivo SET resumo_json = ? WHERE chave = ? "
            "AND (resumo_json IS NULL OR trim(resumo_json) = '')",
            [(js, ch) for ch, js in pares],
        )
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _arquivo_fiscal_res_de_item_indexado(
    cnpj: str, it: dict, empresa: Path
) -> tuple[dict | None, bool]:
    """
    Monta o registo do relatório a partir do índice SQLite.
    Respeita status do arquivo (cancelada marcada, inutilizada manual, …)
    — não volta a «autorizada» só porque o XML no disco é de autorização.
    Preferência: resumo_json em cache (sem reler o XML).
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    chave = str(it.get("chave") or "").strip()
    rel = str(it.get("caminho_relativo") or "").replace("\\", "/")
    nome = str(it.get("nome_arquivo") or Path(rel).name or "")
    is_pr = bool(int(it.get("is_propria") or 0))
    mod = str(it.get("modelo") or "NF-e")
    ser = str(it.get("serie") or "1")
    try:
        num = int(it.get("numero") or 0)
    except (TypeError, ValueError):
        num = 0

    # Inutilizada manual (sem XML) — .txt ou chave MANUAL_INUT_
    if (
        chave.startswith("MANUAL_INUT_")
        or "manual_inutilizadas" in rel.lower()
        or nome.lower().endswith(".txt")
    ):
        cached = _arquivo_fiscal_res_de_resumo_json(it)
        if cached:
            return _arquivo_fiscal_aplicar_overrides_indice(cached, it), True
        if num <= 0:
            return None, False
        res = item_registro_manual_inutilizado(cx, mod, ser, num)
        # Preferir ano/mês do índice quando existirem
        if it.get("ano"):
            res["Ano"] = f"{int(it['ano']):04d}"
        if it.get("mes"):
            res["Mes"] = f"{int(it['mes']):02d}"
        if it.get("data_emissao"):
            res["Data_Emissao"] = str(it.get("data_emissao") or "")
        return res, True

    cached = _arquivo_fiscal_res_de_resumo_json(it)
    if cached:
        res = _arquivo_fiscal_aplicar_overrides_indice(cached, it)
        return _arquivo_fiscal_data_emissao_cancelada_original(empresa, it, res), is_pr

    path = empresa / rel.replace("/", os.sep) if rel else None
    if path is None or not path.is_file():
        return None, False
    if not path.name.lower().endswith(".xml"):
        return None, False
    try:
        raw = path.read_bytes()
    except OSError:
        return None, False
    res, is_p = identify_xml_info(raw, cx, path.name)
    if not res:
        return None, False
    res = _arquivo_fiscal_aplicar_overrides_indice(res, it)
    res = _arquivo_fiscal_data_emissao_cancelada_original(empresa, it, res)
    return res, is_pr if it.get("is_propria") is not None else is_p


def _arquivo_fiscal_montar_lote_de_itens(
    cnpj: str,
    itens: list[dict],
    *,
    progresso_label: str = "",
) -> tuple[dict, int, int]:
    """Devolve (lote_dict chave→(res, is_propria), lidos, ignorados)."""
    from concurrent.futures import ThreadPoolExecutor, as_completed

    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    empresa = _arquivo_fiscal_pasta_empresa(cx)
    lote_dict: dict = {}
    lidos = 0
    ignorados = 0
    _total = len(itens)
    _headless = bool(os.environ.get("GARIMPEIRO_HEADLESS"))
    resumos_novos: list[tuple[str, str]] = []

    def _meter(key: str, res: dict, is_p: bool) -> None:
        nonlocal lidos
        if key in lote_dict:
            if res.get("Status") in (
                "CANCELADOS",
                "INUTILIZADOS",
                "DENEGADOS",
                "REJEITADOS",
            ):
                lote_dict[key] = (res, is_p)
        else:
            lote_dict[key] = (res, is_p)
        lidos += 1

    com_cache: list[dict] = []
    sem_cache: list[dict] = []
    for it in itens:
        chave_it = str(it.get("chave") or "")
        rel_it = str(it.get("caminho_relativo") or "").replace("\\", "/").lower()
        nome_it = str(it.get("nome_arquivo") or "").lower()
        is_manual = (
            chave_it.startswith("MANUAL_INUT_")
            or "manual_inutilizadas" in rel_it
            or nome_it.endswith(".txt")
        )
        if is_manual or _arquivo_fiscal_res_de_resumo_json(it) is not None:
            com_cache.append(it)
        else:
            sem_cache.append(it)

    for _i, it in enumerate(com_cache, start=1):
        if _headless and _total >= 1000 and _i % 2000 == 0 and progresso_label:
            print(
                f"[garimpeiro] {progresso_label}: cache {_i}/{len(com_cache)}…",
                file=sys.stderr,
                flush=True,
            )
        res, is_p = _arquivo_fiscal_res_de_item_indexado(cx, it, empresa)
        if not res:
            ignorados += 1
            continue
        key = str(res.get("Chave") or "").strip()
        if not key:
            ignorados += 1
            continue
        _meter(key, res, is_p)

    def _parse_miss(it: dict) -> tuple[dict | None, bool, str | None]:
        res, is_p = _arquivo_fiscal_res_de_item_indexado(cx, it, empresa)
        js = None
        if res:
            try:
                js = _relatorio_serializar(res)
            except Exception:
                js = None
        return res, is_p, js

    n_miss = len(sem_cache)
    workers = 1
    if n_miss >= 40:
        workers = min(8, max(2, (os.cpu_count() or 4)))
    if workers == 1 or n_miss < 40:
        for _i, it in enumerate(sem_cache, start=1):
            if _headless and n_miss >= 1000 and _i % 2000 == 0 and progresso_label:
                print(
                    f"[garimpeiro] {progresso_label}: disco {_i}/{n_miss}…",
                    file=sys.stderr,
                    flush=True,
                )
            res, is_p, js = _parse_miss(it)
            if not res:
                ignorados += 1
                continue
            key = str(res.get("Chave") or "").strip()
            if not key:
                ignorados += 1
                continue
            _meter(key, res, is_p)
            if js:
                resumos_novos.append((key, js))
    else:
        if _headless and progresso_label:
            print(
                f"[garimpeiro] {progresso_label}: a ler {n_miss} XML sem cache "
                f"({workers} threads)…",
                file=sys.stderr,
                flush=True,
            )
        with ThreadPoolExecutor(max_workers=workers) as pool:
            futs = {pool.submit(_parse_miss, it): it for it in sem_cache}
            feitos = 0
            for fut in as_completed(futs):
                feitos += 1
                if _headless and n_miss >= 1000 and feitos % 2000 == 0 and progresso_label:
                    print(
                        f"[garimpeiro] {progresso_label}: disco {feitos}/{n_miss}…",
                        file=sys.stderr,
                        flush=True,
                    )
                try:
                    res, is_p, js = fut.result()
                except Exception:
                    ignorados += 1
                    continue
                if not res:
                    ignorados += 1
                    continue
                key = str(res.get("Chave") or "").strip()
                if not key:
                    ignorados += 1
                    continue
                _meter(key, res, is_p)
                if js:
                    resumos_novos.append((key, js))

    if resumos_novos:
        _arquivo_fiscal_persistir_resumos_json(cx, resumos_novos)

    return lote_dict, lidos, ignorados


def _arquivo_fiscal_listar_inutilizadas_competencia(
    cnpj: str,
    ano: int,
    mes: int,
) -> list[dict]:
    """
    Inutilizadas do mês pela mesma regra da UI: (ano = ? OR ano IS NULL) +
    competência pela numeração (_arquivo_fiscal_inferir_mes_competencia_inutilizada).
    Inclui registos manuais Sefaz (ano/mês NULL).
    """
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    ano_i, mes_i = int(ano), int(mes)
    if len(cx) != 14 or not 1 <= mes_i <= 12:
        return []
    if not _arquivo_fiscal_db_path(cx).is_file():
        return []
    por_mes_nums = _arquivo_fiscal_cache_ano(cx, ano_i)["por_mes"]
    conn = _arquivo_fiscal_conn(cx)
    try:
        rows = conn.execute(
            """
            SELECT chave, nome_arquivo, caminho_relativo, ano, mes, status, slug_pasta,
                   is_propria, serie, modelo, data_emissao, numero, resumo_json
            FROM xml_arquivo
            WHERE cnpj_empresa = ? AND is_propria = 1
              AND upper(trim(COALESCE(status, ''))) = 'INUTILIZADOS'
              AND numero IS NOT NULL AND numero > 0
              AND (ano = ? OR ano IS NULL)
            ORDER BY modelo, serie, numero
            """,
            (cx, ano_i),
        ).fetchall()
    finally:
        conn.close()
    cols = (
        "chave",
        "nome_arquivo",
        "caminho_relativo",
        "ano",
        "mes",
        "status",
        "slug_pasta",
        "is_propria",
        "serie",
        "modelo",
        "data_emissao",
        "numero",
        "resumo_json",
    )
    out: list[dict] = []
    for r in rows:
        it = dict(zip(cols, r))
        try:
            nota = int(it.get("numero") or 0)
        except (TypeError, ValueError):
            continue
        if nota <= 0:
            continue
        try:
            mes_db = int(it["mes"]) if it.get("mes") is not None else None
        except (TypeError, ValueError):
            mes_db = None
        mes_comp = _arquivo_fiscal_inferir_mes_competencia_inutilizada(
            por_mes_nums,
            str(it.get("modelo") or ""),
            str(it.get("serie") or ""),
            nota,
            mes_armazenado=mes_db,
        )
        if mes_comp != mes_i:
            continue
        # Marca competência no item para o Excel / resumo
        it["ano"] = ano_i
        it["mes"] = mes_i
        out.append(it)
    vistos: dict[tuple, dict] = {}
    ordem: list[tuple] = []
    for it in out:
        try:
            n = int(it.get("numero") or 0)
        except (TypeError, ValueError):
            continue
        k = (
            _normaliza_modelo_filtro(str(it.get("modelo") or "")),
            _normaliza_serie_filtro(str(it.get("serie") or "")),
            n,
        )
        ch = str(it.get("chave") or "")
        score = 0 if ch.startswith("MANUAL_INUT_") else 1
        if k not in vistos:
            ordem.append(k)
            vistos[k] = (score, it)
        elif score >= vistos[k][0]:
            vistos[k] = (score, it)
    return [vistos[k][1] for k in ordem]


def _arquivo_fiscal_itens_para_excel_competencia(
    cnpj: str,
    ano: int,
    mes: int,
) -> list[dict]:
    """Documentos do mês + inutilizadas na competência correta (como na UI)."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj)
    itens = _arquivo_fiscal_listar(
        cx, ano=int(ano), mes=int(mes), incluir_resumo=True
    )
    base = [
        i
        for i in itens
        if str(i.get("status") or "").strip().upper() != "INUTILIZADOS"
    ]
    vistos = {str(i.get("chave") or "").strip() for i in base if i.get("chave")}
    for it in _arquivo_fiscal_listar_inutilizadas_competencia(cx, int(ano), int(mes)):
        ch = str(it.get("chave") or "").strip()
        if ch and ch in vistos:
            continue
        if ch:
            vistos.add(ch)
        base.append(it)
    return base


def _excel_df_buracos_competencia(cnpj: str, ano: int, mes: int) -> pd.DataFrame:
    """
    Buracos do Excel do mês — iguais ao painel: reais (faltam no arquivo) e
    «falsos» (nº falta neste mês, mas a NF já foi emitida noutro).
    """
    cols = [
        "Tipo",
        "Série",
        "Num_Faltante",
        "Situação",
        "Emitida em",
        "Data emissão",
        "Status NF",
        "Mês possível",
    ]
    try:
        df_bur, df_fal = _arquivo_fiscal_buracos_painel_periodo(
            cnpj, int(ano), [int(mes)]
        )
    except Exception:
        return pd.DataFrame(columns=cols)
    rows: list[dict] = []
    if df_fal is not None and not df_fal.empty:
        for _, row in df_fal.iterrows():
            emitida = str(row.get("Emitida em") or "").strip() or "outro período"
            rows.append(
                {
                    "Tipo": row.get("Tipo", ""),
                    "Série": row.get("Série", ""),
                    "Num_Faltante": row.get("Num_Faltante", ""),
                    "Situação": f"Já emitida em {emitida}",
                    "Emitida em": emitida,
                    "Data emissão": row.get("Data emissão", "") or "—",
                    "Status NF": row.get("Status NF", "") or "—",
                    "Mês possível": "",
                }
            )
    if df_bur is not None and not df_bur.empty:
        for _, row in df_bur.iterrows():
            mes_pos = str(row.get("Mês possível") or "").strip()
            if mes_pos and mes_pos not in ("—", "-"):
                sit = f"Falta no arquivo · possível {mes_pos}"
            else:
                sit = "Falta no arquivo"
            rows.append(
                {
                    "Tipo": row.get("Tipo", ""),
                    "Série": row.get("Série", ""),
                    "Num_Faltante": row.get("Num_Faltante", ""),
                    "Situação": sit,
                    "Emitida em": "",
                    "Data emissão": "—",
                    "Status NF": "—",
                    "Mês possível": mes_pos,
                }
            )
    return pd.DataFrame(rows, columns=cols) if rows else pd.DataFrame(columns=cols)


def _arquivo_fiscal_gerar_excel_competencia(
    cnpj_limpo: str,
    ano: int,
    mes: int,
    *,
    destino_excel: str | Path | None = None,
) -> tuple[str | None, str]:
    """Excel só do mês indicado (não altera o relatório completo da empresa)."""
    cx = _arquivo_fiscal_cnpj_limpo(cnpj_limpo)
    if len(cx) != 14:
        return None, "CNPJ inválido."
    if not 1 <= int(mes) <= 12:
        return None, "Mês inválido."
    if destino_excel is not None:
        dest = Path(destino_excel).expanduser().resolve()
    else:
        dest = _arquivo_fiscal_excel_path_competencia(cx, int(ano), int(mes))

    itens = _arquivo_fiscal_itens_para_excel_competencia(cx, int(ano), int(mes))
    if not itens:
        return None, f"Nenhum documento indexado para {int(mes):02d}/{int(ano)}."

    lote_dict, _lidos, ignorados = _arquivo_fiscal_montar_lote_de_itens(
        cx,
        itens,
        progresso_label=f"Excel mês {int(mes):02d}/{int(ano)}",
    )

    if not lote_dict:
        return (
            None,
            f"**{len(itens)}** indexado(s) em {int(mes):02d}/{int(ano)}, "
            "mas nenhum documento legível no disco.",
        )

    st.session_state["cnpj_widget"] = format_cnpj_visual(cx)
    _relatorio_set_list([t[0] for t in lote_dict.values()])
    st.session_state["garimpo_ok"] = True
    # Mantém inutilizadas do arquivo (manuais / competência) na folha Inutilizadas
    st.session_state["_relatorio_excel_competencia"] = (int(ano), int(mes), cx)
    st.session_state["_relatorio_excel_arquivo"] = True
    try:
        reconstruir_dataframes_relatorio_simples()
    finally:
        st.session_state.pop("_relatorio_excel_competencia", None)
        st.session_state.pop("_relatorio_excel_arquivo", None)
    df_geral = st.session_state.get("df_geral")
    if df_geral is None or not isinstance(df_geral, pd.DataFrame) or df_geral.empty:
        return None, "Relatório vazio após leitura dos XML do mês."
    st.session_state["df_faltantes"] = _excel_df_buracos_competencia(
        cx, int(ano), int(mes)
    )
    try:
        xb = excel_relatorio_geral_com_dashboard_bytes(df_geral, cnpj_limpo=cx)
    except Exception as e:
        return None, f"Erro ao montar Excel do mês: {e}"
    if not xb:
        return None, "Não foi possível gerar bytes do Excel do mês."
    try:
        dest.parent.mkdir(parents=True, exist_ok=True)
        _arquivo_fiscal_excel_escrever_bytes(cx, dest, xb)
        _arquivo_fiscal_excel_competencia_gravar_meta(cx, int(ano), int(mes))
    except OSError as e:
        return None, f"Erro ao gravar ficheiro: {e}"
    msg = (
        f"Excel do mês gravado em `{dest}` — **{len(lote_dict)}** documento(s) "
        f"({int(mes):02d}/{int(ano)})"
    )
    if ignorados:
        msg += f"; **{ignorados}** ficheiro(s) ignorado(s)."
    return str(dest), msg


def _arquivo_fiscal_resolver_pasta_xml(pasta: str | Path) -> Path | None:
    """Aceita pasta da empresa (com subpasta XML/) ou a própria pasta XML."""
    try:
        p = Path(pasta).expanduser().resolve()
    except (OSError, ValueError):
        return None
    if not p.is_dir():
        return None
    sub = p / _ARQUIVO_FISCAL_SUBPASTA_XML
    if sub.is_dir():
        return sub
    if any(p.rglob("*.xml")):
        return p
    return None


def _arquivo_fiscal_gerar_excel_a_partir_pasta_xml(
    pasta: str | Path,
    cnpj_limpo: str,
    *,
    destino_excel: str | Path | None = None,
) -> tuple[str | None, str]:
    """
    Monta o Excel completo a partir do índice SQLite (status reais do arquivo)
    e grava na pasta da empresa. Devolve (caminho_excel, mensagem).
    """
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj_limpo)
    if len(cnpj) != 14:
        return None, "CNPJ inválido — são necessários 14 dígitos."
    base_xml = _arquivo_fiscal_resolver_pasta_xml(pasta)
    if base_xml is None and _arquivo_fiscal_total(cnpj) <= 0:
        return None, f"Pasta não encontrada ou sem XML: `{pasta}`"

    itens = _arquivo_fiscal_listar(cnpj, incluir_resumo=True)
    if not itens:
        # Fallback legado: pasta sem SQLite útil
        if base_xml is None:
            return None, f"Nenhum documento indexado para o CNPJ **{cnpj}**."
        xml_iter = sorted(base_xml.rglob("*.xml"))
        if not xml_iter:
            return None, f"Nenhum ficheiro .xml em `{base_xml}`."
        lote_dict: dict = {}
        ignorados = 0
        for path in xml_iter:
            try:
                raw = path.read_bytes()
            except OSError:
                ignorados += 1
                continue
            res, is_p = identify_xml_info(raw, cnpj, path.name)
            if not res:
                ignorados += 1
                continue
            key = res["Chave"]
            if key in lote_dict:
                if res["Status"] in (
                    "CANCELADOS",
                    "INUTILIZADOS",
                    "DENEGADOS",
                    "REJEITADOS",
                ):
                    lote_dict[key] = (res, is_p)
            else:
                lote_dict[key] = (res, is_p)
        _total_xml = len(xml_iter)
    else:
        lote_dict, _lidos, ignorados = _arquivo_fiscal_montar_lote_de_itens(
            cnpj,
            itens,
            progresso_label="Excel completo",
        )
        _total_xml = len(itens)

    if not lote_dict:
        return (
            None,
            f"**{_total_xml}** documento(s) no índice, mas nenhum reconhecido para o CNPJ **{cnpj}**.",
        )
    st.session_state["cnpj_widget"] = format_cnpj_visual(cnpj)
    _relatorio_set_list([t[0] for t in lote_dict.values()])
    st.session_state["garimpo_ok"] = True
    st.session_state["_relatorio_excel_arquivo"] = True
    try:
        reconstruir_dataframes_relatorio_simples()
    finally:
        st.session_state.pop("_relatorio_excel_arquivo", None)
    df_geral = st.session_state.get("df_geral")
    if df_geral is None or not isinstance(df_geral, pd.DataFrame) or df_geral.empty:
        return None, "Relatório vazio após leitura do arquivo."
    try:
        xb = excel_relatorio_geral_com_dashboard_bytes(df_geral, cnpj_limpo=cnpj)
    except Exception as e:
        return None, f"Erro ao montar Excel: {e}"
    if not xb:
        return None, "Não foi possível gerar bytes do Excel."
    try:
        if destino_excel is not None:
            dest = Path(destino_excel).expanduser().resolve()
        else:
            dest = _arquivo_fiscal_excel_path(cnpj)
        dest.parent.mkdir(parents=True, exist_ok=True)
        _arquivo_fiscal_excel_escrever_bytes(cnpj, dest, xb)
        _arquivo_fiscal_excel_gravar_meta(cnpj)
    except OSError as e:
        return None, f"Erro ao gravar ficheiro: {e}"
    msg = (
        f"Excel gravado em `{dest}` — **{len(lote_dict)}** documento(s) único(s) "
        f"a partir de **{_total_xml}** no arquivo"
    )
    if ignorados:
        msg += f"; **{ignorados}** ficheiro(s) ignorado(s)."
    return str(dest), msg


def _arquivo_fiscal_gravar_excel_relatorio(cnpj_limpo: str) -> str | None:
    """
    Grava na pasta do arquivo fiscal o Excel completo do garimpo
    (mesmas folhas do download: Geral, Buracos, Canceladas, Dashboard, etc.).
    Devolve o caminho gravado ou None.
    """
    if not _garimpo_arquivo_fiscal_disponivel():
        return None
    cnpj = _arquivo_fiscal_cnpj_limpo(cnpj_limpo)
    if len(cnpj) != 14:
        return None
    df_geral = st.session_state.get("df_geral")
    if df_geral is None or not isinstance(df_geral, pd.DataFrame) or df_geral.empty:
        return None
    try:
        xb = excel_relatorio_geral_com_dashboard_bytes(df_geral, cnpj_limpo=cnpj)
        if not xb:
            return None
        dest = _arquivo_fiscal_excel_path(cnpj)
        _arquivo_fiscal_excel_escrever_bytes(cnpj, dest, xb)
        _arquivo_fiscal_excel_gravar_meta(cnpj)
        st.session_state["_arquivo_fiscal_excel_ultimo"] = str(dest)
        return str(dest)
    except OSError:
        return None
    except Exception:
        return None


def _garimpo_arquivo_fiscal_disponivel() -> bool:
    return not _arquivo_fiscal_desativado_env() and not _streamlit_likely_community_cloud()


def _garimpo_modo_simples() -> bool:
    """True = Garimpo simples: lê/separa/extrai nesta sessão, sem ArquivoFiscal nem espelho."""
    try:
        v = str(st.session_state.get(SESSION_KEY_GARIMPO_MODO_TRABALHO) or "").strip().lower()
    except Exception:
        return False
    return v == GARIMPO_MODO_SIMPLES


def _garimpo_aplicar_modo_simples_sem_persistencia() -> None:
    """Garante que o Garimpo simples não deixa captura/espelho ativos na sessão."""
    if not _garimpo_modo_simples():
        return
    try:
        st.session_state[SESSION_KEY_ARQUIVO_FISCAL_CAPTURA] = False
    except Exception:
        pass
    try:
        st.session_state["mariana_usar_pasta_destino"] = False
    except Exception:
        pass


def _garimpo_voltar_tela_inicio() -> None:
    st.session_state[SESSION_KEY_GARIMPO_TELA] = "inicio"
    st.session_state["confirmado"] = False


def _garimpo_ui_barra_navegacao_modo() -> None:
    _c1, _c2 = st.columns([1, 6])
    with _c1:
        if st.button("\u2190 In\u00edcio", key="btn_nav_voltar_inicio"):
            _garimpo_voltar_tela_inicio()
            st.rerun()
    with _c2:
        _modo = st.session_state.get(SESSION_KEY_GARIMPO_TELA)
        if _modo == "garimpo":
            st.caption("Modo **novo garimpo** — leitura de XML/ZIP e relatório.")
        elif _modo == "arquivo":
            st.caption("Modo **documentos j\u00e1 lidos** — arquivo fiscal permanente.")
        elif _modo == "inutil":
            st.caption("Modo **inutilizadas** — declarar notas da Sefaz sem novo garimpo.")
        elif _modo == "sped":
            st.caption("Modo **SPED × XML** — cruzar escrituração fiscal com o garimpo.")


def _garimpo_ui_indicar_inutilizadas(cnpj_limpo: str, *, key_prefix: str = "inut_") -> None:
    """Indicar inutilizadas só no arquivo fiscal — sem ler XML de novo."""
    _k = lambda s: f"{key_prefix}{s}"
    if not _garimpo_arquivo_fiscal_disponivel():
        st.warning("Disponível no Garimpeiro 2.0 neste PC.")
        return
    if len(_arquivo_fiscal_cnpj_limpo(cnpj_limpo)) != 14:
        st.warning("CNPJ inválido na barra lateral — são necessários 14 dígitos.")
        return
    st.markdown(
        f'<h4>{_garim_emoji("\U0001f6ab")} Indicar inutilizadas (sem novo garimpo)</h4>',
        unsafe_allow_html=True,
    )
    st.caption(
        "Declare notas que a Sefaz mostra como inutilizadas mas que não estão nos XML. "
        "Usa o **arquivo fiscal** já indexado — não precisa enviar ficheiros nem clicar em **Processar dados**."
    )
    if not _garimpo_pode_indicar_inutilizadas(cnpj_limpo):
        st.info(
            "Informe o CNPJ e faça um garimpo com captura, ou escolha uma empresa que já tenha "
            "XML no arquivo fiscal (menu **Documentos já lidos**)."
        )
        return
    if st.session_state.get("garimpo_ok"):
        st.caption(
            "Há um garimpo aberto nesta sessão. Aqui atualiza o **arquivo fiscal** e o Excel; "
            "para refletir no relatório do garimpo use **Inutilizadas** no painel lateral ou **Processar dados**."
        )
    n_tot, n_man = _arquivo_fiscal_contar_inutilizadas(cnpj_limpo)
    n_xml = _arquivo_fiscal_total(cnpj_limpo)
    st.info(
        f"**Arquivo fiscal:** {n_xml:,} XML indexados · {n_tot} inutilizada(s) "
        f"({n_man} registada(s) manualmente).".replace(",", ".")
    )

    tab_u, tab_f, tab_b, tab_p = st.tabs(
        ["Uma nota", "Faixa de números", "Dos buracos", "Planilha / colar"]
    )

    with tab_u:
        cu1, cu2, cu3 = st.columns(3)
        with cu1:
            _mod_u = st.selectbox(
                "Modelo",
                ["NF-e", "NFC-e", "CT-e", "CT-e OS", "MDF-e"],
                key=_k("mod_unica"),
            )
        with cu2:
            _ser_u = st.text_input("Série", value="1", key=_k("ser_unica")).strip()
        with cu3:
            _nota_u = st.number_input("Nota", min_value=1, value=1, step=1, key=_k("nota_unica"))
        if st.button("Adicionar inutilizada", type="primary", key=_k("btn_unica")):
            with st.spinner("A registar…"):
                ok, msg = registrar_inutil_unica_arquivo_fiscal(
                    cnpj_limpo, _mod_u, _ser_u, int(_nota_u)
                )
            if ok:
                st.success(msg)
            else:
                st.error(msg)

    with tab_f:
        st.caption(
            "Marca como inutilizadas as notas da faixa que forem **buracos** (faltantes nos XML indexados)."
        )
        cf1, cf2 = st.columns(2)
        with cf1:
            _mod_f = st.selectbox(
                "Modelo",
                ["NF-e", "NFC-e", "CT-e", "CT-e OS", "MDF-e"],
                key=_k("mod_faixa"),
            )
            _ser_f = st.text_input("Série", value="1", key=_k("ser_faixa")).strip()
        with cf2:
            _n0_f = st.number_input("Nota inicial", min_value=1, value=1, step=1, key=_k("n0_faixa"))
            _n1_f = st.number_input("Nota final", min_value=1, value=1, step=1, key=_k("n1_faixa"))
        if st.button("Aplicar faixa", type="primary", key=_k("btn_faixa")):
            with st.spinner("A aplicar faixa…"):
                ok, msg = aplicar_inutilizadas_arquivo_fiscal(
                    cnpj_limpo,
                    mf_faixa=_mod_f,
                    sf_faixa=_ser_f,
                    n0_faixa=int(_n0_f),
                    n1_faixa=int(_n1_f),
                )
            if ok:
                st.success(msg)
            else:
                st.error(msg)

    with tab_b:
        _mods_bur = ["NF-e", "NFC-e", "CT-e", "CT-e OS", "MDF-e"]
        cb1, cb2 = st.columns(2)
        with cb1:
            _mod_b = st.selectbox("Modelo", _mods_bur, key=_k("mod_bur"))
        with cb2:
            _ser_b = st.text_input("Série", value="1", key=_k("ser_bur")).strip()
        _nums_bur = _arquivo_fiscal_buracos_numeros_mod_serie(cnpj_limpo, _mod_b, _ser_b)
        if not _nums_bur:
            st.info("Sem buracos neste modelo/série no arquivo fiscal.")
        else:
            st.caption(f"{len(_nums_bur)} buraco(s) — só estes podem ser declarados aqui.")
            _pick_b = st.multiselect(
                "Marque as notas:",
                options=_nums_bur,
                format_func=lambda x: f"Nota n.º {x}",
                key=_k("pick_bur"),
            )
            if st.button("Aplicar selecionados", type="primary", key=_k("btn_bur")):
                with st.spinner("A aplicar…"):
                    ok, msg = aplicar_inutilizadas_arquivo_fiscal(
                        cnpj_limpo,
                        pick_bur_inut=_pick_b,
                        mb_bur=_mod_b,
                        sb_bur=_ser_b,
                    )
                if ok:
                    st.success(msg)
                else:
                    st.error(msg)

    with tab_p:
        _bytes_m = bytes_modelo_planilha_inutil_sem_xml_xlsx()
        if _bytes_m:
            st.download_button(
                "Baixar modelo Excel",
                data=_bytes_m,
                file_name="MODELO_inutilizadas_sem_XML_garimpeiro.xlsx",
                mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                key=_k("dl_modelo"),
            )
        else:
            st.warning(_msg_sem_espaco_disco_garimpeiro())
        st.text_area(
            "Colar tabela (site Sefaz ou Excel)",
            height=130,
            key=_k("texto_colar"),
            placeholder="Cole as linhas da Sefaz (cabeçalho opcional): Ano, Modelo, Série, Nº Inicial, Nº Final…",
        )
        _up = st.file_uploader(
            "Ou importar ficheiro .csv, .xlsx ou .xls",
            type=["csv", "xlsx", "xls"],
            key=_k("up_planilha"),
        )
        if st.button("Aplicar planilha e/ou texto", type="primary", key=_k("btn_plan")):
            with st.spinner("A processar lista…"):
                ok, msg = aplicar_inutilizadas_arquivo_fiscal(
                    cnpj_limpo,
                    up_inut_planilha=_up,
                    texto_inut_planilha=st.session_state.get(_k("texto_colar")),
                )
            if ok:
                st.success(msg)
            else:
                st.error(msg)


def _garimpo_ui_cruzamento_sped(cnpj_limpo: str, *, key_prefix: str = "sped_") -> None:
    """Importar SPED(s) e cruzar chaves C100/D100 com o relatório / arquivo."""
    _k = lambda s: f"{key_prefix}{s}"
    if not _garimpo_arquivo_fiscal_disponivel():
        st.warning("Disponível no Garimpeiro 2.0 neste PC.")
        return
    cx = _arquivo_fiscal_cnpj_limpo(cnpj_limpo)
    if len(cx) != 14:
        st.warning("CNPJ inválido na barra lateral.")
        return
    st.markdown(
        f'<h4>{_garim_emoji("\U0001f4cb")} SPED × XML — o que não foi escriturado</h4>',
        unsafe_allow_html=True,
    )
    st.caption(
        "Envie o(s) arquivo(s) **SPED Fiscal** (`.txt`). O sistema lê as chaves dos registos "
        "**C100** (NF-e/NFC-e) e **D100** (CT-e). Na listagem abaixo pode **excluir** um envio "
        "errado ou **usar** outro como vigente para aquele mês. Um novo envio do mesmo mês "
        "substitui o anterior automaticamente. **Mês SPED** vazio no Excel = ainda não escriturada; "
        "vários meses no mesmo campo (ex.: `03/2026; 06/2026`) = apareceu em mais de um SPED."
    )
    mapa = _sped_mapa_chaves_empresa(cx)
    indice = sped_cruzamento.indice_sped_carregar(_sped_indice_path(cx))
    hist = sped_cruzamento.historico_sped_resumo(indice)
    if hist:
        n_ativos = sum(1 for h in hist if h.get("ativo"))
        st.info(
            f"Cruzamento vigente: **{len(mapa):,}** chave(s) · "
            f"**{n_ativos}** SPED ativo(s) · "
            f"**{len(hist)}** envio(s) no histórico.".replace(",", ".")
        )
        st.markdown("##### Histórico de envios — gerir")
        for i, ar in enumerate(hist):
            eid = str(ar.get("id") or "")
            vig = "✅ vigente" if ar.get("ativo") else "substituído"
            ret = " · retificação" if ar.get("retificacao") else ""
            c_a, c_b, c_c, c_d, c_e = st.columns([2.2, 1.2, 1.2, 0.8, 0.8])
            with c_a:
                st.markdown(
                    f"`{ar.get('importado_em', '')}`\n\n"
                    f"**{ar.get('nome', '?')}**"
                )
            with c_b:
                st.markdown(f"**{ar.get('competencia', '?')}**")
            with c_c:
                st.markdown(f"{int(ar.get('chaves') or 0):,} chaves".replace(",", "."))
            with c_d:
                if st.button(
                    "Usar",
                    key=_k(f"sped_usar_{i}"),
                    disabled=not eid or bool(ar.get("ativo")),
                    help="Torna este envio o vigente para a competência dele.",
                ):
                    ok_a, msg_a = _sped_ativar_entrada_empresa(cx, eid)
                    if ok_a:
                        st.success(msg_a)
                        st.rerun()
                    else:
                        st.error(msg_a)
            with c_e:
                if st.button(
                    "Excluir",
                    key=_k(f"sped_del_{i}"),
                    disabled=not eid,
                    help="Remove do histórico (e a cópia em SPED/historico/).",
                ):
                    ok_d, msg_d = _sped_remover_entrada_empresa(cx, eid)
                    if ok_d:
                        st.success(msg_d)
                        st.rerun()
                    else:
                        st.error(msg_d)
            st.caption(f"{vig}{ret}")
            if ar.get("arquivo_guardado"):
                st.caption(f"Cópia: `{ar.get('arquivo_guardado')}`")
            if i < len(hist) - 1:
                st.divider()
    else:
        st.info("Ainda não há SPED importado para este CNPJ.")

    up = st.file_uploader(
        "Arquivo(s) SPED (.txt)",
        type=["txt"],
        accept_multiple_files=True,
        key=_k("up_sped"),
    )
    c1, c2 = st.columns(2)
    with c1:
        if st.button("Processar SPED", type="primary", key=_k("btn_proc"), disabled=not up):
            uploads: list[tuple[str, bytes]] = []
            for f in up or []:
                try:
                    uploads.append((str(f.name), bytes(f.getvalue())))
                except Exception:
                    pass
            with st.spinner("A ler blocos C e D…"):
                ok, msg = _sped_processar_ficheiros_empresa(cx, uploads)
            if ok:
                st.success(msg)
                st.rerun()
            else:
                st.error(msg)
    with c2:
        if st.button(
            "Limpar índice SPED desta empresa",
            key=_k("btn_limpar"),
            disabled=not hist,
        ):
            _sped_limpar_indice_empresa(cx)
            st.success("Índice SPED removido.")
            st.rerun()

    df_g = st.session_state.get("df_geral")
    if isinstance(df_g, pd.DataFrame) and not df_g.empty and mapa:
        st.markdown("---")
        stats = sped_cruzamento.estatisticas_cruzamento_sped(df_g, mapa)
        st.markdown(
            f"**Relatório da sessão:** {stats['total_chave']:,} documento(s) com chave · "
            f"**{stats['com_sped']:,}** no SPED · "
            f"**{stats['sem_sped']:,}** sem escrituração no SPED importado.".replace(",", ".")
        )
        df_v = sped_cruzamento.df_adicionar_coluna_mes_sped(df_g, mapa)
        df_v = _df_garantir_coluna_razao_social_participante(df_v, cx)
        _mask_sem = df_v["Chave"].map(
            lambda c: bool(sped_cruzamento.chave44_digitos(c))
        ) & (df_v["Mês SPED"].astype(str).str.strip() == "")
        df_sem = df_v.loc[_mask_sem]
        if not df_sem.empty:
            st.markdown("**Amostra — sem SPED (primeiras 50 linhas)**")
            cols_show = [
                c
                for c in (
                    "Mês SPED",
                    "Razão Social Participante",
                    "Modelo",
                    "Série",
                    "Nota",
                    "Data Emissão",
                    "Chave",
                    "Status Final",
                    "Origem",
                )
                if c in df_sem.columns
            ]
            st.dataframe(df_sem[cols_show].head(50), use_container_width=True)
        if st.session_state.get("garimpo_ok"):
            xb = excel_relatorio_geral_com_dashboard_bytes(df_v)
            if xb:
                st.download_button(
                    "Descarregar Excel com coluna Mês SPED",
                    xb,
                    file_name="relatorio_com_sped.xlsx",
                    mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                    key=_k("dl_excel_sped"),
                )
    elif not st.session_state.get("garimpo_ok"):
        st.caption(
            "Faça um **garimpo** para ver a lista de notas sem SPED. O Excel gravado no arquivo "
            "fiscal inclui a coluna «Mês SPED» depois de importar o SPED."
        )


def _garimpo_ui_arquivo_fiscal_painel_historico(
    cnpj_limpo: str,
    *,
    key_prefix: str = "home_",
    mostrar_download: bool = True,
) -> None:
    """
    Dashboard do arquivo fiscal: KPIs, navegação por mês, séries (1ª/última nota) e download.
    """
    _k = lambda s: f"{key_prefix}{s}"
    _zk = f"_{key_prefix}arquivo_fiscal_zip_dl"
    _znk = f"_{key_prefix}arquivo_fiscal_zip_dl_n"
    _tot = _arquivo_fiscal_total(cnpj_limpo)
    if _tot <= 0:
        return
    _kpis = _arquivo_fiscal_kpis_empresa(cnpj_limpo)
    _comp = _arquivo_fiscal_competencias_resumo(cnpj_limpo)
    _anos = sorted({a for a, _ in _comp.keys()}, reverse=True)
    if not _anos:
        st.caption("Arquivo indexado, mas sem competência (ano/mês) nos registos.")
        return

    st.markdown('<div class="garim-arq-painel">', unsafe_allow_html=True)
    st.markdown(
        f'<h3>{_garim_emoji("\U0001f4ca")} O que o Garimpeiro já leu desta empresa</h3>',
        unsafe_allow_html=True,
    )
    k1, k2, k3, k4, k5 = st.columns(5)
    k1.metric("XML indexados", f"{_kpis['total']:,}".replace(",", "."))
    k2.metric("Meses com arquivo", _kpis["meses"])
    k3.metric("Emissão própria", f"{_kpis['propria']:,}".replace(",", "."))
    k4.metric("Terceiros", f"{_kpis['terceiros']:,}".replace(",", "."))
    k5.metric("Combinações série", _kpis["series"])

    _ano_key = _k("arquivo_nav_ano")
    _meses_key = _k("arquivo_nav_meses")
    _ult = _arquivo_fiscal_ultima_competencia(cnpj_limpo)
    if _ano_key not in st.session_state:
        st.session_state[_ano_key] = int(_ult[0]) if _ult else int(_anos[0])
    if _meses_key not in st.session_state:
        st.session_state[_meses_key] = [int(_ult[1])] if _ult else [1]

    ca, cb = st.columns([1, 3])
    with ca:
        _ano_sel = st.selectbox(
            "Ano",
            options=_anos,
            key=_ano_key,
        )
    with cb:
        st.caption(
            "Clique nos **meses** com dados (vários) — clique de novo para desmarcar."
        )

    _meses_ano = {m: _comp.get((int(_ano_sel), m), {}) for m in range(1, 13)}
    _nav_meses = [
        int(m)
        for m in (st.session_state.get(_meses_key) or [])
        if 1 <= int(m) <= 12 and (int(_ano_sel), int(m)) in _comp
    ]
    if not _nav_meses:
        _primeiro = next((m for m in range(1, 13) if _comp.get((int(_ano_sel), m))), None)
        if _primeiro:
            _nav_meses = [_primeiro]
            st.session_state[_meses_key] = _nav_meses

    _r1 = st.columns(4)
    _r2 = st.columns(4)
    _r3 = st.columns(4)
    for idx, m in enumerate(range(1, 13)):
        row = _r1 if idx < 4 else (_r2 if idx < 8 else _r3)
        col = row[idx % 4]
        info = _meses_ano.get(m) or {}
        n = int(info.get("total") or 0)
        with col:
            if n > 0:
                _lbl = f"{_MESES_ARQUIVO_CURTO[m]}\n{n:,}".replace(",", ".")
                _ativo = m in _nav_meses
                if st.button(
                    _lbl,
                    key=_k(f"arq_nav_m_{_ano_sel}_{m}"),
                    use_container_width=True,
                    type="primary" if _ativo else "secondary",
                ):
                    _ms = set(_nav_meses)
                    if m in _ms:
                        if len(_ms) > 1:
                            _ms.discard(m)
                    else:
                        _ms.add(m)
                    st.session_state[_meses_key] = sorted(_ms)
                    st.session_state[_k("arquivo_fiscal_filtro_ano")] = int(_ano_sel)
                    st.session_state[_k("arquivo_fiscal_filtro_mes")] = (
                        sorted(_ms)[0] if len(_ms) == 1 else 0
                    )
                    st.rerun()
            else:
                st.button(
                    _MESES_ARQUIVO_CURTO[m],
                    key=_k(f"arq_nav_m_vazio_{_ano_sel}_{m}"),
                    disabled=True,
                    use_container_width=True,
                )

    _nav_meses = sorted(
        int(m)
        for m in (st.session_state.get(_meses_key) or [])
        if 1 <= int(m) <= 12 and (int(_ano_sel), int(m)) in _comp
    )
    if _nav_meses:
        _info_m = _arquivo_fiscal_resumo_periodo(cnpj_limpo, int(_ano_sel), _nav_meses)
        _ms_txt = ", ".join(f"{m:02d}" for m in _nav_meses)
        if len(_nav_meses) == 1:
            _tit_comp = f"**Competência {int(_ano_sel)}/{_nav_meses[0]:02d}**"
        else:
            _tit_comp = f"**Competências {int(_ano_sel)} ({_ms_txt})**"
        st.markdown(
            f"{_tit_comp} — "
            f"**{_info_m['total']:,}** XML "
            f"({_info_m['propria']:,} própria · {_info_m['terceiros']:,} terceiros)".replace(
                ",", "."
            )
        )
        if len(_nav_meses) == 1:
            _df_ser = _arquivo_fiscal_series_por_competencia(
                cnpj_limpo, int(_ano_sel), _nav_meses[0]
            )
        else:
            _df_ser = _arquivo_fiscal_series_por_competencia(
                cnpj_limpo, int(_ano_sel), meses=_nav_meses
            )
        if not _df_ser.empty:
            _cfg_ser = {}
            if hasattr(st, "column_config"):
                _cfg_ser = {
                    "1ª nota": st.column_config.TextColumn("1ª nota"),
                    "Últ. nota": st.column_config.TextColumn("Últ. nota"),
                }
            st.dataframe(
                _df_ser,
                hide_index=True,
                use_container_width=True,
                column_config=_cfg_ser or None,
            )
        else:
            st.caption("Sem numeração de notas neste mês (ex.: só eventos ou inutilizações).")
        _escopo_bur = st.selectbox(
            "Buracos (emissão própria) — período",
            options=["Mês selecionado", "Ano inteiro"],
            key=_k("arquivo_buracos_escopo"),
        )
        if _escopo_bur == "Ano inteiro":
            _meses_bur = sorted(
                m for m in range(1, 13) if (int(_ano_sel), m) in _comp
            )
        else:
            _meses_bur = list(_nav_meses)
        _df_bur_reais = _arquivo_fiscal_buracos_reais_periodo(
            cnpj_limpo, int(_ano_sel), _meses_bur
        )
        _df_bur_falsos = _arquivo_fiscal_falsos_buracos_periodo(
            cnpj_limpo, int(_ano_sel), _meses_bur
        )
        if _df_bur_reais is not None and not _df_bur_reais.empty:
            with st.expander(
                f"Buracos reais ({len(_df_bur_reais)}) — {_escopo_bur.lower()}",
                expanded=False,
            ):
                st.dataframe(_df_bur_reais, hide_index=True, use_container_width=True)
        else:
            st.caption("Nenhum buraco real neste período (ou só uma nota por série).")
        if _df_bur_falsos is not None and not _df_bur_falsos.empty:
            with st.expander(
                f"Falsos buracos ({len(_df_bur_falsos)}) — NF noutro período",
                expanded=True,
            ):
                st.caption(
                    "Falta no mês pela numeração (coluna **Buraco em**), mas a NF já foi lida — "
                    "veja **Emitida em** e **Data emissão** (ex.: buraco em mai, emitida em jun/2026)."
                )
                st.dataframe(_df_bur_falsos, hide_index=True, use_container_width=True)

    if mostrar_download:
        st.markdown("##### Download do período selecionado")
        c1, c2, c3 = st.columns(3)
        with c1:
            if _k("arquivo_fiscal_filtro_ano") not in st.session_state:
                st.session_state[_k("arquivo_fiscal_filtro_ano")] = int(_ano_sel)
            if _k("arquivo_fiscal_filtro_mes") not in st.session_state:
                st.session_state[_k("arquivo_fiscal_filtro_mes")] = (
                    _nav_meses[0] if len(_nav_meses) == 1 else 0
                )
            st.number_input(
                "Ano (download)",
                min_value=2000,
                max_value=2100,
                step=1,
                key=_k("arquivo_fiscal_filtro_ano"),
            )
        with c2:
            st.selectbox(
                "Mês (download)",
                options=[0] + list(range(1, 13)),
                format_func=lambda m: "Todos do ano" if m == 0 else f"{m:02d}",
                key=_k("arquivo_fiscal_filtro_mes"),
            )
        with c3:
            _lado = st.selectbox(
                "Origem",
                options=["todos", "propria", "terceiros"],
                format_func=lambda x: {
                    "todos": "Todas",
                    "propria": "Emissão própria",
                    "terceiros": "Terceiros",
                }.get(x, x),
                key=_k("arquivo_fiscal_filtro_lado"),
            )
        _st_filt = st.selectbox(
            "Status",
            options=["", "NORMAIS", "CANCELADOS", "INUTILIZADOS", "DENEGADOS", "REJEITADOS"],
            format_func=lambda s: "Todos" if not s else s.capitalize(),
            key=_k("arquivo_fiscal_filtro_status"),
        )
        with st.expander("Filtro avançado (série, notas, datas de emissão)", expanded=False):
            _fa1, _fa2, _fa3 = st.columns(3)
            with _fa1:
                _filt_serie = st.text_input(
                    "Série",
                    value="",
                    placeholder="ex.: 2 (vazio = todas)",
                    key=_k("arquivo_fiscal_filtro_serie"),
                )
            with _fa2:
                _filt_d1 = st.text_input(
                    "Data emissão — de",
                    value="",
                    placeholder="dd/mm/aaaa",
                    key=_k("arquivo_fiscal_filtro_d1"),
                )
            with _fa3:
                _filt_d2 = st.text_input(
                    "Data emissão — até",
                    value="",
                    placeholder="dd/mm/aaaa",
                    key=_k("arquivo_fiscal_filtro_d2"),
                )
            _fa4, _fa5, _fa6 = st.columns(3)
            with _fa4:
                _filt_mod = st.selectbox(
                    "Modelo",
                    options=["", "NF-e", "NFC-e", "CT-e", "CT-e OS", "NFS-e", "MDF-e"],
                    format_func=lambda m: "Todos" if not m else m,
                    key=_k("arquivo_fiscal_filtro_modelo"),
                )
            with _fa5:
                _filt_n_ini = st.text_input(
                    "Nota — de",
                    value="",
                    placeholder="ex.: 1000 (vazio = sem limite)",
                    key=_k("arquivo_fiscal_filtro_n_ini"),
                )
            with _fa6:
                _filt_n_fim = st.text_input(
                    "Nota — até",
                    value="",
                    placeholder="ex.: 2500 (vazio = sem limite)",
                    key=_k("arquivo_fiscal_filtro_n_fim"),
                )
        _n_ini = _arquivo_fiscal_parse_numero_filtro(_filt_n_ini)
        _n_fim = _arquivo_fiscal_parse_numero_filtro(_filt_n_fim)
        if (_filt_n_ini or "").strip() and _n_ini is None:
            st.warning("«Nota — de» inválida — use só o número da nota.")
        if (_filt_n_fim or "").strip() and _n_fim is None:
            st.warning("«Nota — até» inválida — use só o número da nota.")
        if _n_ini is not None and _n_fim is not None and _n_ini > _n_fim:
            st.warning("A nota inicial não pode ser maior que a nota final.")
            _n_ini = None
            _n_fim = None
        _ip = None
        if _lado == "propria":
            _ip = 1
        elif _lado == "terceiros":
            _ip = 0
        _mes_f = int(st.session_state.get(_k("arquivo_fiscal_filtro_mes")) or 0)
        _mes_dl = int(_mes_f) if _mes_f > 0 else None
        _meses_dl = None
        if _mes_dl is None and len(_nav_meses) > 1:
            _meses_dl = list(_nav_meses)
        _ano_dl = int(st.session_state.get(_k("arquivo_fiscal_filtro_ano")) or _ano_sel)
        _lista = _arquivo_fiscal_listar(
            cnpj_limpo,
            ano=_ano_dl,
            mes=_mes_dl,
            meses=_meses_dl,
            is_propria=_ip,
            status=_st_filt or None,
            serie=_filt_serie or None,
            modelo=_filt_mod or None,
            data_inicio=_arquivo_fiscal_parse_data_filtro(_filt_d1),
            data_fim=_arquivo_fiscal_parse_data_filtro(_filt_d2),
            numero_inicio=_n_ini,
            numero_fim=_n_fim,
        )
        d1, d2 = st.columns(2)
        with d1:
            st.caption(
                f"**{len(_lista)}** documento(s) com estes filtros. "
                f"Arquivo: `{_ARQUIVO_FISCAL_SUBPASTA_XML}/AAAA/Mês/EP_…/` e "
                f"`{_ARQUIVO_FISCAL_SUBPASTA_ZIP}/AAAA/Mês/EP_….zip` (mesmo nome das pastas). "
                f"O botão abaixo gera ZIP(s) só para download (filtro atual, XML na raiz)."
            )
            if st.button(
                "Gerar ZIP para download",
                key=_k("btn_arquivo_fiscal_zip"),
                disabled=not _lista,
                type="primary",
            ):
                with st.spinner("A montar ZIP para download…"):
                    zpaths, nzip, n_aus_zip, zerr = _arquivo_fiscal_zip_filtrado(
                        cnpj_limpo,
                        ano=_ano_dl,
                        mes=_mes_dl,
                        meses=_meses_dl,
                        is_propria=_ip,
                        status=_st_filt or None,
                        serie=_filt_serie or None,
                        modelo=_filt_mod or None,
                        data_inicio=_arquivo_fiscal_parse_data_filtro(_filt_d1),
                        data_fim=_arquivo_fiscal_parse_data_filtro(_filt_d2),
                        numero_inicio=_n_ini,
                        numero_fim=_n_fim,
                    )
                if zerr:
                    st.error(zerr)
                elif zpaths:
                    st.session_state[_zk] = zpaths
                    st.session_state[_znk] = nzip
                    if n_aus_zip > 0:
                        st.warning(
                            f"{n_aus_zip} XML(s) constam no índice mas não existem no disco "
                            f"(não incluídos no ZIP). O ZIP contém {nzip} ficheiro(s)."
                        )
        with d2:
            _xls = _arquivo_fiscal_excel_path(cnpj_limpo)
            if _xls.is_file():
                with open(_xls, "rb") as _xf:
                    st.download_button(
                        "Descarregar Excel do relatório",
                        _xf.read(),
                        file_name=_ARQUIVO_FISCAL_NOME_EXCEL,
                        mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                        key=_k("dl_arquivo_fiscal_excel"),
                        use_container_width=True,
                    )
            else:
                st.caption("Excel do relatório ainda não gerado nesta pasta.")
        _zdl = st.session_state.get(_zk)
        _zdn = int(st.session_state.get(_znk) or 0)
        _zlist = _zdl if isinstance(_zdl, list) else ([_zdl] if _zdl else [])
        for _zi, _zp in enumerate(_zlist):
            if _zp and os.path.isfile(_zp):
                with open(_zp, "rb") as fp:
                    st.download_button(
                        f"Descarregar {os.path.basename(_zp)} ({_zdn} XML no total)"
                        if len(_zlist) == 1
                        else f"Descarregar {os.path.basename(_zp)}",
                        fp.read(),
                        file_name=os.path.basename(_zp),
                        mime="application/zip",
                        key=_k(f"dl_arquivo_fiscal_zip_{_zi}"),
                    )

    st.markdown("</div>", unsafe_allow_html=True)


