                                st.session_state.pop("mariana_sem_xml_msg", None)
                                st.session_state.pop("mariana_excel_completo_path", None)
                                st.session_state.pop("mariana_autent_pastas", None)
                                st.session_state.pop("mariana_pacote_modo", None)
